#[cfg(test)]
fn dummy_accepted_transaction() -> iroha_core::tx::AcceptedTransaction<'static> {
    use std::{borrow::Cow, time::Duration};

    use iroha_data_model::{
        ChainId, Level, account::AccountId, isi::Log, transaction::TransactionBuilder,
    };

    let chain_id: ChainId = "00000000-0000-0000-0000-000000000000"
        .parse()
        .expect("valid chain id");
    let keypair = checked_routing_fixture_keypair(
        0xe1,
        Algorithm::Ed25519,
        "derive dummy accepted transaction fixture key",
    );
    let authority = AccountId::new(keypair.public_key().clone());
    let mut builder = TransactionBuilder::new(
        chain_id,
        authority,
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    );
    builder.set_creation_time(Duration::from_millis(0));
    let tx = builder
        .with_instructions([Log::new(Level::INFO, "dummy".to_owned())])
        .sign(keypair.private_key());
    iroha_core::tx::AcceptedTransaction::new_unchecked(Cow::Owned(tx))
}

mod debug_toggle_override {
    pub(super) fn torii_override_active() -> bool {
        state::torii_active()
    }

    #[cfg(test)]
    pub(super) fn set_torii_override(active: bool) -> bool {
        state::set_torii(active)
    }

    #[cfg(test)]
    pub(super) fn set_iroha_override(active: bool) -> bool {
        state::set_iroha(active)
    }

    #[cfg(test)]
    mod state {
        use std::sync::atomic::{AtomicBool, Ordering};

        pub(super) static TORII_DEBUG_MATCH: AtomicBool = AtomicBool::new(false);
        pub(super) static IROHA_DEBUG_TX_EVAL: AtomicBool = AtomicBool::new(false);

        pub(super) fn set_torii(active: bool) -> bool {
            TORII_DEBUG_MATCH.swap(active, Ordering::SeqCst)
        }

        pub(super) fn torii_active() -> bool {
            TORII_DEBUG_MATCH.load(Ordering::SeqCst)
        }

        pub(super) fn set_iroha(active: bool) -> bool {
            IROHA_DEBUG_TX_EVAL.swap(active, Ordering::SeqCst)
        }
    }

    #[cfg(not(test))]
    mod state {
        pub(super) fn set_torii(_active: bool) -> bool {
            false
        }

        pub(super) fn torii_active() -> bool {
            false
        }

        pub(super) fn set_iroha(_active: bool) -> bool {
            false
        }
    }
}

fn torii_debug_match_enabled() -> bool {
    debug_match_flag::enabled(debug_toggle_override::torii_override_active())
}

/// Compute start/end bounds for paginating a collection of length `len`.
///
/// - `offset` values that exceed `usize::MAX` (on the current platform) or the
///   collection length clamp to the end of the collection, yielding an empty
///   slice.
/// - When `cap` is provided, user-supplied limits are clamped to that maximum.
fn pagination_bounds(
    len: usize,
    offset: u64,
    limit: Option<u64>,
    cap: Option<u64>,
) -> (usize, usize) {
    let start = match usize::try_from(offset) {
        Ok(off) => off.min(len),
        Err(_) => len,
    };

    let limited = limit.map(|lim| cap.map_or(lim, |cap_lim| lim.min(cap_lim)));

    let end = limited
        .and_then(|lim| usize::try_from(lim).ok())
        .map(|lim| start.saturating_add(lim).min(len))
        .unwrap_or(len);

    (start, end)
}

/// Optional `from`/`limit` window applied to newest-first histories.
#[derive(
    crate::json_macros::JsonDeserialize, norito::derive::NoritoDeserialize, Default, Debug, Clone,
)]
pub struct HistoryWindowQuery {
    /// Optional starting height (inclusive). Defaults to the latest known height.
    pub from: Option<u64>,
    /// Optional result cap (0 yields an empty result set).
    pub limit: Option<u64>,
}

/// Compound cursor window for newest-first SCCP outbox discovery.
#[derive(Default, Debug, Clone, Copy, PartialEq, Eq)]
pub struct SccpRecentWindowQuery {
    /// Inclusive starting height; omitted starts at the newest retained height.
    pub from: Option<u64>,
    /// Last commitment index already consumed at `from`.
    pub after_index: Option<u32>,
    /// Optional result cap.
    pub limit: Option<u64>,
}

/// Apply a height window to a newest-first history vector while clamping to a server cap.
pub fn clamp_history_window<T, F>(
    items_newest_first: Vec<T>,
    from: Option<u64>,
    limit: Option<u64>,
    cap: u64,
    height_fn: F,
) -> Vec<T>
where
    T: Clone,
    F: Fn(&T) -> u64,
{
    let capped_limit = limit
        .map(|lim| lim.min(cap))
        .unwrap_or(cap)
        .min(usize::MAX as u64) as usize;

    let start_from =
        from.unwrap_or_else(|| items_newest_first.first().map(&height_fn).unwrap_or(0));

    items_newest_first
        .into_iter()
        .filter(|item| height_fn(item) <= start_from)
        .take(capped_limit)
        .collect()
}

#[cfg(test)]
mod pagination_tests {
    use super::{clamp_history_window, pagination_bounds};

    #[test]
    fn pagination_bounds_limit_zero_returns_empty() {
        let (start, end) = pagination_bounds(10, 0, Some(0), Some(5));
        assert_eq!((start, end), (0, 0));
    }

    #[test]
    fn clamp_history_window_limit_zero_returns_empty() {
        let items = vec![3u64, 2, 1];
        let windowed = clamp_history_window(items, None, Some(0), 10, |v| *v);
        assert!(windowed.is_empty());
    }
}

#[cfg(feature = "app_api")]
#[derive(Debug)]
struct PageEntry<K, T> {
    key: K,
    seq: usize,
    item: T,
}

#[cfg(feature = "app_api")]
#[derive(Clone)]
enum SortKeyValue {
    Text(String),
    Numeric(iroha_primitives::numeric::Numeric),
}

#[cfg(feature = "app_api")]
impl SortKeyValue {
    fn variant_ord(&self) -> usize {
        match self {
            SortKeyValue::Text(_) => 0,
            SortKeyValue::Numeric(_) => 1,
        }
    }
}

#[cfg(feature = "app_api")]
impl From<String> for SortKeyValue {
    fn from(value: String) -> Self {
        SortKeyValue::Text(value)
    }
}

#[cfg(feature = "app_api")]
impl From<&String> for SortKeyValue {
    fn from(value: &String) -> Self {
        SortKeyValue::Text(value.clone())
    }
}

#[cfg(feature = "app_api")]
impl From<&str> for SortKeyValue {
    fn from(value: &str) -> Self {
        SortKeyValue::Text(value.to_owned())
    }
}

#[cfg(feature = "app_api")]
impl From<iroha_primitives::numeric::Numeric> for SortKeyValue {
    fn from(value: iroha_primitives::numeric::Numeric) -> Self {
        SortKeyValue::Numeric(value)
    }
}

#[cfg(feature = "app_api")]
impl From<&iroha_primitives::numeric::Numeric> for SortKeyValue {
    fn from(value: &iroha_primitives::numeric::Numeric) -> Self {
        SortKeyValue::Numeric(value.clone())
    }
}

#[cfg(feature = "app_api")]
impl PartialEq for SortKeyValue {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (SortKeyValue::Text(lhs), SortKeyValue::Text(rhs)) => lhs == rhs,
            (SortKeyValue::Numeric(lhs), SortKeyValue::Numeric(rhs)) => lhs == rhs,
            _ => false,
        }
    }
}

#[cfg(feature = "app_api")]
impl Eq for SortKeyValue {}

#[cfg(feature = "app_api")]
impl Ord for SortKeyValue {
    fn cmp(&self, other: &Self) -> Ordering {
        match (self, other) {
            (SortKeyValue::Text(lhs), SortKeyValue::Text(rhs)) => lhs.cmp(rhs),
            (SortKeyValue::Numeric(lhs), SortKeyValue::Numeric(rhs)) => lhs.cmp(rhs),
            _ => self.variant_ord().cmp(&other.variant_ord()),
        }
    }
}

#[cfg(feature = "app_api")]
impl PartialOrd for SortKeyValue {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[cfg(feature = "app_api")]
#[derive(Clone, Eq, PartialEq)]
struct SortKeyComponent {
    value: SortKeyValue,
    ascending: bool,
}

#[cfg(feature = "app_api")]
impl SortKeyComponent {
    fn asc<V: Into<SortKeyValue>>(value: V) -> Self {
        Self {
            value: value.into(),
            ascending: true,
        }
    }

    fn desc<V: Into<SortKeyValue>>(value: V) -> Self {
        Self {
            value: value.into(),
            ascending: false,
        }
    }
}

#[cfg(feature = "app_api")]
#[derive(Clone, Eq, PartialEq)]
struct MultiSortKey {
    components: Vec<SortKeyComponent>,
}

#[cfg(feature = "app_api")]
impl MultiSortKey {
    fn new(components: Vec<SortKeyComponent>) -> Self {
        Self { components }
    }

    fn push(&mut self, component: SortKeyComponent) {
        self.components.push(component);
    }

    fn is_empty(&self) -> bool {
        self.components.is_empty()
    }
}

#[cfg(feature = "app_api")]
impl Ord for MultiSortKey {
    fn cmp(&self, other: &Self) -> Ordering {
        for (lhs, rhs) in self.components.iter().zip(other.components.iter()) {
            let ord = if lhs.ascending {
                lhs.value.cmp(&rhs.value)
            } else {
                rhs.value.cmp(&lhs.value)
            };
            if !ord.is_eq() {
                return ord;
            }
        }
        self.components.len().cmp(&other.components.len())
    }
}

#[cfg(feature = "app_api")]
impl PartialOrd for MultiSortKey {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[cfg(feature = "app_api")]
impl<K: Ord, T> PartialEq for PageEntry<K, T> {
    fn eq(&self, other: &Self) -> bool {
        self.seq == other.seq && self.key == other.key
    }
}

#[cfg(feature = "app_api")]
impl<K: Ord, T> Eq for PageEntry<K, T> {}

#[cfg(feature = "app_api")]
impl<K: Ord, T> PartialOrd for PageEntry<K, T> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[cfg(feature = "app_api")]
impl<K: Ord, T> Ord for PageEntry<K, T> {
    fn cmp(&self, other: &Self) -> Ordering {
        match self.key.cmp(&other.key) {
            Ordering::Equal => self.seq.cmp(&other.seq),
            ord => ord,
        }
    }
}

#[cfg(feature = "app_api")]
fn collect_page_streaming<K, T, I>(
    iter: I,
    offset: u64,
    limit: Option<u64>,
    cap: Option<u64>,
) -> (Vec<T>, usize)
where
    I: IntoIterator<Item = (K, T)>,
    K: Ord,
{
    let offset_usize = if offset > usize::MAX as u64 {
        usize::MAX
    } else {
        offset as usize
    };
    let limit_usize = limit
        .filter(|&lim| lim > 0)
        .map(|lim| cap.map_or(lim, |c| lim.min(c)))
        .map(|lim| lim.min(usize::MAX as u64) as usize);
    let page_cap = limit_usize.map(|lim| offset_usize.saturating_add(lim));

    let mut matched: usize = 0;
    let mut seq: usize = 0;
    let mut heap: BinaryHeap<PageEntry<K, T>> = BinaryHeap::new();
    let mut collected: Vec<PageEntry<K, T>> = Vec::new();

    for (key, item) in iter.into_iter() {
        let entry = PageEntry { key, seq, item };
        seq = seq.wrapping_add(1);
        matched = matched.saturating_add(1);
        if let Some(capacity) = page_cap {
            heap.push(entry);
            if heap.len() > capacity {
                heap.pop();
            }
        } else {
            collected.push(entry);
        }
    }

    let mut entries = if page_cap.is_some() {
        heap.into_vec()
    } else {
        collected
    };

    entries.sort_by(|a, b| match a.key.cmp(&b.key) {
        Ordering::Equal => a.seq.cmp(&b.seq),
        ord => ord,
    });

    let skip = offset_usize.min(entries.len());
    let mut page: Vec<T> = Vec::new();
    for entry in entries.into_iter().skip(skip) {
        if let Some(lim) = limit_usize {
            if page.len() >= lim {
                break;
            }
        }
        page.push(entry.item);
    }

    (page, matched)
}

#[cfg(feature = "app_api")]
struct PageResult<T> {
    items: Vec<T>,
    total: Option<usize>,
    has_more: bool,
}

#[cfg(feature = "app_api")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AppCountMode {
    Bounded,
    Exact,
}

#[cfg(feature = "app_api")]
impl AppCountMode {
    const fn label(self) -> &'static str {
        match self {
            Self::Bounded => "bounded",
            Self::Exact => "exact",
        }
    }
}

#[cfg(feature = "app_api")]
fn app_count_mode(raw: Option<&str>, endpoint: &'static str) -> AppCountMode {
    match raw {
        Some("exact") => AppCountMode::Exact,
        Some("bounded") => AppCountMode::Bounded,
        None => AppCountMode::Exact,
        Some(other) => {
            iroha_logger::warn!(
                endpoint,
                count_mode = other,
                "unknown app query count_mode; using bounded"
            );
            AppCountMode::Bounded
        }
    }
}

#[cfg(feature = "app_api")]
fn normalize_app_generic_count_mode(
    envelope: &mut crate::filter::QueryEnvelope,
    endpoint: &'static str,
) {
    let count_mode = app_count_mode(envelope.count_mode.as_deref(), endpoint);
    envelope.count_mode = Some(count_mode.label().to_owned());
}

#[cfg(feature = "app_api")]
fn collect_page_streaming_bounded<K, T, I>(
    iter: I,
    offset: u64,
    limit: Option<u64>,
    cap: Option<u64>,
) -> PageResult<T>
where
    I: IntoIterator<Item = (K, T)>,
    K: Ord,
{
    let offset_usize = if offset > usize::MAX as u64 {
        usize::MAX
    } else {
        offset as usize
    };
    let limit_usize = limit
        .filter(|&lim| lim > 0)
        .map(|lim| cap.map_or(lim, |c| lim.min(c)))
        .or(cap)
        .map(|lim| lim.min(usize::MAX as u64) as usize);
    let take = limit_usize.unwrap_or(usize::MAX);
    let probe_cap = offset_usize.saturating_add(take).saturating_add(1);

    let mut seq: usize = 0;
    let mut heap: BinaryHeap<PageEntry<K, T>> = BinaryHeap::new();
    let mut collected: Vec<PageEntry<K, T>> = Vec::new();
    let bounded = probe_cap != usize::MAX;

    for (key, item) in iter.into_iter() {
        let entry = PageEntry { key, seq, item };
        seq = seq.wrapping_add(1);
        if bounded {
            heap.push(entry);
            if heap.len() > probe_cap {
                heap.pop();
            }
        } else {
            collected.push(entry);
        }
    }

    let mut entries = if bounded { heap.into_vec() } else { collected };
    entries.sort_by(|a, b| match a.key.cmp(&b.key) {
        Ordering::Equal => a.seq.cmp(&b.seq),
        ord => ord,
    });

    let skip = offset_usize.min(entries.len());
    let has_more = entries.len().saturating_sub(skip) > take;
    let items = entries
        .into_iter()
        .skip(skip)
        .take(take)
        .map(|entry| entry.item)
        .collect();
    PageResult {
        items,
        total: None,
        has_more,
    }
}

#[cfg(feature = "app_api")]
fn collect_page_streaming_for_mode<K, T, I>(
    iter: I,
    offset: u64,
    limit: Option<u64>,
    cap: Option<u64>,
    count_mode: AppCountMode,
) -> PageResult<T>
where
    I: IntoIterator<Item = (K, T)>,
    K: Ord,
{
    match count_mode {
        AppCountMode::Bounded => collect_page_streaming_bounded(iter, offset, limit, cap),
        AppCountMode::Exact => {
            let (items, total) = collect_page_streaming(iter, offset, limit, cap);
            let returned_until =
                offset.saturating_add(u64::try_from(items.len()).unwrap_or(u64::MAX));
            PageResult {
                items,
                total: Some(total),
                has_more: u64::try_from(total).unwrap_or(u64::MAX) > returned_until,
            }
        }
    }
}

#[cfg(feature = "app_api")]
#[derive(Copy, Clone)]
struct EffectivePagination {
    limit: Option<u64>,
    offset: u64,
    cap: u64,
}

#[cfg(feature = "app_api")]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct QueryProjectionArchiveCacheKey {
    resource: QueryProjectionResourceKind,
    partition_id: u32,
    asset_definition_id: Option<String>,
    indexed_height: u64,
    indexed_block_hash_hex: Option<String>,
}

#[cfg(feature = "app_api")]
const QUERY_PROJECTION_ARCHIVE_HOT_CACHE_MAX_ENTRIES: usize = 32;
#[cfg(feature = "app_api")]
const QUERY_PROJECTION_ARCHIVE_HOT_CACHE_MAX_BYTES: usize = 256 * 1024 * 1024;

#[cfg(feature = "app_api")]
#[derive(Default)]
struct QueryProjectionArchiveHotCache {
    entries: BTreeMap<QueryProjectionArchiveCacheKey, QueryProjectionShardArchive>,
    insertion_order: VecDeque<QueryProjectionArchiveCacheKey>,
    total_payload_bytes: usize,
}

#[cfg(feature = "app_api")]
impl QueryProjectionArchiveHotCache {
    fn get(&self, key: &QueryProjectionArchiveCacheKey) -> Option<QueryProjectionShardArchive> {
        self.entries.get(key).cloned()
    }

    fn insert(
        &mut self,
        key: QueryProjectionArchiveCacheKey,
        archive: QueryProjectionShardArchive,
    ) {
        let archive_weight = query_projection_archive_cache_weight(&archive);
        if let Some(previous) = self.entries.insert(key.clone(), archive) {
            self.total_payload_bytes = self
                .total_payload_bytes
                .saturating_sub(query_projection_archive_cache_weight(&previous));
            self.insertion_order.retain(|existing| existing != &key);
        }
        self.total_payload_bytes = self.total_payload_bytes.saturating_add(archive_weight);
        self.insertion_order.push_back(key);

        while self.entries.len() > QUERY_PROJECTION_ARCHIVE_HOT_CACHE_MAX_ENTRIES
            || self.total_payload_bytes > QUERY_PROJECTION_ARCHIVE_HOT_CACHE_MAX_BYTES
        {
            let Some(evicted_key) = self.insertion_order.pop_front() else {
                break;
            };
            let Some(evicted) = self.entries.remove(&evicted_key) else {
                continue;
            };
            self.total_payload_bytes = self
                .total_payload_bytes
                .saturating_sub(query_projection_archive_cache_weight(&evicted));
        }
    }

    fn clear(&mut self) {
        self.entries.clear();
        self.insertion_order.clear();
        self.total_payload_bytes = 0;
    }
}

#[cfg(feature = "app_api")]
static QUERY_PROJECTION_ARCHIVE_CACHE: LazyLock<RwLock<QueryProjectionArchiveHotCache>> =
    LazyLock::new(|| RwLock::new(QueryProjectionArchiveHotCache::default()));

#[cfg(feature = "app_api")]
static QUERY_PROJECTION_ARCHIVE_HYDRATION_LOCKS: LazyLock<
    tokio::sync::Mutex<BTreeMap<QueryProjectionArchiveCacheKey, Arc<tokio::sync::Mutex<()>>>>,
> = LazyLock::new(|| tokio::sync::Mutex::new(BTreeMap::new()));

#[cfg(feature = "app_api")]
fn query_projection_block_hash_hex(hash: Option<HashOf<BlockHeader>>) -> Option<String> {
    hash.map(|hash| hex::encode(hash.as_ref().as_ref()))
}

#[cfg(feature = "app_api")]
fn query_projection_archive_cache_key(
    archive: &QueryProjectionShardArchive,
) -> QueryProjectionArchiveCacheKey {
    QueryProjectionArchiveCacheKey {
        resource: archive.resource,
        partition_id: archive.partition_id,
        asset_definition_id: archive.asset_definition_id.clone(),
        indexed_height: archive.indexed_height,
        indexed_block_hash_hex: query_projection_block_hash_hex(archive.indexed_block_hash),
    }
}

#[cfg(feature = "app_api")]
fn query_projection_checkpoint_cache_key(
    shard: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpointShard,
    checkpoint: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpoint,
) -> QueryProjectionArchiveCacheKey {
    QueryProjectionArchiveCacheKey {
        resource: shard.resource,
        partition_id: shard.partition_id,
        asset_definition_id: shard.asset_definition_id.clone(),
        indexed_height: checkpoint.indexed_height,
        indexed_block_hash_hex: query_projection_block_hash_hex(checkpoint.indexed_block_hash),
    }
}

#[cfg(feature = "app_api")]
fn query_projection_archive_cache_weight(archive: &QueryProjectionShardArchive) -> usize {
    archive
        .payload
        .len()
        .saturating_add(core::mem::size_of::<QueryProjectionShardArchive>())
}

#[cfg(feature = "app_api")]
fn query_projection_archive_from_hot_cache(
    key: &QueryProjectionArchiveCacheKey,
) -> Option<QueryProjectionShardArchive> {
    match QUERY_PROJECTION_ARCHIVE_CACHE.read() {
        Ok(cache) => cache.get(key),
        Err(_) => {
            iroha_logger::warn!(
                "query projection archive cache lock poisoned; snapshot aggregate cache unavailable"
            );
            None
        }
    }
}

#[cfg(feature = "app_api")]
pub(crate) fn cache_query_projection_archive_for_query(archive: QueryProjectionShardArchive) {
    match QUERY_PROJECTION_ARCHIVE_CACHE.write() {
        Ok(mut cache) => {
            cache.insert(query_projection_archive_cache_key(&archive), archive);
        }
        Err(_) => {
            iroha_logger::warn!(
                "query projection archive cache lock poisoned; snapshot aggregate cache not updated"
            );
        }
    }
}

#[cfg(all(feature = "app_api", test))]
fn clear_query_projection_archive_cache_for_tests() {
    if let Ok(mut cache) = QUERY_PROJECTION_ARCHIVE_CACHE.write() {
        cache.clear();
    }
}

#[cfg(feature = "app_api")]
fn app_query_page_cap(state: &CoreState) -> u64 {
    let _ = state;
    app_query_limits().max_page_limit
}

#[cfg(feature = "app_api")]
fn enforce_app_pagination(
    limit: Option<u64>,
    offset: u64,
    cap: u64,
    endpoint: &'static str,
) -> Result<EffectivePagination> {
    let limits = app_query_limits();
    let max_cap = limits.max_page_limit.min(cap.max(1));
    let default_limit = limits.default_page_limit.min(max_cap);
    let invalid = |cap| Error::AppQueryValidation {
        code: "invalid_pagination",
        message: format!("limit must be between 1 and {cap} for {endpoint}"),
    };
    let effective_limit = match limit {
        Some(0) => return Err(invalid(cap)),
        Some(lim) if lim > max_cap => return Err(invalid(max_cap)),
        Some(lim) => Some(lim),
        None => Some(default_limit),
    };
    Ok(EffectivePagination {
        limit: effective_limit,
        offset,
        cap: max_cap,
    })
}

#[cfg(feature = "app_api")]
fn map_filter_error(err: crate::filter::ValidateError, endpoint: &'static str) -> Error {
    match err {
        crate::filter::ValidateError::UnsupportedField(field) => Error::AppQueryValidation {
            code: "invalid_field_path",
            message: format!("unsupported field `{field}` for {endpoint}"),
        },
        crate::filter::ValidateError::TypeMismatch(field) => Error::AppQueryValidation {
            code: "type_mismatch",
            message: format!("type mismatch at field `{field}` for {endpoint}"),
        },
    }
}

#[cfg(feature = "app_api")]
fn collect_page_linear<T, I>(
    iter: I,
    offset: u64,
    limit: Option<u64>,
    fetch_size: Option<u64>,
) -> (Vec<T>, usize)
where
    I: IntoIterator<Item = T>,
{
    let offset_usize = if offset > usize::MAX as u64 {
        usize::MAX
    } else {
        offset as usize
    };
    let limit_usize = limit
        .filter(|&lim| lim > 0)
        .map(|lim| lim.min(usize::MAX as u64) as usize);
    let fetch_cap_usize = fetch_size
        .filter(|&cap| cap > 0)
        .map(|cap| cap.min(usize::MAX as u64) as usize);

    let mut matched: usize = 0;
    let mut items: Vec<T> = Vec::new();
    let mut additional_after_fill: usize = 0;

    for item in iter.into_iter() {
        matched = matched.saturating_add(1);
        let within_page =
            matched > offset_usize && limit_usize.map(|lim| items.len() < lim).unwrap_or(true);
        if within_page {
            items.push(item);
            continue;
        }
        if limit_usize.map(|lim| items.len() >= lim).unwrap_or(false) {
            if let Some(cap) = fetch_cap_usize {
                additional_after_fill = additional_after_fill.saturating_add(1);
                if additional_after_fill >= cap {
                    break;
                }
            }
        }
    }

    (items, matched)
}

#[cfg(feature = "app_api")]
fn collect_page_linear_bounded<T, I>(
    iter: I,
    offset: u64,
    limit: Option<u64>,
    fetch_size: Option<u64>,
) -> PageResult<T>
where
    I: IntoIterator<Item = T>,
{
    let offset_usize = if offset > usize::MAX as u64 {
        usize::MAX
    } else {
        offset as usize
    };
    let take = limit
        .filter(|&lim| lim > 0)
        .or(fetch_size)
        .unwrap_or(u64::from(defaults::torii::APP_API_DEFAULT_LIST_LIMIT))
        .min(usize::MAX as u64) as usize;
    let probe = offset_usize.saturating_add(take).saturating_add(1);
    let mut items = Vec::new();
    let mut seen = 0usize;
    let mut has_more = false;
    for item in iter.into_iter().take(probe) {
        if seen < offset_usize {
            seen = seen.saturating_add(1);
            continue;
        }
        if items.len() < take {
            items.push(item);
        } else {
            has_more = true;
            break;
        }
        seen = seen.saturating_add(1);
    }
    PageResult {
        items,
        total: None,
        has_more,
    }
}

#[cfg(feature = "app_api")]
fn collect_page_linear_for_mode<T, I>(
    iter: I,
    offset: u64,
    limit: Option<u64>,
    fetch_size: Option<u64>,
    count_mode: AppCountMode,
) -> PageResult<T>
where
    I: IntoIterator<Item = T>,
{
    match count_mode {
        AppCountMode::Bounded => collect_page_linear_bounded(iter, offset, limit, fetch_size),
        AppCountMode::Exact => {
            let (items, total) = collect_page_linear(iter, offset, limit, fetch_size);
            let returned_until =
                offset.saturating_add(u64::try_from(items.len()).unwrap_or(u64::MAX));
            PageResult {
                items,
                total: Some(total),
                has_more: u64::try_from(total).unwrap_or(u64::MAX) > returned_until,
            }
        }
    }
}

#[cfg(feature = "app_api")]
fn page_result_from_counted_items<T>(
    items: Vec<T>,
    matched: usize,
    offset: u64,
    count_mode: AppCountMode,
) -> PageResult<T> {
    let returned_until = offset.saturating_add(u64::try_from(items.len()).unwrap_or(u64::MAX));
    PageResult {
        items,
        total: (count_mode == AppCountMode::Exact).then_some(matched),
        has_more: u64::try_from(matched).unwrap_or(u64::MAX) > returned_until,
    }
}

#[cfg(feature = "app_api")]
fn insert_page_metadata<T>(
    top: &mut norito::json::Map,
    page: &PageResult<T>,
    count_mode: AppCountMode,
) {
    if let Some(total) = page.total {
        top.insert("total".into(), norito::json::Value::from(total as u64));
    }
    top.insert("has_more".into(), norito::json::Value::from(page.has_more));
    top.insert(
        "count_mode".into(),
        norito::json::Value::from(count_mode.label()),
    );
}

#[cfg(feature = "app_api")]
fn insert_bounded_page_metadata<T>(top: &mut norito::json::Map, page: &PageResult<T>) {
    insert_page_metadata(top, page, AppCountMode::Bounded);
}

#[cfg(all(test, feature = "app_api"))]
mod streaming_pager_tests {
    use std::{cell::Cell, rc::Rc};

    use super::{MultiSortKey, SortKeyComponent, collect_page_linear, collect_page_streaming};

    #[test]
    fn collects_expected_page_with_limit() {
        let (items, total) = collect_page_streaming((0..10).map(|i| (i, i)), 2, Some(3), None);
        assert_eq!(total, 10);
        assert_eq!(items, vec![2, 3, 4]);
    }

    #[test]
    fn respects_large_offset() {
        let (items, total) = collect_page_streaming((0..5).map(|i| (i, i)), 10, Some(2), None);
        assert_eq!(total, 5);
        assert!(items.is_empty());
    }

    #[test]
    fn collects_all_when_limit_absent() {
        let (items, total) = collect_page_streaming((0..3).map(|i| (i, i)), 1, None, None);
        assert_eq!(total, 3);
        assert_eq!(items, vec![1, 2]);
    }

    #[test]
    fn orders_multi_key_with_mixed_directions() {
        let data = vec![
            (
                MultiSortKey::new(vec![
                    SortKeyComponent::asc("alpha".to_string()),
                    SortKeyComponent::desc("2".to_string()),
                ]),
                "alpha-2",
            ),
            (
                MultiSortKey::new(vec![
                    SortKeyComponent::asc("alpha".to_string()),
                    SortKeyComponent::desc("3".to_string()),
                ]),
                "alpha-3",
            ),
            (
                MultiSortKey::new(vec![
                    SortKeyComponent::asc("beta".to_string()),
                    SortKeyComponent::desc("1".to_string()),
                ]),
                "beta-1",
            ),
        ];
        let (items, total) = collect_page_streaming(data, 0, None, None);
        assert_eq!(total, 3);
        assert_eq!(items, vec!["alpha-3", "alpha-2", "beta-1"]);
    }

    #[test]
    fn preserves_insertion_order_when_keys_equal() {
        let key = MultiSortKey::new(vec![SortKeyComponent::asc("same".to_string())]);
        let data = vec![(key.clone(), 1usize), (key.clone(), 2usize), (key, 3usize)];
        let (items, _) = collect_page_streaming(data, 0, None, None);
        assert_eq!(items, vec![1, 2, 3]);
    }

    #[test]
    fn linear_collects_expected_window() {
        let (items, total) = collect_page_linear(0..5, 1, Some(2), None);
        assert_eq!(total, 5);
        assert_eq!(items, vec![1, 2]);
    }

    #[test]
    fn linear_respects_fetch_cap_after_page_fill() {
        let counter = Rc::new(Cell::new(0usize));
        let iter_counter = counter.clone();
        let iter = (0..10).inspect(move |_| {
            let seen = iter_counter.get();
            iter_counter.set(seen + 1);
        });
        let (items, total) = collect_page_linear(iter, 0, Some(2), Some(3));
        assert_eq!(items, vec![0, 1]);
        assert_eq!(total, 5);
        assert_eq!(counter.get(), 5);
    }
}

/// Telemetry handle that pairs a runtime [`Telemetry`] instance with capability gating.
#[derive(Clone)]
pub struct MaybeTelemetry<G = TelemetryProfile> {
    gate: G,
    telemetry: Option<Telemetry>,
}

impl<G> fmt::Debug for MaybeTelemetry<G>
where
    G: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("MaybeTelemetry")
            .field("gate", &self.gate)
            .field("has_telemetry", &self.telemetry.is_some())
            .finish()
    }
}

impl<G> MaybeTelemetry<G>
where
    G: TelemetryGate + Clone,
{
    /// Create a new telemetry handle with the given gate and optional runtime handle.
    pub fn new(telemetry: Option<Telemetry>, gate: G) -> Self {
        Self { gate, telemetry }
    }

    /// Return the active telemetry profile.
    pub fn profile(&self) -> TelemetryProfile {
        self.gate.profile()
    }

    /// Whether metrics collection/exposure is permitted.
    pub fn allows_metrics(&self) -> bool {
        self.telemetry.is_some() && self.gate.allows_metrics()
    }

    /// Whether expensive metrics are permitted.
    pub fn allows_expensive_metrics(&self) -> bool {
        self.telemetry.is_some() && self.gate.allows_expensive_metrics()
    }

    /// Whether developer-only telemetry outputs are permitted.
    pub fn allows_developer_outputs(&self) -> bool {
        self.telemetry.is_some() && self.gate.allows_developer_outputs()
    }

    /// Whether telemetry observations are currently enabled.
    pub fn is_enabled(&self) -> bool {
        self.allows_metrics()
    }

    /// Access the underlying telemetry handle if available.
    pub fn telemetry(&self) -> Option<&Telemetry> {
        self.telemetry.as_ref()
    }

    /// Clone the underlying telemetry handle if available.
    pub fn telemetry_cloned(&self) -> Option<Telemetry> {
        self.telemetry.clone()
    }

    /// Execute the callback when metrics are allowed and telemetry is present.
    pub fn with_metrics<T>(&self, f: impl FnOnce(&Telemetry) -> T) -> Option<T> {
        if !self.allows_metrics() {
            return None;
        }
        self.telemetry.as_ref().map(f)
    }

    #[cfg(feature = "telemetry")]
    /// Forward a SoraNet privacy telemetry event to the underlying aggregator when metrics are enabled.
    pub fn record_soranet_privacy_event(&self, event: &SoranetPrivacyEventV1) {
        if !self.allows_metrics() {
            return;
        }
        if let Some(telemetry) = self.telemetry() {
            telemetry.record_soranet_privacy_event(event);
        }
    }

    #[cfg(feature = "telemetry")]
    #[allow(clippy::future_not_send)]
    /// Record a rejected SoraNet privacy ingest attempt with a labeled reason.
    pub async fn record_soranet_privacy_ingest_reject(
        &self,
        endpoint: &'static str,
        reason: &'static str,
    ) {
        if !self.allows_metrics() {
            return;
        }
        if let Some(telemetry) = self.telemetry.as_ref() {
            telemetry
                .metrics()
                .await
                .soranet_privacy_ingest_reject_total
                .with_label_values(&[endpoint, reason])
                .inc();
        }
    }

    #[cfg(feature = "telemetry")]
    /// Ingest a Prio collector share into the privacy aggregator when metrics are enabled.
    pub fn ingest_soranet_privacy_share(
        &self,
        share: SoranetPrivacyPrioShareV1,
    ) -> Result<(), PrivacyShareError> {
        if !self.allows_metrics() {
            return Ok(());
        }
        match self.telemetry() {
            Some(telemetry) => telemetry.ingest_soranet_privacy_share(share),
            None => Ok(()),
        }
    }

    /// Whether the handle currently has an underlying telemetry instance.
    pub fn is_configured(&self) -> bool {
        self.telemetry.is_some()
    }

    /// Access metrics after synchronizing with the telemetry worker.
    #[cfg(feature = "telemetry")]
    #[allow(clippy::future_not_send)]
    pub async fn metrics(&self) -> &iroha_telemetry::metrics::Metrics {
        let telemetry = self
            .telemetry
            .as_ref()
            .expect("telemetry metrics requested without handle");
        telemetry.metrics().await
    }

    /// Map the handle to another gate value while retaining the telemetry instance.
    pub fn map_gate<H>(self, gate: H) -> MaybeTelemetry<H>
    where
        H: TelemetryGate + Clone,
    {
        MaybeTelemetry {
            telemetry: self.telemetry,
            gate,
        }
    }
}

