/// Wrapped response for proof lookups that preserves payload size for egress gating.
#[cfg(feature = "app_api")]
pub struct ProofHttpResponse {
    /// Final HTTP response.
    pub response: axum::response::Response,
    /// Serialized payload length in bytes (0 for 304).
    pub bytes: u64,
}

#[cfg(feature = "app_api")]
impl axum::response::IntoResponse for ProofHttpResponse {
    fn into_response(self) -> axum::response::Response {
        self.response
    }
}

#[cfg(feature = "app_api")]
/// GET /v1/zk/proof/{backend}/{hash} — read proof record by backend and proof hash (hex).
pub async fn handle_get_proof(
    state: Arc<CoreState>,
    limits: ProofApiLimits,
    telemetry: &MaybeTelemetry,
    headers: Option<&axum::http::HeaderMap>,
    axum::extract::Path((backend, hash_hex)): axum::extract::Path<(String, String)>,
) -> Result<ProofHttpResponse> {
    use iroha_data_model::proof::{ProofId, ProofStatus};
    let start = std::time::Instant::now();
    // Parse 32-byte hash from hex (allow 0x prefix); reuse commitment parser
    let proof_hash = match parse_commitment_hex(&hash_hex) {
        Ok(hash) => hash,
        Err(err) => {
            telemetry.with_metrics(|tel| {
                tel.observe_torii_proof_request("v1/zk/proof", "bad_request", 0, start.elapsed())
            });
            return Err(err);
        }
    };
    let id = ProofId {
        backend: backend.clone(),
        proof_hash,
    };
    let world = state.world_view();
    let rec = world.proofs().get(&id).cloned().ok_or_else(|| {
        telemetry.with_metrics(|tel| {
            tel.observe_torii_proof_request("v1/zk/proof", "not_found", 0, start.elapsed())
        });
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        ))
    })?;
    let etag_value = format!("\"{}\"", hex::encode(rec.id.proof_hash));
    let cache_control_value = format!("public, max-age={}", limits.cache_max_age.as_secs().max(1));
    if let Some(hdrs) = headers {
        if let Some(if_none_match) = hdrs
            .get(axum::http::header::IF_NONE_MATCH)
            .and_then(|v| v.to_str().ok())
        {
            let token = if_none_match
                .trim()
                .trim_start_matches("W/")
                .trim_matches('"');
            if token.eq_ignore_ascii_case(etag_value.trim_matches('"')) {
                let mut resp = axum::response::Response::builder()
                    .status(axum::http::StatusCode::NOT_MODIFIED)
                    .body(axum::body::Body::empty())
                    .map_err(|err| {
                        Error::Query(iroha_data_model::ValidationFail::InternalError(
                            err.to_string(),
                        ))
                    })?;
                let headers_mut = resp.headers_mut();
                if let Ok(etag) = axum::http::HeaderValue::from_str(&etag_value) {
                    headers_mut.insert(axum::http::header::ETAG, etag);
                }
                if let Ok(cache_header) = axum::http::HeaderValue::from_str(&cache_control_value) {
                    headers_mut.insert(axum::http::header::CACHE_CONTROL, cache_header);
                }
                telemetry.with_metrics(|tel| {
                    tel.inc_torii_proof_cache_hit("v1/zk/proof");
                    tel.observe_torii_proof_request(
                        "v1/zk/proof",
                        "not_modified",
                        0,
                        start.elapsed(),
                    );
                });
                return Ok(ProofHttpResponse {
                    response: resp,
                    bytes: 0,
                });
            }
        }
    }
    // Build JSON response
    let mut m = norito::json::Map::new();
    m.insert("backend".into(), norito::json::Value::from(backend));
    m.insert(
        "proof_hash".into(),
        norito::json::Value::from(hex::encode(rec.id.proof_hash)),
    );
    m.insert(
        "status".into(),
        norito::json::Value::from(match rec.status {
            ProofStatus::Submitted => "Submitted",
            ProofStatus::Verified => "Verified",
            ProofStatus::Rejected => "Rejected",
        }),
    );
    if let Some(h) = rec.verified_at_height {
        m.insert("verified_at_height".into(), norito::json::Value::from(h));
    }
    if let Some(vkref) = rec.vk_ref {
        let mut v = norito::json::Map::new();
        v.insert("backend".into(), norito::json::Value::from(vkref.backend));
        v.insert("name".into(), norito::json::Value::from(vkref.name));
        m.insert("vk_ref".into(), norito::json::Value::Object(v));
    } else {
        m.insert("vk_ref".into(), norito::json::Value::Null);
    }
    if let Some(commit) = rec.vk_commitment {
        m.insert(
            "vk_commitment".into(),
            norito::json::Value::from(hex::encode(commit)),
        );
    } else {
        m.insert("vk_commitment".into(), norito::json::Value::Null);
    }
    if let Some(bridge) = rec.bridge.as_ref() {
        m.insert("bridge".into(), bridge_record_to_json(bridge));
    }
    let body = norito::json::to_json_pretty(&norito::json::Value::Object(m)).map_err(|e| {
        telemetry.with_metrics(|tel| {
            tel.observe_torii_proof_request("v1/zk/proof", "error", 0, start.elapsed())
        });
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            e.to_string(),
        ))
    })?;
    let bytes = body.len() as u64;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    if let Ok(cache_header) = axum::http::HeaderValue::from_str(&cache_control_value) {
        resp.headers_mut()
            .insert(axum::http::header::CACHE_CONTROL, cache_header);
    }
    if let Ok(etag) = axum::http::HeaderValue::from_str(&etag_value) {
        resp.headers_mut().insert(axum::http::header::ETAG, etag);
    }
    telemetry.with_metrics(|tel| {
        tel.observe_torii_proof_request("v1/zk/proof", "ok", bytes, start.elapsed())
    });
    Ok(ProofHttpResponse {
        response: resp,
        bytes,
    })
}

#[cfg(feature = "app_api")]
#[derive(Debug, crate::json_macros::JsonDeserialize, norito::derive::NoritoDeserialize)]
/// DTO for FindProofRecordById as a signed core query
pub struct ProofFindByIdQueryDto {
    /// Authority account id to sign the query
    pub authority: iroha_data_model::account::AccountId,
    /// Private key used to sign
    pub private_key: iroha_data_model::prelude::ExposedPrivateKey,
    /// Proof backend (e.g., "halo2/ipa")
    pub backend: String,
    /// Proof hash (64-hex)
    pub hash_hex: String,
}

#[cfg(feature = "app_api")]
/// Build a SignedQuery for FindProofRecordById from DTO
pub fn signed_find_proof_by_id(
    dto: &ProofFindByIdQueryDto,
) -> Result<iroha_data_model::query::SignedQuery> {
    use iroha_data_model::query::{
        QueryRequest, prelude::SingularQueryBox, proof::prelude::FindProofRecordById,
    };
    // Parse hash
    let bytes = hex::decode(dto.hash_hex.trim_start_matches("0x")).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(e.to_string()),
        ))
    })?;
    if bytes.len() != 32 {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "expected 32-byte hash".into(),
            ),
        )));
    }
    let mut arr = [0u8; 32];
    arr.copy_from_slice(&bytes);
    let id = iroha_data_model::proof::ProofId {
        backend: dto.backend.clone(),
        proof_hash: arr,
    };
    let singular = SingularQueryBox::FindProofRecordById(FindProofRecordById { id });
    let req = QueryRequest::Singular(singular).with_authority(dto.authority.clone().into());
    // Build a temporary KeyPair from the private key. Public key derived within KeyPair::from
    let key_pair = iroha_crypto::KeyPair::from(dto.private_key.0.clone());
    req.try_sign(&key_pair).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "failed to sign proof query: {err}"
            )),
        ))
    })
}

/// POST /v1/zk/verify — minimal demo decode endpoint that accepts either Norito
/// (`application/x-norito`) or JSON and returns `{ "ok": true|false }`.
///
/// This is a convenience, non-consensus-critical handler intended for quick
/// end-to-end demos. It does not perform cryptographic verification or any
/// VK/circuit/schema binding checks; it only checks that the body decodes under
/// the declared content type.
pub async fn handle_v1_zk_verify(
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> Result<impl IntoResponse> {
    let ct = headers
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    let ok = if ct.contains(super::utils::NORITO_MIME_TYPE) {
        // For Norito, treat non-empty body as accepted. We avoid binding to a
        // specific envelope type in this app-facing convenience endpoint.
        !body.is_empty()
    } else if ct.contains("application/json") {
        norito::json::from_slice::<norito::json::Value>(&body).is_ok()
    } else {
        // Unknown content type; try JSON as a last resort.
        norito::json::from_slice::<norito::json::Value>(&body).is_ok()
    };
    let payload = json_object(vec![json_entry("ok", ok)]);
    let body = json::to_json_pretty(&payload).map_err(norito_internal_error)?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

