/// GET /v1/sumeragi/consensus-keys — Registered consensus/committee keys (sorted by activation height desc)
#[iroha_futures::telemetry_future]
pub async fn handle_v1_sumeragi_consensus_keys(
    app: &SharedAppState,
    accept: Option<axum::http::HeaderValue>,
) -> Result<Response> {
    let world = app.state.world_view();
    let mut records: Vec<ConsensusKeyRecord> = world
        .consensus_keys()
        .iter()
        .map(|(_, rec)| rec.clone())
        .collect();
    records.sort_by(|a, b| {
        b.activation_height
            .cmp(&a.activation_height)
            .then_with(|| a.id.cmp(&b.id))
    });

    let format = match crate::utils::negotiate_response_format(accept.as_ref()) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };

    if matches!(format, crate::utils::ResponseFormat::Norito) {
        return Ok(crate::NoritoBody(records).into_response());
    }

    let body = json::to_json_pretty(&records).map_err(norito_internal_error)?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

/// Maximum number of commit certificates returned in a single response.
const COMMIT_CERT_PAGE_CAP: u64 = 128;

/// GET /v1/sumeragi/commit-certificates — Bounded history of commit certificates (newest first)
#[iroha_futures::telemetry_future]
pub async fn handle_v1_sumeragi_commit_qcs(
    crate::NoritoQuery(window): crate::NoritoQuery<HistoryWindowQuery>,
    accept: Option<axum::http::HeaderValue>,
) -> Result<Response> {
    let certificates = sumeragi::status::commit_qc_history();
    let certificates = clamp_history_window(
        certificates,
        window.from,
        window.limit,
        COMMIT_CERT_PAGE_CAP,
        |cert| cert.height,
    );
    let format = match crate::utils::negotiate_response_format(accept.as_ref()) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };

    if matches!(format, crate::utils::ResponseFormat::Norito) {
        return Ok(crate::NoritoBody(certificates).into_response());
    }

    let body = json::to_json_pretty(&certificates).map_err(norito_internal_error)?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

/// Run synchronous query work while retaining admission through physical completion.
pub(crate) async fn run_admitted_blocking<T, F>(
    admission: crate::QueryAdmissionPermit,
    worker_failure: &'static str,
    work: F,
) -> Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T> + Send + 'static,
{
    tokio::task::spawn_blocking(move || {
        // Keep every owned permit in the physical worker. Dropping or aborting
        // the HTTP future detaches `spawn_blocking`; it must not free capacity
        // while CPU or file work is still running.
        let _admission = admission;
        work()
    })
    .await
    .map_err(|_| sccp_internal_error(worker_failure))?
}

#[cfg(feature = "app_api")]
async fn run_sccp_submit_blocking<T, F>(worker_failure: &'static str, work: F) -> Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T> + Send + 'static,
{
    tokio::task::spawn_blocking(work)
        .await
        .map_err(|_| sccp_internal_error(worker_failure))?
}

/// GET /v1/bridge/finality/{height} — Self-contained finality proof for a block.
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_v1_bridge_finality(
    state: Arc<CoreState>,
    height: u64,
    format: crate::utils::ResponseFormat,
    admission: crate::QueryAdmissionPermit,
) -> Result<Response> {
    run_admitted_blocking(
        admission,
        "bridge finality verification worker failed",
        move || {
            let proof = iroha_core::bridge::build_finality_proof(state.as_ref(), height)
                .map_err(map_bridge_finality_error)?;

            if matches!(format, crate::utils::ResponseFormat::Norito) {
                return Ok(crate::NoritoBody(proof).into_response());
            }

            let body = json::to_json_pretty(&proof).map_err(norito_internal_error)?;
            let mut resp = axum::response::Response::new(axum::body::Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                axum::http::HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        },
    )
    .await
}

/// GET /v1/bridge/finality/attestation/{height} — Challenge-bound node-signed
/// finality proof for the exact durable state tip plus its committed genesis.
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_v1_bridge_finality_attestation(
    state: Arc<CoreState>,
    status: iroha_data_model::block::consensus_v2::SumeragiV2Status,
    height: u64,
    challenge: [u8; 32],
    signer: KeyPair,
    format: crate::utils::ResponseFormat,
    admission: crate::QueryAdmissionPermit,
) -> Result<Response> {
    run_admitted_blocking(
        admission,
        "bridge finality attestation worker failed",
        move || {
            let view = state.view();
            let attestation = iroha_core::bridge::build_finality_attestation(
                &view, status, height, challenge, &signer,
            )
            .map_err(map_bridge_finality_attestation_error)?;

            if matches!(format, crate::utils::ResponseFormat::Norito) {
                return Ok(crate::NoritoBody(attestation).into_response());
            }

            let body = json::to_json_pretty(&attestation).map_err(norito_internal_error)?;
            let mut resp = axum::response::Response::new(axum::body::Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                axum::http::HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        },
    )
    .await
}

/// GET /v1/bridge/finality/bundle/{height} — Compact commitment + exact v2 proof for a block.
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_v1_bridge_finality_bundle(
    state: Arc<CoreState>,
    height: u64,
    format: crate::utils::ResponseFormat,
    admission: crate::QueryAdmissionPermit,
) -> Result<Response> {
    run_admitted_blocking(
        admission,
        "bridge finality bundle worker failed",
        move || {
            let bundle = iroha_core::bridge::build_finality_bundle(state.as_ref(), height)
                .map_err(map_bridge_finality_error)?;

            if matches!(format, crate::utils::ResponseFormat::Norito) {
                return Ok(crate::NoritoBody(bundle).into_response());
            }

            let body = json::to_json_pretty(&bundle).map_err(norito_internal_error)?;
            let mut resp = axum::response::Response::new(axum::body::Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                axum::http::HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        },
    )
    .await
}

fn map_bridge_finality_error(err: iroha_core::bridge::BridgeFinalityError) -> Error {
    match err {
        iroha_core::bridge::BridgeFinalityError::InvalidHeight(_)
        | iroha_core::bridge::BridgeFinalityError::FinalityArtifactNotFound(_) => {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::NotFound,
            ))
        }
        iroha_core::bridge::BridgeFinalityError::FinalityArtifactRead { .. }
        | iroha_core::bridge::BridgeFinalityError::FinalityArtifactMismatch { .. } => Error::Query(
            iroha_data_model::ValidationFail::InternalError(format!("{err:?}")),
        ),
    }
}

fn map_bridge_finality_attestation_error(
    err: iroha_core::bridge::BridgeFinalityAttestationBuildError,
) -> Error {
    use iroha_core::bridge::{
        BridgeFinalityAttestationBuildError as BuildError, BridgeFinalityError,
    };

    let not_found = matches!(
        &err,
        BuildError::EmptyState
            | BuildError::HeightIsNotDurableTip { .. }
            | BuildError::FinalityProof(
                BridgeFinalityError::InvalidHeight(_)
                    | BridgeFinalityError::FinalityArtifactNotFound(_)
            )
            | BuildError::GenesisFinalityProof(
                BridgeFinalityError::InvalidHeight(_)
                    | BridgeFinalityError::FinalityArtifactNotFound(_)
            )
    );
    if not_found {
        return Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        ));
    }
    Error::Query(iroha_data_model::ValidationFail::InternalError(
        err.to_string(),
    ))
}

fn sccp_bad_request(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(message.into()),
    ))
}

fn sccp_not_found() -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::NotFound,
    ))
}

fn sccp_internal_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::InternalError(
        message.into(),
    ))
}

fn sccp_bundle_response<T>(value: &T, accept: Option<&axum::http::HeaderValue>) -> Result<Response>
where
    T: Clone + Send + norito::core::NoritoSerialize + norito::json::JsonSerialize + 'static,
{
    let format = match crate::utils::negotiate_response_format(accept) {
        Ok(format) => format,
        Err(response) => return Ok(response),
    };
    sccp_bundle_response_with_format(value, format)
}

fn sccp_bundle_response_with_format<T>(
    value: &T,
    format: crate::utils::ResponseFormat,
) -> Result<Response>
where
    T: Clone + Send + norito::core::NoritoSerialize + norito::json::JsonSerialize + 'static,
{
    if matches!(format, crate::utils::ResponseFormat::Norito) {
        let mut response = crate::NoritoBody(value.clone()).into_response();
        response
            .headers_mut()
            .insert(header::VARY, axum::http::HeaderValue::from_static("Accept"));
        return Ok(response);
    }

    let body = json::to_json_pretty(value).map_err(norito_internal_error)?;
    let mut response = Response::new(Body::from(body));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    response
        .headers_mut()
        .insert(header::VARY, axum::http::HeaderValue::from_static("Accept"));
    Ok(response)
}

fn parse_sccp_message_id_hex(value: &str) -> Result<[u8; 32]> {
    if value.len() != 64 {
        return Err(sccp_bad_request(
            "message_id must be exactly 64 lowercase hexadecimal characters",
        ));
    }
    if !value
        .as_bytes()
        .iter()
        .copied()
        .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
    {
        return Err(sccp_bad_request(
            "message_id must be exactly 64 lowercase hexadecimal characters",
        ));
    }
    let mut out = [0u8; 32];
    hex::decode_to_slice(value, &mut out)
        .map_err(|err| sccp_bad_request(format!("invalid message_id: {err}")))?;
    if out == [0; 32] {
        return Err(sccp_bad_request("message_id must be nonzero"));
    }
    Ok(out)
}

// The first-release SCCP API is state-derived and query-free. Keep the retired
// pre-release destination-query implementation out of every build while the
// surrounding non-SCCP routing file is mechanically split into smaller modules.
/// Reject query parameters on a query-free SCCP endpoint.
pub fn reject_sccp_query(raw_query: Option<&str>) -> Result<()> {
    if raw_query.is_some_and(|query| !query.is_empty()) {
        return Err(sccp_bad_request(
            "this SCCP endpoint does not accept query parameters; route and proof identity are derived from consensus state",
        ));
    }
    Ok(())
}

/// Parse the canonical compound cursor accepted by recent-message discovery.
pub fn parse_sccp_recent_query(raw_query: Option<&str>) -> Result<SccpRecentWindowQuery> {
    const RECENT_SCCP_MESSAGES_CAP: u64 = 50;
    const MAX_CANONICAL_QUERY_BYTES: usize = 64;

    let Some(query) = raw_query.filter(|query| !query.is_empty()) else {
        return Ok(SccpRecentWindowQuery::default());
    };
    if query.len() > MAX_CANONICAL_QUERY_BYTES {
        return Err(sccp_bad_request(
            "recent SCCP query exceeds the canonical 64-byte bound",
        ));
    }
    let mut seen = BTreeSet::new();
    let mut window = SccpRecentWindowQuery::default();
    for segment in query.split('&') {
        if segment.is_empty() {
            return Err(sccp_bad_request(
                "recent SCCP query must not contain empty segments",
            ));
        }
        let Some((key, value)) = segment.split_once('=') else {
            return Err(sccp_bad_request(
                "recent SCCP query fields must use canonical `key=value` syntax",
            ));
        };
        if !matches!(key, "from" | "after_index" | "limit") {
            return Err(sccp_bad_request(format!(
                "recent SCCP query field `{key}` is not supported; only `from`, `after_index`, and `limit` are allowed"
            )));
        }
        if !seen.insert(key) {
            return Err(sccp_bad_request(format!(
                "recent SCCP query field `{key}` must appear at most once"
            )));
        }
        let parsed = value.parse::<u64>().ok();
        let canonical_value = parsed.is_some_and(|parsed| parsed.to_string() == value);
        if value.is_empty()
            || !value.bytes().all(|byte| byte.is_ascii_digit())
            || (value.len() > 1 && value.starts_with('0'))
            || !canonical_value
        {
            return Err(sccp_bad_request(format!(
                "recent SCCP query field `{key}` must be one canonical unsigned decimal integer"
            )));
        }
        let parsed = parsed.ok_or_else(|| {
            sccp_bad_request(format!(
                "recent SCCP query field `{key}` must be one canonical unsigned decimal integer"
            ))
        })?;
        match key {
            "from" if parsed == 0 => {
                return Err(sccp_bad_request(
                    "recent SCCP query field `from` must be a positive block height",
                ));
            }
            "limit" if !(1..=RECENT_SCCP_MESSAGES_CAP).contains(&parsed) => {
                return Err(sccp_bad_request(format!(
                    "recent SCCP query field `limit` must be between 1 and {RECENT_SCCP_MESSAGES_CAP}"
                )));
            }
            "after_index"
                if parsed
                    >= u64::from(
                        iroha_data_model::bridge::SCCP_OUTBOUND_MESSAGES_MAX_PER_BLOCK_V1,
                    ) =>
            {
                return Err(sccp_bad_request(format!(
                    "recent SCCP query field `after_index` must be between 0 and {}",
                    iroha_data_model::bridge::SCCP_OUTBOUND_MESSAGES_MAX_PER_BLOCK_V1 - 1
                )));
            }
            "from" => window.from = Some(parsed),
            "after_index" => {
                window.after_index =
                    Some(u32::try_from(parsed).expect("bounded SCCP cursor index fits u32"));
            }
            "limit" => window.limit = Some(parsed),
            _ => {
                return Err(sccp_bad_request(
                    "recent SCCP query contains an unsupported field",
                ));
            }
        }
    }
    if window.after_index.is_some() && window.from.is_none() {
        return Err(sccp_bad_request(
            "recent SCCP query field `after_index` requires the paired `from` height",
        ));
    }
    Ok(window)
}

/// Validate the canonical recent-message query without retaining its values.
pub fn validate_sccp_recent_query(raw_query: Option<&str>) -> Result<()> {
    parse_sccp_recent_query(raw_query).map(|_| ())
}

