/// Execute a signed query while honoring pagination/cursor overrides and telemetry policies.
#[iroha_futures::telemetry_future]
#[cfg_attr(not(feature = "telemetry"), allow(unused_variables))]
pub async fn handle_queries_with_opts(
    live_query_store: LiveQueryStoreHandle,
    state: Arc<CoreState>,
    query: SignedQuery,
    tel: MaybeTelemetry,
    crate::NoritoQuery(opts): crate::NoritoQuery<QueryOptions>,
    format: crate::utils::ResponseFormat,
) -> Result<Response> {
    #[cfg(feature = "telemetry")]
    let verify_started = std::time::Instant::now();
    let query = match verify_signed_query_request(query) {
        Ok(query) => {
            #[cfg(feature = "telemetry")]
            observe_route_stage_latency(&tel, "query", "verify", "ok", verify_started.elapsed());
            query
        }
        Err(err) => {
            #[cfg(feature = "telemetry")]
            observe_route_stage_latency(&tel, "query", "verify", "error", verify_started.elapsed());
            return Err(err);
        }
    };

    #[cfg(feature = "telemetry")]
    let handle_started = std::time::Instant::now();
    let resp =
        match execute_verified_query_with_opts(live_query_store, state, query, tel.clone(), opts)
            .await
        {
            Ok(resp) => {
                #[cfg(feature = "telemetry")]
                observe_route_stage_latency(
                    &tel,
                    "query",
                    "handle",
                    "ok",
                    handle_started.elapsed(),
                );
                resp
            }
            Err(err) => {
                #[cfg(feature = "telemetry")]
                observe_route_stage_latency(
                    &tel,
                    "query",
                    "handle",
                    "error",
                    handle_started.elapsed(),
                );
                return Err(err);
            }
        };

    #[cfg(feature = "telemetry")]
    let response_started = std::time::Instant::now();
    let response = crate::utils::respond_with_format(resp, format);
    #[cfg(feature = "telemetry")]
    observe_route_stage_latency(
        &tel,
        "query",
        "encode_or_response",
        "ok",
        response_started.elapsed(),
    );
    Ok(response)
}

/// Simple liveness probe. Returns a constant string when Torii is up.
pub async fn handle_health() -> &'static str {
    "Healthy"
}

async fn fetch_network_time_status() -> iroha_core::time::NetworkTimeStatus {
    match task::spawn_blocking(iroha_core::time::now).await {
        Ok(status) => status,
        Err(join_err) => {
            iroha_logger::warn!(
                ?join_err,
                "Failed to fetch network time snapshot; using local clock as fallback"
            );
            iroha_core::time::NetworkTimeStatus {
                now: std::time::SystemTime::now(),
                offset_ms: 0,
                confidence_ms: 0,
                sample_count: 0,
                peer_count: 0,
                fallback: true,
                health: iroha_core::time::NtsHealth {
                    min_samples_ok: false,
                    offset_ok: true,
                    confidence_ok: true,
                    healthy: false,
                },
            }
        }
    }
}

/// Network Time Service: return current network time snapshot.
pub async fn handle_time_now() -> impl IntoResponse {
    let s = fetch_network_time_status().await;
    let now_ms: u64 = s
        .now
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .try_into()
        .unwrap_or(0);
    let mut obj = norito::json::Map::new();
    obj.insert("now".into(), norito::json::Value::from(now_ms));
    obj.insert("offset_ms".into(), norito::json::Value::from(s.offset_ms));
    obj.insert(
        "confidence_ms".into(),
        norito::json::Value::from(s.confidence_ms),
    );
    obj.insert(
        "sample_count".into(),
        norito::json::Value::from(s.sample_count as u64),
    );
    obj.insert(
        "peer_count".into(),
        norito::json::Value::from(s.peer_count as u64),
    );
    obj.insert("fallback".into(), norito::json::Value::from(s.fallback));
    let mut health = norito::json::Map::new();
    health.insert(
        "healthy".into(),
        norito::json::Value::from(s.health.healthy),
    );
    health.insert(
        "min_samples_ok".into(),
        norito::json::Value::from(s.health.min_samples_ok),
    );
    health.insert(
        "offset_ok".into(),
        norito::json::Value::from(s.health.offset_ok),
    );
    health.insert(
        "confidence_ok".into(),
        norito::json::Value::from(s.health.confidence_ok),
    );
    obj.insert("health".into(), norito::json::Value::Object(health));
    let body = norito::json::to_json_pretty(&obj).unwrap_or_else(|_| "{}".into());
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    resp
}

/// Network Time Service diagnostics.
pub async fn handle_time_status() -> impl IntoResponse {
    let mut obj = norito::json::Map::new();
    let status = fetch_network_time_status().await;
    let snapshot = tokio::task::spawn_blocking(iroha_core::time::debug_snapshot)
        .await
        .unwrap_or_default();
    obj.insert(
        "peers".into(),
        norito::json::Value::from(status.peer_count as u64),
    );
    obj.insert(
        "samples_used".into(),
        norito::json::Value::from(status.sample_count as u64),
    );
    obj.insert(
        "offset_ms".into(),
        norito::json::Value::from(status.offset_ms),
    );
    obj.insert(
        "confidence_ms".into(),
        norito::json::Value::from(status.confidence_ms),
    );
    obj.insert(
        "fallback".into(),
        norito::json::Value::from(status.fallback),
    );
    let mut health = norito::json::Map::new();
    health.insert(
        "healthy".into(),
        norito::json::Value::from(status.health.healthy),
    );
    health.insert(
        "min_samples_ok".into(),
        norito::json::Value::from(status.health.min_samples_ok),
    );
    health.insert(
        "offset_ok".into(),
        norito::json::Value::from(status.health.offset_ok),
    );
    health.insert(
        "confidence_ok".into(),
        norito::json::Value::from(status.health.confidence_ok),
    );
    obj.insert("health".into(), norito::json::Value::Object(health));
    let samples = snapshot
        .into_iter()
        .map(|(peer, offset_ms, rtt_ms, count)| {
            let mut o = norito::json::Map::new();
            o.insert("peer".into(), norito::json::Value::from(peer));
            o.insert(
                "last_offset_ms".into(),
                norito::json::Value::from(offset_ms),
            );
            o.insert("last_rtt_ms".into(), norito::json::Value::from(rtt_ms));
            o.insert("count".into(), norito::json::Value::from(count as u64));
            norito::json::Value::Object(o)
        })
        .collect::<Vec<_>>();
    obj.insert("samples".into(), norito::json::Value::Array(samples));
    // RTT histogram snapshot
    let bounds = iroha_core::time::rtt_bucket_bounds_ms();
    let counts = iroha_core::time::rtt_bucket_counts();
    let mut buckets = Vec::new();
    for (le, cnt) in bounds.iter().zip(counts.iter()) {
        let mut b = norito::json::Map::new();
        b.insert("le".into(), norito::json::Value::from(*le));
        b.insert("count".into(), norito::json::Value::from(*cnt));
        buckets.push(norito::json::Value::Object(b));
    }
    let mut rtt = norito::json::Map::new();
    rtt.insert("buckets".into(), norito::json::Value::Array(buckets));
    rtt.insert(
        "sum_ms".into(),
        norito::json::Value::from(iroha_core::time::rtt_ms_sum()),
    );
    rtt.insert(
        "count".into(),
        norito::json::Value::from(iroha_core::time::rtt_ms_count()),
    );
    obj.insert("rtt".into(), norito::json::Value::Object(rtt));
    obj.insert("note".into(), norito::json::Value::from("NTS running"));
    let body = norito::json::to_json_pretty(&obj).unwrap_or_else(|_| "{}".into());
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    resp
}

#[cfg(test)]
mod nts_tests {
    use http_body_util::BodyExt as _;

    use super::*;

    #[tokio::test]
    async fn nts_now_returns_expected_keys() {
        let resp = handle_time_now().await.into_response();
        assert_eq!(resp.status(), axum::http::StatusCode::OK);
        let (parts, body) = resp.into_parts();
        let content_type = parts
            .headers
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|v| v.to_str().ok())
            .unwrap_or("");
        assert!(content_type.contains("application/json"));
        let bytes = body.collect().await.unwrap().to_bytes();
        let val: norito::json::Value = norito::json::from_slice(&bytes).expect("valid json body");
        assert!(val.get("now").is_some(), "missing now");
        assert!(val.get("offset_ms").is_some(), "missing offset_ms");
        assert!(val.get("confidence_ms").is_some(), "missing confidence_ms");
        assert!(val.get("sample_count").is_some(), "missing sample_count");
        assert!(val.get("peer_count").is_some(), "missing peer_count");
        assert!(val.get("fallback").is_some(), "missing fallback");
        assert!(val.get("health").is_some(), "missing health");
    }

    #[tokio::test]
    async fn nts_status_returns_expected_keys() {
        let resp = handle_time_status().await.into_response();
        assert_eq!(resp.status(), axum::http::StatusCode::OK);
        let (parts, body) = resp.into_parts();
        let content_type = parts
            .headers
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|v| v.to_str().ok())
            .unwrap_or("");
        assert!(content_type.contains("application/json"));
        let bytes = body.collect().await.unwrap().to_bytes();
        let val: norito::json::Value = norito::json::from_slice(&bytes).expect("valid json body");
        assert!(val.get("peers").is_some(), "missing peers");
        assert!(val.get("samples_used").is_some(), "missing samples_used");
        assert!(val.get("offset_ms").is_some(), "missing offset_ms");
        assert!(val.get("confidence_ms").is_some(), "missing confidence_ms");
        assert!(val.get("fallback").is_some(), "missing fallback");
        assert!(val.get("health").is_some(), "missing health");
        assert!(val.get("samples").is_some(), "missing samples");
        assert!(val.get("note").is_some(), "missing note");
    }
}

fn contract_manifest_response_body(
    manifest: &manifest::ContractManifest,
) -> core::result::Result<String, norito::json::Error> {
    let response = ContractCodeRecordDto {
        code_hash: manifest
            .code_hash
            .as_ref()
            .map(|hash| hex::encode(hash.as_ref())),
        abi_hash: manifest
            .abi_hash
            .as_ref()
            .map(|hash| hex::encode(hash.as_ref())),
        manifest: manifest.clone(),
        code_bytes: None,
    };
    norito::json::to_json_pretty(&response)
}

/// Fetch on-chain contract manifest by code_hash.
#[iroha_futures::telemetry_future]
pub async fn handle_get_contract_code(
    state: Arc<CoreState>,
    axum::extract::Path(code_hash): axum::extract::Path<String>,
) -> Result<impl IntoResponse> {
    let parse_hash = |s: &str| -> core::result::Result<iroha_crypto::Hash, String> {
        if s.len() != 64
            || !s
                .as_bytes()
                .iter()
                .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
        {
            return Err("code hash must be exactly 32 lowercase hexadecimal bytes".to_owned());
        }
        let mut arr = [0_u8; 32];
        hex::decode_to_slice(s, &mut arr)
            .map_err(|e| format!("failed to decode exact code hash `{s}`: {e}"))?;
        Ok(iroha_crypto::Hash::prehashed(arr))
    };
    let h = parse_hash(&code_hash).map_err(|e| {
        // Treat bad path parameter as a query conversion error (HTTP 400)
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(e),
        ))
    })?;
    let world = state.world_view();
    let manifest = world.contract_manifests().get(&h).cloned().ok_or_else(|| {
        // Map absence to a query NotFound (HTTP 404)
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        ))
    })?;
    let body = contract_manifest_response_body(&manifest).map_err(|error| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "failed to serialize the complete contract manifest: {error}"
        )))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

#[cfg(test)]
mod contract_manifest_response_tests {
    use iroha_data_model::smart_contract::entrypoint::{
        EntrypointArgumentFieldV1, EntrypointArgumentSchemaV1, EntrypointValueKindV1,
        EntrypointValueTypeNodeV1, EntrypointValueTypeV1,
    };
    use iroha_data_model::smart_contract::manifest::{
        AccessSetHints, ContractErrorCodeDescriptor, ContractManifest, DynamicAccessHint,
        EntryPointKind, EntrypointDescriptor, EntrypointParamDescriptor, KotobaTranslation,
        KotobaTranslationEntry, StateDescriptor,
    };

    use super::*;

    #[test]
    fn response_serializes_the_complete_canonical_manifest() {
        let expected_manifest = ContractManifest {
            seiyaku_name: Some("Treasury".to_owned()),
            code_hash: Some(Hash::new(b"complete-code")),
            abi_hash: Some(Hash::new(b"complete-abi")),
            compiler_fingerprint: Some("kotodama-rust-v1".to_owned()),
            features_bitmap: Some(0),
            access_set_hints: Some(AccessSetHints {
                read_keys: vec!["state:Balances".to_owned()],
                write_keys: vec!["state:Balances".to_owned()],
                dynamic_reads: vec![DynamicAccessHint {
                    base_key: "state:Balances".to_owned(),
                    key_type: "AccountId".to_owned(),
                    bound_kind: "List".to_owned(),
                    max_keys: 64,
                }],
                dynamic_writes: Vec::new(),
            }),
            entrypoints: Some(vec![EntrypointDescriptor {
                name: "transfer".to_owned(),
                kind: EntryPointKind::Kotoage,
                params: vec![EntrypointParamDescriptor {
                    name: "amount".to_owned(),
                    type_name: "quantity".to_owned(),
                }],
                argument_schema: Some(EntrypointArgumentSchemaV1 {
                    fields: vec![EntrypointArgumentFieldV1 {
                        name: "amount".to_owned(),
                        ty: EntrypointValueTypeV1 {
                            nodes: vec![EntrypointValueTypeNodeV1::Leaf(
                                EntrypointValueKindV1::Quantity,
                            )],
                        },
                    }],
                }),
                return_type: Some("int".to_owned()),
                return_schema: Some(EntrypointValueTypeV1 {
                    nodes: vec![EntrypointValueTypeNodeV1::Leaf(EntrypointValueKindV1::Int)],
                }),
                permission: Some("TreasuryTransfer".to_owned()),
                read_keys: vec!["state:Balances".to_owned()],
                write_keys: vec!["state:Balances".to_owned()],
                access_hints_complete: Some(true),
                access_hints_skipped: Vec::new(),
                triggers: Vec::new(),
            }]),
            states: Some(vec![StateDescriptor {
                name: "Balances".to_owned(),
                type_name: "StateMap<AccountId,quantity>".to_owned(),
            }]),
            error_codes: Some(vec![ContractErrorCodeDescriptor {
                namespace: "TreasuryError".to_owned(),
                name: "InsufficientFunds".to_owned(),
                code: 7,
            }]),
            kotoba: Some(vec![KotobaTranslationEntry {
                msg_id: "insufficient_funds".to_owned(),
                translations: vec![KotobaTranslation {
                    lang: "ja".to_owned(),
                    text: "残高不足".to_owned(),
                }],
            }]),
            provenance: None,
        };

        let body = contract_manifest_response_body(&expected_manifest)
            .expect("serialize manifest response");
        let value = norito::json::parse_value(&body).expect("parse manifest response");
        assert_eq!(
            value.get("code_hash").and_then(Value::as_str),
            expected_manifest
                .code_hash
                .as_ref()
                .map(|hash| hex::encode(hash.as_ref()))
                .as_deref()
        );
        assert_eq!(
            value.get("abi_hash").and_then(Value::as_str),
            expected_manifest
                .abi_hash
                .as_ref()
                .map(|hash| hex::encode(hash.as_ref()))
                .as_deref()
        );
        assert!(value.get("code_bytes").is_none());
        let manifest_value = value.get("manifest").cloned().expect("manifest value");
        let decoded: ContractManifest =
            norito::json::from_value(manifest_value).expect("decode complete manifest");
        assert_eq!(decoded, expected_manifest);
        let manifest = value
            .get("manifest")
            .and_then(norito::json::Value::as_object)
            .expect("manifest object");

        assert_eq!(
            manifest.get("seiyaku_name").and_then(Value::as_str),
            Some("Treasury")
        );
        assert!(manifest.get("contract_name").is_none());
        for field in [
            "code_hash",
            "abi_hash",
            "compiler_fingerprint",
            "features_bitmap",
            "access_set_hints",
            "entrypoints",
            "states",
            "error_codes",
            "kotoba",
            "provenance",
        ] {
            assert!(manifest.contains_key(field), "missing `{field}`");
        }
        let entrypoint = manifest
            .get("entrypoints")
            .and_then(Value::as_array)
            .and_then(|entrypoints| entrypoints.first())
            .and_then(Value::as_object)
            .expect("entrypoint descriptor");
        for field in [
            "name",
            "kind",
            "params",
            "argument_schema",
            "return_type",
            "return_schema",
            "permission",
            "read_keys",
            "write_keys",
            "access_hints_complete",
            "access_hints_skipped",
            "triggers",
        ] {
            assert!(
                entrypoint.contains_key(field),
                "missing entrypoint `{field}`"
            );
        }
    }
}

