#[cfg(feature = "app_api")]
fn prepare_bridge_message_submit(
    chain_id: Arc<ChainId>,
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    req: BridgeMessageSubmitDto,
) -> Result<PreparedBridgeMessageSubmit> {
    use base64::Engine as _;
    use iroha_data_model::prelude as dm;
    use iroha_primitives::const_vec::ConstVec;

    let BridgeMessageSubmitDto {
        authority,
        fee_payment,
        signature_b64,
        transaction_payload_b64,
        native_proof_b64,
        creation_time_ms,
    } = req;
    validate_app_api_fee_payment(&fee_payment, false)?;
    validate_sccp_taira_chain_id(chain_id.as_ref())?;
    let direct_submit = validate_sccp_submit_signing_state(
        &authority,
        signature_b64.as_deref(),
        transaction_payload_b64.as_deref(),
        creation_time_ms,
    )?;

    let (native_proof, native_proof_bytes) = decode_sccp_native_proof_b64(&native_proof_b64)?;
    validate_sccp_taira_transfer_recipient(&native_proof.payload)?;
    let source_height = native_proof.source.source_finality.height;
    let lane = native_proof.source.lane;
    let native_backend = native_proof.source.proof.backend();
    if !lane.is_well_formed()
        || !lane.source.is_external()
        || lane.target != iroha_data_model::bridge::SccpNetworkV1::SoraTaira
    {
        return Err(conversion_error(
            "native SCCP proof must select an exact external-source to Taira-target lane"
                .to_owned(),
        ));
    }
    let payload = &native_proof.payload;
    let target_domain = sccp_message_target_domain(payload);
    let source_domain = iroha_sccp::sccp_message_source_domain(payload);
    if target_domain != lane.target.domain_id() || source_domain != lane.source.domain_id() {
        return Err(conversion_error(format!(
            "native SCCP payload domains {source_domain}->{target_domain} do not match exact lane {}->{}",
            lane.source.profile_key(),
            lane.target.profile_key()
        )));
    }
    if target_domain != iroha_sccp::SCCP_DOMAIN_SORA {
        return Err(conversion_error(format!(
            "native SCCP proof targets domain {target_domain}, but this endpoint only accepts inbound messages for SORA"
        )));
    }
    let message_id = native_proof.source.message_id;
    if message_id == [0; 32] {
        return Err(conversion_error(
            "native SCCP proof message_id must be nonzero".to_owned(),
        ));
    }

    let payload_kind = sccp_message_payload_kind_key(payload).to_owned();
    let counterparty_domain = lane.source.domain_id();
    let counterparty_chain = lane.source.profile_key().to_owned();
    let message_id_hex = hex::encode(message_id);
    let route_configuration_hash = {
        let registry = state.sccp_registry_snapshot();
        governed_sccp_native_route_configuration_hash(registry.as_ref(), &native_proof)?
    };
    let bridge_proof = iroha_data_model::bridge::BridgeProof {
        range: iroha_data_model::bridge::BridgeProofRange {
            start_height: source_height,
            end_height: source_height,
        },
        payload: iroha_data_model::bridge::BridgeProofPayload::NativeProtocol(
            iroha_data_model::bridge::BridgeNativeProtocolProofV1 {
                backend: native_backend,
                route_configuration_hash,
                encoded_envelope: native_proof_bytes,
            },
        ),
    };
    let range_start_height = bridge_proof.range.start_height;
    let range_end_height = bridge_proof.range.end_height;
    let route_configuration_hash_hex = hex::encode(route_configuration_hash);
    let backend = bridge_proof.backend_label();

    let prepared = if direct_submit {
        let creation_time_ms = creation_time_ms.expect("validated direct SCCP creation time");
        let tx = build_exact_sccp_signed_transaction(
            state.as_ref(),
            chain_id.as_ref(),
            &authority,
            creation_time_ms,
            &bridge_proof,
            transaction_payload_b64
                .as_deref()
                .expect("validated direct SCCP transaction payload"),
            signature_b64
                .as_deref()
                .expect("validated direct SCCP signature"),
            "bridge message",
        )?;
        if !fee_payment.has_same_payer_and_gas_bound(&tx.payload().fee_payment) {
            return Err(conversion_error(
                "prepared SCCP payload changed the requested payer, sponsor revision, or gas bound"
                    .to_owned(),
            ));
        }
        let routing_plan = scaffold_transaction_routing_plan(
            chain_id.as_ref(),
            queue.as_ref(),
            state.as_ref(),
            &authority,
            creation_time_ms,
            tx.payload().fee_payment.clone(),
            tx.metadata().clone(),
            tx.instructions().clone(),
            "/v1/bridge/messages",
        )?;
        let tx_hash_hex = hex::encode(tx.hash().as_ref());
        PreparedBridgeMessageSubmit::Direct {
            transaction: tx,
            routing_plan,
            response: BridgeSubmitResponseDto {
                submitted: true,
                payload_kind,
                message_id_hex,
                backend,
                counterparty_domain,
                counterparty_chain: counterparty_chain.to_owned(),
                route_configuration_hash_hex,
                range_start_height,
                range_end_height,
                creation_time_ms,
                tx_hash_hex: Some(tx_hash_hex),
                transaction_payload_b64: None,
                signing_message_b64: None,
            },
        }
    } else {
        let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
        let instruction: dm::InstructionBox =
            dm::SubmitBridgeProof::new(bridge_proof.clone()).into();
        let mut builder =
            dm::TransactionBuilder::new((*chain_id).clone(), authority.clone().into(), fee_payment);
        builder.set_creation_time(Duration::from_millis(creation_time_ms));
        let builder = builder.with_executable(dm::Executable::Instructions(ConstVec::from(vec![
            instruction,
        ])));
        let builder = quote_app_api_transaction_builder(
            builder,
            queue.as_ref(),
            state.as_ref(),
            "SCCP bridge-message preparation",
        )?;
        let transaction_payload_b64 =
            base64::engine::general_purpose::STANDARD.encode(builder.encode_payload());
        let signing_message_b64 =
            base64::engine::general_purpose::STANDARD.encode(builder.payload_hash_bytes());
        PreparedBridgeMessageSubmit::Prepare(BridgeSubmitResponseDto {
            submitted: false,
            payload_kind,
            message_id_hex,
            backend,
            counterparty_domain,
            counterparty_chain: counterparty_chain.to_owned(),
            route_configuration_hash_hex,
            range_start_height,
            range_end_height,
            creation_time_ms,
            tx_hash_hex: None,
            transaction_payload_b64: Some(transaction_payload_b64),
            signing_message_b64: Some(signing_message_b64),
        })
    };

    Ok(prepared)
}

/// POST /v1/bridge/messages — prepare or submit one native SCCP proof-admission transaction.
#[cfg(feature = "app_api")]
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_post_bridge_message_submit(
    chain_id: Arc<ChainId>,
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    request_body: axum::body::Bytes,
    admission: crate::QueryAdmissionPermit,
) -> Result<(axum::response::Response, bool)> {
    run_sccp_submit_blocking("SCCP bridge-message admission worker failed", move || {
        // Keep all admission capacity with the physical verifier/serializer.
        let _admission = admission;
        let request: BridgeMessageSubmitDto =
            norito::json::from_slice(&request_body).map_err(|error| {
                conversion_error(format!(
                    "invalid closed SCCP bridge-message submission JSON: {error}"
                ))
            })?;
        let prepared = prepare_bridge_message_submit(
            Arc::clone(&chain_id),
            Arc::clone(&queue),
            Arc::clone(&state),
            request,
        )?;
        let (body, charge_prepare_egress) = match prepared {
            PreparedBridgeMessageSubmit::Direct {
                transaction,
                routing_plan,
                response,
            } => {
                let body = norito::json::to_vec_pretty(&response).map_err(|error| {
                    sccp_internal_error(format!(
                        "failed to encode exact SCCP bridge-message response: {error}"
                    ))
                })?;
                handle_transaction_with_metrics_and_routing_plan_sync(
                    chain_id,
                    queue,
                    state,
                    transaction,
                    telemetry,
                    Some(routing_plan),
                    "/v1/bridge/messages",
                )?;
                (body, false)
            }
            PreparedBridgeMessageSubmit::Prepare(response) => (
                norito::json::to_vec_pretty(&response).map_err(|error| {
                    sccp_internal_error(format!(
                        "failed to encode exact SCCP bridge-message response: {error}"
                    ))
                })?,
                true,
            ),
        };
        let mut response = axum::response::Response::new(axum::body::Body::from(body));
        response.headers_mut().insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/json"),
        );
        Ok((response, charge_prepare_egress))
    })
    .await
}

/// POST /v1/contracts/view — execute a read-only contract view entrypoint locally.
#[cfg(feature = "app_api")]
pub fn handle_post_contract_view(
    state: Arc<CoreState>,
    NoritoJson(req): NoritoJson<ContractViewDto>,
) -> Result<(StatusCode, Vec<u8>)> {
    let view = evaluate_contract_view_request(state, req)?;
    let (status, body) = match view {
        Ok(response) => (
            StatusCode::OK,
            encode_contract_view_success_bounded(
                &response,
                CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
            )?,
        ),
        Err(response) => (
            StatusCode::UNPROCESSABLE_ENTITY,
            encode_contract_view_error_bounded(&response, CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES)?,
        ),
    };
    Ok((status, body))
}

#[cfg(feature = "app_api")]
/// POST /v1/contracts/view/batch — execute multiple read-only contract view entrypoints locally.
pub fn handle_post_contract_view_batch(
    state: Arc<CoreState>,
    NoritoJson(req): NoritoJson<ContractViewBatchDto>,
) -> Result<Vec<u8>> {
    validate_contract_view_batch_request(&req)?;
    let ContractViewBatchDto {
        authority,
        gas_limit,
        items,
    } = req;
    let default_gas_limit = gas_limit.unwrap_or(DEFAULT_CONTRACT_ARGUMENT_GAS_LIMIT);

    let mut body = Vec::with_capacity(CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES.min(16 * 1024));
    append_contract_simulation_json_literal(
        &mut body,
        b"{\"items\":[",
        CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
    )?;
    let mut all_ok = true;
    for (index, item) in items.into_iter().enumerate() {
        let request_id = item.request_id;
        let item_response = evaluate_contract_view_request(
            Arc::clone(&state),
            ContractViewDto {
                authority: authority.clone(),
                contract_address: item.contract_address,
                contract_alias: item.contract_alias,
                entrypoint: item.entrypoint,
                payload: item.payload,
                gas_limit: item.gas_limit.unwrap_or(default_gas_limit),
            },
        )?;
        if index > 0 {
            append_contract_simulation_json_literal(
                &mut body,
                b",",
                CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
            )?;
        }
        append_contract_simulation_json_literal(
            &mut body,
            b"{",
            CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
        )?;
        let mut has_field = false;
        if let Some(request_id) = request_id.as_deref() {
            append_contract_simulation_json_literal(
                &mut body,
                b"\"request_id\":",
                CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
            )?;
            append_contract_json_string(
                &mut body,
                request_id,
                CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
            )?;
            has_field = true;
        }
        if has_field {
            append_contract_simulation_json_literal(
                &mut body,
                b",",
                CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
            )?;
        }
        match item_response {
            Ok(ok) => append_contract_view_success_fields(
                &mut body,
                &ok,
                CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
            )?,
            Err(err) => {
                all_ok = false;
                append_contract_view_error_fields(
                    &mut body,
                    &err,
                    CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
                )?;
            }
        }
        append_contract_simulation_json_literal(
            &mut body,
            b"}",
            CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
        )?;
    }

    append_contract_simulation_json_literal(
        &mut body,
        if all_ok {
            b"],\"ok\":true}"
        } else {
            b"],\"ok\":false}"
        },
        CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
    )?;
    Ok(body)
}

#[cfg(feature = "app_api")]
/// Validate contract-view batch admission before routing or VM execution.
pub fn validate_contract_view_batch_request(req: &ContractViewBatchDto) -> Result<()> {
    if req.items.is_empty() {
        return Err(conversion_error(
            "contract view batch must include at least one item".to_owned(),
        ));
    }
    if req.items.len() > CONTRACT_VIEW_BATCH_MAX_ITEMS {
        return Err(conversion_error(format!(
            "contract view batch exceeds the {CONTRACT_VIEW_BATCH_MAX_ITEMS}-item limit"
        )));
    }
    if req.gas_limit == Some(0) || req.items.iter().any(|item| item.gas_limit == Some(0)) {
        return Err(conversion_error(
            "contract view batch gas_limit values must be positive".to_owned(),
        ));
    }
    Ok(())
}

#[cfg(feature = "app_api")]
// Canonical argument preparation checks a conservative predecode gas quote
// covering bounded complete materialization. Keep implicit contract-call/view
// budgets above the strict admission floor; representative bounded schemas fit.
const DEFAULT_CONTRACT_ARGUMENT_GAS_LIMIT: u64 = 1_500_000;

#[cfg(feature = "app_api")]
fn current_time_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|elapsed| u64::try_from(elapsed.as_millis()).unwrap_or(u64::MAX))
        .unwrap_or(0)
}

pub(crate) fn asset_alias_observation_time_ms(state: &CoreState) -> u64 {
    state
        .latest_block_header_fast()
        .map(|header| header.creation_time_ms)
        .unwrap_or(0)
}

#[cfg(feature = "app_api")]
fn advertised_contract_entrypoint<'a>(
    manifest: &'a manifest::ContractManifest,
    selector: &str,
) -> Result<&'a manifest::EntrypointDescriptor> {
    let advertised_entrypoints = manifest.entrypoints.as_ref().ok_or_else(|| {
        conversion_error(
            "stored contract manifest does not advertise callable entrypoints".to_owned(),
        )
    })?;
    advertised_entrypoints
        .iter()
        .find(|candidate| candidate.name == selector)
        .ok_or_else(|| conversion_error(format!("unknown contract entrypoint `{selector}`")))
}

#[cfg(feature = "app_api")]
fn ensure_contract_entrypoint_kind<'a>(
    manifest: &'a manifest::ContractManifest,
    selector: &str,
    expected: manifest::EntryPointKind,
) -> Result<&'a manifest::EntrypointDescriptor> {
    let descriptor = advertised_contract_entrypoint(manifest, selector)?;
    if descriptor.kind != expected {
        let expected_kind = match expected {
            manifest::EntryPointKind::Kotoage => "kotoage by-call",
            manifest::EntryPointKind::View => "read-only view",
            manifest::EntryPointKind::Hajimari => "hajimari",
            manifest::EntryPointKind::Kaizen => "kaizen",
        };
        return Err(conversion_error(format!(
            "contract entrypoint `{selector}` is not a {expected_kind} entrypoint"
        )));
    }
    Ok(descriptor)
}

#[cfg(feature = "app_api")]
fn ensure_public_contract_entrypoint<'a>(
    manifest: &'a manifest::ContractManifest,
    selector: &str,
) -> Result<&'a manifest::EntrypointDescriptor> {
    ensure_contract_entrypoint_kind(manifest, selector, manifest::EntryPointKind::Kotoage)
}

#[cfg(feature = "app_api")]
fn ensure_callable_contract_entrypoint<'a>(
    manifest: &'a manifest::ContractManifest,
    selector: &str,
) -> Result<&'a manifest::EntrypointDescriptor> {
    let descriptor = advertised_contract_entrypoint(manifest, selector)?;
    if matches!(descriptor.kind, manifest::EntryPointKind::View) {
        return Err(conversion_error(format!(
            "contract entrypoint `{selector}` is read-only and cannot be invoked as a transaction"
        )));
    }
    Ok(descriptor)
}

#[cfg(feature = "app_api")]
fn ensure_contract_call_entrypoint<'a>(
    manifest: &'a manifest::ContractManifest,
    selector: &str,
    expected_kind: Option<manifest::EntryPointKind>,
) -> Result<&'a manifest::EntrypointDescriptor> {
    match expected_kind {
        Some(kind) => ensure_contract_entrypoint_kind(manifest, selector, kind),
        None => ensure_callable_contract_entrypoint(manifest, selector),
    }
}

#[cfg(feature = "app_api")]
fn ensure_view_contract_entrypoint<'a>(
    manifest: &'a manifest::ContractManifest,
    selector: &str,
) -> Result<&'a manifest::EntrypointDescriptor> {
    ensure_contract_entrypoint_kind(manifest, selector, manifest::EntryPointKind::View)
}

#[cfg(feature = "app_api")]
fn normalize_contract_payload(
    descriptor: &manifest::EntrypointDescriptor,
    payload: Option<&IrohaJson>,
) -> Result<Option<IrohaJson>> {
    if descriptor.argument_schema.is_none() && !descriptor.params.is_empty() {
        return Err(conversion_error(format!(
            "parameterized contract entrypoint `{}` is missing its canonical argument schema",
            descriptor.name
        )));
    }
    match (descriptor.argument_schema.as_ref(), payload) {
        (None, None) => Ok(None),
        (None, Some(_)) => Err(conversion_error(
            "contract payload must be omitted for zero-parameter entrypoints".to_owned(),
        )),
        (Some(_), None) => Err(conversion_error(
            "contract payload is required for parameterized entrypoints".to_owned(),
        )),
        (Some(schema), Some(payload)) => {
            // `IrohaJson` deliberately preserves the exact source slice during
            // request decoding. Do not carry that transport representation into
            // signed metadata: insignificant whitespace and object-key order
            // must not produce different payload digests or transaction bytes.
            // Parsing through `Value` also rejects duplicate object keys and
            // trailing tokens before any contract schema consumes the payload.
            let parsed = payload.try_into_any_norito::<Value>().map_err(|error| {
                conversion_error(format!(
                    "contract payload for entrypoint `{}` must be one strict JSON value without duplicate object keys: {error}",
                    descriptor.name
                ))
            })?;
            let canonical = IrohaJson::from_norito_value_ref(&parsed).map_err(|error| {
                conversion_error(format!(
                    "failed to canonicalize contract payload for entrypoint `{}`: {error}",
                    descriptor.name
                ))
            })?;
            ivm::encode_argument_record_from_json(schema, &canonical).map_err(|error| {
                conversion_error(format!(
                    "contract payload for entrypoint `{}` does not match its exact argument schema: {error}",
                    descriptor.name
                ))
            })?;
            Ok(Some(canonical))
        }
    }
}

#[cfg(feature = "app_api")]
fn normalize_contract_payload_after_authorization<E>(
    authorize: impl FnOnce() -> core::result::Result<(), E>,
    descriptor: &manifest::EntrypointDescriptor,
    payload: Option<&IrohaJson>,
    map_normalization_error: impl FnOnce(Error) -> E,
) -> core::result::Result<Option<IrohaJson>, E> {
    authorize()?;
    normalize_contract_payload(descriptor, payload).map_err(map_normalization_error)
}

#[cfg(feature = "app_api")]
pub(crate) fn normalize_contract_call_metadata_for_bytecode(
    metadata: &mut Metadata,
    bytecode: &[u8],
) -> Result<()> {
    let entrypoint = metadata
        .get("contract_entrypoint")
        .map(|raw| {
            raw.try_into_any_norito::<String>().map_err(|err| {
                conversion_error(format!("invalid contract_entrypoint metadata: {err}"))
            })
        })
        .transpose()?
        .map(|value| value.trim().to_owned());
    if entrypoint.as_deref().is_some_and(str::is_empty) {
        return Err(conversion_error(
            "contract_entrypoint must not be empty".to_owned(),
        ));
    }
    let Some(entrypoint) = entrypoint else {
        if ivm::ProgramMetadata::parse(bytecode)
            .ok()
            .and_then(|parsed| parsed.contract_interface)
            .is_some()
        {
            return Err(conversion_error(
                "self-describing contract calls require explicit contract_entrypoint metadata"
                    .to_owned(),
            ));
        }
        return Ok(());
    };

    let parsed = ivm::ProgramMetadata::parse(bytecode)
        .map_err(|err| conversion_error(format!("invalid contract artifact: {err}")))?;
    let contract_interface = parsed.contract_interface.as_ref().ok_or_else(|| {
        conversion_error(
            "contract entrypoint metadata requires a self-describing contract artifact".to_owned(),
        )
    })?;
    let descriptor = contract_interface
        .entrypoints
        .iter()
        .find(|candidate| candidate.name == entrypoint)
        .ok_or_else(|| conversion_error(format!("unknown contract entrypoint `{entrypoint}`")))?;
    match descriptor.kind {
        manifest::EntryPointKind::View => {
            return Err(conversion_error(format!(
                "contract entrypoint `{entrypoint}` is read-only and cannot be invoked as a transaction"
            )));
        }
        manifest::EntryPointKind::Hajimari | manifest::EntryPointKind::Kaizen => {
            return Err(conversion_error(format!(
                "`{entrypoint}` is a hajimari/始まり or kaizen/改善 entrypoint and requires a top-level deployed ContractCall"
            )));
        }
        manifest::EntryPointKind::Kotoage => {}
    }

    let manifest_descriptor = descriptor.to_manifest_descriptor();
    let payload = metadata.get("contract_payload").cloned();
    let normalized = normalize_contract_payload(&manifest_descriptor, payload.as_ref())?;
    if let Some(payload) = normalized {
        metadata.insert(
            "contract_payload"
                .parse()
                .expect("static metadata key `contract_payload`"),
            payload,
        );
    }
    Ok(())
}

#[cfg(feature = "app_api")]
fn resolve_contract_entrypoint_pc(
    prepared: &ivm::PreparedContract,
    selector: &str,
    expected: manifest::EntryPointKind,
) -> Result<u64> {
    let descriptor = prepared
        .entrypoint_descriptor(selector)
        .ok_or_else(|| conversion_error(format!("unknown contract entrypoint `{selector}`")))?;
    if descriptor.kind != expected {
        return Err(conversion_error(format!(
            "contract artifact entrypoint `{selector}` does not match the requested entrypoint kind"
        )));
    }
    prepared.entrypoint_pc(selector).ok_or_else(|| {
        conversion_error(format!(
            "contract artifact entrypoint `{selector}` has no validated code address"
        ))
    })
}

