/// Canonical server/client ceiling for `/v1/contracts/call/simulate` JSON.
pub const CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES: usize = 8 * 1024 * 1024;
/// Maximum number of VM executions admitted by one contract view batch.
pub const CONTRACT_VIEW_BATCH_MAX_ITEMS: usize = 256;

#[cfg(feature = "app_api")]
fn append_contract_simulation_json_literal(
    out: &mut Vec<u8>,
    literal: &[u8],
    max_bytes: usize,
) -> Result<()> {
    if out.len().saturating_add(literal.len()) > max_bytes {
        return Err(conversion_error(format!(
            "contract tooling response exceeds the {max_bytes}-byte JSON limit"
        )));
    }
    out.extend_from_slice(literal);
    Ok(())
}

#[cfg(feature = "app_api")]
fn append_contract_json_string(out: &mut Vec<u8>, value: &str, max_bytes: usize) -> Result<()> {
    append_contract_simulation_json_literal(out, b"\"", max_bytes)?;
    let bytes = value.as_bytes();
    let mut start = 0;
    for (index, byte) in bytes.iter().copied().enumerate() {
        let escape: Option<&[u8]> = match byte {
            b'\"' => Some(b"\\\""),
            b'\\' => Some(b"\\\\"),
            b'\x08' => Some(b"\\b"),
            b'\x0c' => Some(b"\\f"),
            b'\n' => Some(b"\\n"),
            b'\r' => Some(b"\\r"),
            b'\t' => Some(b"\\t"),
            0x00..=0x1f => {
                if start < index {
                    append_contract_simulation_json_literal(out, &bytes[start..index], max_bytes)?;
                }
                const HEX: &[u8; 16] = b"0123456789abcdef";
                let encoded = [
                    b'\\',
                    b'u',
                    b'0',
                    b'0',
                    HEX[(byte >> 4) as usize],
                    HEX[(byte & 0xf) as usize],
                ];
                append_contract_simulation_json_literal(out, &encoded, max_bytes)?;
                start = index + 1;
                None
            }
            _ => None,
        };
        if let Some(escape) = escape {
            if start < index {
                append_contract_simulation_json_literal(out, &bytes[start..index], max_bytes)?;
            }
            append_contract_simulation_json_literal(out, escape, max_bytes)?;
            start = index + 1;
        }
    }
    if start < bytes.len() {
        append_contract_simulation_json_literal(out, &bytes[start..], max_bytes)?;
    }
    append_contract_simulation_json_literal(out, b"\"", max_bytes)
}

#[cfg(feature = "app_api")]
fn append_contract_json_number<T: core::fmt::Display>(
    out: &mut Vec<u8>,
    value: &T,
    max_bytes: usize,
) -> Result<()> {
    let value = value.to_string();
    append_contract_simulation_json_literal(out, value.as_bytes(), max_bytes)
}

#[cfg(feature = "app_api")]
fn append_contract_json_optional_string(
    out: &mut Vec<u8>,
    value: Option<&str>,
    max_bytes: usize,
) -> Result<()> {
    match value {
        Some(value) => append_contract_json_string(out, value, max_bytes),
        None => append_contract_simulation_json_literal(out, b"null", max_bytes),
    }
}

#[cfg(feature = "app_api")]
fn append_contract_json_optional_number<T: core::fmt::Display>(
    out: &mut Vec<u8>,
    value: Option<T>,
    max_bytes: usize,
) -> Result<()> {
    match value {
        Some(value) => append_contract_json_number(out, &value, max_bytes),
        None => append_contract_simulation_json_literal(out, b"null", max_bytes),
    }
}

#[cfg(feature = "app_api")]
fn append_contract_json_optional_bool(
    out: &mut Vec<u8>,
    value: Option<bool>,
    max_bytes: usize,
) -> Result<()> {
    match value {
        Some(true) => append_contract_simulation_json_literal(out, b"true", max_bytes),
        Some(false) => append_contract_simulation_json_literal(out, b"false", max_bytes),
        None => append_contract_simulation_json_literal(out, b"null", max_bytes),
    }
}

#[cfg(feature = "app_api")]
fn append_contract_json_optional_iroha(
    out: &mut Vec<u8>,
    value: Option<&IrohaJson>,
    max_bytes: usize,
) -> Result<()> {
    match value {
        Some(value) => {
            append_contract_simulation_json_literal(out, value.get().as_bytes(), max_bytes)
        }
        None => append_contract_simulation_json_literal(out, b"null", max_bytes),
    }
}

#[cfg(feature = "app_api")]
fn append_contract_vm_diagnostic(
    out: &mut Vec<u8>,
    diagnostic: &ContractViewVmDiagnosticDto,
    max_bytes: usize,
) -> Result<()> {
    macro_rules! prefix {
        ($literal:literal) => {
            append_contract_simulation_json_literal(out, $literal, max_bytes)?
        };
    }
    prefix!(b"{\"trap_kind\":");
    append_contract_json_string(out, &diagnostic.trap_kind, max_bytes)?;
    prefix!(b",\"message\":");
    append_contract_json_string(out, &diagnostic.message, max_bytes)?;
    prefix!(b",\"pc\":");
    append_contract_json_number(out, &diagnostic.pc, max_bytes)?;
    prefix!(b",\"function\":");
    append_contract_json_optional_string(out, diagnostic.function.as_deref(), max_bytes)?;
    prefix!(b",\"source_path\":");
    append_contract_json_optional_string(out, diagnostic.source_path.as_deref(), max_bytes)?;
    prefix!(b",\"line\":");
    append_contract_json_optional_number(out, diagnostic.line, max_bytes)?;
    prefix!(b",\"column\":");
    append_contract_json_optional_number(out, diagnostic.column, max_bytes)?;
    prefix!(b",\"gas_limit\":");
    append_contract_json_number(out, &diagnostic.gas_limit, max_bytes)?;
    prefix!(b",\"gas_remaining\":");
    append_contract_json_number(out, &diagnostic.gas_remaining, max_bytes)?;
    prefix!(b",\"gas_used\":");
    append_contract_json_number(out, &diagnostic.gas_used, max_bytes)?;
    prefix!(b",\"cycles\":");
    append_contract_json_number(out, &diagnostic.cycles, max_bytes)?;
    prefix!(b",\"max_cycles\":");
    append_contract_json_number(out, &diagnostic.max_cycles, max_bytes)?;
    prefix!(b",\"stack_limit_bytes\":");
    append_contract_json_number(out, &diagnostic.stack_limit_bytes, max_bytes)?;
    prefix!(b",\"stack_bytes_used\":");
    append_contract_json_number(out, &diagnostic.stack_bytes_used, max_bytes)?;
    prefix!(b",\"entrypoint_pc\":");
    append_contract_json_optional_number(out, diagnostic.entrypoint_pc, max_bytes)?;
    prefix!(b",\"current_function\":");
    append_contract_json_optional_string(out, diagnostic.current_function.as_deref(), max_bytes)?;
    prefix!(b",\"opcode\":");
    append_contract_json_optional_number(out, diagnostic.opcode, max_bytes)?;
    prefix!(b",\"syscall\":");
    append_contract_json_optional_number(out, diagnostic.syscall, max_bytes)?;
    prefix!(b",\"predecoded_loaded\":");
    append_contract_simulation_json_literal(
        out,
        if diagnostic.predecoded_loaded {
            b"true"
        } else {
            b"false"
        },
        max_bytes,
    )?;
    prefix!(b",\"predecoded_hit\":");
    append_contract_json_optional_bool(out, diagnostic.predecoded_hit, max_bytes)?;
    append_contract_simulation_json_literal(out, b"}", max_bytes)
}

#[cfg(feature = "app_api")]
fn append_contract_json_optional_diagnostic(
    out: &mut Vec<u8>,
    diagnostic: Option<&ContractViewVmDiagnosticDto>,
    max_bytes: usize,
) -> Result<()> {
    match diagnostic {
        Some(diagnostic) => append_contract_vm_diagnostic(out, diagnostic, max_bytes),
        None => append_contract_simulation_json_literal(out, b"null", max_bytes),
    }
}

#[cfg(feature = "app_api")]
fn append_bounded_instruction_json(
    out: &mut Vec<u8>,
    instruction: &iroha_data_model::isi::InstructionBox,
    max_bytes: usize,
) -> Result<()> {
    // Host admission limits each instruction's canonical representation to a
    // conservative fraction of this response bound before it is retained.
    let fragment = norito::json::to_vec(instruction).map_err(|err| {
        conversion_error(format!("failed to encode simulation instruction: {err}"))
    })?;
    append_contract_simulation_json_literal(out, &fragment, max_bytes)
}

#[cfg(feature = "app_api")]
fn append_contract_view_target_fields(
    out: &mut Vec<u8>,
    dataspace: &str,
    contract_address: Option<&iroha_data_model::smart_contract::ContractAddress>,
    code_hash_hex: &str,
    abi_hash_hex: &str,
    entrypoint: &str,
    max_bytes: usize,
) -> Result<()> {
    append_contract_simulation_json_literal(out, b",\"dataspace\":", max_bytes)?;
    append_contract_json_string(out, dataspace, max_bytes)?;
    append_contract_simulation_json_literal(out, b",\"contract_address\":", max_bytes)?;
    match contract_address {
        Some(address) => append_contract_json_string(out, &address.to_string(), max_bytes)?,
        None => append_contract_simulation_json_literal(out, b"null", max_bytes)?,
    }
    append_contract_simulation_json_literal(out, b",\"code_hash_hex\":", max_bytes)?;
    append_contract_json_string(out, code_hash_hex, max_bytes)?;
    append_contract_simulation_json_literal(out, b",\"abi_hash_hex\":", max_bytes)?;
    append_contract_json_string(out, abi_hash_hex, max_bytes)?;
    append_contract_simulation_json_literal(out, b",\"entrypoint\":", max_bytes)?;
    append_contract_json_string(out, entrypoint, max_bytes)
}

#[cfg(feature = "app_api")]
fn append_contract_view_success_fields(
    out: &mut Vec<u8>,
    response: &ContractViewResponseDto,
    max_bytes: usize,
) -> Result<()> {
    append_contract_simulation_json_literal(out, b"\"ok\":true", max_bytes)?;
    append_contract_view_target_fields(
        out,
        &response.dataspace,
        response.contract_address.as_ref(),
        &response.code_hash_hex,
        &response.abi_hash_hex,
        &response.entrypoint,
        max_bytes,
    )?;
    append_contract_simulation_json_literal(out, b",\"result\":", max_bytes)?;
    append_contract_simulation_json_literal(out, response.result.get().as_bytes(), max_bytes)
}

#[cfg(feature = "app_api")]
fn append_contract_view_error_fields(
    out: &mut Vec<u8>,
    response: &ContractViewErrorResponseDto,
    max_bytes: usize,
) -> Result<()> {
    append_contract_simulation_json_literal(out, b"\"ok\":false", max_bytes)?;
    append_contract_view_target_fields(
        out,
        &response.dataspace,
        response.contract_address.as_ref(),
        &response.code_hash_hex,
        &response.abi_hash_hex,
        &response.entrypoint,
        max_bytes,
    )?;
    append_contract_simulation_json_literal(out, b",\"error\":", max_bytes)?;
    append_contract_json_string(out, &response.error, max_bytes)?;
    append_contract_simulation_json_literal(out, b",\"vm_diagnostic\":", max_bytes)?;
    append_contract_json_optional_diagnostic(out, response.vm_diagnostic.as_ref(), max_bytes)
}

#[cfg(feature = "app_api")]
fn encode_contract_view_success_bounded(
    response: &ContractViewResponseDto,
    max_bytes: usize,
) -> Result<Vec<u8>> {
    let mut out = Vec::with_capacity(max_bytes.min(16 * 1024));
    append_contract_simulation_json_literal(&mut out, b"{", max_bytes)?;
    append_contract_view_success_fields(&mut out, response, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b"}", max_bytes)?;
    Ok(out)
}

#[cfg(feature = "app_api")]
fn encode_contract_view_error_bounded(
    response: &ContractViewErrorResponseDto,
    max_bytes: usize,
) -> Result<Vec<u8>> {
    let mut out = Vec::with_capacity(max_bytes.min(16 * 1024));
    append_contract_simulation_json_literal(&mut out, b"{", max_bytes)?;
    append_contract_view_error_fields(&mut out, response, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b"}", max_bytes)?;
    Ok(out)
}

#[cfg(feature = "app_api")]
fn encode_contract_call_simulation_response_bounded(
    response: &ContractCallSimulateResponseDto,
    max_bytes: usize,
) -> Result<Vec<u8>> {
    let mut out = Vec::with_capacity(max_bytes.min(16 * 1024));
    append_contract_simulation_json_literal(&mut out, b"{\"ok\":", max_bytes)?;
    append_contract_simulation_json_literal(
        &mut out,
        if response.ok { b"true" } else { b"false" },
        max_bytes,
    )?;
    append_contract_simulation_json_literal(&mut out, b",\"dataspace\":", max_bytes)?;
    append_contract_json_string(&mut out, &response.dataspace, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"contract_address\":", max_bytes)?;
    match response.contract_address.as_ref() {
        Some(address) => append_contract_json_string(&mut out, &address.to_string(), max_bytes)?,
        None => append_contract_simulation_json_literal(&mut out, b"null", max_bytes)?,
    }
    append_contract_simulation_json_literal(&mut out, b",\"code_hash_hex\":", max_bytes)?;
    append_contract_json_string(&mut out, &response.code_hash_hex, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"abi_hash_hex\":", max_bytes)?;
    append_contract_json_string(&mut out, &response.abi_hash_hex, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"entrypoint\":", max_bytes)?;
    append_contract_json_string(&mut out, &response.entrypoint, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"normalized_payload\":", max_bytes)?;
    append_contract_json_optional_iroha(&mut out, response.normalized_payload.as_ref(), max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"gas_limit\":", max_bytes)?;
    append_contract_json_number(&mut out, &response.gas_limit, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"gas_used\":", max_bytes)?;
    append_contract_json_number(&mut out, &response.gas_used, max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"queued_instructions\":[", max_bytes)?;
    for (index, instruction) in response.queued_instructions.iter().enumerate() {
        if index > 0 {
            append_contract_simulation_json_literal(&mut out, b",", max_bytes)?;
        }
        append_bounded_instruction_json(&mut out, instruction, max_bytes)?;
    }
    append_contract_simulation_json_literal(&mut out, b"]", max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"result\":", max_bytes)?;
    append_contract_json_optional_iroha(&mut out, response.result.as_ref(), max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"error\":", max_bytes)?;
    append_contract_json_optional_string(&mut out, response.error.as_deref(), max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b",\"vm_diagnostic\":", max_bytes)?;
    append_contract_json_optional_diagnostic(&mut out, response.vm_diagnostic.as_ref(), max_bytes)?;
    append_contract_simulation_json_literal(&mut out, b"}", max_bytes)?;
    Ok(out)
}

#[cfg(feature = "app_api")]
fn map_vm_diagnostic(diag: &ivm::VmExecutionDiagnostic) -> ContractViewVmDiagnosticDto {
    ContractViewVmDiagnosticDto {
        trap_kind: format!("{:?}", diag.trap_kind),
        message: diag.message.clone(),
        pc: diag.pc,
        function: diag
            .source
            .as_ref()
            .and_then(|source| source.function.clone()),
        source_path: diag.source.as_ref().and_then(|source| source.path.clone()),
        line: diag.source.as_ref().and_then(|source| source.line),
        column: diag.source.as_ref().and_then(|source| source.column),
        gas_limit: diag.budget.gas_limit,
        gas_remaining: diag.budget.gas_remaining,
        gas_used: diag.budget.gas_used,
        cycles: diag.budget.cycles,
        max_cycles: diag.budget.max_cycles,
        stack_limit_bytes: diag.budget.stack_limit_bytes,
        stack_bytes_used: diag.budget.stack_bytes_used,
        entrypoint_pc: diag.context.entrypoint_pc,
        current_function: diag.context.current_function.clone(),
        opcode: diag.context.opcode,
        syscall: diag.context.syscall,
        predecoded_loaded: diag.context.predecoded_loaded,
        predecoded_hit: diag.context.predecoded_hit,
    }
}

#[cfg(feature = "app_api")]
fn exact_contract_permission_target(
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    entrypoint: &str,
    required: &str,
) -> iroha_data_model::permission::Permission {
    if required == "CanInvokeContractEntrypoint" {
        iroha_executor_data_model::permission::smart_contract::CanInvokeContractEntrypoint {
            contract: contract_address.clone(),
            entrypoint: entrypoint.to_owned(),
        }
        .into()
    } else {
        iroha_data_model::permission::Permission::new(required.to_owned(), IrohaJson::new(()))
    }
}

#[cfg(feature = "app_api")]
fn authority_has_exact_contract_permission(
    world: &impl WorldReadOnly,
    authority: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    entrypoint: &str,
    required: &str,
) -> std::result::Result<bool, String> {
    let target = exact_contract_permission_target(contract_address, entrypoint, required);
    let direct = world
        .account_permissions_iter(authority)
        .map_err(|err| format!("failed to resolve contract authority: {err}"))?
        .any(|permission| permission == &target);
    let through_role = world.account_roles_iter(authority).any(|role_id| {
        world
            .roles()
            .get(role_id)
            .is_some_and(|role| role.permissions().any(|permission| permission == &target))
    });
    Ok(direct || through_role)
}

#[cfg(feature = "app_api")]
fn resolve_exact_contract_runtime_alias(
    world: &impl WorldReadOnly,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    requested_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
    code_hash: iroha_crypto::Hash,
) -> core::result::Result<Option<iroha_data_model::smart_contract::ContractAlias>, String> {
    let live_code_hash = world
        .contract_instances()
        .get(contract_address)
        .copied()
        .ok_or_else(|| format!("contract instance `{contract_address}` is no longer active"))?;
    if live_code_hash != code_hash {
        return Err(format!(
            "contract instance `{contract_address}` changed code binding before local execution"
        ));
    }

    let live_alias = world
        .contract_alias_bindings()
        .get(contract_address)
        .map(|binding| binding.alias.clone());
    if let Some(alias) = live_alias.as_ref()
        && world.contract_aliases().get(alias) != Some(contract_address)
    {
        return Err(format!(
            "contract instance `{contract_address}` has an inconsistent live alias binding"
        ));
    }
    if world
        .contract_aliases()
        .iter()
        .any(|(alias, address)| address == contract_address && Some(alias) != live_alias.as_ref())
    {
        return Err(format!(
            "contract instance `{contract_address}` has a non-canonical forward alias binding"
        ));
    }
    if requested_alias.is_some_and(|alias| live_alias.as_ref() != Some(alias)) {
        return Err(format!(
            "contract instance `{contract_address}` changed its requested alias binding before local execution"
        ));
    }
    Ok(live_alias)
}

#[cfg(feature = "app_api")]
fn exact_prepared_entrypoint<'a>(
    prepared: &'a ivm::PreparedContract,
    selector: &str,
    manifest_descriptor: &manifest::EntrypointDescriptor,
) -> core::result::Result<&'a ivm::EmbeddedEntrypointDescriptor, String> {
    let embedded = prepared
        .entrypoint_descriptor(selector)
        .ok_or_else(|| format!("deployed contract is missing embedded entrypoint `{selector}`"))?;
    if &embedded.to_manifest_descriptor() != manifest_descriptor {
        return Err(format!(
            "stored manifest entrypoint `{selector}` no longer matches the verified contract artifact"
        ));
    }
    Ok(embedded)
}

#[cfg(feature = "app_api")]
fn ensure_contract_view_authorized(
    world: &impl WorldReadOnly,
    authority: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    entrypoint: &str,
    required: Option<&str>,
) -> std::result::Result<(), ContractViewExecutionError> {
    let Some(required) = required else {
        return Ok(());
    };
    let required = required.trim();
    if required.is_empty() {
        Err(ContractViewExecutionError {
            message: "contract view authorization must not be empty".to_owned(),
            vm_diagnostic: None,
        })
    } else if authority_has_exact_contract_permission(
        world,
        authority,
        contract_address,
        entrypoint,
        required,
    )
    .map_err(|message| ContractViewExecutionError {
        message,
        vm_diagnostic: None,
    })? {
        Ok(())
    } else {
        Err(ContractViewExecutionError {
            message: format!(
                "contract view entrypoint `{entrypoint}` requires permission `{required}`"
            ),
            vm_diagnostic: None,
        })
    }
}

#[cfg(feature = "app_api")]
fn contract_call_runtime_permission(
    kind: manifest::EntryPointKind,
    declared_permission: Option<&str>,
) -> Option<&str> {
    match kind {
        manifest::EntryPointKind::Kotoage => declared_permission,
        manifest::EntryPointKind::Hajimari => {
            Some(iroha_data_model::smart_contract::CONTRACT_HAJIMARI_PERMISSION_NAME)
        }
        manifest::EntryPointKind::Kaizen => {
            Some(iroha_data_model::smart_contract::CONTRACT_KAIZEN_PERMISSION_NAME)
        }
        manifest::EntryPointKind::View => None,
    }
}

#[cfg(feature = "app_api")]
fn ensure_contract_call_authorized(
    world: &impl WorldReadOnly,
    authority: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    entrypoint: &str,
    required: Option<&str>,
) -> std::result::Result<(), ContractCallSimulationError> {
    let Some(required) = required else {
        return Ok(());
    };
    let required = required.trim();
    if required.is_empty() {
        return Err(ContractCallSimulationError {
            message: "contract entrypoint authorization must not be empty".to_owned(),
            vm_diagnostic: None,
            normalized_payload: None,
            gas_used: 0,
            queued_instructions: Vec::new(),
        });
    }
    if authority_has_exact_contract_permission(
        world,
        authority,
        contract_address,
        entrypoint,
        required,
    )
    .map_err(|message| ContractCallSimulationError {
        message,
        vm_diagnostic: None,
        normalized_payload: None,
        gas_used: 0,
        queued_instructions: Vec::new(),
    })? {
        Ok(())
    } else {
        Err(ContractCallSimulationError {
            message: format!("contract entrypoint `{entrypoint}` requires permission `{required}`"),
            vm_diagnostic: None,
            normalized_payload: None,
            gas_used: 0,
            queued_instructions: Vec::new(),
        })
    }
}

#[cfg(feature = "app_api")]
fn execute_contract_view(
    state: &CoreState,
    authority: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
    program: &iroha_core::smartcontracts::ivm::cache::ProgramSummary,
    selector: &str,
    descriptor: &manifest::EntrypointDescriptor,
    payload: Option<IrohaJson>,
    gas_limit: u64,
) -> std::result::Result<IrohaJson, ContractViewExecutionError> {
    let entry_pc = resolve_contract_entrypoint_pc(
        program.prepared_contract(),
        selector,
        manifest::EntryPointKind::View,
    )
    .map_err(|err| ContractViewExecutionError {
        message: err.to_string(),
        vm_diagnostic: None,
    })?;
    let query_view = state.query_view();
    iroha_core::smartcontracts::code::ensure_contract_ready_for_view(
        &query_view.world,
        contract_address,
        program.code_hash,
    )
    .map_err(|error| ContractViewExecutionError {
        message: error.to_string(),
        vm_diagnostic: None,
    })?;
    let live_alias = resolve_exact_contract_runtime_alias(
        &query_view.world,
        contract_address,
        contract_alias,
        program.code_hash,
    )
    .map_err(|message| ContractViewExecutionError {
        message,
        vm_diagnostic: None,
    })?;
    let embedded_descriptor =
        exact_prepared_entrypoint(program.prepared_contract(), selector, descriptor).map_err(
            |message| ContractViewExecutionError {
                message,
                vm_diagnostic: None,
            },
        )?;
    let runtime_permission = embedded_descriptor.permission.clone();
    let normalized_payload = normalize_contract_payload_after_authorization(
        || {
            ensure_contract_view_authorized(
                &query_view.world,
                authority,
                contract_address,
                selector,
                runtime_permission.as_deref(),
            )
        },
        descriptor,
        payload.as_ref(),
        |error| ContractViewExecutionError {
            message: error.to_string(),
            vm_diagnostic: None,
        },
    )?;
    let mut host = iroha_core::smartcontracts::ivm::host::CoreHostImpl::with_accounts(
        authority.clone(),
        query_view.accounts_snapshot(),
    );
    host.bind_authorized_deployed_contract_view_runtime_context(
        &query_view,
        contract_address,
        live_alias.as_ref(),
        program.prepared_contract(),
        selector,
    )
    .map_err(|error| ContractViewExecutionError {
        message: error.to_string(),
        vm_diagnostic: None,
    })?;
    let arguments = prepare_contract_argument_record(
        program.prepared_contract(),
        selector,
        normalized_payload.as_ref(),
        gas_limit,
    )
    .map_err(|message| ContractViewExecutionError {
        message,
        vm_diagnostic: None,
    })?;
    let prepared_arguments = arguments.clone();
    host.set_entrypoint_argument_record(arguments);
    let mut vm = program
        .checkout_runtime(gas_limit)
        .map_err(|err| ContractViewExecutionError {
            message: format!("failed to prepare contract view runtime: {err}"),
            vm_diagnostic: None,
        })?;
    // Views are not allowed to retain any instruction, durable-state write,
    // FastPQ entry, or completed AXT artifact. Reject before those containers grow.
    host.set_output_limits(iroha_core::smartcontracts::ivm::host::HostOutputLimits::new(0, 0));
    host.set_crypto_config(Arc::clone(&query_view.crypto));
    host.set_halo2_config(&query_view.zk.halo2);
    host.set_chain_id(&query_view.chain_id);
    host.set_axt_timing(query_view.nexus.axt);
    host.set_public_inputs_from_parameters(query_view.world.parameters());
    host.set_vrf_epoch_seeds_from_world(&query_view.world);
    host.set_query_state(&query_view);
    host.set_prepared_contract_cache(program.prepared_contract_cache());

    vm.set_gas_limit(gas_limit);
    if let Some(arguments) = prepared_arguments.as_ref() {
        arguments
            .precharge_vm(&mut vm)
            .map_err(|error| ContractViewExecutionError {
                message: format!("failed to precharge contract view arguments: {error}"),
                vm_diagnostic: None,
            })?;
    }
    let return_pc = vm.memory.code_len();
    vm.set_register(1, return_pc);
    vm.set_program_counter(entry_pc)
        .map_err(|err| ContractViewExecutionError {
            message: format!("failed to seek to contract view entrypoint: {err}"),
            vm_diagnostic: None,
        })?;
    vm.run_with_host(&mut host)
        .map_err(|err| ContractViewExecutionError {
            message: format!("contract view execution failed: {err}"),
            vm_diagnostic: vm.last_diagnostic().map(map_vm_diagnostic),
        })?;

    if let Some(violation) = host.output_budget_violation() {
        return Err(ContractViewExecutionError {
            message: format!("contract view attempted bounded output: {violation:?}"),
            vm_diagnostic: None,
        });
    }

    let queued = host.drain_instructions();
    if !queued.is_empty() {
        return Err(ContractViewExecutionError {
            message: "view entrypoint attempted to emit instructions".to_owned(),
            vm_diagnostic: None,
        });
    }
    let durable_overlay = host.drain_durable_state_overlay();
    if !durable_overlay.is_empty() {
        return Err(ContractViewExecutionError {
            message: "view entrypoint attempted to mutate durable state".to_owned(),
            vm_diagnostic: None,
        });
    }

    let value = descriptor.return_schema.as_ref().map_or_else(
        || Ok(Value::Null),
        |schema| {
            iroha_core::smartcontracts::ivm::return_value::decode_entrypoint_return(&vm, schema)
                .map_err(|err| ContractViewExecutionError {
                    message: err.to_string(),
                    vm_diagnostic: vm.last_diagnostic().map(map_vm_diagnostic),
                })
        },
    )?;
    Ok(IrohaJson::from(value))
}

#[cfg(feature = "app_api")]
fn execute_contract_call_simulation(
    state: &CoreState,
    authority: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
    program: &iroha_core::smartcontracts::ivm::cache::ProgramSummary,
    selector: &str,
    descriptor: &manifest::EntrypointDescriptor,
    payload: Option<IrohaJson>,
    gas_limit: u64,
) -> std::result::Result<ContractCallSimulationExecution, ContractCallSimulationError> {
    let entry_pc =
        resolve_contract_entrypoint_pc(program.prepared_contract(), selector, descriptor.kind)
            .map_err(|err| ContractCallSimulationError {
                message: err.to_string(),
                vm_diagnostic: None,
                normalized_payload: None,
                gas_used: 0,
                queued_instructions: Vec::new(),
            })?;
    let query_view = state.query_view();
    iroha_core::smartcontracts::code::ensure_contract_entrypoint_lifecycle(
        &query_view.world,
        contract_address,
        program.code_hash,
        descriptor.kind,
    )
    .map_err(|error| ContractCallSimulationError {
        message: error.to_string(),
        vm_diagnostic: None,
        normalized_payload: None,
        gas_used: 0,
        queued_instructions: Vec::new(),
    })?;
    let live_alias = resolve_exact_contract_runtime_alias(
        &query_view.world,
        contract_address,
        contract_alias,
        program.code_hash,
    )
    .map_err(|message| ContractCallSimulationError {
        message,
        vm_diagnostic: None,
        normalized_payload: None,
        gas_used: 0,
        queued_instructions: Vec::new(),
    })?;
    let embedded_descriptor =
        exact_prepared_entrypoint(program.prepared_contract(), selector, descriptor).map_err(
            |message| ContractCallSimulationError {
                message,
                vm_diagnostic: None,
                normalized_payload: None,
                gas_used: 0,
                queued_instructions: Vec::new(),
            },
        )?;
    let runtime_permission = contract_call_runtime_permission(
        embedded_descriptor.kind,
        embedded_descriptor.permission.as_deref(),
    )
    .map(str::to_owned);
    let normalized_payload = normalize_contract_payload_after_authorization(
        || {
            ensure_contract_call_authorized(
                &query_view.world,
                authority,
                contract_address,
                selector,
                runtime_permission.as_deref(),
            )
        },
        descriptor,
        payload.as_ref(),
        |error| ContractCallSimulationError {
            message: error.to_string(),
            vm_diagnostic: None,
            normalized_payload: None,
            gas_used: 0,
            queued_instructions: Vec::new(),
        },
    )?;
    let mut host = iroha_core::smartcontracts::ivm::host::CoreHostImpl::with_accounts(
        authority.clone(),
        query_view.accounts_snapshot(),
    );
    host.bind_authorized_deployed_contract_runtime_context(
        &query_view,
        contract_address,
        live_alias.as_ref(),
        program.prepared_contract(),
        selector,
    )
    .map_err(|error| ContractCallSimulationError {
        message: error.to_string(),
        vm_diagnostic: None,
        normalized_payload: normalized_payload.clone(),
        gas_used: 0,
        queued_instructions: Vec::new(),
    })?;
    let arguments = prepare_contract_argument_record(
        program.prepared_contract(),
        selector,
        normalized_payload.as_ref(),
        gas_limit,
    )
    .map_err(|message| ContractCallSimulationError {
        message,
        vm_diagnostic: None,
        normalized_payload: normalized_payload.clone(),
        gas_used: 0,
        queued_instructions: Vec::new(),
    })?;
    let prepared_arguments = arguments.clone();
    host.set_entrypoint_argument_record(arguments);
    let mut vm =
        program
            .checkout_runtime(gas_limit)
            .map_err(|err| ContractCallSimulationError {
                message: format!("failed to prepare contract call runtime: {err}"),
                vm_diagnostic: None,
                normalized_payload: normalized_payload.clone(),
                gas_used: 0,
                queued_instructions: Vec::new(),
            })?;
    let max_items = usize::try_from(
        query_view
            .world
            .parameters()
            .transaction()
            .max_instructions()
            .get(),
    )
    .unwrap_or(usize::MAX);
    host.set_output_limits(
        iroha_core::smartcontracts::ivm::host::HostOutputLimits::new(
            max_items,
            CONTRACT_CALL_SIMULATION_JSON_MAX_BYTES,
        ),
    );
    host.set_crypto_config(Arc::clone(&query_view.crypto));
    host.set_halo2_config(&query_view.zk.halo2);
    host.set_chain_id(&query_view.chain_id);
    host.set_axt_timing(query_view.nexus.axt);
    host.set_public_inputs_from_parameters(query_view.world.parameters());
    host.set_vrf_epoch_seeds_from_world(&query_view.world);
    host.set_query_state(&query_view);
    host.set_prepared_contract_cache(program.prepared_contract_cache());

    vm.set_gas_limit(gas_limit);
    if let Some(arguments) = prepared_arguments.as_ref() {
        arguments
            .precharge_vm(&mut vm)
            .map_err(|error| ContractCallSimulationError {
                message: format!("failed to precharge contract call arguments: {error}"),
                vm_diagnostic: None,
                normalized_payload: normalized_payload.clone(),
                gas_used: 0,
                queued_instructions: Vec::new(),
            })?;
    }
    let return_pc = vm.memory.code_len();
    vm.set_register(1, return_pc);
    vm.set_program_counter(entry_pc)
        .map_err(|err| ContractCallSimulationError {
            message: format!("failed to seek to contract call entrypoint: {err}"),
            vm_diagnostic: None,
            normalized_payload: normalized_payload.clone(),
            gas_used: 0,
            queued_instructions: Vec::new(),
        })?;

    let run_result = vm.run_with_host(&mut host);
    if let Some(violation) = host.output_budget_violation() {
        return Err(ContractCallSimulationError {
            message: format!("contract call simulation output budget exceeded: {violation:?}"),
            vm_diagnostic: vm.last_diagnostic().map(map_vm_diagnostic),
            normalized_payload: normalized_payload.clone(),
            gas_used: gas_limit.saturating_sub(vm.gas_remaining),
            queued_instructions: Vec::new(),
        });
    }
    let queued = host.drain_instructions();
    let _durable_state_overlay = host.drain_durable_state_overlay();
    let gas_used = gas_limit.saturating_sub(vm.gas_remaining);
    let queued_instructions = queued;

    if let Err(err) = run_result {
        return Err(ContractCallSimulationError {
            message: format!("contract call simulation failed: {err}"),
            vm_diagnostic: vm.last_diagnostic().map(map_vm_diagnostic),
            normalized_payload,
            gas_used,
            queued_instructions,
        });
    }

    let result = descriptor
        .return_schema
        .as_ref()
        .map(|schema| {
            iroha_core::smartcontracts::ivm::return_value::decode_entrypoint_return(&vm, schema)
                .map(IrohaJson::from)
                .map_err(|err| ContractCallSimulationError {
                    message: err.to_string(),
                    vm_diagnostic: vm.last_diagnostic().map(map_vm_diagnostic),
                    normalized_payload: normalized_payload.clone(),
                    gas_used,
                    queued_instructions: queued_instructions.clone(),
                })
        })
        .transpose()?;

    Ok(ContractCallSimulationExecution {
        normalized_payload,
        gas_used,
        queued_instructions,
        result,
    })
}

#[cfg(feature = "app_api")]
fn build_contract_call_metadata(
    _manifest: &manifest::ContractManifest,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    code_hash: &Hash,
    contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
    entrypoint: Option<&str>,
    payload: Option<&IrohaJson>,
) -> Metadata {
    let mut metadata = Metadata::default();
    let contract_address_key =
        Name::from_str("contract_address").expect("static metadata key `contract_address`");
    metadata.insert(
        contract_address_key,
        IrohaJson::new(contract_address.to_string()),
    );
    let contract_code_hash_key =
        Name::from_str("contract_code_hash").expect("static metadata key `contract_code_hash`");
    metadata.insert(
        contract_code_hash_key,
        IrohaJson::new(code_hash.to_string()),
    );
    if let Some(alias) = contract_alias {
        let alias_key =
            Name::from_str("contract_alias").expect("static metadata key `contract_alias`");
        metadata.insert(alias_key, IrohaJson::new(alias.to_string()));
    }
    if let Some(entrypoint) = entrypoint {
        let entrypoint_key = Name::from_str("contract_entrypoint")
            .expect("static metadata key `contract_entrypoint`");
        metadata.insert(entrypoint_key, IrohaJson::new(entrypoint.to_owned()));
    }
    if let Some(payload) = payload {
        let payload_key =
            Name::from_str("contract_payload").expect("static metadata key `contract_payload`");
        metadata.insert(payload_key, payload.clone());
    }
    if let Some(module) = canonical_contract_module(
        contract_alias.map(ToString::to_string).as_deref(),
        &contract_address.to_string(),
    ) {
        let module_key =
            Name::from_str("contract_module").expect("static metadata key `contract_module`");
        metadata.insert(module_key, IrohaJson::new(module.to_owned()));
        if let Some(entrypoint) = entrypoint {
            if let Some(event_kind) = canonical_contract_event_kind(module, entrypoint) {
                let event_kind_key = Name::from_str("contract_event_kind")
                    .expect("static metadata key `contract_event_kind`");
                metadata.insert(event_kind_key, IrohaJson::new(event_kind.to_owned()));
                let schema_version_key = Name::from_str("contract_event_schema_version")
                    .expect("static metadata key `contract_event_schema_version`");
                metadata.insert(schema_version_key, IrohaJson::new(1_u64));
                let provenance_key = Name::from_str("contract_event_provenance")
                    .expect("static metadata key `contract_event_provenance`");
                metadata.insert(provenance_key, IrohaJson::new("emitted"));
                if let Some(event_payload) =
                    canonical_contract_event_payload(module, entrypoint, payload)
                {
                    let payload_key = Name::from_str("contract_event_payload")
                        .expect("static metadata key `contract_event_payload`");
                    metadata.insert(payload_key, event_payload);
                }
            }
        }
    }
    metadata
}

#[cfg(feature = "app_api")]
fn validate_app_api_fee_payment(
    fee_payment: &iroha_data_model::transaction::FeePaymentIntent,
    require_gas_limit: bool,
) -> Result<()> {
    fee_payment
        .validate()
        .map_err(|error| conversion_error(format!("invalid fee_payment: {error}")))?;
    if require_gas_limit && fee_payment.gas_limit().is_none() {
        return Err(conversion_error(
            "fee_payment.gas_limit is required for contract execution".to_owned(),
        ));
    }
    Ok(())
}

#[cfg(feature = "app_api")]
fn normalize_transaction_memo(memo: Option<String>) -> Option<String> {
    memo.map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
}

#[cfg(feature = "app_api")]
fn normalize_validation_fee_policy_metadata(
    version: Option<String>,
    hash: Option<String>,
    instruction_index: Option<String>,
    transfer_entry_index: Option<String>,
) -> Result<Option<(u64, String, Option<u64>, Option<u64>)>> {
    let version = version
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty());
    let hash = hash
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty());
    let instruction_index = instruction_index
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty());
    let transfer_entry_index = transfer_entry_index
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty());
    match (version, hash, instruction_index, transfer_entry_index) {
        (None, None, None, None) => Ok(None),
        (None, None, Some(_), _) | (None, None, _, Some(_)) => Err(conversion_error(
            "validation fee coordinate metadata requires validation fee policy metadata".to_owned(),
        )),
        (Some(_), None, _, _) | (None, Some(_), _, _) => Err(conversion_error(
            "validation fee policy metadata requires both version and hash".to_owned(),
        )),
        (Some(version), Some(hash), instruction_index, transfer_entry_index) => {
            let version = version.parse::<u64>().map_err(|_| {
                conversion_error(
                    "validation_fee_policy_version must be an unsigned integer".to_owned(),
                )
            })?;
            if hash.len() != 64 || !hash.bytes().all(|byte| byte.is_ascii_hexdigit()) {
                return Err(conversion_error(
                    "validation_fee_policy_hash must be a 64-character hex string".to_owned(),
                ));
            }
            let instruction_index = instruction_index
                .map(|value| {
                    value.parse::<u64>().map_err(|_| {
                        conversion_error(
                            "validation_fee_instruction_index must be an unsigned integer"
                                .to_owned(),
                        )
                    })
                })
                .transpose()?;
            let transfer_entry_index = transfer_entry_index
                .map(|value| {
                    value.parse::<u64>().map_err(|_| {
                        conversion_error(
                            "validation_fee_transfer_entry_index must be an unsigned integer"
                                .to_owned(),
                        )
                    })
                })
                .transpose()?;
            if transfer_entry_index.is_some() && instruction_index.is_none() {
                return Err(conversion_error(
                    "validation_fee_transfer_entry_index requires validation_fee_instruction_index"
                        .to_owned(),
                ));
            }
            Ok(Some((
                version,
                hash.to_ascii_lowercase(),
                instruction_index,
                transfer_entry_index,
            )))
        }
    }
}

#[cfg(feature = "app_api")]
fn append_canonical_multisig_validation_fee_marker(
    instructions: &mut Vec<iroha_data_model::isi::InstructionBox>,
    validation_fee_policy_metadata: Option<&(u64, String, Option<u64>, Option<u64>)>,
) -> Result<()> {
    use iroha_data_model::validation_fee::ValidationFeeMultisigMarkerV1;

    for instruction in instructions.iter() {
        match ValidationFeeMultisigMarkerV1::parse_instruction(instruction) {
            Ok(None) => {}
            Ok(Some(_)) | Err(_) => {
                return Err(conversion_error(
                    "multisig propose instructions must not supply a top-level validation-fee marker; provide the validated policy fields and coordinate so Torii can inject the canonical signed marker"
                        .to_owned(),
                ));
            }
        }
    }

    let Some((policy_version, policy_hash_hex, Some(instruction_index), transfer_entry_index)) =
        validation_fee_policy_metadata
    else {
        return Ok(());
    };
    let policy_hash: [u8; 32] = hex::decode(policy_hash_hex)
        .map_err(|_| conversion_error("invalid normalized validation-fee policy hash".to_owned()))?
        .try_into()
        .map_err(|_| {
            conversion_error("invalid normalized validation-fee policy hash".to_owned())
        })?;
    instructions.push(
        ValidationFeeMultisigMarkerV1::new(
            *policy_version,
            policy_hash,
            *instruction_index,
            *transfer_entry_index,
        )
        .into_instruction(),
    );
    Ok(())
}

#[cfg(feature = "app_api")]
fn build_multisig_propose_metadata(memo: Option<&str>) -> Metadata {
    let mut metadata = Metadata::default();
    if let Some(memo) = memo {
        let memo_key = Name::from_str("memo").expect("static metadata key `memo`");
        metadata.insert(memo_key, IrohaJson::new(memo.to_owned()));
    }
    metadata
}

#[cfg(feature = "app_api")]
fn build_multisig_propose_metadata_with_validation_fee(
    memo: Option<&str>,
    validation_fee_policy_metadata: Option<(u64, &str, Option<u64>, Option<u64>)>,
) -> Metadata {
    let mut metadata = build_multisig_propose_metadata(memo);
    if let Some((policy_version, policy_hash, instruction_index, transfer_entry_index)) =
        validation_fee_policy_metadata
    {
        let version_key = Name::from_str(
            iroha_data_model::validation_fee::VALIDATION_FEE_POLICY_VERSION_METADATA_KEY,
        )
        .expect("static metadata key `validation_fee_policy_version`");
        metadata.insert(version_key, IrohaJson::new(policy_version));
        let hash_key = Name::from_str(
            iroha_data_model::validation_fee::VALIDATION_FEE_POLICY_HASH_METADATA_KEY,
        )
        .expect("static metadata key `validation_fee_policy_hash`");
        metadata.insert(hash_key, IrohaJson::new(policy_hash.to_owned()));
        if let Some(instruction_index) = instruction_index {
            let instruction_index_key = Name::from_str(
                iroha_data_model::validation_fee::VALIDATION_FEE_INSTRUCTION_INDEX_METADATA_KEY,
            )
            .expect("static metadata key `validation_fee_instruction_index`");
            metadata.insert(instruction_index_key, IrohaJson::new(instruction_index));
        }
        if let Some(transfer_entry_index) = transfer_entry_index {
            let transfer_entry_index_key = Name::from_str(
                iroha_data_model::validation_fee::VALIDATION_FEE_TRANSFER_ENTRY_INDEX_METADATA_KEY,
            )
            .expect("static metadata key `validation_fee_transfer_entry_index`");
            metadata.insert(
                transfer_entry_index_key,
                IrohaJson::new(transfer_entry_index),
            );
        }
    }
    metadata
}

#[cfg(feature = "app_api")]
fn scaffold_transaction_routing_plan(
    chain_id: &ChainId,
    queue: &Queue,
    state: &CoreState,
    routing_authority: &AccountId,
    creation_time_ms: u64,
    fee_payment: iroha_data_model::transaction::FeePaymentIntent,
    metadata: Metadata,
    executable: Executable,
    context: &'static str,
) -> Result<RoutingPlan> {
    let mut builder = TransactionBuilder::new(
        chain_id.clone(),
        routing_authority.clone(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    );
    builder.set_creation_time(Duration::from_millis(creation_time_ms));
    let tx = sign_app_api_scaffold_transaction(
        builder
            .with_fee_payment_intent(fee_payment)
            .with_metadata(metadata)
            .with_executable(executable),
        routing_authority.clone(),
        context,
    )?;
    let accepted = iroha_core::tx::AcceptedTransaction::new_unchecked(std::borrow::Cow::Owned(tx));
    queue
        .route_plan_with_state(&accepted, state)
        .map_err(|err| Error::PushIntoQueue {
            source: Box::new(iroha_core::queue::Error::UnresolvedRoute {
                reason: err.to_string(),
            }),
            backpressure: queue.current_backpressure(),
        })
}

#[cfg(feature = "app_api")]
fn multisig_immediate_execution_routing_plan(
    chain_id: &ChainId,
    queue: &Queue,
    state: &CoreState,
    routing_authority: &AccountId,
    creation_time_ms: u64,
    fee_payment: iroha_data_model::transaction::FeePaymentIntent,
    metadata: Metadata,
    executable: Executable,
    context: &'static str,
) -> Result<RoutingPlan> {
    scaffold_transaction_routing_plan(
        chain_id,
        queue,
        state,
        routing_authority,
        creation_time_ms,
        fee_payment,
        metadata,
        executable,
        context,
    )
}

#[cfg(feature = "app_api")]
fn derive_multisig_contract_call_trigger_id(
    multisig_account_id: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    entrypoint: &str,
    payload: Option<&IrohaJson>,
    code_hash: &Hash,
) -> Result<iroha_data_model::trigger::TriggerId> {
    let payload_repr = payload
        .map(|value| norito::json::to_json(value).unwrap_or_else(|_| "<payload>".to_owned()))
        .unwrap_or_default();
    let seed = format!(
        "{multisig_account_id}|{contract_address}|{entrypoint}|{payload_repr}|{}",
        hex::encode(code_hash.as_ref())
    );
    let digest = blake3_hash(seed.as_bytes());
    let trigger_name = format!("msig_cc_{}", &hex::encode(digest.as_bytes())[..24]);
    let trigger_name = Name::from_str(&trigger_name)
        .map_err(|err| conversion_error(format!("failed to derive trigger id: {err}")))?;
    Ok(iroha_data_model::trigger::TriggerId::new(trigger_name))
}

#[cfg(feature = "app_api")]
fn build_multisig_contract_call_instructions(
    multisig_account_id: &iroha_data_model::account::AccountId,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
    entrypoint: &str,
    payload: Option<&IrohaJson>,
    arguments: Option<&[u8]>,
    manifest: &manifest::ContractManifest,
    code_hash: &Hash,
) -> Result<(
    Vec<iroha_data_model::isi::InstructionBox>,
    HashOf<Vec<iroha_data_model::isi::InstructionBox>>,
)> {
    let descriptor = advertised_contract_entrypoint(manifest, entrypoint)?;
    if matches!(
        descriptor.kind,
        manifest::EntryPointKind::Hajimari | manifest::EntryPointKind::Kaizen
    ) {
        return Err(conversion_error(format!(
            "`{entrypoint}` is a hajimari/始まり or kaizen/改善 entrypoint and cannot be invoked through a multisig trigger"
        )));
    }
    let arguments =
        bound_signed_contract_arguments(arguments.map(<[u8]>::to_vec)).map_err(conversion_error)?;
    let trigger_id = derive_multisig_contract_call_trigger_id(
        multisig_account_id,
        contract_address,
        entrypoint,
        payload,
        code_hash,
    )?;
    let trigger_metadata = build_contract_call_metadata(
        manifest,
        contract_address,
        code_hash,
        contract_alias,
        Some(entrypoint),
        payload,
    );
    let filter = iroha_data_model::events::execute_trigger::ExecuteTriggerEventFilter::new()
        .for_trigger(trigger_id.clone());
    let action = iroha_data_model::trigger::action::Action::new(
        iroha_data_model::transaction::Executable::ContractCall(
            iroha_data_model::transaction::executable::ContractInvocation {
                contract_address: contract_address.clone(),
                expected_code_hash: *code_hash,
                entrypoint: entrypoint.to_owned(),
                arguments,
            },
        ),
        iroha_data_model::trigger::action::Repeats::Exactly(1),
        multisig_account_id.clone(),
        filter,
    )
    .with_metadata(trigger_metadata);
    let trigger = iroha_data_model::trigger::Trigger::new(trigger_id.clone(), action);
    let execute_trigger = payload.cloned().map_or_else(
        || iroha_data_model::isi::ExecuteTrigger::new(trigger_id.clone()),
        |payload| iroha_data_model::isi::ExecuteTrigger::new(trigger_id.clone()).with_args(payload),
    );
    let instructions = vec![
        iroha_data_model::isi::InstructionBox::from(iroha_data_model::isi::Register::trigger(
            trigger,
        )),
        iroha_data_model::isi::InstructionBox::from(execute_trigger),
    ];
    let instructions_hash = HashOf::new(&instructions);
    Ok((instructions, instructions_hash))
}

