    fn multisig_test_world() -> (
        World,
        dm::AccountId,
        dm::AccountId,
        dm::AccountId,
        String,
        String,
    ) {
        let domain_id: DomainId = DomainId::try_new("banka", "universal").expect("domain");
        let label_name: Name = "cbdc".parse().expect("label");
        let alias_literal = format!("{label_name}@{domain_id}");

        let signer_one =
            checked_multisig_selector_keypair(0x60, "derive multisig selector signer one key");
        let signer_two =
            checked_multisig_selector_keypair(0x61, "derive multisig selector signer two key");
        let signer_one_id = dm::AccountId::new(signer_one.public_key().clone());
        let signer_two_id = dm::AccountId::new(signer_two.public_key().clone());

        let policy = MultisigPolicy::new(
            2,
            vec![
                MultisigMember::new(signer_one.public_key().clone(), 1).expect("member"),
                MultisigMember::new(signer_two.public_key().clone(), 1).expect("member"),
            ],
        )
        .expect("policy");
        let multisig_id = dm::AccountId::new_multisig(policy);
        let multisig_account_id: dm::AccountId = multisig_id.clone().into();

        let spec = MultisigSpec {
            signatories: BTreeMap::from([
                (signer_one_id.clone().into(), 1_u8),
                (signer_two_id.clone().into(), 1_u8),
            ]),
            quorum: NonZeroU16::new(2).expect("quorum"),
            transaction_ttl_ms: NonZeroU64::new(60_000).expect("ttl"),
        };

        let mut multisig_metadata = Metadata::default();
        multisig_metadata.insert(
            Name::from_str(MULTISIG_SPEC_METADATA_KEY).expect("spec key"),
            IrohaJson::new(spec.clone()),
        );

        let active_instructions = vec![dm::Log::new(dm::Level::INFO, "active".to_owned()).into()];
        let active_hash = HashOf::new(&active_instructions);
        let executed_instructions =
            vec![dm::Log::new(dm::Level::INFO, "executed".to_owned()).into()];
        let executed_hash = HashOf::new(&executed_instructions);

        let expired_instructions = vec![dm::Log::new(dm::Level::INFO, "expired".to_owned()).into()];
        let expired_hash = HashOf::new(&expired_instructions);

        let authority = signer_one_id.account().clone();
        let domain = Domain::new(domain_id.clone()).build(&authority);
        let multisig_account = Account::new(multisig_id.account().clone())
            .with_metadata(multisig_metadata)
            .build(&authority);
        let signer_one_account = Account::new(signer_one_id.account().clone()).build(&authority);
        let signer_two_account = Account::new(signer_two_id.account().clone()).build(&authority);

        let mut world = World::with(
            [domain],
            [multisig_account, signer_one_account, signer_two_account],
            [],
        );
        bind_universal_account_alias_on_world_for_test(
            &world,
            &multisig_account_id,
            &alias_literal,
        );
        insert_native_multisig_account_state(
            &mut world,
            &multisig_account_id,
            Some(domain_id.clone()),
            &spec,
        );
        world.smart_contract_state_mut_for_testing().insert(
            multisig_proposal_state_contract_key(&multisig_account_id, &active_hash),
            norito::to_bytes(
                &iroha_executor_data_model::isi::multisig::MultisigProposalState::new(
                    multisig_account_id.clone(),
                    active_hash,
                    active_instructions,
                    1_700_000_000_000,
                    4_000_000_000_000,
                    BTreeSet::from([signer_one_id.clone().into()]),
                    None,
                ),
            )
            .expect("encode active proposal state"),
        );
        world.smart_contract_state_mut_for_testing().insert(
            multisig_proposal_state_contract_key(&multisig_account_id, &executed_hash),
            norito::to_bytes(
                &iroha_executor_data_model::isi::multisig::MultisigProposalState::new(
                    multisig_account_id.clone(),
                    executed_hash,
                    executed_instructions,
                    1_700_000_000_001,
                    4_000_000_000_000,
                    BTreeSet::from([signer_one_id.clone().into(), signer_two_id.clone().into()]),
                    Some(true),
                ),
            )
            .expect("encode executed proposal state"),
        );
        world.smart_contract_state_mut_for_testing().insert(
            multisig_proposal_state_contract_key(&multisig_account_id, &expired_hash),
            norito::to_bytes(
                &iroha_executor_data_model::isi::multisig::MultisigProposalState::new(
                    multisig_account_id.clone(),
                    expired_hash,
                    expired_instructions,
                    1_600_000_000_000,
                    1_600_000_000_001,
                    BTreeSet::new(),
                    None,
                ),
            )
            .expect("encode expired proposal state"),
        );
        for signatory in [signer_one_id.clone().into(), signer_two_id.clone().into()] {
            world.smart_contract_state_mut_for_testing().insert(
                multisig_signatory_index_contract_key(&signatory),
                norito::to_bytes(&BTreeSet::from([multisig_account_id.clone()]))
                    .expect("encode signatory index state"),
            );
        }
        (
            world,
            multisig_account_id,
            signer_one_id.into(),
            signer_two_id.into(),
            alias_literal,
            active_hash.to_string(),
        )
    }

    fn quorum_one_multisig_world() -> (World, dm::AccountId, dm::AccountId, String, KeyPair) {
        let domain_id: DomainId = DomainId::try_new("banka", "universal").expect("domain");
        let label_name: Name = "cbdc".parse().expect("label");
        let alias_literal = format!("{label_name}@{domain_id}");

        let signer =
            checked_multisig_selector_keypair(0x62, "derive quorum-one multisig selector key");
        let signer_id = dm::AccountId::new(signer.public_key().clone());
        let policy = MultisigPolicy::new(
            1,
            vec![MultisigMember::new(signer.public_key().clone(), 1).expect("member")],
        )
        .expect("policy");
        let multisig_id = dm::AccountId::new_multisig(policy);
        let multisig_account_id: dm::AccountId = multisig_id.clone().into();

        let spec = MultisigSpec {
            signatories: BTreeMap::from([(signer_id.clone(), 1_u8)]),
            quorum: NonZeroU16::new(1).expect("quorum"),
            transaction_ttl_ms: NonZeroU64::new(60_000).expect("ttl"),
        };
        let mut multisig_metadata = Metadata::default();
        multisig_metadata.insert(
            Name::from_str(MULTISIG_SPEC_METADATA_KEY).expect("spec key"),
            IrohaJson::new(spec.clone()),
        );

        let authority = signer_id.account().clone();
        let domain = Domain::new(domain_id.clone()).build(&authority);
        let multisig_account = Account::new(multisig_id.account().clone())
            .with_metadata(multisig_metadata)
            .build(&authority);
        let signer_account = Account::new(signer_id.account().clone()).build(&authority);

        let mut world = World::with([domain], [multisig_account, signer_account], []);
        bind_universal_account_alias_on_world_for_test(
            &world,
            &multisig_account_id,
            &alias_literal,
        );
        insert_native_multisig_account_state(
            &mut world,
            &multisig_account_id,
            Some(domain_id),
            &spec,
        );

        (
            world,
            multisig_account_id,
            signer_id.into(),
            alias_literal,
            signer,
        )
    }

    fn minimal_ivm_program(abi_version: u8) -> Vec<u8> {
        let meta = ivm::ProgramMetadata {
            version_major: 1,
            version_minor: 1,
            mode: 0,
            vector_length: 0,
            max_cycles: 1,
            abi_version,
        };
        let mut out = meta.encode();
        let interface = ivm::EmbeddedContractInterfaceV1 {
            seiyaku_name: "TestContract".to_owned(),
            compiler_fingerprint: "torii-tests".to_owned(),
            abi_hash: ivm::syscalls::compute_abi_hash(ivm::SyscallPolicy::AbiV1),
            features_bitmap: 0,
            access_set_hints: None,
            kotoba: Vec::new(),
            entrypoints: vec![ivm::EmbeddedEntrypointDescriptor {
                name: "main".to_owned(),
                kind: iroha_data_model::smart_contract::manifest::EntryPointKind::Kotoage,
                params: Vec::new(),
                argument_schema: None,
                return_type: None,
                return_schema: None,
                permission: Some("CanEnactGovernance".to_owned()),
                read_keys: Vec::new(),
                write_keys: Vec::new(),
                access_hints_complete: Some(true),
                access_hints_skipped: Vec::new(),
                triggers: Vec::new(),
                entry_pc: 0,
            }],
            error_codes: Vec::new(),
            states: Vec::new(),
        };
        out.extend_from_slice(&interface.encode_section());
        out.extend_from_slice(&ivm::encoding::wide::encode_halt().to_le_bytes());
        out
    }

