    fn install_contract_instance(
        state: &State,
        authority: &dm::AccountId,
        authority_keypair: &KeyPair,
        contract_address: &iroha_data_model::smart_contract::ContractAddress,
    ) {
        install_contract_instance_with_code(
            state,
            authority,
            authority_keypair,
            contract_address,
            minimal_ivm_program(1),
            None,
        );
    }

    fn derived_universal_contract_address(
        authority: &dm::AccountId,
        deploy_nonce: u64,
    ) -> iroha_data_model::smart_contract::ContractAddress {
        iroha_data_model::smart_contract::ContractAddress::derive(
            0,
            authority,
            deploy_nonce,
            iroha_data_model::nexus::DataSpaceId::new(0),
        )
        .expect("contract address")
    }

    fn install_contract_instance_with_code(
        state: &State,
        authority: &dm::AccountId,
        authority_keypair: &KeyPair,
        contract_address: &iroha_data_model::smart_contract::ContractAddress,
        code: Vec<u8>,
        contract_alias: Option<iroha_data_model::smart_contract::ContractAlias>,
    ) {
        let mut block = state.block(dm::BlockHeader::new(
            NonZeroU64::new(1).expect("height"),
            None,
            None,
            None,
            0,
            0,
        ));
        let mut stx = block.transaction();

        let register_permission: permission::Permission = CanRegisterSmartContractCode.into();
        Grant::account_permission(register_permission, authority.clone())
            .execute(authority, &mut stx)
            .expect("grant CanRegisterSmartContractCode");

        let enact_permission: permission::Permission = CanEnactGovernance.into();
        Grant::account_permission(enact_permission, authority.clone())
            .execute(authority, &mut stx)
            .expect("grant CanEnactGovernance");

        let verified = ivm::verify_contract_artifact(&code).expect("verify contract artifact");
        let code_hash =
            register_code_bytes(authority, code, &mut stx).expect("register contract bytes");
        assert_eq!(
            verified.code_hash, code_hash,
            "verified code hash must match stored bytes"
        );
        let manifest = verified.manifest.signed(authority_keypair);
        register_manifest(authority, manifest, &mut stx).expect("register manifest");
        activate_instance(authority, contract_address.clone(), code_hash, &mut stx)
            .expect("activate instance");
        if let Some(contract_alias) = contract_alias {
            let alias_dataspace = contract_address
                .dataspace_id()
                .expect("test contract dataspace");
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::account::CanManageAccountAlias {
                        scope: iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Dataspace(
                            alias_dataspace,
                        ),
                    },
                ),
                authority.clone(),
            )
            .execute(authority, &mut stx)
            .expect("grant contract-alias namespace permission");
            iroha_data_model::isi::contract_alias::SetContractAlias::bind(
                contract_address.clone(),
                contract_alias,
                None,
            )
            .execute(authority, &mut stx)
            .expect("bind contract alias");
        }

        stx.apply();
        block.commit().expect("commit block");
    }

    fn expect_not_found(err: Error) {
        match err {
            Error::Query(ValidationFail::QueryFailed(QueryExecutionFail::NotFound)) => {}
            other => panic!("expected not found error, got {other:?}"),
        }
    }

    fn expect_conversion(err: Error) -> String {
        match err {
            Error::Query(ValidationFail::QueryFailed(QueryExecutionFail::Conversion(message))) => {
                message
            }
            other => panic!("expected conversion error, got {other:?}"),
        }
    }

    fn expect_app_validation(err: Error, expected_code: &str) -> String {
        match err {
            Error::AppQueryValidation { code, message } => {
                assert_eq!(code, expected_code);
                message
            }
            other => panic!("expected app validation error, got {other:?}"),
        }
    }

    fn expect_app_not_found(err: Error, expected_code: &str) -> String {
        match err {
            Error::AppNotFound { code, message } => {
                assert_eq!(code, expected_code);
                message
            }
            other => panic!("expected app not-found error, got {other:?}"),
        }
    }

    fn expect_app_conflict(err: Error, expected_code: &str) -> String {
        match err {
            Error::AppConflict { code, message } => {
                assert_eq!(code, expected_code);
                message
            }
            other => panic!("expected app conflict error, got {other:?}"),
        }
    }

    async fn decode_json_response(resp: Response) -> norito::json::Value {
        let body = resp
            .into_body()
            .collect()
            .await
            .expect("collect body")
            .to_bytes();
        norito::json::from_slice(&body).expect("json body")
    }

