    #[test]
    fn multisig_proposal_selector_requires_exactly_one_canonical_hash() {
        let instructions: Vec<dm::InstructionBox> =
            vec![dm::Log::new(dm::Level::INFO, "x".to_owned()).into()];
        let canonical = HashOf::new(&instructions).to_string();
        assert_eq!(
            resolve_multisig_proposal_hash(Some(canonical.clone()), None)
                .expect("canonical proposal id")
                .0,
            canonical
        );

        for (proposal_id, instructions_hash) in [
            (None, None),
            (Some(canonical.clone()), Some(canonical.clone())),
            (Some(format!(" {canonical}")), None),
            (Some("not-a-hash".to_owned()), None),
        ] {
            let error = resolve_multisig_proposal_hash(proposal_id, instructions_hash)
                .expect_err("ambiguous or noncanonical selector must fail");
            assert!(matches!(
                error,
                Error::AppQueryValidation {
                    code: "multisig_selector_invalid",
                    ..
                }
            ));
        }
    }

    #[test]
    fn multisig_read_json_contracts_reject_unknown_top_level_fields() {
        let cases = [
            (
                "spec",
                r#"{"multisig_account_alias":"cbdc@banka.universal","unexpected":true}"#,
            ),
            (
                "query",
                r#"{"multisig_account_alias":"cbdc@banka.universal","status":[],"unexpected":true}"#,
            ),
            (
                "resolve",
                r#"{"multisig_account_alias":"cbdc@banka.universal","proposal_id":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","unexpected":true}"#,
            ),
        ];
        for (kind, body) in cases {
            let rejected = match kind {
                "spec" => norito::json::from_str::<MultisigSpecRequestDto>(body).is_err(),
                "query" => {
                    norito::json::from_str::<MultisigProposalsQueryRequestDto>(body).is_err()
                }
                "resolve" => {
                    norito::json::from_str::<MultisigProposalsResolveRequestDto>(body).is_err()
                }
                _ => unreachable!(),
            };
            assert!(rejected, "{kind} must reject unknown fields");
        }
    }

    #[test]
    fn multisig_read_json_contracts_reject_duplicate_selectors() {
        let proposal_id = "a".repeat(64);
        let cases = [
            (
                "spec authority",
                r#"{"multisig_account_alias":"cbdc@banka.universal","multisig_account_alias":"cbdc@banka.universal"}"#.to_owned(),
            ),
            (
                "query authority",
                r#"{"multisig_account_alias":"cbdc@banka.universal","multisig_account_alias":"cbdc@banka.universal","status":[]}"#.to_owned(),
            ),
            (
                "resolve proposal",
                format!(
                    r#"{{"multisig_account_alias":"cbdc@banka.universal","proposal_id":"{proposal_id}","proposal_id":"{proposal_id}"}}"#,
                ),
            ),
        ];
        for (kind, body) in cases {
            let rejected = match kind {
                "spec authority" => {
                    norito::json::from_str::<MultisigSpecRequestDto>(&body).is_err()
                }
                "query authority" => {
                    norito::json::from_str::<MultisigProposalsQueryRequestDto>(&body).is_err()
                }
                "resolve proposal" => {
                    norito::json::from_str::<MultisigProposalsResolveRequestDto>(&body).is_err()
                }
                _ => unreachable!(),
            };
            assert!(rejected, "{kind} must reject duplicate selector fields");
        }
    }

    #[test]
    fn multisig_contract_call_json_contracts_reject_unknown_top_level_fields() {
        let account = checked_multisig_selector_account_id(
            0x76,
            "derive strict contract-call DTO fixture account",
        )
        .to_string();
        let propose = format!(
            r#"{{"multisig_account_id":"{account}","signer_account_id":"{account}","contract_alias":"pkdeploy_issuance_swap_sbp::sbp","entrypoint":"swap","payload":{{"swap_id":"swap_1","pkr_amount":"7600","treasury_amount":"100"}},"fee_payment":{{"payer":"authority","value":{{"charge_limits":[],"gas_limit":10000}}}},"fee_sponsor":"{account}"}}"#,
        );
        assert!(
            norito::json::from_str::<MultisigContractCallProposeDto>(&propose).is_err(),
            "contract-call propose must reject the retired fee_sponsor field",
        );

        let approve = format!(
            r#"{{"multisig_account_id":"{account}","signer_account_id":"{account}","proposal_id":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","fee_payment":{{"payer":"authority","value":{{"charge_limits":[]}}}},"gas_asset_id":"xor#sora"}}"#,
        );
        assert!(
            norito::json::from_str::<MultisigContractCallApproveDto>(&approve).is_err(),
            "contract-call approve must reject the retired gas_asset_id field",
        );

        let direct = format!(
            r#"{{"authority":"{account}","contract_alias":"pkdeploy_issuance_swap_sbp::sbp","entrypoint":"swap","fee_payment":{{"payer":"authority","value":{{"charge_limits":[],"gas_limit":10000}}}},"gas_limit":10000}}"#,
        );
        assert!(
            norito::json::from_str::<ContractCallDto>(&direct).is_err(),
            "direct contract call must reject the retired metadata gas_limit field",
        );
        let simulate = format!(
            r#"{{"authority":"{account}","contract_alias":"pkdeploy_issuance_swap_sbp::sbp","entrypoint":"swap","gas_limit":10000,"fee_sponsor":"{account}"}}"#,
        );
        assert!(
            norito::json::from_str::<ContractCallSimulateDto>(&simulate).is_err(),
            "contract simulation must reject fee-payer selection",
        );
    }

