#[cfg(feature = "app_api")]
fn multisig_proposals_resolve_response(
    state: &Arc<CoreState>,
    req: &MultisigProposalsResolveRequestDto,
    resolve_authority: Option<&AccountId>,
) -> Result<MultisigProposalResolveResponseDto> {
    let (resolved_multisig_account_id, spec) =
        resolve_multisig_account_and_spec(state, &req.selector, resolve_authority)?;
    let (hash_literal, instructions_hash) =
        resolve_multisig_proposal_hash(req.proposal_id.clone(), req.instructions_hash.clone())?;
    let proposal_record = load_multisig_proposal_record(
        state,
        &resolved_multisig_account_id,
        &spec,
        &instructions_hash,
    )?
    .filter(|record| multisig_proposal_is_user_visible(&record.proposal))
    .ok_or_else(multisig_not_found_error)?;
    let world = state.world_view();
    let operation_type = multisig_proposal_operation_type(
        &world,
        &resolved_multisig_account_id,
        &proposal_record.proposal,
    )
    .to_owned();
    let intent = multisig_proposal_intent(
        &world,
        &resolved_multisig_account_id,
        &proposal_record.proposal,
    );
    Ok(MultisigProposalResolveResponseDto {
        resolved_multisig_account_id,
        proposal_id: hash_literal.clone(),
        instructions_hash: hash_literal,
        operation_type,
        intent,
        proposal: proposal_record.proposal,
        status: proposal_record.status.as_str().to_owned(),
        terminal_at_ms: proposal_record.terminal_at_ms,
    })
}

#[cfg(feature = "app_api")]
fn format_unix_timestamp_ms_rfc3339(value: u64) -> Result<String> {
    let timestamp = OffsetDateTime::from_unix_timestamp_nanos(i128::from(value) * 1_000_000)
        .map_err(|err| conversion_error(format!("invalid unix timestamp: {err}")))?;
    timestamp
        .format(&Rfc3339)
        .map_err(|err| conversion_error(format!("failed to format timestamp: {err}")))
}

#[cfg(feature = "app_api")]
fn load_asset_transfer_control_store(
    account_id: &iroha_data_model::account::AccountId,
    metadata: &iroha_data_model::metadata::Metadata,
) -> Result<iroha_data_model::asset::AssetTransferControlStoreV1> {
    let metadata_key = iroha_data_model::name::Name::from_str(
        iroha_data_model::asset::ASSET_TRANSFER_CONTROL_METADATA_KEY,
    )
    .map_err(|err| conversion_error(format!("invalid control metadata key: {err}")))?;
    let Some(raw) = metadata.get(&metadata_key) else {
        return Ok(iroha_data_model::asset::AssetTransferControlStoreV1::default());
    };
    raw.try_into_any_norito::<iroha_data_model::asset::AssetTransferControlStoreV1>()
        .map_err(|err| {
            conversion_error(format!(
                "invalid account metadata `{}` on {}: {err}",
                iroha_data_model::asset::ASSET_TRANSFER_CONTROL_METADATA_KEY,
                account_id
            ))
        })
}

#[cfg(feature = "app_api")]
pub async fn handle_post_asset_transfer_control_get(
    state: Arc<CoreState>,
    NoritoJson(req): NoritoJson<AssetTransferControlGetRequestDto>,
) -> Result<JsonBody<AssetTransferControlGetResponseDto>> {
    let world = state.world_view();
    let account = world
        .account(&req.account_id)
        .map_err(|_| conversion_error(format!("account not found: {}", req.account_id)))?;
    world
        .asset_definition(&req.asset_definition_id)
        .map_err(|_| {
            conversion_error(format!(
                "asset definition not found: {}",
                req.asset_definition_id
            ))
        })?;

    let store = load_asset_transfer_control_store(account.id(), account.metadata())?;
    let record = store.find(&req.asset_definition_id).cloned().unwrap_or(
        iroha_data_model::asset::AssetTransferControlRecord {
            asset_definition_id: req.asset_definition_id.clone(),
            outgoing_frozen: false,
            blacklisted: false,
            holding_limit: None,
            limits: Vec::new(),
            usages: Vec::new(),
            updated_at_ms: None,
        },
    );

    let cap_by_window = record
        .limits
        .iter()
        .map(|limit| (limit.window, limit.cap_amount.clone()))
        .collect::<BTreeMap<_, _>>();

    let limits = record
        .limits
        .iter()
        .map(|limit| AssetTransferControlLimitDto {
            window: limit.window.as_str().to_owned(),
            cap_amount: limit.cap_amount.clone(),
        })
        .collect::<Vec<_>>();

    let mut usages = record
        .usages
        .iter()
        .map(|usage| {
            Ok(AssetTransferUsageBucketDto {
                window: usage.window.as_str().to_owned(),
                bucket_start: format_unix_timestamp_ms_rfc3339(usage.bucket_start_ms)?,
                spent_amount: usage.spent_amount.clone(),
                cap_amount: cap_by_window.get(&usage.window).cloned().flatten(),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    usages.sort_by(|left, right| {
        left.window
            .cmp(&right.window)
            .then_with(|| left.bucket_start.cmp(&right.bucket_start))
    });

    Ok(JsonBody(AssetTransferControlGetResponseDto {
        control: AssetTransferControlDto {
            account_id: req.account_id,
            asset_definition_id: req.asset_definition_id,
            outgoing_frozen: record.outgoing_frozen,
            blacklisted: record.blacklisted,
            holding_limit: record.holding_limit,
            limits,
            updated_at: record
                .updated_at_ms
                .map(format_unix_timestamp_ms_rfc3339)
                .transpose()?,
        },
        usages,
    }))
}

/// Fetch proof verification record by proof id.
#[iroha_futures::telemetry_future]
pub async fn handle_get_proof_record(
    state: Arc<CoreState>,
    axum::extract::Path(id_str): axum::extract::Path<String>,
) -> Result<NoritoBody<iroha_data_model::proof::ProofRecord>> {
    use core::str::FromStr as _;
    let id = iroha_data_model::proof::ProofId::from_str(&id_str).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "invalid proof id: {e}"
            )),
        ))
    })?;
    let view = state.query_view();
    let rec = view.world().proofs().get(&id).cloned().ok_or_else(|| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        ))
    })?;
    Ok(NoritoBody(rec))
}

fn compute_prunable_proofs(
    mut items: Vec<(iroha_data_model::proof::ProofId, u64)>,
    cap: usize,
    grace_blocks: u64,
    prune_batch: usize,
    current_height: u64,
) -> Vec<iroha_data_model::proof::ProofId> {
    if items.is_empty() {
        return Vec::new();
    }
    items.sort_by(|(id_a, height_a), (id_b, height_b)| {
        height_a.cmp(height_b).then_with(|| id_a.cmp(id_b))
    });
    let retention_floor = if grace_blocks == 0 {
        u64::MAX
    } else {
        current_height.saturating_sub(grace_blocks)
    };

    let mut removals = Vec::new();
    let mut retained = Vec::new();

    for (id, height) in items {
        if grace_blocks > 0 && height < retention_floor {
            removals.push(id);
        } else {
            retained.push((id, height));
        }
    }

    if cap > 0 && retained.len() > cap {
        let overflow = retained.len() - cap;
        removals.extend(retained.into_iter().take(overflow).map(|(id, _)| id));
    }

    if prune_batch > 0 && removals.len() > prune_batch {
        removals.truncate(prune_batch);
    }
    removals
}

/// Report proof retention configuration and current counts.
pub fn handle_proof_retention_status(
    state: Arc<CoreState>,
) -> iroha_torii_shared::ProofRetentionStatus {
    let world = state.world_view();
    let height_hint = u64::try_from(state.committed_height()).unwrap_or(0);
    let cap = state.zk.proof_history_cap;
    let grace_blocks = state.zk.proof_retention_grace_blocks;
    let prune_batch = state.zk.proof_prune_batch;

    let mut per_backend: std::collections::BTreeMap<
        String,
        Vec<(iroha_data_model::proof::ProofId, u64)>,
    > = std::collections::BTreeMap::new();
    for (id, record) in world.proofs().iter() {
        let height = record.verified_at_height.unwrap_or(0);
        per_backend
            .entry(id.backend.clone())
            .or_default()
            .push((id.clone(), height));
    }

    let mut backends = Vec::new();
    let mut total_records: u64 = 0;
    let mut total_prunable: u64 = 0;

    for (backend, entries) in per_backend {
        let prunable =
            compute_prunable_proofs(entries.clone(), cap, grace_blocks, prune_batch, height_hint);
        let mut oldest: Option<u64> = None;
        let mut newest: Option<u64> = None;
        for (_, height) in &entries {
            if let Some(old) = oldest {
                if *height < old {
                    oldest = Some(*height);
                }
            } else {
                oldest = Some(*height);
            }
            if let Some(new) = newest {
                if *height > new {
                    newest = Some(*height);
                }
            } else {
                newest = Some(*height);
            }
        }

        total_records += entries.len() as u64;
        total_prunable += prunable.len() as u64;

        backends.push(iroha_torii_shared::ProofRetentionBackendStatus {
            backend,
            records: entries.len() as u64,
            prunable: prunable.len() as u64,
            oldest_height: oldest,
            newest_height: newest,
        });
    }

    backends.sort_by(|a, b| a.backend.cmp(&b.backend));

    iroha_torii_shared::ProofRetentionStatus {
        cap_per_backend: cap,
        grace_blocks,
        prune_batch,
        total_records,
        total_prunable,
        backends,
    }
}

#[cfg(feature = "app_api")]
#[derive(
    Debug,
    crate::json_macros::JsonDeserialize,
    norito::derive::NoritoDeserialize,
    crate::json_macros::JsonSerialize,
    norito::derive::NoritoSerialize,
)]
/// DTO for registering a verifying key
pub struct ZkVkRegisterDto {
    /// Account authorizing the operation
    pub authority: iroha_data_model::account::AccountId,
    /// Exposed private key used to sign the transaction
    pub private_key: iroha_data_model::prelude::ExposedPrivateKey,
    /// Verifier backend identifier (e.g., “groth16”)
    pub backend: String,
    /// Verifying key name within the backend namespace
    pub name: String,
    /// Version number of the verifying key
    pub version: u32,
    /// Circuit identifier associated with the verifying key.
    pub circuit_id: String,
    /// Hex-encoded 32-byte hash of the public inputs schema.
    pub public_inputs_schema_hash_hex: String,
    /// Optional curve label; defaults to `unknown`.
    #[norito(default)]
    pub curve: Option<String>,
    /// Optional gas schedule identifier attached to the verifier.
    #[norito(default)]
    pub gas_schedule_id: Option<String>,
    /// Optional declared verifying key length; required when `vk_bytes` is omitted.
    #[norito(default)]
    pub vk_len: Option<u32>,
    /// Optional maximum proof byte length accepted by this verifier.
    #[norito(default)]
    pub max_proof_bytes: Option<u32>,
    /// Optional metadata URI (CID) describing the verifier artefacts.
    #[norito(default)]
    pub metadata_uri_cid: Option<String>,
    /// Optional URI (CID) pointing to the verifying key bundle.
    #[norito(default)]
    pub vk_bytes_cid: Option<String>,
    /// Optional activation height (inclusive) for the verifier.
    #[norito(default)]
    pub activation_height: Option<u64>,
    /// Optional withdraw height after which the verifier must not be used.
    #[norito(default)]
    pub withdraw_height: Option<u64>,
    /// Optional hex-encoded 32-byte commitment. If `vk_bytes` is present, commitment
    /// is computed from bytes and backend and this field is ignored (or validated if provided).
    #[norito(default)]
    pub commitment_hex: Option<String>,
    /// Optional verifying key bytes (base64). When present, the commitment is computed server-side.
    #[norito(with = "base64_bytes")]
    #[norito(default)]
    pub vk_bytes: Option<Vec<u8>>,
    /// Optional status; defaults to Active
    #[norito(default)]
    pub status: Option<iroha_data_model::confidential::ConfidentialStatus>,
}

