#[cfg(feature = "app_api")]
fn prepare_contract_call(
    state: &CoreState,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
    contract_alias: Option<iroha_data_model::smart_contract::ContractAlias>,
) -> core::result::Result<PreparedContractCall, Error> {
    let world = state.world_view();
    let binding = world
        .contract_instances()
        .get(contract_address)
        .copied()
        .ok_or_else(|| {
            contract_not_found_error(
                "contract_instance_not_found",
                format!("contract instance `{contract_address}` is not active"),
            )
        })?;

    let code_bytes = world.contract_code().get(&binding).ok_or_else(|| {
        contract_not_found_error(
            "contract_code_not_found",
            format!(
                "contract code `{}` is not available",
                hex::encode(binding.as_ref())
            ),
        )
    })?;

    let program = state
        .prepare_contract_query_program(binding, code_bytes.as_ref())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    let dataspace_id = contract_address
        .dataspace_id()
        .map_err(|err| conversion_error(err.to_string()))?;
    let dataspace = state
        .nexus_snapshot()
        .dataspace_catalog
        .by_id(dataspace_id)
        .map(|entry| entry.alias.clone())
        .ok_or_else(|| {
            contract_not_found_error(
                "contract_dataspace_not_found",
                format!(
                    "contract dataspace `{}` is not in the active catalog",
                    dataspace_id
                ),
            )
        })?;
    let manifest = world
        .contract_manifests()
        .get(&binding)
        .cloned()
        .ok_or_else(|| {
            contract_not_found_error(
                "contract_manifest_not_found",
                format!(
                    "contract manifest for code `{}` is not available",
                    hex::encode(binding.as_ref())
                ),
            )
        })?;
    if manifest.signature_payload() != program.prepared_contract().manifest().signature_payload() {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "stored manifest does not match the verified contract artifact".into(),
            ),
        )));
    }

    Ok(PreparedContractCall {
        abi_hash: program.abi_hash,
        program,
        code_hash: binding,
        manifest,
        dataspace,
        contract_address: contract_address.clone(),
        contract_alias,
    })
}

#[cfg(feature = "app_api")]
fn prepare_contract_call_by_address(
    state: &CoreState,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
) -> core::result::Result<PreparedContractCall, Error> {
    prepare_contract_call(state, contract_address, None)
}

#[cfg(feature = "app_api")]
fn prepare_contract_call_by_alias(
    state: &CoreState,
    contract_alias: &iroha_data_model::smart_contract::ContractAlias,
    now_ms: u64,
) -> core::result::Result<PreparedContractCall, Error> {
    let world = state.world_view();
    let contract_address = world
        .contract_address_by_alias_at(contract_alias, now_ms)
        .ok_or_else(|| {
            contract_not_found_error(
                "contract_alias_not_found",
                format!("contract alias `{contract_alias}` is not active"),
            )
        })?;
    prepare_contract_call(state, &contract_address, Some(contract_alias.clone()))
}

#[cfg(feature = "app_api")]
fn resolve_contract_call_target(
    state: &CoreState,
    contract_address: Option<&iroha_data_model::smart_contract::ContractAddress>,
    contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
) -> core::result::Result<PreparedContractCall, Error> {
    match (contract_address, contract_alias) {
        (Some(_), Some(_)) => Err(conversion_error(
            "exactly one of contract_address or contract_alias must be provided".to_owned(),
        )),
        (Some(contract_address), None) => prepare_contract_call_by_address(state, contract_address),
        (None, Some(contract_alias)) => {
            prepare_contract_call_by_alias(state, contract_alias, current_time_millis())
        }
        _ => Err(conversion_error(
            "provide exactly one contract target via contract_address or contract_alias".to_owned(),
        )),
    }
}

#[cfg(feature = "app_api")]
fn dataspace_alias_for_contract_address(
    state: &CoreState,
    contract_address: &iroha_data_model::smart_contract::ContractAddress,
) -> core::result::Result<String, Error> {
    let dataspace_id = contract_address
        .dataspace_id()
        .map_err(|err| conversion_error(err.to_string()))?;
    state
        .nexus_snapshot()
        .dataspace_catalog
        .by_id(dataspace_id)
        .map(|entry| entry.alias.clone())
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::NotFound,
            ))
        })
}

