    fn signed_capacity_transaction(
        chain_id: &ChainId,
        authority_key: &iroha_crypto::KeyPair,
        signing_key: &iroha_crypto::KeyPair,
        instructions: impl IntoIterator<Item = dm::InstructionBox>,
    ) -> SignedTransaction {
        dm::TransactionBuilder::new(
            chain_id.clone(),
            dm::AccountId::new(authority_key.public_key().clone()).into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions(instructions)
        .sign(signing_key.private_key())
    }

    fn signed_capacity_declaration_transaction(
        chain_id: &ChainId,
        key_pair: &iroha_crypto::KeyPair,
        record: CapacityDeclarationRecord,
    ) -> SignedTransaction {
        signed_capacity_transaction(
            chain_id,
            key_pair,
            key_pair,
            [dm::InstructionBox::from(
                iroha_data_model::isi::sorafs::RegisterCapacityDeclaration::new(record),
            )],
        )
    }

    fn signed_capacity_telemetry_transaction(
        chain_id: &ChainId,
        key_pair: &iroha_crypto::KeyPair,
        record: CapacityTelemetryRecord,
    ) -> SignedTransaction {
        signed_capacity_transaction(
            chain_id,
            key_pair,
            key_pair,
            [dm::InstructionBox::from(
                iroha_data_model::isi::sorafs::RecordCapacityTelemetry::new(record),
            )],
        )
    }

    fn capacity_validation_code(error: Error) -> &'static str {
        match error {
            Error::AppQueryValidation { code, .. } => code,
            other => panic!("expected capacity validation error, got {other:?}"),
        }
    }

    fn sample_por_artifacts() -> (PorChallengeV1, PorProofV1, AuditVerdictV1) {
        use ed25519_dalek::{Signer as _, SigningKey};

        let descriptor = sorafs_manifest::chunker_registry::default_descriptor();
        let chunker_handle = format!(
            "{}.{}@{}",
            descriptor.namespace, descriptor.name, descriptor.semver
        );
        let manifest_digest = [0xB2; 32];
        let provider_id = [0xC3; 32];
        let epoch_id = 222;
        let drand_round = 333;
        let drand_randomness = [0xDD; 32];
        let vrf_output = [0xEE; 32];
        let seed = derive_challenge_seed(
            &drand_randomness,
            Some(&vrf_output),
            &manifest_digest,
            epoch_id,
        );
        let challenge_id =
            derive_challenge_id(&seed, &manifest_digest, &provider_id, epoch_id, drand_round);

        let challenge = PorChallengeV1 {
            version: POR_CHALLENGE_VERSION_V1,
            challenge_id,
            manifest_digest,
            provider_id,
            epoch_id,
            drand_round,
            drand_randomness,
            drand_signature: [0xF1; 48],
            vrf_output: Some(vrf_output),
            vrf_proof: Some(iroha_crypto::vrf::VrfProof::SigInG1([0xF2; 48])),
            forced: false,
            chunking_profile: chunker_handle,
            seed,
            sample_tier: 1,
            sample_count: 1,
            sample_indices: vec![0],
            issued_at: 1_700_000_000,
            deadline_at: 1_700_000_600,
        };

        let provider_key = SigningKey::from_bytes(&[0x44; 32]);
        let mut proof = PorProofV1 {
            version: POR_PROOF_VERSION_V1,
            challenge_id: challenge.challenge_id,
            manifest_digest: challenge.manifest_digest,
            provider_id: challenge.provider_id,
            samples: vec![PorProofSampleV1 {
                sample_index: 0,
                chunk_offset: 0,
                chunk_size: 65_536,
                chunk_digest: [0x11; 32],
                leaf_digest: [0x22; 32],
            }],
            auth_path: vec![[0x33; 32]],
            signature: sorafs_manifest::provider_advert::AdvertSignature {
                algorithm: sorafs_manifest::provider_advert::SignatureAlgorithm::Ed25519,
                public_key: provider_key.verifying_key().to_bytes().to_vec(),
                signature: vec![0; 64],
            },
            submitted_at: 1_700_000_100,
        };
        let proof_payload = proof
            .signature_payload_bytes()
            .expect("encode PoR proof signing payload");
        proof.signature.signature = provider_key.sign(&proof_payload).to_bytes().to_vec();

        let auditor_key = SigningKey::from_bytes(&[0x66; 32]);
        let mut verdict = AuditVerdictV1 {
            version: AUDIT_VERDICT_VERSION_V1,
            manifest_digest: challenge.manifest_digest,
            provider_id: challenge.provider_id,
            challenge_id: challenge.challenge_id,
            proof_digest: Some(proof.proof_digest()),
            outcome: AuditOutcomeV1::Success,
            failure_reason: None,
            decided_at: 1_700_000_200,
            auditor_signatures: vec![sorafs_manifest::provider_advert::AdvertSignature {
                algorithm: sorafs_manifest::provider_advert::SignatureAlgorithm::Ed25519,
                public_key: auditor_key.verifying_key().to_bytes().to_vec(),
                signature: vec![0; 64],
            }],
            metadata: Vec::new(),
        };
        let verdict_payload = verdict
            .signature_payload_bytes()
            .expect("encode PoR verdict signing payload");
        verdict.auditor_signatures[0].signature =
            auditor_key.sign(&verdict_payload).to_bytes().to_vec();

        (challenge, proof, verdict)
    }

    pub(super) fn build_por_challenge(
        salt: u8,
        provider_id: [u8; 32],
        epoch_id: u64,
        issued_at: u64,
    ) -> PorChallengeV1 {
        let descriptor = sorafs_manifest::chunker_registry::default_descriptor();
        let chunker_handle = format!(
            "{}.{}@{}",
            descriptor.namespace, descriptor.name, descriptor.semver
        );
        let manifest_digest = [salt; 32];
        let drand_randomness = [salt.wrapping_add(1); 32];
        let vrf_output = [salt.wrapping_add(2); 32];
        let drand_round = epoch_id + u64::from(salt);
        let seed = derive_challenge_seed(
            &drand_randomness,
            Some(&vrf_output),
            &manifest_digest,
            epoch_id,
        );
        let challenge_id =
            derive_challenge_id(&seed, &manifest_digest, &provider_id, epoch_id, drand_round);
        PorChallengeV1 {
            version: POR_CHALLENGE_VERSION_V1,
            challenge_id,
            manifest_digest,
            provider_id,
            epoch_id,
            drand_round,
            drand_randomness,
            drand_signature: [salt.wrapping_add(3); 48],
            vrf_output: Some(vrf_output),
            vrf_proof: Some(iroha_crypto::vrf::VrfProof::SigInG1(
                [salt.wrapping_add(4); 48],
            )),
            forced: false,
            chunking_profile: chunker_handle,
            seed,
            sample_tier: 1,
            sample_count: 1,
            sample_indices: vec![0],
            issued_at,
            deadline_at: issued_at + 600,
        }
    }

