#[cfg(feature = "app_api")]
pub fn parse_account_path_segment(
    literal: &str,
    telemetry: &MaybeTelemetry,
    endpoint: &'static str,
) -> Result<(iroha_data_model::account::AccountId, String), Error> {
    use iroha_data_model::query::error::QueryExecutionFail;

    parse_account_literal(literal, telemetry, endpoint)
        .map(|parsed| {
            let (account_id, canonical, _) = parsed.into_parts();
            (account_id, canonical)
        })
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                QueryExecutionFail::Conversion(format!(
                    "invalid account_id `{literal}`: {}",
                    err.reason()
                )),
            ))
        })
}

pub(crate) fn parse_account_literal_with_state(
    _state: &CoreState,
    literal: &str,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<(iroha_data_model::account::AccountId, String), iroha_data_model::error::ParseError> {
    match AccountId::parse_encoded(literal) {
        Ok(parsed) => {
            let (account_id, canonical, _) = parsed.into_parts();
            if literal != canonical {
                let err = iroha_data_model::error::ParseError::new(
                    "account id must use its exact canonical I105 literal",
                );
                record_account_literal_reject(telemetry, context, literal, err.reason());
                return Err(err);
            }
            record_account_literal_accept(telemetry, context, &account_id);
            Ok((account_id, canonical))
        }
        Err(base_err) => {
            // This generic parser deliberately accepts account IDs only. Alias resolution is a
            // permissioned operation and must use a caller-aware path that verifies the exact
            // applicable domain or dataspace `CanResolveAccountAlias` grant before consulting
            // active SNS state.
            record_account_literal_reject(telemetry, context, literal, base_err.reason());
            Err(base_err)
        }
    }
}

#[cfg(feature = "app_api")]
pub(crate) fn parse_account_path_segment_with_state(
    state: &CoreState,
    literal: &str,
    telemetry: &MaybeTelemetry,
    endpoint: &'static str,
) -> Result<(iroha_data_model::account::AccountId, String), Error> {
    use iroha_data_model::{ValidationFail, query::error::QueryExecutionFail};

    parse_account_literal_with_state(state, literal, telemetry, endpoint).map_err(|err| {
        Error::Query(ValidationFail::QueryFailed(QueryExecutionFail::Conversion(
            format!("invalid account_id `{literal}`: {}", err.reason()),
        )))
    })
}

#[cfg(feature = "app_api")]
pub fn parse_lane_id_literal(literal: &str) -> Result<LaneId, Error> {
    use iroha_data_model::{ValidationFail, query::error::QueryExecutionFail};

    let trimmed = literal.trim();
    let parsed = trimmed.parse::<u32>().map_err(|_| {
        Error::Query(ValidationFail::QueryFailed(QueryExecutionFail::Conversion(
            format!("invalid lane id literal `{trimmed}`"),
        )))
    })?;
    Ok(LaneId::new(parsed))
}

#[cfg(feature = "app_api")]
fn canonicalize_account_literal_value(
    value: &mut norito::json::Value,
    state: Option<&CoreState>,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<(), Error> {
    use iroha_data_model::{ValidationFail, query::error::QueryExecutionFail};

    match value {
        norito::json::Value::String(literal) => {
            let current_literal = literal.clone();
            let parsed = match state {
                Some(state) => parse_account_literal_with_state(
                    state,
                    current_literal.as_str(),
                    telemetry,
                    context,
                )
                .map(|(_, canonical)| canonical),
                None => parse_account_literal(current_literal.as_str(), telemetry, context).map(
                    |parsed| {
                        let (_, canonical, _) = parsed.into_parts();
                        canonical
                    },
                ),
            };
            match parsed {
                Ok(parsed) => {
                    *literal = parsed;
                    Ok(())
                }
                Err(err) => Err(Error::Query(ValidationFail::QueryFailed(
                    QueryExecutionFail::Conversion(format!(
                        "invalid account filter literal `{current_literal}`: {}",
                        err.reason()
                    )),
                ))),
            }
        }
        _ => Err(Error::Query(ValidationFail::TooComplex)),
    }
}

#[cfg(feature = "app_api")]
fn scoped_accounts_for_subject_sorted(
    world: &impl WorldReadOnly,
    parsed_account: &AccountId,
) -> Vec<AccountId> {
    let subject = parsed_account.subject_id();
    let mut accounts: Vec<AccountId> = world
        .accounts_for_subject_iter(&subject)
        .map(|entry| entry.id().clone())
        .collect();
    if accounts.is_empty() {
        accounts.push(parsed_account.clone());
    }
    accounts.sort_by(|left, right| left.controller().cmp(right.controller()));
    accounts.dedup();
    accounts
}

#[cfg(feature = "app_api")]
fn canonicalize_filter_account_literals(
    expr: &mut FilterExpr,
    field_name: &str,
    state: Option<&CoreState>,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<(), Error> {
    use crate::filter::FilterExpr as F;

    match expr {
        F::And(list) | F::Or(list) => {
            for e in list {
                canonicalize_filter_account_literals(e, field_name, state, telemetry, context)?;
            }
            Ok(())
        }
        F::Not(inner) => {
            canonicalize_filter_account_literals(inner, field_name, state, telemetry, context)
        }
        F::Eq(field, value) | F::Ne(field, value) => {
            if field.0.as_str() == field_name {
                canonicalize_account_literal_value(value, state, telemetry, context)
            } else {
                Ok(())
            }
        }
        F::In(field, list) | F::Nin(field, list) => {
            if field.0.as_str() == field_name {
                for value in list {
                    canonicalize_account_literal_value(value, state, telemetry, context)?;
                }
            }
            Ok(())
        }
        F::Exists(_) | F::IsNull(_) | F::Lt(_, _) | F::Lte(_, _) | F::Gt(_, _) | F::Gte(_, _) => {
            Ok(())
        }
    }
}

#[cfg(feature = "app_api")]
fn canonicalize_accounts_filter_literals(
    expr: &mut FilterExpr,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<()> {
    canonicalize_filter_account_literals(expr, "id", None, telemetry, context)
}

#[cfg(feature = "app_api")]
fn canonicalize_accounts_filter_literals_with_state(
    expr: &mut FilterExpr,
    state: &CoreState,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<()> {
    canonicalize_filter_account_literals(expr, "id", Some(state), telemetry, context)
}

#[cfg(feature = "app_api")]
fn canonicalize_repo_filter_literals(
    expr: &mut FilterExpr,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<()> {
    for field in ["initiator", "counterparty", "custodian"] {
        canonicalize_filter_account_literals(expr, field, None, telemetry, context)?;
    }
    Ok(())
}

#[cfg(feature = "app_api")]
fn canonicalize_query_account_literal(
    label: &'static str,
    literal: Option<&str>,
    state: Option<&CoreState>,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<Option<String>> {
    use iroha_data_model::{ValidationFail, query::error::QueryExecutionFail};

    literal
        .map(|raw| {
            let canonical = match state {
                Some(state) => parse_account_literal_with_state(state, raw, telemetry, context)
                    .map(|(_, canonical)| canonical),
                None => parse_account_literal(raw, telemetry, context).map(|parsed| {
                    let (_, canonical, _) = parsed.into_parts();
                    canonical
                }),
            };
            canonical.map_err(|err| {
                Error::Query(ValidationFail::QueryFailed(QueryExecutionFail::Conversion(
                    format!("invalid `{label}` literal `{raw}`: {}", err.reason()),
                )))
            })
        })
        .transpose()
}

pub fn parse_account_literal(
    literal: &str,
    telemetry: &MaybeTelemetry,
    context: &'static str,
) -> Result<iroha_data_model::account::ParsedAccountId, iroha_data_model::error::ParseError> {
    match AccountId::parse_encoded(literal) {
        Ok(parsed) => {
            record_account_literal_accept(telemetry, context, parsed.account_id());
            Ok(parsed)
        }
        Err(err) => {
            record_account_literal_reject(telemetry, context, literal, err.reason());
            Err(err)
        }
    }
}

fn record_account_literal_accept(
    telemetry: &MaybeTelemetry,
    context: &'static str,
    _account_id: &AccountId,
) {
    telemetry.with_metrics(|metrics| {
        metrics.inc_torii_address_domain(context, "default");
    });
}

fn record_account_literal_reject(
    telemetry: &MaybeTelemetry,
    context: &'static str,
    literal: &str,
    reason: &'static str,
) {
    telemetry.with_metrics(|metrics| {
        if literal_is_local8(literal) {
            metrics.inc_torii_address_domain(context, "local8");
            if let Some(domain_label) = local8_domain_label(literal) {
                metrics.inc_torii_address_domain(context, &domain_label);
            }
        }
        metrics.inc_torii_address_invalid(context, reason);
    });
}

fn local8_domain_label(literal: &str) -> Option<String> {
    use iroha_data_model::domain::DomainId;

    let trimmed = literal.trim();
    let (_, domain_part) = trimmed.rsplit_once('@')?;
    let parsed = DomainId::parse_fully_qualified(domain_part).ok()?;
    Some(parsed.to_string())
}

fn literal_is_local8(literal: &str) -> bool {
    let trimmed = literal.trim_start();
    let address_part = trimmed
        .split_once('@')
        .map(|(address, _)| address)
        .unwrap_or(trimmed);
    address_part
        .to_ascii_lowercase()
        .trim_start_matches("0x")
        .starts_with("sn1")
}

#[cfg(feature = "app_api")]
fn explorer_qr_error(err: iroha_torii_shared::qr::QrError) -> Error {
    use iroha_data_model::query::error::QueryExecutionFail;

    Error::Query(ValidationFail::QueryFailed(QueryExecutionFail::Conversion(
        format!("failed to render account QR: {err}"),
    )))
}

#[cfg(all(test, feature = "app_api", feature = "telemetry"))]
mod address_metrics_tests {
    use std::sync::{LazyLock, Mutex, MutexGuard};

    use iroha_data_model::{
        account::{
            AccountAddress, AccountId,
            address::{AddressDomainKind, default_domain_name, set_default_domain_name},
        },
        domain::DomainId,
    };
    use norito::json::Value;

    use super::*;
    use crate::filter::{FieldPath, FilterExpr};

    const TEST_CONTEXT: &str = "/tests/account-metrics";
    const KAIGI_SSE_CONTEXT: &str = "/v1/kaigi/relays/events?relay";
    static DEFAULT_DOMAIN_LOCK: LazyLock<Mutex<()>> = LazyLock::new(|| Mutex::new(()));

    fn local8_literal() -> &'static str {
        "sn12zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz@kaigi.sora"
    }

    #[tokio::test(flavor = "current_thread")]
    async fn parse_account_literal_counts_local8_attempts() {
        let telemetry = MaybeTelemetry::for_tests();
        let metrics = telemetry.metrics().await;
        let reason = iroha_data_model::account::AccountId::parse_encoded(local8_literal())
            .expect_err("local8 literal should fail")
            .reason();
        let invalid_counter = metrics
            .torii_address_invalid_total
            .with_label_values(&[TEST_CONTEXT, reason]);
        let before_invalid = invalid_counter.get();

        assert!(parse_account_literal(local8_literal(), &telemetry, TEST_CONTEXT).is_err());

        assert_eq!(invalid_counter.get(), before_invalid + 1);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn parse_account_literal_records_local8_domain_labels() {
        let telemetry = MaybeTelemetry::for_tests();
        let metrics = telemetry.metrics().await;
        let domain_label = local8_domain_label(local8_literal()).expect("domain parses");
        let local8_counter = metrics
            .torii_address_domain_total
            .with_label_values(&[TEST_CONTEXT, "local8"]);
        let domain_counter = metrics
            .torii_address_domain_total
            .with_label_values(&[TEST_CONTEXT, domain_label.as_str()]);
        let before_local8 = local8_counter.get();
        let before_domain = domain_counter.get();

        assert!(parse_account_literal(local8_literal(), &telemetry, TEST_CONTEXT).is_err());

        assert_eq!(local8_counter.get(), before_local8 + 1);
        assert_eq!(domain_counter.get(), before_domain + 1);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn filter_validation_records_address_metrics() {
        let telemetry = MaybeTelemetry::for_tests();
        let metrics = telemetry.metrics().await;
        let reason = iroha_data_model::account::AccountId::parse_encoded(local8_literal())
            .expect_err("local8 literal should fail")
            .reason();
        let invalid_counter = metrics
            .torii_address_invalid_total
            .with_label_values(&[CONTEXT_ACCOUNTS_TRANSACTIONS_QUERY_FILTER, reason]);
        let before_invalid = invalid_counter.get();

        let expr = FilterExpr::Eq(
            FieldPath("authority".to_string()),
            Value::String(local8_literal().into()),
        );
        assert!(validate_tx_filter_adapter(&expr, &telemetry).is_err());

        assert_eq!(invalid_counter.get(), before_invalid + 1);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn account_filter_rejects_alias_literals() {
        let telemetry = MaybeTelemetry::for_tests();
        let mut expr = FilterExpr::Eq(
            FieldPath("id".to_string()),
            Value::String("alias@invalid-domain".into()),
        );

        let result =
            canonicalize_accounts_filter_literals(&mut expr, &telemetry, ENDPOINT_ACCOUNTS_QUERY);

        assert!(result.is_err(), "alias literals must be rejected");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn account_literal_metric_tracks_selection() {
        let telemetry = MaybeTelemetry::for_tests();
        let endpoint = ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY;

        let before = {
            let metrics = telemetry.metrics().await;
            metrics
                .torii_account_literal_total
                .with_label_values(&[endpoint, "i105"])
                .get()
        };

        record_account_literal_selection(&telemetry, endpoint);

        let after = {
            let metrics = telemetry.metrics().await;
            metrics
                .torii_account_literal_total
                .with_label_values(&[endpoint, "i105"])
                .get()
        };
        assert_eq!(after, before + 1);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn kaigi_sse_invalid_literal_records_metric() {
        let telemetry = MaybeTelemetry::for_tests();
        let metrics = telemetry.metrics().await;
        let literal = "sorainvalid@kaigi";
        let reason = AccountId::parse_encoded(literal)
            .expect_err("literal must fail")
            .reason();
        let before = metrics
            .torii_address_invalid_total
            .with_label_values(&[KAIGI_SSE_CONTEXT, reason])
            .get();

        assert!(
            parse_account_literal(literal, &telemetry, KAIGI_SSE_CONTEXT).is_err(),
            "literal should be rejected"
        );

        let after = metrics
            .torii_address_invalid_total
            .with_label_values(&[KAIGI_SSE_CONTEXT, reason])
            .get();
        assert_eq!(after, before + 1);
    }

    struct DefaultDomainGuard {
        _lock: MutexGuard<'static, ()>,
        previous: String,
    }

    impl DefaultDomainGuard {
        fn set(label: &str) -> Self {
            let lock = DEFAULT_DOMAIN_LOCK
                .lock()
                .expect("acquire default domain lock");
            let previous = default_domain_name();
            set_default_domain_name(label.to_owned()).expect("set default domain label");
            Self {
                _lock: lock,
                previous: previous.to_string(),
            }
        }
    }

    impl Drop for DefaultDomainGuard {
        fn drop(&mut self) {
            let _ = set_default_domain_name(self.previous.clone());
        }
    }

    fn i105_literal(domain_label: &str) -> String {
        let _domain = DomainId::try_new(domain_label, "universal").expect("domain parses");
        let kp = checked_routing_fixture_keypair(
            0x97,
            iroha_crypto::Algorithm::Ed25519,
            "derive account literal metric fixture key",
        );
        let account = AccountId::new(kp.public_key().clone());
        account.to_string()
    }

    #[tokio::test(flavor = "current_thread")]
    async fn parse_account_literal_records_default_domain_metrics() {
        let _guard = DefaultDomainGuard::set("wonderland");
        let telemetry = MaybeTelemetry::for_tests();
        let endpoint = TEST_CONTEXT;
        let literal = i105_literal("wonderland");
        let label = AddressDomainKind::Default.as_str();

        let before = {
            let metrics = telemetry.metrics().await;
            metrics
                .torii_address_domain_total
                .with_label_values(&[endpoint, label])
                .get()
        };

        parse_account_literal(&literal, &telemetry, endpoint).expect("literal should parse");

        let after = {
            let metrics = telemetry.metrics().await;
            metrics
                .torii_address_domain_total
                .with_label_values(&[endpoint, label])
                .get()
        };

        assert_eq!(after, before + 1);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn kaigi_sse_accepts_i105_literal() {
        let telemetry = MaybeTelemetry::for_tests();
        let literal = "sorauﾛ1NﾗhBUd2BﾂｦﾄiﾔﾆﾂﾇKSﾃaﾘﾒﾓQﾗrﾒoﾘﾅnｳﾘbQｳQJﾆLJ5HSE";

        let parsed = parse_account_literal(&literal, &telemetry, KAIGI_SSE_CONTEXT)
            .expect("i105 literal should parse");
        assert_eq!(parsed.canonical(), parsed.account_id().to_string());
    }
}

#[cfg(all(test, feature = "app_api", feature = "telemetry"))]
mod account_path_metric_tests {
    use super::*;

    #[tokio::test]
    async fn invalid_literal_records_endpoint_counter() {
        let telemetry = MaybeTelemetry::for_tests();
        let endpoint = ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY;
        let literal = "bad@banka.dataspace";
        let reason = AccountId::parse_encoded(literal)
            .expect_err("literal must be rejected")
            .reason();

        let before = {
            let metrics = telemetry.metrics().await;
            metrics
                .torii_address_invalid_total
                .with_label_values(&[endpoint, reason])
                .get()
        };
        assert!(
            parse_account_path_segment(literal, &telemetry, endpoint).is_err(),
            "literal should be rejected"
        );
        let after = {
            let metrics = telemetry.metrics().await;
            metrics
                .torii_address_invalid_total
                .with_label_values(&[endpoint, reason])
                .get()
        };
        assert_eq!(after, before + 1);
    }
}

#[cfg(all(test, feature = "app_api", feature = "telemetry"))]
mod stateful_account_path_parser_tests {
    use std::sync::Arc;

    use iroha_core::{
        kura::Kura,
        query::store::LiveQueryStore,
        state::{State, World},
    };
    use iroha_data_model::{
        account::Account,
        domain::{Domain, DomainId},
    };
    use iroha_test_samples::ALICE_ID;

    use super::*;

    #[tokio::test]
    async fn stateful_account_path_parser_resolves_bound_alias_literal() {
        let domain_id: DomainId = DomainId::try_new("banka", "universal").expect("domain");
        let authority = ALICE_ID.clone();
        let scoped_account_id = authority.clone();
        let world = World::with(
            [Domain::new(domain_id).build(&authority)],
            [Account::new(scoped_account_id.account().clone()).build(&authority)],
            [],
        );
        let state = Arc::new(State::new_for_testing(
            world,
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        ));
        bind_account_alias_for_test(&state, &scoped_account_id, "operator@banka.universal");
        let telemetry = MaybeTelemetry::for_tests();

        let (resolved, canonical) = parse_account_path_segment_with_state(
            &state,
            "operator@banka.universal",
            &telemetry,
            ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY,
        )
        .expect("bound alias literal should resolve on account_id paths");

        assert_eq!(resolved, authority);
        assert_eq!(canonical, authority.to_string());
    }
}

#[cfg(feature = "app_api")]
/// Load the canonical committed-transaction snapshot visible to Torii.
pub(crate) fn committed_transactions_snapshot(
    state: &CoreState,
) -> Result<Vec<iroha_data_model::query::CommittedTransaction>> {
    let view = state.view();
    iroha_core::smartcontracts::isi::tx::committed_transactions_snapshot(&view)
        .map_err(|err| Error::Query(iroha_data_model::ValidationFail::QueryFailed(err)))
}

#[cfg(feature = "app_api")]
fn committed_transactions_indexed_snapshot(
    state: &CoreState,
    filter: iroha_data_model::query::dsl::CompoundPredicate<
        iroha_data_model::query::CommittedTransaction,
    >,
) -> Result<Vec<iroha_data_model::query::CommittedTransaction>> {
    let view = state.view();
    iroha_core::smartcontracts::isi::tx::committed_transactions_indexed_snapshot(&view, filter)
        .map_err(|err| Error::Query(iroha_data_model::ValidationFail::QueryFailed(err)))
}

/// POST /v1/accounts/{account_id}/transactions/query
///
/// Body: JSON `QueryEnvelope` with optional `filter`, `select`, and `pagination`.
///
/// Example:
///   curl -X POST \
///     -H 'Content-Type: application/json' \
///     -H 'Accept: application/json' \
///     -d '{"filter": {"op":"eq","args":[{"FieldPath":"authority"},"sorauﾛ1NﾗhBUd2BﾂｦﾄiﾔﾆﾂﾇKSﾃaﾘﾒﾓQﾗrﾒoﾘﾅnｳﾘbQｳQJﾆLJ5HSE"]}, "pagination": {"limit": 50}}' \
///     http://127.0.0.1:8080/v1/accounts/sorauﾛ1NﾗhBUd2BﾂｦﾄiﾔﾆﾂﾇKSﾃaﾘﾒﾓQﾗrﾒoﾘﾅnｳﾘbQｳQJﾆLJ5HSE/transactions/query
///
/// Returns: `{ "items": [ {"authority": "...", "timestamp_ms": 0, "entrypoint_hash": "...", "result_ok": true } ], "total": N }`
///
/// Supported filter fields: `authority`, `timestamp_ms`, `entrypoint_hash`, `result_ok`,
/// `metadata.<key>`, and `asset_id` (matches asset ids referenced by instruction payloads).
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_account_transactions(
    state: Arc<CoreState>,
    axum::extract::Path(account_id): axum::extract::Path<String>,
    NoritoJson(envelope): NoritoJson<QueryEnvelope>,
    telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    handle_v1_account_transactions_with_policy(
        state,
        axum::extract::Path(account_id),
        NoritoJson(envelope),
        telemetry,
        None,
    )
    .await
}

/// POST /v1/accounts/{account_id}/transactions/query` with configurable address enforcement.
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_account_transactions_with_policy(
    state: Arc<CoreState>,
    axum::extract::Path(account_id): axum::extract::Path<String>,
    NoritoJson(envelope): NoritoJson<QueryEnvelope>,
    telemetry: MaybeTelemetry,
    allowed_asset_definition_id: Option<AssetDefinitionId>,
) -> Result<impl IntoResponse> {
    #[cfg(feature = "telemetry")]
    use std::time::Instant;

    use iroha_data_model::query::dsl::CompoundPredicate;
    #[cfg(feature = "telemetry")]
    let start = Instant::now();
    #[cfg(feature = "telemetry")]
    let filter_depth = envelope
        .filter
        .as_ref()
        .map(|expr| {
            // Compute depth of FilterExpr tree
            fn depth(e: &FilterExpr) -> usize {
                use crate::filter::FilterExpr as F;
                match e {
                    F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                    F::Not(inner) => 1 + depth(inner),
                    _ => 1,
                }
            }
            depth(expr)
        })
        .unwrap_or(0);

    let (account_id, _canonical_literal) = parse_account_path_segment_with_state(
        state.as_ref(),
        &account_id,
        &telemetry,
        ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY,
    )?;
    record_account_literal_selection(&telemetry, ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY);
    let limits = app_query_limits();
    let cap = app_query_page_cap(&state);
    let allowed_asset_selector = allowed_asset_definition_id
        .clone()
        .map(TxHistoryAssetSelector::DefinitionId);

    if envelope.select.is_some() || envelope.aggregate.is_some() {
        if let Some(ref expr) = envelope.filter {
            fn depth(e: &crate::filter::FilterExpr) -> usize {
                use crate::filter::FilterExpr as F;
                match e {
                    F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                    F::Not(inner) => 1 + depth(inner),
                    _ => 1,
                }
            }
            if depth(expr) > 10 {
                return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
            }
            validate_tx_filter_adapter(expr, &telemetry)?;
            crate::filter::validate_filter(expr)
                .map_err(|e| map_filter_error(e, ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY))?;
        }
        let pagination = enforce_app_pagination(
            envelope.pagination.limit,
            envelope.pagination.offset,
            cap,
            ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY,
        )?;
        let _fetch_size = limits
            .clamp_fetch_size(envelope.fetch_size)
            .map(|opt| opt.map(|val| val.min(pagination.cap)))?;
        let predicate = envelope
            .filter
            .as_ref()
            .map_or(CompoundPredicate::PASS, tx_predicate_from_filter);
        let committed_txs = committed_transactions_indexed_snapshot(state.as_ref(), predicate)?;
        let rows = committed_txs
            .iter()
            .filter(|tx| tx_matches_account_history_subject(tx, &account_id))
            .filter(|tx| {
                allowed_asset_selector
                    .as_ref()
                    .is_none_or(|expected| tx_matches_asset_selector(tx, expected))
            })
            .map(tx_to_query_row);
        return execute_generic_resource_query(
            state.as_ref(),
            crate::generic_query::RESOURCE_ACCOUNT_TRANSACTIONS,
            envelope,
            rows,
            "live",
        );
    }

    let committed_txs = committed_transactions_snapshot(state.as_ref())?;
    let count_mode = app_count_mode(
        envelope.count_mode.as_deref(),
        ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY,
    );
    let page = {
        // Validate JSON filter (structural + endpoint-specific) and execute typed predicate (PASS for now)
        let predicate = if let Some(ref expr_wrap) = envelope.filter {
            let expr = expr_wrap;
            // Extra guard: reject overly deep filters early with 422
            {
                fn depth(e: &crate::filter::FilterExpr) -> usize {
                    use crate::filter::FilterExpr as F;
                    match e {
                        F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                        F::Not(inner) => 1 + depth(inner),
                        _ => 1,
                    }
                }
                if depth(expr) > 10 {
                    return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
                }
            }
            // Endpoint-specific validation first (depth, set sizes, value types)
            validate_tx_filter_adapter(expr, &telemetry)?;
            // Structural validation (field path form + basic type checks)
            crate::filter::validate_filter(expr)
                .map_err(|e| map_filter_error(e, ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY))?;
            if filter_expr_references_field(expr, "authority") {
                CompoundPredicate::PASS
            } else {
                tx_predicate_from_filter(expr)
            }
        } else {
            CompoundPredicate::PASS
        };
        let pagination = enforce_app_pagination(
            envelope.pagination.limit,
            envelope.pagination.offset,
            cap,
            ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY,
        )?;
        let fetch_size = limits
            .clamp_fetch_size(envelope.fetch_size)
            .map(|opt| opt.map(|val| val.min(pagination.cap)))?;
        let sort_spec = envelope.sort.clone();
        let filter_clone = envelope.filter.clone();
        let select_clone = envelope.select.clone();

        if sort_spec.is_empty() {
            let filter_ref = filter_clone.as_ref();
            let select_ref = &select_clone;
            let filtered_iter = committed_txs.iter().filter_map(|tx| {
                if !predicate.applies(tx) {
                    return None;
                }
                if !tx_matches_account_history_subject(tx, &account_id) {
                    return None;
                }
                if let Some(expected) = allowed_asset_selector.as_ref() {
                    if !tx_matches_asset_selector(tx, expected) {
                        return None;
                    }
                }
                let include = filter_ref.map(|expr| filter_tx(expr, tx)).unwrap_or(true);
                if include {
                    Some(project_tx(tx, select_ref))
                } else {
                    None
                }
            });
            collect_page_linear_for_mode(
                filtered_iter,
                pagination.offset,
                pagination.limit,
                fetch_size,
                count_mode,
            )
        } else {
            // NOTE: Materialize+sort for correctness and stable tie-breaking.
            // The previous bounded-heap top-K selection introduced subtle
            // ordering discrepancies for complex multi-key sorts. Given the
            // expected result sizes on this endpoint and for deterministic
            // behavior in tests, we collect, sort, and then slice.
            let filter_ref = filter_clone.as_ref();
            let select_ref = &select_clone;
            let mut projections: Vec<TxProjection> = Vec::new();
            let debug_filter = torii_debug_match_enabled();
            for tx in &committed_txs {
                if !predicate.applies(tx) {
                    continue;
                }
                if !tx_matches_account_history_subject(tx, &account_id) {
                    continue;
                }
                if let Some(expected) = allowed_asset_selector.as_ref() {
                    if !tx_matches_asset_selector(tx, expected) {
                        continue;
                    }
                }
                let include = filter_ref.map(|expr| filter_tx(expr, tx)).unwrap_or(true);
                if debug_filter {
                    // Print candidate fields and per-clause results if filter provided
                    let result_ok = tx.result().as_ref().is_ok();
                    let ts = match tx.entrypoint() {
                        iroha_data_model::transaction::signed::TransactionEntrypoint::External(
                            s,
                        ) => Some(s.creation_time().as_millis() as u64),
                        _ => None,
                    };
                    let entry_str = format!("{}", tx.entrypoint_hash());
                    let auth = match tx.entrypoint() {
                        iroha_data_model::transaction::signed::TransactionEntrypoint::External(
                            s,
                        ) => Some(format!("{}", s.authority())),
                        _ => None,
                    };
                    eprintln!(
                        "[torii-filter-debug] cand: result_ok={:?} ts={:?} entry={} auth={:?}",
                        result_ok, ts, entry_str, auth
                    );
                    eprintln!("[torii-filter-debug] tx.result()={:?}", tx.result());
                    if let Some(expr) = filter_clone.as_ref() {
                        // Helper to summarize a simple clause for readability in logs
                        fn clause_str(e: &crate::filter::FilterExpr) -> String {
                            use crate::filter::FilterExpr as F;
                            match e {
                                F::Eq(f, v) => format!("eq({}, {:?})", f.0, v),
                                F::Ne(f, v) => format!("ne({}, {:?})", f.0, v),
                                F::Lt(f, v) => format!("lt({}, {:?})", f.0, v),
                                F::Lte(f, v) => format!("lte({}, {:?})", f.0, v),
                                F::Gt(f, v) => format!("gt({}, {:?})", f.0, v),
                                F::Gte(f, v) => format!("gte({}, {:?})", f.0, v),
                                F::In(f, list) => format!("in({}, {} items)", f.0, list.len()),
                                F::Nin(f, list) => format!("nin({}, {} items)", f.0, list.len()),
                                F::Exists(f) => format!("exists({})", f.0),
                                F::IsNull(f) => format!("is_null({})", f.0),
                                F::Not(inner) => format!("not({})", clause_str(inner)),
                                F::And(list) => format!("and({} clauses)", list.len()),
                                F::Or(list) => format!("or({} clauses)", list.len()),
                            }
                        }
                        use crate::filter::FilterExpr as F;
                        match expr {
                            F::And(list) => {
                                for (i, c) in list.iter().enumerate() {
                                    let ok = filter_tx(c, tx);
                                    eprintln!(
                                        "[torii-filter-debug]  clause[{i}] {} => {}",
                                        clause_str(c),
                                        ok
                                    );
                                }
                            }
                            other => {
                                let ok = filter_tx(other, tx);
                                eprintln!(
                                    "[torii-filter-debug]  clause {} => {}",
                                    clause_str(other),
                                    ok
                                );
                            }
                        }
                        eprintln!("[torii-filter-debug] include => {}", include);
                    }
                }
                if include {
                    projections.push(project_tx(tx, select_ref));
                }
            }

            // Sort projections by requested spec using a single composite key per row
            // to ensure deterministic ordering across all keys and platforms.
            let spec_keys = sort_spec;
            // Build structured sort keys and keep deterministic tie-breakers.
            let has_entry = spec_keys.iter().any(|k| k.key.0 == "entrypoint_hash");
            let has_auth = spec_keys.iter().any(|k| k.key.0 == "authority");
            let sort_key = |p: &TxProjection| -> MultiSortKey {
                let mut comps: Vec<SortKeyComponent> = Vec::new();
                for key in &spec_keys {
                    let asc = matches!(key.order, crate::filter::Order::Asc);
                    match key.key.0.as_str() {
                        "timestamp_ms" => {
                            let ts = p.timestamp_ms.unwrap_or(u64::MAX);
                            let val = iroha_primitives::numeric::Numeric::from(ts);
                            comps.push(if asc {
                                SortKeyComponent::asc(val)
                            } else {
                                SortKeyComponent::desc(val)
                            });
                        }
                        "authority" => {
                            let s = p.authority.as_deref().unwrap_or("").to_string();
                            comps.push(if asc {
                                SortKeyComponent::asc(s)
                            } else {
                                SortKeyComponent::desc(s)
                            });
                        }
                        "entrypoint_hash" => {
                            let s = p.entrypoint_hash.clone();
                            comps.push(if asc {
                                SortKeyComponent::asc(s)
                            } else {
                                SortKeyComponent::desc(s)
                            });
                        }
                        "result_ok" => {
                            let flag = if p.result_ok { "1" } else { "0" };
                            comps.push(if asc {
                                SortKeyComponent::asc(flag)
                            } else {
                                SortKeyComponent::desc(flag)
                            });
                        }
                        _ => {}
                    }
                }
                if !has_entry {
                    comps.push(SortKeyComponent::asc(p.entrypoint_hash.clone()));
                }
                if !has_auth {
                    comps.push(SortKeyComponent::asc(
                        p.authority.as_deref().unwrap_or("").to_string(),
                    ));
                }
                MultiSortKey::new(comps)
            };

            let iter = projections.into_iter().map(|p| (sort_key(&p), p));
            collect_page_streaming_for_mode(
                iter,
                pagination.offset,
                pagination.limit,
                Some(pagination.cap),
                count_mode,
            )
        }
    };

    // Telemetry wiring for app-facing transaction query endpoint
    #[cfg(feature = "telemetry")]
    if telemetry.is_enabled() {
        let metrics = telemetry.metrics().await;
        let endpoint = ENDPOINT_ACCOUNTS_TRANSACTIONS_QUERY;
        metrics
            .torii_filter_depth
            .with_label_values(&[endpoint])
            .observe(filter_depth as f64);
        metrics
            .torii_filter_match_count
            .with_label_values(&[endpoint])
            .observe(page.total.unwrap_or(page.items.len()) as f64);
        let elapsed_ms = start.elapsed().as_secs_f64() * 1000.0;
        metrics
            .torii_scan_ms
            .with_label_values(&[endpoint])
            .observe(elapsed_ms);
        metrics
            .torii_stream_rows
            .with_label_values(&[endpoint])
            .observe(page.items.len() as f64);
    }
    // Build Norito JSON response: { items: [...], total: N }
    let items_json = tx_projections_to_json(&page.items);
    let mut top = norito::json::Map::new();
    top.insert("items".into(), norito::json::Value::Array(items_json));
    insert_page_metadata(&mut top, &page, count_mode);
    let body = norito::json::to_json_pretty(&top).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            e.to_string(),
        ))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

/// POST /v1/transactions/query
///
/// Body: JSON `QueryEnvelope` with optional `filter`, `select`, and `pagination`.
///
/// Returns committed transactions without requiring clients to first discover
/// and fan out over every account. Supported filter fields match the account
/// transaction query endpoint.
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_transactions_query(
    state: Arc<CoreState>,
    NoritoJson(envelope): NoritoJson<QueryEnvelope>,
    telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    handle_v1_transactions_query_with_policy(state, NoritoJson(envelope), telemetry, None).await
}

/// POST `/v1/transactions/query` with configurable asset enforcement.
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_transactions_query_with_policy(
    state: Arc<CoreState>,
    NoritoJson(envelope): NoritoJson<QueryEnvelope>,
    telemetry: MaybeTelemetry,
    allowed_asset_definition_id: Option<AssetDefinitionId>,
) -> Result<impl IntoResponse> {
    handle_v1_transactions_query_scoped_with_policy(
        state,
        NoritoJson(envelope),
        telemetry,
        allowed_asset_definition_id,
        ENDPOINT_TRANSACTIONS_QUERY,
        None,
    )
    .await
}

/// POST `/v1/transactions/visible/query` with server-side viewer visibility.
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_transactions_visible_query_with_policy(
    state: Arc<CoreState>,
    NoritoJson(envelope): NoritoJson<QueryEnvelope>,
    telemetry: MaybeTelemetry,
    visibility: TxHistoryVisibilityScope,
    allowed_asset_definition_id: Option<AssetDefinitionId>,
) -> Result<impl IntoResponse> {
    handle_v1_transactions_query_scoped_with_policy(
        state,
        NoritoJson(envelope),
        telemetry,
        allowed_asset_definition_id,
        ENDPOINT_TRANSACTIONS_VISIBLE_QUERY,
        Some(visibility),
    )
    .await
}

#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
async fn handle_v1_transactions_query_scoped_with_policy(
    state: Arc<CoreState>,
    NoritoJson(envelope): NoritoJson<QueryEnvelope>,
    telemetry: MaybeTelemetry,
    allowed_asset_definition_id: Option<AssetDefinitionId>,
    endpoint: &'static str,
    visibility: Option<TxHistoryVisibilityScope>,
) -> Result<impl IntoResponse> {
    #[cfg(feature = "telemetry")]
    use std::time::Instant;

    use iroha_data_model::query::dsl::CompoundPredicate;

    #[cfg(feature = "telemetry")]
    let start = Instant::now();
    #[cfg(feature = "telemetry")]
    let filter_depth = envelope
        .filter
        .as_ref()
        .map(|expr| {
            fn depth(e: &FilterExpr) -> usize {
                use crate::filter::FilterExpr as F;
                match e {
                    F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                    F::Not(inner) => 1 + depth(inner),
                    _ => 1,
                }
            }
            depth(expr)
        })
        .unwrap_or(0);

    let limits = app_query_limits();
    let cap = app_query_page_cap(&state);
    let allowed_asset_selector = allowed_asset_definition_id
        .clone()
        .map(TxHistoryAssetSelector::DefinitionId);

    if envelope.select.is_some() || envelope.aggregate.is_some() {
        if let Some(ref expr) = envelope.filter {
            fn depth(e: &crate::filter::FilterExpr) -> usize {
                use crate::filter::FilterExpr as F;
                match e {
                    F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                    F::Not(inner) => 1 + depth(inner),
                    _ => 1,
                }
            }
            if depth(expr) > 10 {
                return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
            }
            validate_tx_filter_adapter_for_endpoint(expr, &telemetry, endpoint)?;
            crate::filter::validate_filter(expr).map_err(|e| map_filter_error(e, endpoint))?;
        }
        let pagination = enforce_app_pagination(
            envelope.pagination.limit,
            envelope.pagination.offset,
            cap,
            endpoint,
        )?;
        let _fetch_size = limits
            .clamp_fetch_size(envelope.fetch_size)
            .map(|opt| opt.map(|val| val.min(pagination.cap)))?;
        let predicate = envelope
            .filter
            .as_ref()
            .map_or(CompoundPredicate::PASS, tx_predicate_from_filter);
        let committed_txs = committed_transactions_indexed_snapshot(state.as_ref(), predicate)?;
        let rows = committed_txs
            .iter()
            .filter(|tx| {
                visibility
                    .as_ref()
                    .is_none_or(|scope| tx_matches_history_visibility_scope(tx, scope))
            })
            .filter(|tx| {
                allowed_asset_selector
                    .as_ref()
                    .is_none_or(|expected| tx_matches_asset_selector(tx, expected))
            })
            .map(tx_to_query_row);
        return execute_generic_resource_query(
            state.as_ref(),
            crate::generic_query::RESOURCE_ACCOUNT_TRANSACTIONS,
            envelope,
            rows,
            "live",
        );
    }

    let committed_txs = committed_transactions_snapshot(state.as_ref())?;
    let count_mode = app_count_mode(envelope.count_mode.as_deref(), endpoint);
    let page = {
        let predicate = if let Some(ref expr_wrap) = envelope.filter {
            let expr = expr_wrap;
            {
                fn depth(e: &crate::filter::FilterExpr) -> usize {
                    use crate::filter::FilterExpr as F;
                    match e {
                        F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                        F::Not(inner) => 1 + depth(inner),
                        _ => 1,
                    }
                }
                if depth(expr) > 10 {
                    return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
                }
            }
            validate_tx_filter_adapter_for_endpoint(expr, &telemetry, endpoint)?;
            crate::filter::validate_filter(expr).map_err(|e| map_filter_error(e, endpoint))?;
            if filter_expr_references_field(expr, "authority") {
                CompoundPredicate::PASS
            } else {
                tx_predicate_from_filter(expr)
            }
        } else {
            CompoundPredicate::PASS
        };
        let pagination = enforce_app_pagination(
            envelope.pagination.limit,
            envelope.pagination.offset,
            cap,
            endpoint,
        )?;
        let fetch_size = limits
            .clamp_fetch_size(envelope.fetch_size)
            .map(|opt| opt.map(|val| val.min(pagination.cap)))?;
        let sort_spec = envelope.sort.clone();
        let filter_clone = envelope.filter.clone();
        let select_clone = envelope.select.clone();

        if sort_spec.is_empty() {
            let filter_ref = filter_clone.as_ref();
            let select_ref = &select_clone;
            let filtered_iter = committed_txs.iter().filter_map(|tx| {
                if !predicate.applies(tx) {
                    return None;
                }
                if visibility
                    .as_ref()
                    .is_some_and(|scope| !tx_matches_history_visibility_scope(tx, scope))
                {
                    return None;
                }
                if let Some(expected) = allowed_asset_selector.as_ref() {
                    if !tx_matches_asset_selector(tx, expected) {
                        return None;
                    }
                }
                let include = filter_ref.map(|expr| filter_tx(expr, tx)).unwrap_or(true);
                if include {
                    Some(project_tx(tx, select_ref))
                } else {
                    None
                }
            });
            collect_page_linear_for_mode(
                filtered_iter,
                pagination.offset,
                pagination.limit,
                fetch_size,
                count_mode,
            )
        } else {
            let filter_ref = filter_clone.as_ref();
            let select_ref = &select_clone;
            let mut projections: Vec<TxProjection> = Vec::new();
            for tx in &committed_txs {
                if !predicate.applies(tx) {
                    continue;
                }
                if visibility
                    .as_ref()
                    .is_some_and(|scope| !tx_matches_history_visibility_scope(tx, scope))
                {
                    continue;
                }
                if let Some(expected) = allowed_asset_selector.as_ref() {
                    if !tx_matches_asset_selector(tx, expected) {
                        continue;
                    }
                }
                let include = filter_ref.map(|expr| filter_tx(expr, tx)).unwrap_or(true);
                if include {
                    projections.push(project_tx(tx, select_ref));
                }
            }

            let spec_keys = sort_spec;
            let has_entry = spec_keys.iter().any(|k| k.key.0 == "entrypoint_hash");
            let has_auth = spec_keys.iter().any(|k| k.key.0 == "authority");
            let sort_key = |p: &TxProjection| -> MultiSortKey {
                let mut comps: Vec<SortKeyComponent> = Vec::new();
                for key in &spec_keys {
                    let asc = matches!(key.order, crate::filter::Order::Asc);
                    match key.key.0.as_str() {
                        "timestamp_ms" => {
                            let ts = p.timestamp_ms.unwrap_or(u64::MAX);
                            let val = iroha_primitives::numeric::Numeric::from(ts);
                            comps.push(if asc {
                                SortKeyComponent::asc(val)
                            } else {
                                SortKeyComponent::desc(val)
                            });
                        }
                        "authority" => {
                            let s = p.authority.as_deref().unwrap_or("").to_string();
                            comps.push(if asc {
                                SortKeyComponent::asc(s)
                            } else {
                                SortKeyComponent::desc(s)
                            });
                        }
                        "entrypoint_hash" => {
                            let s = p.entrypoint_hash.clone();
                            comps.push(if asc {
                                SortKeyComponent::asc(s)
                            } else {
                                SortKeyComponent::desc(s)
                            });
                        }
                        "result_ok" => {
                            let flag = if p.result_ok { "1" } else { "0" };
                            comps.push(if asc {
                                SortKeyComponent::asc(flag)
                            } else {
                                SortKeyComponent::desc(flag)
                            });
                        }
                        _ => {}
                    }
                }
                if !has_entry {
                    comps.push(SortKeyComponent::asc(p.entrypoint_hash.clone()));
                }
                if !has_auth {
                    comps.push(SortKeyComponent::asc(
                        p.authority.as_deref().unwrap_or("").to_string(),
                    ));
                }
                MultiSortKey::new(comps)
            };

            let iter = projections.into_iter().map(|p| (sort_key(&p), p));
            collect_page_streaming_for_mode(
                iter,
                pagination.offset,
                pagination.limit,
                Some(pagination.cap),
                count_mode,
            )
        }
    };

    #[cfg(feature = "telemetry")]
    if telemetry.is_enabled() {
        let metrics = telemetry.metrics().await;
        metrics
            .torii_filter_depth
            .with_label_values(&[endpoint])
            .observe(filter_depth as f64);
        metrics
            .torii_filter_match_count
            .with_label_values(&[endpoint])
            .observe(page.total.unwrap_or(page.items.len()) as f64);
        let elapsed_ms = start.elapsed().as_secs_f64() * 1000.0;
        metrics
            .torii_scan_ms
            .with_label_values(&[endpoint])
            .observe(elapsed_ms);
        metrics
            .torii_stream_rows
            .with_label_values(&[endpoint])
            .observe(page.items.len() as f64);
    }

    let items_json = tx_projections_to_json(&page.items);
    let mut top = norito::json::Map::new();
    top.insert("items".into(), norito::json::Value::Array(items_json));
    insert_page_metadata(&mut top, &page, count_mode);
    let body = norito::json::to_json_pretty(&top).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            e.to_string(),
        ))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

