    #[test]
    fn explorer_transaction_filters_match_asset_id() {
        let (authority, keypair): (dm::AccountId, KeyPair) = account_with_key();
        let (other_account, _) = account_with_key();
        let def = test_asset_definition_id();
        let asset_id = dm::AssetId::new(def.clone(), authority.clone());
        let other_asset_id = dm::AssetId::new(def, other_account);
        let mint = dm::Mint::asset_quantity(1_u32, asset_id.clone());
        let tx = make_external_tx_with_instructions(
            &authority,
            &keypair,
            1_710_000_000_000,
            vec![mint.into()],
        );
        let dm::TransactionEntrypoint::External(signed) = &tx.entrypoint else {
            panic!("expected external transaction");
        };

        let filters = ExplorerTransactionFilters {
            authority: None,
            status: None,
            block: None,
            asset_id: Some(asset_id.clone()),
        };
        assert!(filters.matches(signed, 1, &tx.result));

        let filters = ExplorerTransactionFilters {
            authority: None,
            status: None,
            block: None,
            asset_id: Some(other_asset_id),
        };
        assert!(!filters.matches(signed, 1, &tx.result));
    }

