    #[tokio::test]
    async fn handle_queries_iterable_assets_non_empty() {
        use iroha_data_model::query::{
            QueryBox, QueryOutputBatchBox, QueryRequest, QueryWithParams,
            dsl::{CompoundPredicate, SelectorTuple},
            parameters::QueryParams,
        };
        let alice_keypair = checked_query_endpoint_keypair(
            0x8E,
            iroha_crypto::Algorithm::Ed25519,
            "derive iterable assets query fixture authority key",
        );
        let alice_id: AccountId = AccountId::new(alice_keypair.public_key().clone());
        let domain_id: DomainId = DomainId::try_new("wonderland", "universal").unwrap();

        // Build a small world with a single asset for Alice.
        let domain = Domain::new(domain_id.clone()).build(&alice_id);
        let account = Account::new(alice_id.clone()).build(&alice_id);
        let asset_def_id: AssetDefinitionId =
            test_asset_definition_id_from_hex("550e8400e29b41d4a7164466554400dd");
        let asset_def = AssetDefinition::numeric(asset_def_id.clone()).build(&alice_id);
        let asset_id = AssetId::new(asset_def_id, alice_id.clone());
        let asset = Asset::new(asset_id.clone(), Quantity::from(13_u32));
        let world = World::with_assets([domain], [account], [asset_def], [asset], []);
        let state = Arc::new(iroha_core::state::State::new_for_testing(
            world,
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        ));

        // Build a SignedQuery for iterable FindAssets (feature-agnostic via erased query)
        use iroha_data_model::query::ErasedIterQuery;
        let payload = norito::codec::Encode::encode(&FindAssets);
        let qbox: QueryBox<QueryOutputBatchBox> = Box::new(ErasedIterQuery::<Asset>::new(
            CompoundPredicate::<Asset>::PASS,
            SelectorTuple::<Asset>::default(),
            payload,
        ));
        let iter = QueryWithParams::new(&qbox, QueryParams::default());
        let payload = QueryRequest::Start(iter).with_authority(alice_id.clone());
        let signed = payload.sign(&alice_keypair);

        // Execute via handler
        let response = handle_queries_with_opts(
            LiveQueryStore::start_test(),
            state.clone(),
            signed,
            MaybeTelemetry::for_tests(),
            crate::NoritoQuery(QueryOptions::default()),
            crate::utils::ResponseFormat::Norito,
        )
        .await
        .expect("handle");
        assert_eq!(response.status(), axum::http::StatusCode::OK);
        let body = http_body_util::BodyExt::collect(response.into_body())
            .await
            .expect("body")
            .to_bytes();
        let resp: QueryResponse = norito::decode_from_bytes(body.as_ref()).expect("decode");

        let QueryResponse::Iterable(first) = resp else {
            panic!("expected iterable")
        };
        let (batch, _, _) = first.into_parts();
        let v = match batch.into_iter().next().expect("slice") {
            QueryOutputBatchBox::Asset(v) => v,
            other => panic!("unexpected batch variant: {other:?}"),
        };
        assert!(
            v.iter()
                .any(|a| a.id() == &asset_id && *a.value() == Quantity::from(13_u32))
        );
    }

    #[tokio::test]
    async fn handle_queries_rejects_fetch_size_above_max() {
        use iroha_data_model::query::{
            QueryBox, QueryOutputBatchBox, QueryRequest, QueryWithParams,
            dsl::{CompoundPredicate, SelectorTuple},
            parameters::{FetchSize, MAX_FETCH_SIZE, QueryParams},
        };

        let alice_keypair = checked_query_endpoint_keypair(
            0x8F,
            iroha_crypto::Algorithm::Ed25519,
            "derive oversized fetch-size query fixture authority key",
        );
        let alice_id: AccountId = AccountId::new(alice_keypair.public_key().clone());

        let state = Arc::new(iroha_core::state::State::new_for_testing(
            World::new(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        ));

        let over_max = MAX_FETCH_SIZE
            .checked_add(1)
            .expect("nonzero add must succeed");

        // Build an iterable FindAssets query with an oversized fetch size.
        use iroha_data_model::query::ErasedIterQuery;
        let payload = norito::codec::Encode::encode(&FindAssets);
        let qbox: QueryBox<QueryOutputBatchBox> = Box::new(ErasedIterQuery::<Asset>::new(
            CompoundPredicate::<Asset>::PASS,
            SelectorTuple::<Asset>::default(),
            payload,
        ));
        let iter = QueryWithParams::new(
            &qbox,
            QueryParams {
                fetch_size: FetchSize::new(Some(over_max)),
                ..QueryParams::default()
            },
        );

        let payload = QueryRequest::Start(iter).with_authority(alice_id.clone());
        let signed = payload.sign(&alice_keypair);

        let err = handle_queries_with_opts(
            LiveQueryStore::start_test(),
            state.clone(),
            signed,
            MaybeTelemetry::for_tests(),
            crate::NoritoQuery(QueryOptions::default()),
            crate::utils::ResponseFormat::Norito,
        )
        .await
        .expect_err("oversized fetch size should be rejected");

        assert!(matches!(
            err,
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::FetchSizeTooBig
            ))
        ));
    }

