#[cfg(feature = "app_api")]
struct ContractEventsSseState {
    rx: tokio::sync::broadcast::Receiver<EventBox>,
    state: Arc<CoreState>,
    pending: VecDeque<ContractEventProjection>,
    last_block_height: Option<u64>,
    terminal: bool,
}

#[cfg(not(test))]
const SSE_HEARTBEAT_INTERVAL: Duration = Duration::from_secs(15);
#[cfg(test)]
const SSE_HEARTBEAT_INTERVAL: Duration = Duration::from_millis(25);

#[cfg(feature = "app_api")]
#[derive(Debug, crate::json_macros::JsonSerialize)]
struct StreamErrorEvent {
    code: String,
    message: String,
    dropped_messages: Option<u64>,
    replay_available: bool,
}

#[cfg(feature = "app_api")]
fn stream_error_event(
    code: &'static str,
    message: impl Into<String>,
    dropped_messages: Option<u64>,
) -> SseEvent {
    let payload = StreamErrorEvent {
        code: code.to_owned(),
        message: message.into(),
        dropped_messages,
        replay_available: false,
    };
    let data = norito::json::to_json(&payload).unwrap_or_else(|error| {
        iroha_logger::error!(%error, code, "failed to encode SSE stream error payload");
        "{\"code\":\"stream_internal_error\",\"message\":\"failed to encode stream error\",\"dropped_messages\":null,\"replay_available\":false}".to_owned()
    });
    SseEvent::default().event("stream_error").data(data)
}

/// Reject an SSE resume attempt before stream establishment.
///
/// The canonical live streams do not retain a replay log. Returning a native
/// SSE error keeps the rejection compatible with `Accept: text/event-stream`
/// while making the unsupported resume request explicit and machine-readable.
#[cfg(feature = "app_api")]
pub fn stream_resume_unsupported_response() -> Response {
    let event = stream_error_event(
        "stream_resume_unsupported",
        "Last-Event-ID is unsupported because this live stream has no replay log.",
        None,
    );
    let stream = stream::once(async move { Ok::<_, Infallible>(event) });
    let mut response = Sse::new(stream).into_response();
    *response.status_mut() = StatusCode::BAD_REQUEST;
    response.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        axum::http::HeaderValue::from_static("no-store"),
    );
    response.headers_mut().insert(
        axum::http::HeaderName::from_static("x-iroha-stream-error"),
        axum::http::HeaderValue::from_static("stream_resume_unsupported"),
    );
    response
        .extensions_mut()
        .insert(crate::ReviewedProtocolNativeError::StreamResumeUnsupported);
    response
}

/// GET /v1/contracts/events/sse – Server-Sent Events stream of generic contract events.
#[cfg(feature = "app_api")]
pub fn handle_v1_contracts_events_sse(
    events: EventsSender,
    state: Arc<CoreState>,
    crate::NoritoQuery(params): crate::NoritoQuery<ContractEventsSseParams>,
) -> Result<Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>>, crate::Error> {
    let query = contract_event_query_from_sse_params(&params);
    let stream = stream::unfold(
        ContractEventsSseState {
            rx: events.subscribe(),
            state,
            pending: VecDeque::new(),
            last_block_height: None,
            terminal: false,
        },
        move |mut state| {
            let query = query.clone();
            async move {
                use tokio::sync::broadcast::error::RecvError;
                if state.terminal {
                    return None;
                }
                loop {
                    if let Some(event) = state.pending.pop_front() {
                        let json_value = contract_event_projection_to_json_value(&event);
                        let ev = match norito::json::to_json(&json_value) {
                            Ok(json) => SseEvent::default().event("contract_event").data(json),
                            Err(error) => {
                                iroha_logger::error!(%error, event_id = %event.event_id, "failed to encode contract SSE event");
                                state.pending.clear();
                                state.terminal = true;
                                stream_error_event(
                                    "stream_encode_error",
                                    "The server could not encode a contract event.",
                                    None,
                                )
                            }
                        };
                        return Some((Ok(ev), state));
                    }
                    match state.rx.recv().await {
                        Ok(event_box) => {
                            let Some(height) = committed_block_height(&event_box) else {
                                continue;
                            };
                            if state
                                .last_block_height
                                .is_some_and(|last_height| height <= last_height)
                            {
                                continue;
                            }
                            state.last_block_height = Some(height);
                            let Ok(height_usize) = usize::try_from(height) else {
                                iroha_logger::warn!(
                                    height,
                                    "failed to emit contract event SSE payload: block height exceeds host pointer width"
                                );
                                continue;
                            };
                            for projection in contract_event_projections_for_height_range(
                                state.state.as_ref(),
                                height_usize,
                                height_usize,
                            ) {
                                if contract_event_matches(&projection, &query) {
                                    state.pending.push_back(projection);
                                }
                            }
                        }
                        Err(RecvError::Lagged(dropped_messages)) => {
                            state.pending.clear();
                            state.terminal = true;
                            let ev = stream_error_event(
                                "stream_lagged",
                                "The contract event stream lost buffered events and cannot replay them.",
                                Some(dropped_messages),
                            );
                            return Some((Ok(ev), state));
                        }
                        Err(RecvError::Closed) => {
                            state.terminal = true;
                            let ev = stream_error_event(
                                "stream_source_closed",
                                "The contract event source closed.",
                                None,
                            );
                            return Some((Ok(ev), state));
                        }
                    }
                }
            }
        },
    );

    Ok(Sse::new(stream).keep_alive(
        KeepAlive::new()
            .interval(SSE_HEARTBEAT_INTERVAL)
            .text("heartbeat"),
    ))
}

/// GET /v1/events/sse – Server-Sent Events stream of JSON events.
///
/// Notes:
/// - Accepts an optional `?filter=` query param containing a JSON-encoded `FilterExpr`.
/// - Supported Proof-specific filters (in addition to pipeline filters):
///   - `proof_backend == "<backend>"` or `proof_backend IN ["b1","b2",...]`
///   - `proof_call_hash == "<64-hex>"` or `proof_call_hash IN ["<64-hex>", ...]`
///   - `proof_envelope_hash == "<64-hex>"` or `proof_envelope_hash IN ["<64-hex>", ...]`
/// - When only proof-specific filters are supplied, non-proof events are not emitted.
/// - Invalid or unsupported filters are rejected with `400 Bad Request`.
/// - Each SSE `data:` chunk is a single JSON-encoded event object.
///
/// curl example:
///   curl -N "http://127.0.0.1:8080/v1/events/sse"
#[cfg(feature = "app_api")]
pub fn handle_v1_events_sse(
    events: EventsSender,
    crate::NoritoQuery(params): crate::NoritoQuery<EventsSseParams>,
) -> Result<Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>>, crate::Error> {
    let SseFilterSpec {
        filters,
        proof_backend,
        proof_call_hash,
        proof_envelope_hash,
    } = parse_sse_filter_params(params.filter.as_deref())?;
    let proof_only = filters.is_none()
        && crate::proof_filters::has_any_proof_filters(
            proof_backend.as_ref(),
            proof_call_hash.as_ref(),
            proof_envelope_hash.as_ref(),
        );
    let stream = stream::unfold(
        EventsSseState {
            rx: events.subscribe(),
            pending: VecDeque::new(),
            terminal: false,
        },
        move |mut state| {
            let filters = filters.clone();
            let proof_backend = proof_backend.clone();
            let proof_call_hash = proof_call_hash.clone();
            let proof_envelope_hash = proof_envelope_hash.clone();
            async move {
                use tokio::sync::broadcast::error::RecvError;
                if state.terminal {
                    return None;
                }
                loop {
                    if let Some(event_box) = state.pending.pop_front() {
                        let json_val = event_to_json_value(&event_box);
                        let ev = match norito::json::to_json(&json_val) {
                            Ok(json) => SseEvent::default().data(json),
                            Err(error) => {
                                iroha_logger::error!(%error, "failed to encode SSE event");
                                state.pending.clear();
                                state.terminal = true;
                                stream_error_event(
                                    "stream_encode_error",
                                    "The server could not encode an event.",
                                    None,
                                )
                            }
                        };
                        return Some((Ok(ev), state));
                    }
                    match state.rx.recv().await {
                        Ok(event_box) => {
                            let mut consider_event = |event_box| {
                                if let Some(flt) = filters.as_ref() {
                                    // Drop events that don't match any filter.
                                    if !flt.iter().any(|f| f.matches(&event_box)) {
                                        return;
                                    }
                                }
                                if !crate::proof_filters::event_matches_proof_filters(
                                    &event_box,
                                    proof_backend.as_ref(),
                                    proof_call_hash.as_ref(),
                                    proof_envelope_hash.as_ref(),
                                    proof_only,
                                ) {
                                    return;
                                }
                                state.pending.push_back(event_box);
                            };

                            match event_box {
                                EventBox::PipelineBatch(events) => {
                                    for event in events {
                                        consider_event(EventBox::Pipeline(event));
                                    }
                                }
                                event_box => {
                                    consider_event(event_box);
                                }
                            }
                        }
                        Err(RecvError::Lagged(dropped_messages)) => {
                            state.pending.clear();
                            state.terminal = true;
                            let ev = stream_error_event(
                                "stream_lagged",
                                "The event stream lost buffered events and cannot replay them.",
                                Some(dropped_messages),
                            );
                            return Some((Ok(ev), state));
                        }
                        Err(RecvError::Closed) => {
                            state.terminal = true;
                            let ev = stream_error_event(
                                "stream_source_closed",
                                "The event source closed.",
                                None,
                            );
                            return Some((Ok(ev), state));
                        }
                    }
                }
            }
        },
    );

    Ok(Sse::new(stream).keep_alive(
        KeepAlive::new()
            .interval(SSE_HEARTBEAT_INTERVAL)
            .text("heartbeat"),
    ))
}

