#[derive(Clone, Copy)]
enum ExplorerStreamKind {
    Blocks,
    Transactions,
    Instructions,
}

#[cfg(feature = "app_api")]
pub fn handle_v1_explorer_blocks_stream(
    kura: Arc<Kura>,
    events: EventsSender,
) -> Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>> {
    explorer_stream(kura, events, ExplorerStreamKind::Blocks)
}

#[cfg(feature = "app_api")]
pub fn handle_v1_explorer_transactions_stream(
    kura: Arc<Kura>,
    events: EventsSender,
) -> Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>> {
    explorer_stream(kura, events, ExplorerStreamKind::Transactions)
}

#[cfg(feature = "app_api")]
pub fn handle_v1_explorer_instructions_stream(
    kura: Arc<Kura>,
    events: EventsSender,
) -> Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>> {
    explorer_stream(kura, events, ExplorerStreamKind::Instructions)
}

#[cfg(feature = "app_api")]
fn explorer_stream(
    kura: Arc<Kura>,
    events: EventsSender,
    kind: ExplorerStreamKind,
) -> Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>> {
    let mut keepalive_interval = tokio::time::interval(Duration::from_secs(15));
    keepalive_interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    let stream = stream::unfold(
        ExplorerStreamState {
            rx: events.subscribe(),
            kura,
            pending: VecDeque::new(),
            kind,
            keepalive_interval,
        },
        |mut state| async move {
            use tokio::sync::broadcast::error::RecvError;
            loop {
                if let Some(payload) = state.pending.pop_front() {
                    let ev = SseEvent::default().data(payload);
                    return Some((Ok(ev), state));
                }
                tokio::select! {
                    recv = state.rx.recv() => {
                        match recv {
                            Ok(event) => {
                                if let Some(height) = committed_block_height(&event) {
                                    populate_explorer_queue(
                                        &state.kura,
                                        height,
                                        state.kind,
                                        &mut state.pending,
                                    );
                                }
                            }
                            Err(RecvError::Lagged(_)) => {
                                let ev = SseEvent::default().comment("lagged");
                                return Some((Ok(ev), state));
                            }
                            Err(RecvError::Closed) => return None,
                        }
                    }
                    _ = state.keepalive_interval.tick() => {
                        let ev = SseEvent::default().comment("keepalive");
                        return Some((Ok(ev), state));
                    }
                }
            }
        },
    );
    Sse::new(stream)
}

#[cfg(feature = "app_api")]
struct ExplorerStreamState {
    rx: tokio::sync::broadcast::Receiver<EventBox>,
    kura: Arc<Kura>,
    pending: VecDeque<String>,
    kind: ExplorerStreamKind,
    keepalive_interval: tokio::time::Interval,
}

#[cfg(feature = "app_api")]
fn populate_explorer_queue(
    kura: &Arc<Kura>,
    height: u64,
    kind: ExplorerStreamKind,
    queue: &mut VecDeque<String>,
) {
    match kind {
        ExplorerStreamKind::Blocks => {
            let height_usize: usize = match height.try_into() {
                Ok(value) => value,
                Err(_) => {
                    iroha_logger::warn!(
                        height,
                        "failed to emit explorer block SSE payload: block height exceeds host pointer width"
                    );
                    return;
                }
            };
            let nonzero_height = match NonZeroUsize::new(height_usize) {
                Some(value) => value,
                None => {
                    iroha_logger::warn!(
                        height,
                        "failed to emit explorer block SSE payload: block height must be at least 1"
                    );
                    return;
                }
            };
            let Some(block) = kura.get_block(nonzero_height) else {
                return;
            };
            let dto = crate::explorer::ExplorerBlockDto::from_block(&block);
            if let Ok(body) = norito::json::to_json(&dto) {
                queue.push_back(body);
            } else {
                iroha_logger::warn!(height, "failed to serialize explorer block SSE payload");
            }
        }
        ExplorerStreamKind::Transactions => {
            let filters = ExplorerTransactionFilters {
                authority: None,
                status: None,
                block: Some(height),
                asset_id: None,
            };
            match collect_transaction_summaries_from_kura(kura, height, &filters) {
                Ok(items) => {
                    for dto in items {
                        if let Ok(body) = norito::json::to_json(&dto) {
                            queue.push_back(body);
                        } else {
                            iroha_logger::warn!(
                                height,
                                "failed to serialize explorer transaction SSE payload"
                            );
                        }
                    }
                }
                Err(error) => {
                    iroha_logger::warn!(%error, "failed to collect explorer transactions for SSE");
                }
            }
        }
        ExplorerStreamKind::Instructions => {
            let filters = ExplorerInstructionFilters {
                account: None,
                authority: None,
                transaction_hash: None,
                status: None,
                block: Some(height),
                kind: None,
                asset_id: None,
            };
            match collect_instruction_history_from_kura(kura, height, &filters) {
                Ok(items) => {
                    for dto in items {
                        if let Ok(body) = norito::json::to_json(&dto) {
                            queue.push_back(body);
                        } else {
                            iroha_logger::warn!(
                                height,
                                "failed to serialize explorer instruction SSE payload"
                            );
                        }
                    }
                }
                Err(error) => {
                    iroha_logger::warn!(%error, "failed to collect explorer instructions for SSE");
                }
            }
        }
    }
}

#[cfg(feature = "app_api")]
fn committed_block_height(event: &EventBox) -> Option<u64> {
    match event {
        EventBox::Pipeline(pipeline_event) => {
            let PipelineEventBox::Block(block_event) = pipeline_event else {
                return None;
            };
            match block_event.status() {
                BlockStatus::Committed | BlockStatus::Applied => {
                    Some(block_event.header().height().get())
                }
                _ => None,
            }
        }
        EventBox::PipelineBatch(events) => events.iter().find_map(|event| {
            let PipelineEventBox::Block(block_event) = event else {
                return None;
            };
            match block_event.status() {
                BlockStatus::Committed | BlockStatus::Applied => {
                    Some(block_event.header().height().get())
                }
                _ => None,
            }
        }),
        _ => None,
    }
}

#[cfg(all(feature = "app_api", feature = "telemetry"))]
