    use iroha_data_model::{
        account::AccountId,
        asset::{Asset, AssetDefinition, AssetDefinitionId, AssetId},
        block::BlockHeader,
        domain::DomainId,
        isi::Transfer,
        metadata::Metadata,
        prelude::*,
        transaction::SignedTransaction,
        validation_fee::{
            VALIDATION_FEE_DS_SCALE, VALIDATION_FEE_INSTRUCTION_INDEX_METADATA_KEY,
            VALIDATION_FEE_POLICY_ACTIVATION_DELAY_BLOCKS, VALIDATION_FEE_POLICY_HASH_METADATA_KEY,
            VALIDATION_FEE_POLICY_SCHEMA_VERSION, VALIDATION_FEE_POLICY_VERSION_METADATA_KEY,
            ValidationFeeChargingMode, ValidationFeeFinalizationEvidenceV1,
            ValidationFeeGovernanceVotingModeV1, ValidationFeeGovernanceWindowV1,
            ValidationFeeMultisigMarkerV1, ValidationFeeParliamentAuthorizationV1,
            ValidationFeePlainElectorateEligibilityRuleV1, ValidationFeePlainElectorateMemberV1,
            ValidationFeePlainElectorateRulesV1, ValidationFeePlainElectorateSnapshotV1,
            ValidationFeePolicyRegistryEntryV1, ValidationFeePolicyRegistryV1,
            ValidationFeePolicyV1,
        },
    };
    use iroha_executor_data_model::isi::multisig::MultisigPropose;
    use iroha_primitives::{json::Json, numeric::Quantity};
    use sha2::Digest as _;

    use super::*;

    const TEST_VALIDATION_FEE_ASSET_SCALE: u8 = VALIDATION_FEE_DS_SCALE;
    const TEST_VALIDATION_FEE_MINOR_UNITS: u64 = 10;
    const TEST_REFERENDUM_START_HEIGHT: u64 = 1;
    const TEST_REFERENDUM_DURATION_BLOCKS: u64 = 3_600;
    const TEST_REFERENDUM_END_HEIGHT: u64 =
        TEST_REFERENDUM_START_HEIGHT + TEST_REFERENDUM_DURATION_BLOCKS - 1;
    const TEST_POLICY_ENACTMENT_HEIGHT: u64 = TEST_REFERENDUM_END_HEIGHT + 1;
    const TEST_POLICY_EFFECTIVE_HEIGHT: u64 =
        TEST_POLICY_ENACTMENT_HEIGHT + VALIDATION_FEE_POLICY_ACTIVATION_DELAY_BLOCKS;
    const TEST_ACTIVE_VALIDATION_HEIGHT: u64 = TEST_POLICY_EFFECTIVE_HEIGHT + 1;

    fn fixture_key_pair(seed: u8, algorithm: Algorithm, context: &'static str) -> KeyPair {
        checked_routing_fixture_keypair(seed, algorithm, context)
    }

    fn ed25519_key_pair(seed: u8, context: &'static str) -> KeyPair {
        fixture_key_pair(seed, Algorithm::Ed25519, context)
    }

    fn block_header(height: u64, timestamp_ms: u64) -> BlockHeader {
        BlockHeader::new(
            NonZeroU64::new(height).expect("height"),
            None,
            None,
            None,
            timestamp_ms,
            0,
        )
    }

    fn account(seed: u8, context: &'static str) -> (AccountId, KeyPair) {
        let key_pair = ed25519_key_pair(seed, context);
        (AccountId::new(key_pair.public_key().clone()), key_pair)
    }

    fn fee_asset_definition_id() -> AssetDefinitionId {
        AssetDefinitionId::new(
            DomainId::try_new("fees", "paynet").expect("domain id"),
            "fee_token".parse().expect("asset name"),
        )
    }

    fn test_world(
        user: &AccountId,
        recipient: &AccountId,
        treasury: &AccountId,
        fee_asset: &AssetDefinitionId,
    ) -> World {
        let domain_id = DomainId::try_new("fees", "paynet").expect("domain id");
        let domain = Domain::new(domain_id).build(user);
        let asset_definition = AssetDefinition::numeric(fee_asset.clone()).build(user);
        let user_asset = Asset::new(
            AssetId::new(fee_asset.clone(), user.clone()),
            Quantity::from(100_u32),
        );
        World::with_assets(
            [domain],
            [
                Account::new(user.clone()).build(user),
                Account::new(recipient.clone()).build(user),
                Account::new(treasury.clone()).build(user),
            ],
            [asset_definition],
            [user_asset],
            [],
        )
    }

    fn test_state() -> (
        Arc<State>,
        AccountId,
        KeyPair,
        AccountId,
        AccountId,
        AssetDefinitionId,
    ) {
        let (user, user_key_pair) = account(1, "derive validation-fee Torii user key");
        let (recipient, _) = account(2, "derive validation-fee Torii recipient key");
        let (treasury, _) = account(3, "derive validation-fee Torii treasury key");
        let fee_asset = fee_asset_definition_id();
        let state = State::new_for_testing(
            test_world(&user, &recipient, &treasury, &fee_asset),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        (
            Arc::new(state),
            user,
            user_key_pair,
            recipient,
            treasury,
            fee_asset,
        )
    }

    fn test_app_state() -> (
        crate::SharedAppState,
        AccountId,
        KeyPair,
        AccountId,
        AccountId,
        AssetDefinitionId,
    ) {
        let (user, user_key_pair) = account(1, "derive validation-fee Torii user key");
        let (recipient, _) = account(2, "derive validation-fee Torii recipient key");
        let (treasury, _) = account(3, "derive validation-fee Torii treasury key");
        let fee_asset = fee_asset_definition_id();
        let app = crate::tests_runtime_handlers::mk_app_state_for_tests_with_world(test_world(
            &user, &recipient, &treasury, &fee_asset,
        ));
        (app, user, user_key_pair, recipient, treasury, fee_asset)
    }

    fn queue() -> Arc<Queue> {
        let events: iroha_core::EventsSender = tokio::sync::broadcast::channel(8).0;
        Arc::new(Queue::from_config(
            iroha_config::parameters::actual::Queue {
                capacity: NonZeroUsize::new(32).expect("queue capacity non-zero"),
                capacity_per_user: NonZeroUsize::new(32).expect("queue per-user capacity non-zero"),
                transaction_time_to_live: Duration::from_secs(60),
                ..Default::default()
            },
            events,
        ))
    }

    fn commit_empty_genesis_like_block(state: &Arc<State>) -> [u8; 32] {
        let block_signer = fixture_key_pair(
            240,
            Algorithm::BlsNormal,
            "derive validation-fee Torii genesis block signer",
        );
        let new_block = BlockBuilder::new(Vec::new())
            .chain(0, None)
            .sign(block_signer.private_key())
            .unpack(|_| {});
        let mut state_block = state.block(new_block.header());
        let valid_block =
            ValidBlock::validate_unchecked(new_block.into(), &mut state_block).unpack(|_| {});
        let committed_block = valid_block.commit_unchecked().unpack(|_| {});
        let genesis_hash = committed_block.as_ref().hash();
        let _events = state_block.apply_without_execution(&committed_block, Vec::new());
        state_block.commit().expect("commit initial block hash");
        *genesis_hash.as_ref()
    }

    fn validation_fee_policy(
        state: &Arc<State>,
        fee_asset: AssetDefinitionId,
        treasury: AccountId,
        genesis_hash: [u8; 32],
    ) -> ValidationFeePolicyV1 {
        ValidationFeePolicyV1 {
            schema_version: VALIDATION_FEE_POLICY_SCHEMA_VERSION,
            chain_id: state.chain_id.clone(),
            genesis_hash,
            policy_version: 1,
            previous_policy_hash: None,
            ds_asset_id: fee_asset,
            ds_scale: TEST_VALIDATION_FEE_ASSET_SCALE,
            fee: iroha_data_model::validation_fee::initial_validation_fee_amount(),
            treasury_account_id: treasury,
            charging_mode: ValidationFeeChargingMode::PerQualifyingTransferInstruction,
            effective_from_height: TEST_POLICY_EFFECTIVE_HEIGHT,
            expires_after_height: TEST_POLICY_EFFECTIVE_HEIGHT.checked_add(100),
            exemption_classes: Vec::new(),
            treasury_payout_binding: None,
        }
    }

    fn validation_fee_policy_asset(policy: &ValidationFeePolicyV1) -> AssetDefinitionId {
        policy.ds_asset_id.clone()
    }

    fn validation_fee_policy_treasury(policy: &ValidationFeePolicyV1) -> AccountId {
        policy.treasury_account_id.clone()
    }

    fn install_validation_fee_policy(
        state: &Arc<State>,
        authority: &AccountId,
        policy: ValidationFeePolicyV1,
    ) {
        use iroha_data_model::{
            governance::types::{
                GovernanceFinalizationEvidence, ParliamentBodies, ParliamentBody, ParliamentRoster,
                ProposalKind, ValidationFeePolicyProposal,
            },
            isi::governance::VotingMode,
        };

        let member = authority.clone();
        let rosters = [
            ParliamentBody::RulesCommittee,
            ParliamentBody::AgendaCouncil,
            ParliamentBody::InterestPanel,
            ParliamentBody::ReviewPanel,
            ParliamentBody::PolicyJury,
            ParliamentBody::OversightCommittee,
            ParliamentBody::FmaCommittee,
        ]
        .into_iter()
        .map(|body| {
            (
                body,
                ParliamentRoster {
                    body,
                    epoch: 1,
                    members: vec![member.clone()],
                    alternates: Vec::new(),
                    verified: 1,
                    candidate_count: 1,
                    derived_by: Default::default(),
                },
            )
        })
        .collect();
        let bodies = ParliamentBodies {
            selection_epoch: 1,
            rosters,
        };
        let roster_digest = Blake2b512::digest(
            norito::to_bytes(&bodies).expect("encode validation-fee Parliament bodies"),
        );
        let mut roster_root = [0; 32];
        roster_root.copy_from_slice(&roster_digest[..32]);
        let plain_electorate_rules = ValidationFeePlainElectorateRulesV1 {
            voting_asset_id: policy.ds_asset_id.clone(),
            ballot_amount: 150_u64.into(),
            ballot_duration_blocks: TEST_REFERENDUM_DURATION_BLOCKS,
            citizenship_amount: 10_000_u64.into(),
            max_members: 256,
            conviction_step_blocks: 100,
            max_conviction: 6,
            min_turnout: 1,
            approval_threshold_numerator: 1,
            approval_threshold_denominator: 2,
            eligibility_rule:
                ValidationFeePlainElectorateEligibilityRuleV1::ProposalOperatorAtOrBeforeGateOthersAfterGate,
        };
        let kind = ProposalKind::ValidationFeePolicy(ValidationFeePolicyProposal {
            policy: policy.clone(),
            payout_lifecycle_proposal_id: None,
            plain_electorate_rules: plain_electorate_rules.clone(),
        });
        let proposal_id = kind.fingerprint();
        let approval_gate_height = TEST_REFERENDUM_START_HEIGHT - 1;
        let electorate = ValidationFeePlainElectorateSnapshotV1::from_canonical_members(
            proposal_id,
            authority.clone(),
            TEST_REFERENDUM_START_HEIGHT,
            approval_gate_height,
            vec![ValidationFeePlainElectorateMemberV1 {
                account_id: authority.clone(),
                bonded_height: approval_gate_height,
                bonded_amount: plain_electorate_rules.citizenship_amount.clone(),
            }],
        )
        .expect("canonical validation-fee Torii PLAIN electorate snapshot");
        assert_eq!(
            electorate.context_error(proposal_id, authority, &plain_electorate_rules),
            None
        );
        let authorization = ValidationFeeParliamentAuthorizationV1 {
            proposal_id,
            proposal_fingerprint: proposal_id,
            proposal_time_roster_root: roster_root,
            plain_electorate_snapshot_root: electorate.roster_root,
            plain_electorate_snapshot_member_count: electorate.member_count,
            plain_electorate_snapshot_captured_at_height: electorate.captured_at_height,
            plain_electorate_snapshot_approval_gate_height: electorate.approval_gate_height,
            referendum_window: ValidationFeeGovernanceWindowV1 {
                lower: TEST_REFERENDUM_START_HEIGHT,
                upper: TEST_REFERENDUM_END_HEIGHT,
            },
            finalization: ValidationFeeFinalizationEvidenceV1 {
                referendum_id: proposal_id,
                finalized_at_height: TEST_REFERENDUM_END_HEIGHT,
                mode: ValidationFeeGovernanceVotingModeV1::Plain,
                approve: 1,
                reject: 0,
                abstain: 0,
                min_turnout: 1,
                approval_threshold_numerator: 1,
                approval_threshold_denominator: 2,
                approved: true,
            },
            enacted_at_height: TEST_POLICY_ENACTMENT_HEIGHT,
        };
        let entry = ValidationFeePolicyRegistryEntryV1::from_enactment(
            policy,
            plain_electorate_rules,
            authorization,
            None,
        )
        .expect("validation-fee registry entry");
        let registry = ValidationFeePolicyRegistryV1 {
            registered_policies: vec![entry],
        };
        let mut block = state.block(block_header(
            TEST_POLICY_ENACTMENT_HEIGHT,
            1_700_000_001_000,
        ));
        let mut stx = block.transaction();
        stx.world.governance_proposals_mut().insert(
            proposal_id,
            iroha_core::state::GovernanceProposalRecord {
                proposer: authority.clone(),
                kind,
                created_height: TEST_REFERENDUM_START_HEIGHT,
                status: iroha_core::state::GovernanceProposalStatus::Enacted,
                pipeline: iroha_core::state::GovernancePipeline::default(),
                parliament_snapshot: Some(iroha_core::state::GovernanceParliamentSnapshot {
                    selection_epoch: 1,
                    beacon: [0x55; 32],
                    roster_root,
                    bodies,
                }),
                finalization_evidence: Some(GovernanceFinalizationEvidence {
                    proposal_id,
                    referendum_id: proposal_id,
                    finalized_at_height: TEST_REFERENDUM_END_HEIGHT,
                    mode: VotingMode::Plain,
                    approve: 1,
                    reject: 0,
                    abstain: 0,
                    min_turnout: 1,
                    approval_threshold_numerator: 1,
                    approval_threshold_denominator: 2,
                    approved: true,
                }),
                enacted_at_height: Some(TEST_POLICY_ENACTMENT_HEIGHT),
            },
        );
        let referendum_id = hex::encode(proposal_id);
        stx.world.governance_referenda_mut().insert(
            referendum_id.clone(),
            iroha_core::state::GovernanceReferendumRecord {
                h_start: TEST_REFERENDUM_START_HEIGHT,
                h_end: TEST_REFERENDUM_END_HEIGHT,
                status: iroha_core::state::GovernanceReferendumStatus::Closed,
                mode: iroha_core::state::GovernanceReferendumMode::Plain,
            },
        );
        let mut approvals = iroha_core::state::GovernanceStageApprovals::default();
        for body in [
            ParliamentBody::RulesCommittee,
            ParliamentBody::AgendaCouncil,
            ParliamentBody::InterestPanel,
            ParliamentBody::ReviewPanel,
            ParliamentBody::PolicyJury,
            ParliamentBody::OversightCommittee,
            ParliamentBody::FmaCommittee,
        ] {
            approvals
                .ensure_stage(body, 1, 1, 10_000)
                .record(authority.clone());
        }
        approvals.approval_gate_height = Some(approval_gate_height);
        approvals.validation_fee_plain_electorate_snapshot = Some(electorate);
        stx.world
            .governance_stage_approvals_mut()
            .insert(referendum_id, approvals);
        stx.world
            .parameters_mut_for_testing()
            .get_mut()
            .set_parameter(Parameter::Custom(registry.into_custom_parameter()));
        stx.apply();
        block.commit().expect("commit validation-fee policy");
    }

    fn metadata_for_policy(
        policy: &ValidationFeePolicyV1,
        fee_instruction_index: usize,
    ) -> Metadata {
        let mut metadata = Metadata::default();
        metadata.insert(
            VALIDATION_FEE_POLICY_VERSION_METADATA_KEY
                .parse()
                .expect("metadata key"),
            Json::new(policy.policy_version),
        );
        metadata.insert(
            VALIDATION_FEE_POLICY_HASH_METADATA_KEY
                .parse()
                .expect("metadata key"),
            Json::new(hex::encode(policy.policy_hash().expect("policy hash"))),
        );
        metadata.insert(
            VALIDATION_FEE_INSTRUCTION_INDEX_METADATA_KEY
                .parse()
                .expect("metadata key"),
            Json::new(u64::try_from(fee_instruction_index).expect("instruction index fits")),
        );
        metadata
    }

    fn signed_transfer(
        state: &Arc<State>,
        user: &AccountId,
        user_key_pair: &KeyPair,
        recipient: &AccountId,
        fee_asset: &AssetDefinitionId,
        policy: &ValidationFeePolicyV1,
        include_fee: bool,
    ) -> SignedTransaction {
        let principal = Transfer::asset_quantity(
            AssetId::new(fee_asset.clone(), user.clone()),
            1_u32,
            recipient.clone(),
        );
        let mut instructions: Vec<InstructionBox> = vec![principal.into()];
        if include_fee {
            instructions.push(
                Transfer::asset_quantity(
                    AssetId::new(fee_asset.clone(), user.clone()),
                    policy.fee.clone(),
                    validation_fee_policy_treasury(policy),
                )
                .into(),
            );
        }
        let metadata = if include_fee {
            metadata_for_policy(policy, 1)
        } else {
            Metadata::default()
        };
        TransactionBuilder::new(
            state.chain_id.clone(),
            user.clone(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions(instructions)
        .with_metadata(metadata)
        .sign(user_key_pair.private_key())
    }

    async fn submit_via_public_transaction_handler(
        app: crate::SharedAppState,
        transaction: SignedTransaction,
    ) -> axum::http::StatusCode {
        use axum::{extract::State as AxumState, response::IntoResponse};

        crate::handler_post_transaction(
            AxumState(app),
            axum::http::HeaderMap::new(),
            None,
            crate::utils::extractors::JsonOrNoritoVersioned(transaction),
        )
        .await
        .expect("public transaction handler should accept a statelessly valid transaction")
        .into_response()
        .status()
    }

    async fn submit_via_public_transaction_batch_handler(
        app: crate::SharedAppState,
        transactions: Vec<SignedTransaction>,
    ) -> axum::http::StatusCode {
        use axum::extract::State as AxumState;

        let payloads = transactions
            .iter()
            .map(iroha_version::codec::EncodeVersioned::encode_versioned)
            .collect();
        crate::handler_post_transactions_batch(
            AxumState(app),
            axum::http::HeaderMap::new(),
            crate::utils::extractors::Norito(payloads),
        )
        .await
        .expect("public transaction batch handler should accept statelessly valid transactions")
        .status()
    }

    async fn submit_via_public_transaction_batch_http(
        app: crate::SharedAppState,
        transactions: Vec<SignedTransaction>,
    ) -> axum::http::StatusCode {
        use tower::ServiceExt as _;

        let payloads = transactions
            .iter()
            .map(iroha_version::codec::EncodeVersioned::encode_versioned)
            .collect::<Vec<_>>();
        let body = norito::to_bytes(&payloads).expect("encode transaction batch payloads");
        let router = axum::Router::new()
            .route(
                iroha_torii_shared::uri::TRANSACTIONS_BATCH,
                axum::routing::post(crate::handler_post_transactions_batch),
            )
            .with_state(app);
        let request = axum::http::Request::builder()
            .method(axum::http::Method::POST)
            .uri(iroha_torii_shared::uri::TRANSACTIONS_BATCH)
            .header(
                axum::http::header::CONTENT_TYPE,
                crate::utils::NORITO_MIME_TYPE,
            )
            .body(axum::body::Body::from(body))
            .expect("HTTP transaction batch request");
        router
            .oneshot(request)
            .await
            .expect("router response")
            .status()
    }

    fn validate_single_queued_transaction_in_block(
        state: &Arc<State>,
        queue: &Arc<Queue>,
        height: u64,
    ) -> String {
        let max_txs_in_block = NonZeroUsize::new(1024).expect("nonzero");
        let mut guards = Vec::new();
        queue.get_transactions_for_block(&state.view(), max_txs_in_block, &mut guards);
        assert_eq!(guards.len(), 1, "expected one queued transaction");
        let accepted = guards
            .iter()
            .map(TransactionGuard::clone_accepted)
            .next()
            .expect("queued transaction");
        let mut block = state.block(block_header(height, 1_700_000_002_000 + height));
        let mut ivm_cache = IvmCache::new();
        let (_, result) = block.validate_transaction(accepted, &mut ivm_cache);
        match result {
            Ok(_) => "ok".to_string(),
            Err(error) => format!("{error:?}"),
        }
    }

    #[tokio::test]
    async fn torii_raw_fee_asset_transfer_reaches_validator_fee_admission() {
        let (state, user, user_key_pair, recipient, treasury, fee_asset) = test_state();
        let chain_id = Arc::new(state.chain_id.clone());
        let genesis_hash = commit_empty_genesis_like_block(&state);
        let policy = validation_fee_policy(&state, fee_asset.clone(), treasury, genesis_hash);
        install_validation_fee_policy(&state, &user, policy.clone());

        let missing_fee_queue = queue();
        let missing_fee_tx = signed_transfer(
            &state,
            &user,
            &user_key_pair,
            &recipient,
            &fee_asset,
            &policy,
            false,
        );
        handle_transaction(
            Arc::clone(&chain_id),
            Arc::clone(&missing_fee_queue),
            Arc::clone(&state),
            missing_fee_tx,
        )
        .await
        .expect("Torii should enqueue a statelessly valid raw transaction");
        let missing_fee_error = validate_single_queued_transaction_in_block(
            &state,
            &missing_fee_queue,
            TEST_ACTIVE_VALIDATION_HEIGHT,
        );
        assert!(
            missing_fee_error.contains("missing validation-fee transfer of 10 minor units"),
            "unexpected missing-fee rejection: {missing_fee_error}"
        );

        let exact_fee_queue = queue();
        let exact_fee_tx = signed_transfer(
            &state,
            &user,
            &user_key_pair,
            &recipient,
            &fee_asset,
            &policy,
            true,
        );
        handle_transaction(
            Arc::clone(&chain_id),
            Arc::clone(&exact_fee_queue),
            Arc::clone(&state),
            exact_fee_tx,
        )
        .await
        .expect("Torii should enqueue a raw transaction carrying the exact validation fee");
        let exact_fee_result = validate_single_queued_transaction_in_block(
            &state,
            &exact_fee_queue,
            TEST_ACTIVE_VALIDATION_HEIGHT,
        );
        assert_eq!(exact_fee_result, "ok");
    }

    #[tokio::test]
    async fn torii_native_multisig_signed_fee_coordinate_resolves_nested_context() {
        let (state, user, user_key_pair, recipient, treasury, fee_asset) = test_state();
        let chain_id = Arc::new(state.chain_id.clone());
        let genesis_hash = commit_empty_genesis_like_block(&state);
        let policy =
            validation_fee_policy(&state, fee_asset.clone(), treasury.clone(), genesis_hash);
        install_validation_fee_policy(&state, &user, policy.clone());
        let (multisig, _) = account(4, "derive validation-fee multisig account");

        let proposal = || {
            MultisigPropose::new(
                multisig.clone(),
                vec![
                    Transfer::asset_quantity(
                        AssetId::new(fee_asset.clone(), multisig.clone()),
                        1_u32,
                        recipient.clone(),
                    )
                    .into(),
                    Transfer::asset_quantity(
                        AssetId::new(fee_asset.clone(), multisig.clone()),
                        policy.fee.clone(),
                        treasury.clone(),
                    )
                    .into(),
                    ValidationFeeMultisigMarkerV1::new(
                        policy.policy_version,
                        policy.policy_hash().expect("policy hash"),
                        1,
                        None,
                    )
                    .into_instruction(),
                ],
                None,
            )
        };
        let signed = |instructions: Vec<InstructionBox>, coordinate| {
            TransactionBuilder::new(
                state.chain_id.clone(),
                user.clone(),
                iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
            )
            .with_instructions(instructions)
            .with_metadata(metadata_for_policy(&policy, coordinate))
            .sign(user_key_pair.private_key())
        };

        let exact_queue = queue();
        handle_transaction(
            Arc::clone(&chain_id),
            Arc::clone(&exact_queue),
            Arc::clone(&state),
            signed(vec![proposal().into()], 1),
        )
        .await
        .expect("Torii should enqueue the nested exact-fee proposal");
        let exact_result = validate_single_queued_transaction_in_block(
            &state,
            &exact_queue,
            TEST_ACTIVE_VALIDATION_HEIGHT,
        );
        assert!(
            !exact_result.contains("validation-fee admission rejected transaction"),
            "nested exact fee must pass validation-fee admission: {exact_result}"
        );

        let wrong_queue = queue();
        handle_transaction(
            Arc::clone(&chain_id),
            Arc::clone(&wrong_queue),
            Arc::clone(&state),
            signed(vec![proposal().into()], 0),
        )
        .await
        .expect("Torii should enqueue the nested wrong-coordinate proposal");
        let wrong_result = validate_single_queued_transaction_in_block(
            &state,
            &wrong_queue,
            TEST_ACTIVE_VALIDATION_HEIGHT,
        );
        assert!(
            wrong_result.contains("metadata and signed multisig validation-fee marker disagree"),
            "nested principal coordinate must reject: {wrong_result}"
        );

        let ambiguous_queue = queue();
        let xor = AssetDefinitionId::new(
            DomainId::try_new("fees", "paynet").expect("domain id"),
            "xor".parse().expect("asset name"),
        );
        handle_transaction(
            chain_id,
            Arc::clone(&ambiguous_queue),
            Arc::clone(&state),
            signed(
                vec![
                    proposal().into(),
                    Transfer::asset_quantity(
                        AssetId::new(xor, user.clone()),
                        1_u32,
                        recipient.clone(),
                    )
                    .into(),
                ],
                1,
            ),
        )
        .await
        .expect("Torii should enqueue the ambiguous-coordinate proposal");
        let ambiguous_result = validate_single_queued_transaction_in_block(
            &state,
            &ambiguous_queue,
            TEST_ACTIVE_VALIDATION_HEIGHT,
        );
        assert!(
            ambiguous_result.contains("matches multiple transfer contexts"),
            "ambiguous nested coordinate must reject: {ambiguous_result}"
        );
    }

