#[cfg(feature = "app_api")]
fn compact_number(value: f64, max_fraction_digits: usize) -> String {
    if !value.is_finite() {
        return "-".to_owned();
    }
    let mut rendered = format!("{value:.prec$}", prec = max_fraction_digits);
    while rendered.contains('.') && rendered.ends_with('0') {
        rendered.pop();
    }
    if rendered.ends_with('.') {
        rendered.pop();
    }
    if rendered.is_empty() {
        "0".to_owned()
    } else {
        rendered
    }
}

#[cfg(feature = "app_api")]
fn format_signed_asset_amount(value: f64, symbol: &str) -> String {
    if !value.is_finite() {
        return "-".to_owned();
    }
    let sign = if value > 0.0 {
        "+"
    } else if value < 0.0 {
        "-"
    } else {
        ""
    };
    format!("{sign}{} {}", compact_number(value.abs(), 4), symbol)
}

#[cfg(feature = "app_api")]
fn format_percent_ratio(value: Option<f64>) -> String {
    value
        .map(|raw| format!("{}%", compact_number(raw * 100.0, 2)))
        .unwrap_or_else(|| "-".to_owned())
}

#[cfg(feature = "app_api")]
fn asset_ticker(asset_id: &str) -> String {
    asset_id
        .split('#')
        .next()
        .unwrap_or(asset_id)
        .trim()
        .to_ascii_uppercase()
}

#[cfg(feature = "app_api")]
fn humanize_identifier(raw: &str) -> String {
    raw.split('_')
        .filter(|segment| !segment.is_empty())
        .map(|segment| {
            let mut chars = segment.chars();
            match chars.next() {
                Some(first) => format!("{}{}", first.to_ascii_uppercase(), chars.as_str()),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(feature = "app_api")]
fn format_timestamp_label(timestamp_ms: Option<u64>) -> String {
    timestamp_ms
        .and_then(|raw| OffsetDateTime::from_unix_timestamp((raw / 1000) as i64).ok())
        .map(|dt| format!("{:02}:{:02} UTC", dt.hour(), dt.minute()))
        .unwrap_or_else(|| "-".to_owned())
}

#[cfg(feature = "app_api")]
fn value_as_i64(value: &Value) -> Option<i64> {
    value
        .as_i64()
        .or_else(|| value.as_u64().and_then(|raw| i64::try_from(raw).ok()))
        .or_else(|| value.as_str().and_then(|raw| raw.parse::<i64>().ok()))
}

#[cfg(feature = "app_api")]
fn object_lookup_i64(object: &Map, keys: &[&str]) -> Option<i64> {
    keys.iter()
        .find_map(|key| object.get(*key).and_then(value_as_i64))
}

#[cfg(feature = "app_api")]
fn object_lookup_string(object: &Map, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        object
            .get(*key)
            .and_then(Value::as_str)
            .map(|value| value.trim().to_owned())
            .filter(|value| !value.is_empty())
    })
}

#[cfg(feature = "app_api")]
fn iroha_json_to_value(value: &IrohaJson) -> Result<Value> {
    json::parse_value(value.get())
        .map_err(|err| conversion_error(format!("invalid contract view JSON: {err}")))
}

#[cfg(feature = "app_api")]
fn parse_contract_view_int(value: &Value) -> Option<i64> {
    match value {
        Value::Array(values) => values.first().and_then(value_as_i64),
        Value::Object(object) => object_lookup_i64(object, &["value", "result"]),
        other => value_as_i64(other),
    }
}

#[cfg(feature = "app_api")]
const URANAI_DPM_VIRTUAL_SHARES_XOR: i64 = 100;

#[cfg(feature = "app_api")]
#[derive(Debug, Clone)]
struct UranaiOutcomeDescriptor {
    outcome_id: String,
    label: String,
}

#[cfg(feature = "app_api")]
#[derive(Debug, Clone)]
struct UranaiDpmReplayState {
    market_id: String,
    outcome_count: usize,
    outcomes: Vec<UranaiOutcomeDescriptor>,
    outstanding_shares: Vec<i64>,
    trade_count: u64,
    volume_xor_total: i64,
    incomplete_replay: bool,
    initialized: bool,
}

#[cfg(feature = "app_api")]
#[derive(Debug, Copy, Clone, PartialEq, Eq)]
enum UranaiReplayAction {
    CreateMarket,
    Buy,
    Sell,
    PrivateBuy,
}

#[cfg(feature = "app_api")]
impl UranaiDpmReplayState {
    fn new(market_id: &str) -> Self {
        let outcome_count = 2;
        Self {
            market_id: market_id.to_owned(),
            outcome_count,
            outcomes: uranai_default_outcome_descriptors(outcome_count),
            outstanding_shares: vec![0; outcome_count],
            trade_count: 0,
            volume_xor_total: 0,
            incomplete_replay: false,
            initialized: false,
        }
    }

    fn configure_market(&mut self, payload: &Map) {
        if self.trade_count > 0 {
            self.incomplete_replay = true;
            return;
        }
        let outcome_count = uranai_market_outcome_count(payload).max(2);
        self.outcome_count = outcome_count;
        self.outcomes = uranai_outcome_descriptors_from_payload(payload, outcome_count);
        self.outstanding_shares = vec![0; outcome_count];
        self.initialized = true;
    }

    fn ensure_outcome(&mut self, outcome_index: i64) -> Option<usize> {
        let index = usize::try_from(outcome_index).ok()?;
        if index >= self.outcome_count {
            self.incomplete_replay = true;
            self.outcome_count = index + 1;
            self.outstanding_shares.resize(self.outcome_count, 0);
            self.outcomes = uranai_default_outcome_descriptors(self.outcome_count);
        }
        Some(index)
    }

    fn apply_buy(&mut self, outcome_index: usize, collateral_in: i64) -> bool {
        if !self.initialized {
            self.incomplete_replay = true;
        }
        if collateral_in <= 0 {
            self.incomplete_replay = true;
            return false;
        }
        let Some(shares_out) =
            uranai_quote_dpm_buy(&self.outstanding_shares, outcome_index, collateral_in)
        else {
            self.incomplete_replay = true;
            return false;
        };
        if shares_out <= 0 {
            self.incomplete_replay = true;
            return false;
        }
        let Some(next_shares) = self.outstanding_shares[outcome_index].checked_add(shares_out)
        else {
            self.incomplete_replay = true;
            return false;
        };
        let Some(next_volume) = self.volume_xor_total.checked_add(collateral_in) else {
            self.incomplete_replay = true;
            return false;
        };
        self.outstanding_shares[outcome_index] = next_shares;
        self.trade_count = self.trade_count.saturating_add(1);
        self.volume_xor_total = next_volume;
        true
    }

    fn apply_sell(&mut self, outcome_index: usize, shares_in: i64) -> bool {
        if !self.initialized {
            self.incomplete_replay = true;
        }
        if shares_in <= 0 {
            self.incomplete_replay = true;
            return false;
        }
        let Some(collateral_out) =
            uranai_quote_dpm_sell(&self.outstanding_shares, outcome_index, shares_in)
        else {
            self.incomplete_replay = true;
            return false;
        };
        if collateral_out <= 0 {
            self.incomplete_replay = true;
            return false;
        }
        let Some(next_shares) = self.outstanding_shares[outcome_index].checked_sub(shares_in)
        else {
            self.incomplete_replay = true;
            return false;
        };
        let Some(next_volume) = self.volume_xor_total.checked_add(collateral_out) else {
            self.incomplete_replay = true;
            return false;
        };
        self.outstanding_shares[outcome_index] = next_shares;
        self.trade_count = self.trade_count.saturating_add(1);
        self.volume_xor_total = next_volume;
        true
    }

    fn history_point(
        &self,
        projection: &ContractEventProjection,
        side: &'static str,
        traded_outcome_index: usize,
    ) -> Value {
        let mut object = Map::new();
        object.insert("marketId".into(), Value::from(self.market_id.clone()));
        object.insert(
            "timestampMs".into(),
            Value::from(projection.timestamp_ms.unwrap_or_default()),
        );
        object.insert("blockHeight".into(), Value::from(projection.block_height));
        object.insert(
            "txHashHex".into(),
            Value::from(projection.tx_hash_hex.clone()),
        );
        object.insert("tradeCount".into(), Value::from(self.trade_count));
        object.insert(
            "volumeXorTotal".into(),
            Value::from(self.volume_xor_total.max(0) as u64),
        );
        object.insert("side".into(), Value::from(side));
        object.insert(
            "tradedOutcomeIndex".into(),
            Value::from(traded_outcome_index as u64),
        );
        object.insert(
            "outcomes".into(),
            Value::Array(self.outcome_snapshot_values()),
        );
        Value::Object(object)
    }

    fn outcome_snapshot_values(&self) -> Vec<Value> {
        let total_quantity = self
            .outstanding_shares
            .iter()
            .map(|shares| uranai_dpm_quantity(*shares) as f64)
            .sum::<f64>();
        let exact_cost = self
            .outstanding_shares
            .iter()
            .map(|shares| {
                let quantity = uranai_dpm_quantity(*shares) as f64;
                quantity * quantity
            })
            .sum::<f64>()
            .sqrt();

        (0..self.outcome_count)
            .map(|outcome_index| {
                let descriptor = self
                    .outcomes
                    .get(outcome_index)
                    .cloned()
                    .unwrap_or_else(|| {
                        uranai_default_outcome_descriptor(self.outcome_count, outcome_index)
                    });
                let shares = self
                    .outstanding_shares
                    .get(outcome_index)
                    .copied()
                    .unwrap_or_default();
                let quantity = uranai_dpm_quantity(shares) as f64;
                let mut object = Map::new();
                object.insert("outcomeIndex".into(), Value::from(outcome_index as u64));
                object.insert("outcomeId".into(), Value::from(descriptor.outcome_id));
                object.insert("label".into(), Value::from(descriptor.label));
                object.insert(
                    "probability".into(),
                    Value::from(if total_quantity > 0.0 {
                        quantity / total_quantity
                    } else {
                        0.0
                    }),
                );
                object.insert(
                    "priceXor".into(),
                    Value::from(if exact_cost > 0.0 {
                        quantity / exact_cost
                    } else {
                        0.0
                    }),
                );
                object.insert("reserveXor".into(), Value::from(0_u64));
                object.insert(
                    "outstandingSharesXor".into(),
                    Value::from(shares.max(0) as u64),
                );
                Value::Object(object)
            })
            .collect()
    }
}

#[cfg(feature = "app_api")]
fn uranai_default_outcome_descriptor(
    outcome_count: usize,
    outcome_index: usize,
) -> UranaiOutcomeDescriptor {
    match (outcome_count, outcome_index) {
        (2, 0) => UranaiOutcomeDescriptor {
            outcome_id: "yes".to_owned(),
            label: "Yes".to_owned(),
        },
        (2, 1) => UranaiOutcomeDescriptor {
            outcome_id: "no".to_owned(),
            label: "No".to_owned(),
        },
        _ => UranaiOutcomeDescriptor {
            outcome_id: format!("outcome-{outcome_index}"),
            label: format!("Outcome {}", outcome_index + 1),
        },
    }
}

#[cfg(feature = "app_api")]
fn uranai_default_outcome_descriptors(outcome_count: usize) -> Vec<UranaiOutcomeDescriptor> {
    (0..outcome_count)
        .map(|outcome_index| uranai_default_outcome_descriptor(outcome_count, outcome_index))
        .collect()
}

#[cfg(feature = "app_api")]
fn uranai_market_outcome_count(payload: &Map) -> usize {
    object_lookup_i64(payload, &["outcome_count", "outcomeCount"])
        .and_then(|value| usize::try_from(value).ok())
        .or_else(|| {
            payload
                .get("spec_json")
                .or_else(|| payload.get("specJson"))
                .and_then(Value::as_object)
                .and_then(|object| object_lookup_i64(object, &["outcomeCount", "outcome_count"]))
                .and_then(|value| usize::try_from(value).ok())
        })
        .unwrap_or(2)
}

#[cfg(feature = "app_api")]
fn uranai_outcome_descriptors_from_payload(
    payload: &Map,
    outcome_count: usize,
) -> Vec<UranaiOutcomeDescriptor> {
    let defaults = uranai_default_outcome_descriptors(outcome_count);
    let Some(spec) = payload
        .get("spec_json")
        .or_else(|| payload.get("specJson"))
        .and_then(Value::as_object)
    else {
        return defaults;
    };
    let Some(outcomes) = spec.get("outcomes").and_then(Value::as_array) else {
        return defaults;
    };

    (0..outcome_count)
        .map(|outcome_index| {
            let default = defaults
                .get(outcome_index)
                .cloned()
                .unwrap_or_else(|| uranai_default_outcome_descriptor(outcome_count, outcome_index));
            let Some(Value::Object(object)) = outcomes.get(outcome_index) else {
                return default;
            };
            UranaiOutcomeDescriptor {
                outcome_id: object_lookup_string(object, &["id", "outcome_id", "outcomeId"])
                    .unwrap_or(default.outcome_id),
                label: object_lookup_string(object, &["label", "name"]).unwrap_or(default.label),
            }
        })
        .collect()
}

#[cfg(feature = "app_api")]
fn uranai_dpm_quantity(shares: i64) -> u128 {
    u128::from(u64::try_from(URANAI_DPM_VIRTUAL_SHARES_XOR).expect("positive virtual reserve"))
        + u128::from(u64::try_from(shares.max(0)).expect("nonnegative shares"))
}

#[cfg(feature = "app_api")]
fn uranai_int_sqrt_floor(value: u128) -> u128 {
    let mut low = 0_u128;
    let mut high = 1_u128 << 64;
    while low + 1 < high {
        let mid = low + (high - low) / 2;
        if mid <= value / mid {
            low = mid;
        } else {
            high = mid;
        }
    }
    low
}

#[cfg(feature = "app_api")]
fn uranai_dpm_cost(outstanding_shares: &[i64]) -> Option<u128> {
    let mut sum = 0_u128;
    for shares in outstanding_shares {
        let quantity = uranai_dpm_quantity(*shares);
        sum = sum.checked_add(quantity.checked_mul(quantity)?)?;
    }
    Some(uranai_int_sqrt_floor(sum))
}

#[cfg(feature = "app_api")]
fn uranai_quote_dpm_buy(
    outstanding_shares: &[i64],
    outcome_index: usize,
    collateral_in: i64,
) -> Option<i64> {
    if collateral_in <= 0 || outcome_index >= outstanding_shares.len() {
        return Some(0);
    }
    let selected_quantity = uranai_dpm_quantity(outstanding_shares[outcome_index]);
    let collateral = u128::from(u64::try_from(collateral_in).ok()?);
    let target_cost = uranai_dpm_cost(outstanding_shares)?.checked_add(collateral)?;
    let rounded_target = target_cost.checked_add(1)?;
    let target_square = rounded_target.checked_mul(rounded_target)?.checked_sub(1)?;
    let mut other_squares = 0_u128;
    for (index, shares) in outstanding_shares.iter().enumerate() {
        if index == outcome_index {
            continue;
        }
        let quantity = uranai_dpm_quantity(*shares);
        other_squares = other_squares.checked_add(quantity.checked_mul(quantity)?)?;
    }
    if target_square <= other_squares {
        return Some(0);
    }
    let selected_after = uranai_int_sqrt_floor(target_square - other_squares);
    let shares_out = selected_after.checked_sub(selected_quantity)?;
    i64::try_from(shares_out).ok()
}

#[cfg(feature = "app_api")]
fn uranai_quote_dpm_sell(
    outstanding_shares: &[i64],
    outcome_index: usize,
    shares_in: i64,
) -> Option<i64> {
    if shares_in <= 0 || outcome_index >= outstanding_shares.len() {
        return Some(0);
    }
    let current_shares = outstanding_shares[outcome_index].max(0);
    if current_shares < shares_in {
        return Some(0);
    }
    let before = uranai_dpm_cost(outstanding_shares)?;
    let mut next = outstanding_shares.to_vec();
    next[outcome_index] = current_shares.checked_sub(shares_in)?;
    let collateral_out = before.checked_sub(uranai_dpm_cost(&next)?)?;
    i64::try_from(collateral_out).ok()
}

#[cfg(feature = "app_api")]
fn uranai_replay_action(event_kind: &str) -> Option<UranaiReplayAction> {
    match event_kind.trim().to_ascii_lowercase().as_str() {
        "market_created" | "create_market" => Some(UranaiReplayAction::CreateMarket),
        "shares_bought" | "buy" => Some(UranaiReplayAction::Buy),
        "shares_sold" | "sell" => Some(UranaiReplayAction::Sell),
        "private_shares_bought" | "private_buy" => Some(UranaiReplayAction::PrivateBuy),
        _ => None,
    }
}

#[cfg(feature = "app_api")]
fn uranai_payload_market_id(payload: &Map) -> Option<String> {
    object_lookup_string(payload, &["market_id", "marketId"])
}

#[cfg(feature = "app_api")]
fn uranai_projection_contract_matches(
    projection: &ContractEventProjection,
    params: &UranaiMarketHistoryParams,
) -> bool {
    if !projection.result_ok || projection.module != "uranai" {
        return false;
    }
    if let Some(contract_address) = params.contract_address.as_deref() {
        if projection.contract_address != contract_address {
            return false;
        }
    }
    if let Some(contract_alias) = params.contract_alias.as_deref() {
        if projection.contract_alias.as_deref() != Some(contract_alias) {
            return false;
        }
    }
    true
}

#[cfg(feature = "app_api")]
fn uranai_history_timestamp_in_range(
    timestamp_ms: Option<u64>,
    params: &UranaiMarketHistoryParams,
) -> bool {
    if params.since_timestamp_ms.is_none() && params.until_timestamp_ms.is_none() {
        return true;
    }
    let Some(timestamp_ms) = timestamp_ms else {
        return false;
    };
    if params
        .since_timestamp_ms
        .is_some_and(|since| timestamp_ms < since)
    {
        return false;
    }
    if params
        .until_timestamp_ms
        .is_some_and(|until| timestamp_ms > until)
    {
        return false;
    }
    true
}

#[cfg(feature = "app_api")]
fn collect_uranai_market_history_points(
    index: &ContractEventIndex,
    params: &UranaiMarketHistoryParams,
) -> (Vec<Value>, bool, Option<String>, Option<String>) {
    let market_id = params.market_id.trim();
    let mut replay = UranaiDpmReplayState::new(market_id);
    let mut points = Vec::new();
    let mut contract_address = params.contract_address.clone();
    let mut contract_alias = params.contract_alias.clone();
    let mut candidates = index
        .items
        .iter()
        .enumerate()
        .filter(|(_position, projection)| uranai_projection_contract_matches(projection, params))
        .filter(|(_position, projection)| uranai_replay_action(&projection.event_kind).is_some())
        .collect::<Vec<_>>();
    candidates.sort_by(|(left_position, left), (right_position, right)| {
        left.block_height
            .cmp(&right.block_height)
            .then_with(|| left_position.cmp(right_position))
    });

    for (_position, projection) in candidates {
        let action = uranai_replay_action(&projection.event_kind)
            .expect("filtered candidates have replay actions");
        let Some(payload) = event_payload_object(projection) else {
            replay.incomplete_replay = true;
            continue;
        };
        match uranai_payload_market_id(&payload).as_deref() {
            Some(payload_market_id) if payload_market_id == market_id => {}
            Some(_) => continue,
            None => {
                replay.incomplete_replay = true;
                continue;
            }
        };
        contract_address.get_or_insert_with(|| projection.contract_address.clone());
        if contract_alias.is_none() {
            contract_alias = projection.contract_alias.clone();
        }

        match action {
            UranaiReplayAction::CreateMarket => replay.configure_market(&payload),
            UranaiReplayAction::Buy | UranaiReplayAction::PrivateBuy => {
                let Some(outcome_index) =
                    object_lookup_i64(&payload, &["outcome_index", "outcomeIndex"])
                        .and_then(|raw| replay.ensure_outcome(raw))
                else {
                    replay.incomplete_replay = true;
                    continue;
                };
                let collateral_in =
                    object_lookup_i64(&payload, &["collateral_in", "collateralIn"]).unwrap_or(0);
                if replay.apply_buy(outcome_index, collateral_in)
                    && uranai_history_timestamp_in_range(projection.timestamp_ms, params)
                {
                    points.push(replay.history_point(
                        projection,
                        if action == UranaiReplayAction::PrivateBuy {
                            "private_buy"
                        } else {
                            "buy"
                        },
                        outcome_index,
                    ));
                }
            }
            UranaiReplayAction::Sell => {
                let Some(outcome_index) =
                    object_lookup_i64(&payload, &["outcome_index", "outcomeIndex"])
                        .and_then(|raw| replay.ensure_outcome(raw))
                else {
                    replay.incomplete_replay = true;
                    continue;
                };
                let shares_in =
                    object_lookup_i64(&payload, &["shares_in", "sharesIn"]).unwrap_or(0);
                if replay.apply_sell(outcome_index, shares_in)
                    && uranai_history_timestamp_in_range(projection.timestamp_ms, params)
                {
                    points.push(replay.history_point(projection, "sell", outcome_index));
                }
            }
        }
    }

    (
        points,
        replay.incomplete_replay,
        contract_address,
        contract_alias,
    )
}

#[cfg(feature = "app_api")]
fn uranai_market_history_rollup_to_json_value(
    index: &ContractEventIndex,
    params: &UranaiMarketHistoryParams,
    pagination: EffectivePagination,
    count_mode: AppCountMode,
) -> Value {
    let (points, incomplete_replay, contract_address, contract_alias) =
        collect_uranai_market_history_points(index, params);
    let page =
        collect_page_linear_for_mode(points, params.offset, pagination.limit, None, count_mode);
    let mut top = Map::new();
    top.insert("ok".into(), Value::Bool(true));
    top.insert(
        "marketId".into(),
        Value::from(params.market_id.trim().to_owned()),
    );
    if let Some(contract_address) = contract_address {
        top.insert("contract_address".into(), Value::from(contract_address));
    }
    if let Some(contract_alias) = contract_alias {
        top.insert("contract_alias".into(), Value::from(contract_alias));
    }
    top.insert("incompleteReplay".into(), Value::Bool(incomplete_replay));
    if incomplete_replay {
        top.insert(
            "warning".into(),
            Value::from(
                "Market history replay skipped one or more malformed or mismatched events.",
            ),
        );
    }
    top.insert("offset".into(), Value::from(params.offset));
    top.insert(
        "limit".into(),
        Value::from(pagination.limit.unwrap_or(pagination.cap)),
    );
    if page.has_more {
        top.insert(
            "next_offset".into(),
            Value::from(params.offset.saturating_add(page.items.len() as u64)),
        );
    }
    insert_page_metadata(&mut top, &page, count_mode);
    top.insert("items".into(), Value::Array(page.items));
    Value::Object(top)
}

#[cfg(feature = "app_api")]
fn parse_router_assets_from_value(value: &Value) -> Result<(String, String)> {
    match value {
        Value::Array(values) if values.len() >= 2 => {
            let base = values
                .first()
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    conversion_error("router_assets returned malformed base asset".to_owned())
                })?;
            let quote = values
                .get(1)
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    conversion_error("router_assets returned malformed quote asset".to_owned())
                })?;
            Ok((base.to_owned(), quote.to_owned()))
        }
        Value::Object(object) => {
            let base = object_lookup_string(object, &["base_asset", "baseAsset"])
                .ok_or_else(|| conversion_error("router_assets missing base asset".to_owned()))?;
            let quote = object_lookup_string(object, &["quote_asset", "quoteAsset"])
                .ok_or_else(|| conversion_error("router_assets missing quote asset".to_owned()))?;
            Ok((base, quote))
        }
        _ => Err(conversion_error(
            "router_assets returned malformed value".to_owned(),
        )),
    }
}

#[cfg(feature = "app_api")]
fn parse_swap_history_record(record_id: u64, value: &Value) -> Result<SwapFillRollupItem> {
    let (trader, input_is_base, amount_in, amount_out, min_out) = match value {
        Value::Array(values) if values.len() >= 5 => (
            values
                .first()
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    conversion_error(format!("swap history record {record_id} missing trader"))
                })?
                .to_owned(),
            values.get(1).and_then(value_as_i64).ok_or_else(|| {
                conversion_error(format!(
                    "swap history record {record_id} missing input_is_base"
                ))
            })?,
            values.get(2).and_then(value_as_i64).ok_or_else(|| {
                conversion_error(format!("swap history record {record_id} missing amount_in"))
            })?,
            values.get(3).and_then(value_as_i64).ok_or_else(|| {
                conversion_error(format!(
                    "swap history record {record_id} missing amount_out"
                ))
            })?,
            values.get(4).and_then(value_as_i64).ok_or_else(|| {
                conversion_error(format!("swap history record {record_id} missing min_out"))
            })?,
        ),
        Value::Object(object) => (
            object_lookup_string(object, &["trader", "authority"]).ok_or_else(|| {
                conversion_error(format!("swap history record {record_id} missing trader"))
            })?,
            object_lookup_i64(object, &["input_is_base", "inputIsBase"]).ok_or_else(|| {
                conversion_error(format!(
                    "swap history record {record_id} missing input_is_base"
                ))
            })?,
            object_lookup_i64(object, &["amount_in", "amountIn"]).ok_or_else(|| {
                conversion_error(format!("swap history record {record_id} missing amount_in"))
            })?,
            object_lookup_i64(object, &["amount_out", "amountOut"]).ok_or_else(|| {
                conversion_error(format!(
                    "swap history record {record_id} missing amount_out"
                ))
            })?,
            object_lookup_i64(object, &["min_out", "minOut"]).ok_or_else(|| {
                conversion_error(format!("swap history record {record_id} missing min_out"))
            })?,
        ),
        _ => {
            return Err(conversion_error(format!(
                "swap history record {record_id} malformed"
            )));
        }
    };
    let side = if input_is_base == 1 { "buy" } else { "sell" }.to_owned();
    let price = if input_is_base == 1 {
        amount_in as f64 / (amount_out.max(1) as f64)
    } else {
        amount_out as f64 / (amount_in.max(1) as f64)
    };
    let protection_ratio = (min_out > 0).then_some((amount_out - min_out) as f64 / min_out as f64);
    Ok(SwapFillRollupItem {
        record_id,
        trader,
        input_is_base,
        amount_in,
        amount_out,
        min_out,
        side,
        price,
        protection_ratio,
        timestamp_ms: None,
        execution_hash: None,
    })
}

#[cfg(feature = "app_api")]
fn parse_contract_alias_literal(
    literal: Option<&str>,
) -> Result<Option<iroha_data_model::smart_contract::ContractAlias>> {
    literal
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            iroha_data_model::smart_contract::ContractAlias::from_str(value)
                .map_err(|err| conversion_error(format!("invalid contract_alias `{value}`: {err}")))
        })
        .transpose()
}

#[cfg(feature = "app_api")]
fn parse_contract_address_literal(
    literal: Option<&str>,
) -> Result<Option<iroha_data_model::smart_contract::ContractAddress>> {
    literal
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            iroha_data_model::smart_contract::ContractAddress::from_str(value).map_err(|err| {
                conversion_error(format!("invalid contract_address `{value}`: {err}"))
            })
        })
        .transpose()
}

#[cfg(feature = "app_api")]
fn resolve_rollup_contract_target(
    state: &CoreState,
    contract_address_literal: Option<&str>,
    contract_alias_literal: Option<&str>,
    default_alias_literal: &str,
) -> Result<PreparedContractCall> {
    let contract_address = parse_contract_address_literal(contract_address_literal)?;
    let contract_alias = parse_contract_alias_literal(contract_alias_literal)?;
    match (contract_address.as_ref(), contract_alias.as_ref()) {
        (Some(_), Some(_)) => Err(conversion_error(
            "exactly one of contract_address or contract_alias must be provided".to_owned(),
        )),
        (Some(contract_address), None) => prepare_contract_call_by_address(state, contract_address),
        (None, Some(contract_alias)) => {
            prepare_contract_call_by_alias(state, contract_alias, current_time_millis())
        }
        (None, None) => {
            let alias =
                iroha_data_model::smart_contract::ContractAlias::from_str(default_alias_literal)
                    .map_err(|err| {
                        conversion_error(format!(
                            "invalid default contract alias `{default_alias_literal}`: {err}"
                        ))
                    })?;
            prepare_contract_call_by_alias(state, &alias, current_time_millis())
        }
    }
}

#[cfg(feature = "app_api")]
fn call_contract_view_value(
    state: Arc<CoreState>,
    authority: &iroha_data_model::account::AccountId,
    contract_address: iroha_data_model::smart_contract::ContractAddress,
    _contract_alias: Option<iroha_data_model::smart_contract::ContractAlias>,
    entrypoint: &str,
    payload: Option<Value>,
    gas_limit: u64,
) -> Result<Value> {
    let response = evaluate_contract_view_request(
        state,
        ContractViewDto {
            authority: authority.clone(),
            contract_address: Some(contract_address),
            contract_alias: None,
            entrypoint: entrypoint.to_owned(),
            payload: payload.map(IrohaJson::new),
            gas_limit,
        },
    )?;
    let result = match response {
        Ok(ok) => ok.result,
        Err(err) => {
            return Err(conversion_error(format!(
                "contract view `{entrypoint}` failed: {}",
                err.error
            )));
        }
    };
    iroha_json_to_value(&result)
}

#[cfg(feature = "app_api")]
fn load_swap_fill_rollup(
    state: Arc<CoreState>,
    params: &ContractRollupSwapsFillsParams,
) -> Result<SwapFillRollup> {
    let telemetry = MaybeTelemetry::disabled();
    let (authority_id, authority) = parse_account_literal_with_state(
        state.as_ref(),
        &params.authority,
        &telemetry,
        ENDPOINT_CONTRACTS_ROLLUPS_SWAPS_FILLS,
    )
    .map_err(|err| {
        conversion_error(format!(
            "invalid authority `{}`: {}",
            params.authority,
            err.reason()
        ))
    })?;
    let prepared = resolve_rollup_contract_target(
        state.as_ref(),
        params.contract_address.as_deref(),
        params.contract_alias.as_deref(),
        "dlmm_router::dlmm.universal",
    )?;
    let contract_address = prepared.contract_address.clone();
    let contract_alias = prepared.contract_alias.clone();
    let gas_limit = DEFAULT_CONTRACT_ARGUMENT_GAS_LIMIT;
    let assets_value = call_contract_view_value(
        Arc::clone(&state),
        &authority_id,
        contract_address.clone(),
        contract_alias.clone(),
        "router_assets",
        None,
        gas_limit,
    )?;
    let (base_asset_id, quote_asset_id) = parse_router_assets_from_value(&assets_value)?;
    let history_head_value = call_contract_view_value(
        Arc::clone(&state),
        &authority_id,
        contract_address.clone(),
        contract_alias.clone(),
        "swap_history_head",
        None,
        gas_limit,
    )?;
    let history_head = parse_contract_view_int(&history_head_value)
        .and_then(|raw| u64::try_from(raw).ok())
        .ok_or_else(|| {
            conversion_error("swap_history_head returned an unexpected value".to_owned())
        })?;

    let scan_limit = params
        .scan_limit
        .unwrap_or(DEFAULT_TRADER_SWAP_SCAN_LIMIT)
        .clamp(1, MAX_TRADER_SWAP_SCAN_LIMIT) as usize;
    let mut records = Vec::new();
    let mut scanned = 0usize;
    let mut cursor = history_head;
    while cursor > 0 && scanned < scan_limit {
        let record_value = call_contract_view_value(
            Arc::clone(&state),
            &authority_id,
            contract_address.clone(),
            contract_alias.clone(),
            "mirror_swap_history",
            Some(crate::json_object(vec![crate::json_entry(
                "record_id",
                cursor,
            )])),
            gas_limit,
        )?;
        scanned = scanned.saturating_add(1);
        let record = parse_swap_history_record(cursor, &record_value)?;
        if record.trader == authority {
            records.push(record);
        }
        cursor = cursor.saturating_sub(1);
    }

    let index = contract_event_index_snapshot(state.as_ref());
    let mut swap_events: Vec<ContractEventProjection> = index
        .items
        .iter()
        .rev()
        .filter(|projection| {
            projection.result_ok
                && projection.authority.as_deref() == Some(authority.as_str())
                && projection.contract_address == contract_address.to_string()
                && projection.module == "swaps"
                && matches!(
                    projection.event_kind.as_str(),
                    "swap_executed" | "route_swap"
                )
        })
        .cloned()
        .collect();

    let mut stitched = Vec::with_capacity(records.len());
    for mut record in records {
        let matched_index = swap_events.iter().position(|projection| {
            let Some(Value::Object(object)) = projection.payload.as_ref() else {
                return false;
            };
            object_lookup_i64(&object, &["amount_in", "amount"]) == Some(record.amount_in)
                && object_lookup_i64(&object, &["min_out"]) == Some(record.min_out)
                && object_lookup_i64(&object, &["input_is_base"]) == Some(record.input_is_base)
        });
        let matched = matched_index.map(|index| swap_events.remove(index));
        if let Some(event) =
            matched.or_else(|| (!swap_events.is_empty()).then(|| swap_events.remove(0)))
        {
            record.timestamp_ms = event.timestamp_ms;
            record.execution_hash = Some(event.tx_hash_hex);
        }
        stitched.push(record);
    }

    Ok(SwapFillRollup {
        authority,
        contract_address: contract_address.to_string(),
        contract_alias: contract_alias.map(|value| value.to_string()),
        base_asset_id,
        quote_asset_id,
        history_head,
        scanned,
        total: stitched.len(),
        items: stitched,
    })
}

#[cfg(feature = "app_api")]
fn swap_fill_rollup_to_json_value(
    rollup: &SwapFillRollup,
    limit: Option<u64>,
    offset: u64,
) -> Value {
    let offset = usize::try_from(offset).unwrap_or(usize::MAX);
    let limit = limit
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(rollup.items.len());
    let items = rollup
        .items
        .iter()
        .skip(offset)
        .take(limit)
        .map(|item| {
            let mut object = Map::new();
            object.insert("recordId".into(), Value::from(item.record_id));
            object.insert("trader".into(), Value::from(item.trader.clone()));
            object.insert("inputIsBase".into(), Value::from(item.input_is_base));
            object.insert("amountIn".into(), Value::from(item.amount_in));
            object.insert("amountOut".into(), Value::from(item.amount_out));
            object.insert("minOut".into(), Value::from(item.min_out));
            object.insert("side".into(), Value::from(item.side.clone()));
            object.insert("price".into(), Value::from(item.price));
            object.insert(
                "protectionRatio".into(),
                item.protection_ratio.map_or(Value::Null, Value::from),
            );
            object.insert(
                "timestampMs".into(),
                item.timestamp_ms.map_or(Value::Null, Value::from),
            );
            object.insert(
                "executionHash".into(),
                item.execution_hash
                    .as_ref()
                    .map_or(Value::Null, |value| Value::from(value.clone())),
            );
            Value::Object(object)
        })
        .collect::<Vec<_>>();
    let mut top = Map::new();
    top.insert("ok".into(), Value::Bool(true));
    top.insert("authority".into(), Value::from(rollup.authority.clone()));
    top.insert(
        "contract_address".into(),
        Value::from(rollup.contract_address.clone()),
    );
    if let Some(alias) = rollup.contract_alias.as_ref() {
        top.insert("contract_alias".into(), Value::from(alias.clone()));
    }
    top.insert(
        "base_asset_id".into(),
        Value::from(rollup.base_asset_id.clone()),
    );
    top.insert(
        "quote_asset_id".into(),
        Value::from(rollup.quote_asset_id.clone()),
    );
    top.insert("history_head".into(), Value::from(rollup.history_head));
    top.insert("scanned".into(), Value::from(rollup.scanned as u64));
    top.insert("total".into(), Value::from(rollup.total as u64));
    top.insert("items".into(), Value::Array(items));
    Value::Object(top)
}

#[cfg(feature = "app_api")]
fn compute_swap_analytics(items: &[SwapFillRollupItem]) -> SwapAnalytics {
    let mut quote_inventory = 0.0_f64;
    let mut cost_basis_base = 0.0_f64;
    let mut realized_pnl_base = 0.0_f64;
    let mut total_base_spent = 0.0_f64;
    let mut total_base_realized = 0.0_f64;
    let mut total_quote_bought = 0.0_f64;
    let mut total_quote_sold = 0.0_f64;
    let mut win_count = 0.0_f64;
    let mut sell_count = 0.0_f64;
    let mut cushion_ratio_sum = 0.0_f64;
    let mut cushion_count = 0.0_f64;

    for fill in items.iter().rev() {
        if fill.side == "buy" {
            total_base_spent += fill.amount_in as f64;
            total_quote_bought += fill.amount_out as f64;
            quote_inventory += fill.amount_out as f64;
            cost_basis_base += fill.amount_in as f64;
        } else {
            total_base_realized += fill.amount_out as f64;
            total_quote_sold += fill.amount_in as f64;
            sell_count += 1.0;

            let inventory_before = quote_inventory;
            let basis_before = cost_basis_base;
            let sold_quote = (fill.amount_in as f64).min(inventory_before);
            let cost_portion = if inventory_before > 0.0 {
                (basis_before * sold_quote) / inventory_before
            } else {
                0.0
            };
            let trade_realized = fill.amount_out as f64 - cost_portion;
            realized_pnl_base += trade_realized;
            if trade_realized > 0.0 {
                win_count += 1.0;
            }
            quote_inventory = (inventory_before - fill.amount_in as f64).max(0.0);
            cost_basis_base = (basis_before - cost_portion).max(0.0);
        }
        if let Some(ratio) = fill.protection_ratio {
            cushion_ratio_sum += ratio;
            cushion_count += 1.0;
        }
    }

    let avg_entry = (total_quote_bought > 0.0).then_some(total_base_spent / total_quote_bought);
    let avg_exit = (total_quote_sold > 0.0).then_some(total_base_realized / total_quote_sold);
    let last_price = items.first().map(|item| item.price);
    let unrealized_pnl_base = last_price.map(|price| (quote_inventory * price) - cost_basis_base);
    let total_pnl_base = unrealized_pnl_base.map(|value| realized_pnl_base + value);

    SwapAnalytics {
        avg_entry,
        avg_exit,
        open_quote_amount: quote_inventory,
        realized_pnl_base,
        unrealized_pnl_base,
        total_pnl_base,
        total_base_spent,
        total_base_realized,
        last_price,
        win_rate: (sell_count > 0.0).then_some(win_count / sell_count),
        avg_cushion_ratio: (cushion_count > 0.0).then_some(cushion_ratio_sum / cushion_count),
    }
}

#[cfg(feature = "app_api")]
fn swap_analytics_to_json_value(analytics: &SwapAnalytics) -> Value {
    let mut object = Map::new();
    object.insert(
        "avgEntry".into(),
        analytics.avg_entry.map_or(Value::Null, Value::from),
    );
    object.insert(
        "avgExit".into(),
        analytics.avg_exit.map_or(Value::Null, Value::from),
    );
    object.insert(
        "openQuoteAmount".into(),
        Value::from(analytics.open_quote_amount),
    );
    object.insert(
        "realizedPnlBase".into(),
        Value::from(analytics.realized_pnl_base),
    );
    object.insert(
        "unrealizedPnlBase".into(),
        analytics
            .unrealized_pnl_base
            .map_or(Value::Null, Value::from),
    );
    object.insert(
        "totalPnlBase".into(),
        analytics.total_pnl_base.map_or(Value::Null, Value::from),
    );
    object.insert(
        "totalBaseSpent".into(),
        Value::from(analytics.total_base_spent),
    );
    object.insert(
        "totalBaseRealized".into(),
        Value::from(analytics.total_base_realized),
    );
    object.insert(
        "lastPrice".into(),
        analytics.last_price.map_or(Value::Null, Value::from),
    );
    object.insert(
        "winRate".into(),
        analytics.win_rate.map_or(Value::Null, Value::from),
    );
    object.insert(
        "avgCushionRatio".into(),
        analytics.avg_cushion_ratio.map_or(Value::Null, Value::from),
    );
    Value::Object(object)
}

#[cfg(feature = "app_api")]
fn event_payload_object(projection: &ContractEventProjection) -> Option<Map> {
    projection.payload.as_ref().and_then(|value| match value {
        Value::Object(object) => Some(object.clone()),
        _ => None,
    })
}

#[cfg(feature = "app_api")]
fn trader_activity_item_from_projection(
    projection: &ContractEventProjection,
) -> TraderActivityItem {
    let payload = event_payload_object(projection).unwrap_or_default();
    let mut action = humanize_identifier(&projection.event_kind);
    let mut exposure = "-".to_owned();
    let mut context = trader_module_label(&projection.module).to_owned();
    match projection.event_kind.as_str() {
        "swap_executed" | "route_swap" => {
            let input_is_base = object_lookup_i64(&payload, &["input_is_base"]).unwrap_or(1);
            let amount_in = object_lookup_i64(&payload, &["amount_in", "amount"]).unwrap_or(0);
            let amount_out = object_lookup_i64(&payload, &["amount_out"]).unwrap_or(0);
            let min_out = object_lookup_i64(&payload, &["min_out"]).unwrap_or(0);
            action = if input_is_base == 1 {
                "Bought quote".to_owned()
            } else {
                "Sold quote".to_owned()
            };
            exposure = format!(
                "{} -> {}",
                compact_number(amount_in as f64, 0),
                compact_number(amount_out as f64, 0)
            );
            context = format!("Min out {}", compact_number(min_out as f64, 0));
        }
        "n3x_minted" => {
            action = "Minted n3x".to_owned();
            let amount = object_lookup_i64(&payload, &["amount"]).unwrap_or(0);
            exposure = format!("{} basket in", compact_number(amount as f64, 0));
            let usdt = object_lookup_i64(&payload, &["usdt_in"]).unwrap_or(0);
            let usdc = object_lookup_i64(&payload, &["usdc_in"]).unwrap_or(0);
            let kusd = object_lookup_i64(&payload, &["kusd_in"]).unwrap_or(0);
            context = format!(
                "{} USDT / {} USDC / {} KUSD",
                compact_number(usdt as f64, 0),
                compact_number(usdc as f64, 0),
                compact_number(kusd as f64, 0)
            );
        }
        "n3x_redeemed" => {
            action = "Redeemed n3x".to_owned();
            let amount = object_lookup_i64(&payload, &["amount", "n3x_amount"]).unwrap_or(0);
            exposure = format!("{} N3X", compact_number(amount as f64, 0));
            context = "Basket redeem".to_owned();
        }
        "perps_position_opened"
        | "perps_position_modified"
        | "perps_margin_added"
        | "perps_margin_removed"
        | "perps_position_closed"
        | "perps_funding_synced"
        | "perps_liquidation_pass" => {
            let position_id = object_lookup_i64(&payload, &["position_id"]);
            let market_id = object_lookup_i64(&payload, &["market_id"]);
            let size = object_lookup_i64(&payload, &["size", "size_delta", "notional"]);
            let margin = object_lookup_i64(&payload, &["margin", "margin_delta", "amount"]);
            exposure = [
                size.map(|value| format!("{} size", compact_number(value as f64, 0))),
                margin.map(|value| format!("{} margin", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = "Perp action".to_owned();
            }
            context = [
                market_id.map(|value| format!("Market {value}")),
                position_id.map(|value| format!("Position #{value}")),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if context.is_empty() {
                context = "Perps Engine".to_owned();
            }
        }
        "farm_staked" | "farm_unstaked" | "farm_rewards_claimed" => {
            let position = object_lookup_string(&payload, &["position"]);
            let amount = object_lookup_i64(&payload, &["amount"]);
            exposure = amount
                .map(|value| compact_number(value as f64, 0))
                .unwrap_or_else(|| "Farm action".to_owned());
            context = position
                .map(|value| format!("Position {value}"))
                .unwrap_or_else(|| "Farm position".to_owned());
        }
        "launchpad_contributed"
        | "launchpad_claimed"
        | "launchpad_refunded"
        | "launchpad_activation_finalized" => {
            let sale = object_lookup_string(&payload, &["sale"]);
            let allocation = object_lookup_string(&payload, &["allocation"]);
            let amount = object_lookup_i64(&payload, &["amount", "payment_amount"]);
            exposure = amount
                .map(|value| compact_number(value as f64, 0))
                .unwrap_or_else(|| "Launchpad action".to_owned());
            context = [sale, allocation]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" · ");
            if context.is_empty() {
                context = "Launchpad".to_owned();
            }
        }
        "options_series_created"
        | "options_position_bought"
        | "options_shout_recorded"
        | "options_position_exercised"
        | "options_series_settled" => {
            let series_id = object_lookup_i64(&payload, &["series_id"]);
            let position_id = object_lookup_i64(&payload, &["position_id"]);
            let notional = object_lookup_i64(&payload, &["notional"]);
            let premium = object_lookup_i64(&payload, &["premium_paid"]);
            exposure = [
                notional.map(|value| format!("{} notional", compact_number(value as f64, 0))),
                premium.map(|value| format!("{} premium", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = "Option action".to_owned();
            }
            context = [
                series_id.map(|value| format!("Series #{value}")),
                position_id.map(|value| format!("Position #{value}")),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if context.is_empty() {
                context = "Options".to_owned();
            }
        }
        "cover_policy_opened"
        | "cover_observation_recorded"
        | "cover_claim_routed"
        | "cover_policy_expired" => {
            let policy_id = object_lookup_i64(&payload, &["policy_id"]);
            let notional = object_lookup_i64(&payload, &["notional", "covered_notional"]);
            let payout = object_lookup_i64(&payload, &["payout_amount"]);
            exposure = [
                notional.map(|value| format!("{} covered", compact_number(value as f64, 0))),
                payout.map(|value| format!("{} payout", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = "Policy action".to_owned();
            }
            context = policy_id
                .map(|value| format!("Policy #{value}"))
                .unwrap_or_else(|| "Cover".to_owned());
        }
        event
            if projection.module == "intents"
                && matches!(
                    event,
                    "intent_opened" | "intent_cancelled" | "intent_filled"
                ) =>
        {
            let intent_id = object_lookup_string(&payload, &["intent_id"]);
            let amount_in = object_lookup_i64(&payload, &["amount_in"]);
            let min_out = object_lookup_i64(&payload, &["min_out"]);
            let amount_out = object_lookup_i64(&payload, &["amount_out"]);
            exposure = [
                amount_in.map(|value| format!("{} in", compact_number(value as f64, 0))),
                amount_out.map(|value| format!("{} out", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = min_out
                    .map(|value| format!("{} min out", compact_number(value as f64, 0)))
                    .unwrap_or_else(|| "Intent action".to_owned());
            }
            context = intent_id
                .map(|value| format!("Intent {value}"))
                .unwrap_or_else(|| "Intents".to_owned());
        }
        event
            if projection.module == "vaults"
                && matches!(
                    event,
                    "vault_registered"
                        | "vault_deposited"
                        | "vault_redeem_requested"
                        | "vault_redeem_claimed"
                ) =>
        {
            let vault_id = object_lookup_string(&payload, &["vault_id"]);
            let position_id = object_lookup_string(&payload, &["position_id"]);
            let amount = object_lookup_i64(&payload, &["amount", "shares"]);
            exposure = amount
                .map(|value| compact_number(value as f64, 0))
                .unwrap_or_else(|| "Vault action".to_owned());
            context = [vault_id, position_id]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" · ");
            if context.is_empty() {
                context = "Vaults".to_owned();
            }
        }
        event
            if projection.module == "operators"
                && matches!(
                    event,
                    "operator_registered"
                        | "operator_bonded"
                        | "operator_heartbeat"
                        | "operator_fees_claimed"
                ) =>
        {
            let service = object_lookup_string(&payload, &["service"]);
            let amount = object_lookup_i64(&payload, &["amount", "min_bond", "fees_accrued"]);
            let health = object_lookup_i64(&payload, &["health_bps"]);
            exposure = [
                amount.map(|value| compact_number(value as f64, 0)),
                health.map(|value| format!("{} bps health", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = "Operator action".to_owned();
            }
            context = service
                .map(|value| format!("Service {value}"))
                .unwrap_or_else(|| "Operators".to_owned());
        }
        event
            if projection.module == "margin"
                && matches!(
                    event,
                    "margin_market_registered"
                        | "margin_collateral_deposited"
                        | "margin_collateral_withdrawn"
                        | "margin_exposure_locked"
                        | "margin_account_liquidated"
                ) =>
        {
            let market_id = object_lookup_string(&payload, &["market_id"]);
            let account_key = object_lookup_string(&payload, &["account_key"]);
            let amount = object_lookup_i64(&payload, &["amount", "exposure_delta"]);
            exposure = amount
                .map(|value| compact_number(value as f64, 0))
                .unwrap_or_else(|| "Margin action".to_owned());
            context = [market_id, account_key]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" · ");
            if context.is_empty() {
                context = "Portfolio Margin".to_owned();
            }
        }
        event
            if projection.module == "rwa"
                && matches!(
                    event,
                    "rwa_lot_issued"
                        | "rwa_share_asset_bound"
                        | "rwa_nav_reported"
                        | "rwa_redemption_requested"
                        | "rwa_redemption_settled"
                ) =>
        {
            let market_id = object_lookup_string(&payload, &["market_id"]);
            let redemption_id = object_lookup_string(&payload, &["redemption_id"]);
            let shares = object_lookup_i64(&payload, &["shares", "total_shares"]);
            let nav = object_lookup_i64(&payload, &["nav_per_share", "initial_nav_per_share"]);
            exposure = [
                shares.map(|value| format!("{} shares", compact_number(value as f64, 0))),
                nav.map(|value| format!("{} NAV", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = "RWA action".to_owned();
            }
            context = [market_id, redemption_id]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" · ");
            if context.is_empty() {
                context = "RWA Markets".to_owned();
            }
        }
        event
            if projection.module == "dlmmHooks"
                && matches!(
                    event,
                    "dlmm_hook_configured"
                        | "dlmm_hook_limit_order_placed"
                        | "dlmm_hook_twamm_scheduled"
                        | "dlmm_hook_execution_recorded"
                ) =>
        {
            let hook_id = object_lookup_string(&payload, &["hook_id"]);
            let order_id = object_lookup_string(&payload, &["order_id"]);
            let amount_in = object_lookup_i64(&payload, &["amount_in"]);
            let min_out = object_lookup_i64(&payload, &["min_out", "amount_out"]);
            exposure = [
                amount_in.map(|value| format!("{} in", compact_number(value as f64, 0))),
                min_out.map(|value| format!("{} out", compact_number(value as f64, 0))),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
            if exposure.is_empty() {
                exposure = "Hook action".to_owned();
            }
            context = [hook_id, order_id]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" · ");
            if context.is_empty() {
                context = "DLMM Hooks".to_owned();
            }
        }
        _ => {
            if !payload.is_empty() {
                let summary = payload
                    .iter()
                    .filter_map(|(key, value)| match value {
                        Value::String(text) if !text.is_empty() => Some(format!("{key}={text}")),
                        Value::Number(number) => Some(match number {
                            norito::json::native::Number::I64(value) => {
                                format!("{key}={value}")
                            }
                            norito::json::native::Number::U64(value) => {
                                format!("{key}={value}")
                            }
                            norito::json::native::Number::F64(value) => {
                                format!("{key}={value}")
                            }
                        }),
                        _ => None,
                    })
                    .take(3)
                    .collect::<Vec<_>>()
                    .join(" · ");
                if !summary.is_empty() {
                    exposure = summary;
                }
            }
        }
    }
    TraderActivityItem {
        module_key: projection.module.clone(),
        module_label: trader_module_label(&projection.module).to_owned(),
        timestamp_ms: projection.timestamp_ms,
        action,
        exposure,
        context,
        execution_hash: projection.tx_hash_hex.clone(),
    }
}

#[cfg(feature = "app_api")]
fn collect_trader_activity_page(
    index: &ContractEventIndex,
    params: &ContractEventGetParams,
    pagination: EffectivePagination,
) -> (Vec<ContractEventProjection>, usize) {
    let offset_usize = usize::try_from(pagination.offset).unwrap_or(usize::MAX);
    let limit_usize = pagination
        .limit
        .and_then(|value| usize::try_from(value).ok())
        .filter(|value| *value > 0);
    let mut matched = 0usize;
    let mut items = Vec::new();

    let mut visit = |projection: &ContractEventProjection| {
        if !trader_module_is_supported(&projection.module)
            || !contract_event_matches(projection, params)
        {
            return;
        }
        matched = matched.saturating_add(1);
        if matched > offset_usize && limit_usize.map(|limit| items.len() < limit).unwrap_or(true) {
            items.push(projection.clone());
        }
    };

    match contract_event_candidate_positions(index, params) {
        ContractEventCandidatePositions::All => {
            for projection in index.items.iter().rev() {
                visit(projection);
            }
        }
        ContractEventCandidatePositions::Indexed(positions) => {
            for position in positions.iter().rev() {
                if let Some(projection) = index.items.get(*position) {
                    visit(projection);
                }
            }
        }
        ContractEventCandidatePositions::Empty => {}
    }
    (items, matched)
}

#[cfg(feature = "app_api")]
fn trader_activity_items_to_json(items: &[TraderActivityItem]) -> Vec<Value> {
    items
        .iter()
        .map(|item| {
            let mut object = Map::new();
            object.insert("moduleKey".into(), Value::from(item.module_key.clone()));
            object.insert("moduleLabel".into(), Value::from(item.module_label.clone()));
            object.insert(
                "timestampMs".into(),
                item.timestamp_ms.map_or(Value::Null, Value::from),
            );
            object.insert("action".into(), Value::from(item.action.clone()));
            object.insert("exposure".into(), Value::from(item.exposure.clone()));
            object.insert("context".into(), Value::from(item.context.clone()));
            object.insert(
                "executionHash".into(),
                Value::from(item.execution_hash.clone()),
            );
            Value::Object(object)
        })
        .collect()
}

#[cfg(feature = "app_api")]
fn module_card_json(
    key: &str,
    contract_address: Option<String>,
    status_tone: &str,
    status_label: &str,
    hero: String,
    blurb: String,
    radar_value: String,
    metrics: [(&str, String); 3],
) -> Value {
    let mut object = Map::new();
    object.insert("key".into(), Value::from(key.to_owned()));
    object.insert(
        "label".into(),
        Value::from(trader_module_label(key).to_owned()),
    );
    object.insert(
        "contractKey".into(),
        Value::from(trader_module_contract_key(key).to_owned()),
    );
    object.insert(
        "contractAddress".into(),
        contract_address.map_or(Value::Null, Value::from),
    );
    object.insert("statusTone".into(), Value::from(status_tone.to_owned()));
    object.insert("statusLabel".into(), Value::from(status_label.to_owned()));
    object.insert("hero".into(), Value::from(hero));
    object.insert("blurb".into(), Value::from(blurb));
    object.insert("radarValue".into(), Value::from(radar_value));
    object.insert(
        "metrics".into(),
        Value::Array(
            metrics
                .into_iter()
                .map(|(label, value)| {
                    crate::json_object(vec![
                        crate::json_entry("label", label),
                        crate::json_entry("value", value),
                    ])
                })
                .collect(),
        ),
    );
    Value::Object(object)
}

#[cfg(feature = "app_api")]
fn resolve_trader_module_contract_address(state: &CoreState, module: &str) -> Option<String> {
    trader_module_alias_candidates(module)
        .iter()
        .find_map(|alias_literal| {
            let alias =
                iroha_data_model::smart_contract::ContractAlias::from_str(alias_literal).ok()?;
            prepare_contract_call_by_alias(state, &alias, current_time_millis())
                .ok()
                .map(|prepared| prepared.contract_address.to_string())
        })
}

#[cfg(feature = "app_api")]
fn build_trader_account_modules_json(
    state: &CoreState,
    fills: &SwapFillRollup,
    analytics: &SwapAnalytics,
    activities: &[TraderActivityItem],
) -> Vec<Value> {
    let base_symbol = asset_ticker(&fills.base_asset_id);
    let quote_symbol = asset_ticker(&fills.quote_asset_id);
    TRADER_MODULE_ORDER
        .iter()
        .map(|module| {
            let contract_address = resolve_trader_module_contract_address(state, module);
            let latest = activities.iter().find(|item| item.module_key == *module);
            if *module == "swaps" {
                return module_card_json(
                    "swaps",
                    contract_address,
                    if fills.items.is_empty() { "watch" } else { "live" },
                    if fills.items.is_empty() {
                        "Awaiting flow"
                    } else {
                        "Trading"
                    },
                    analytics
                        .total_pnl_base
                        .map(|value| format_signed_asset_amount(value, &base_symbol))
                        .unwrap_or_else(|| "No personal PnL yet".to_owned()),
                    if fills.items.is_empty() {
                        "The router is deployed, but this wallet has no successful fills in the visible journal window yet."
                            .to_owned()
                    } else {
                        format!(
                            "Avg entry {} {} · Open {} {} · {} executed fills",
                            analytics
                                .avg_entry
                                .map(|value| compact_number(value, 4))
                                .unwrap_or_else(|| "-".to_owned()),
                            base_symbol,
                            compact_number(analytics.open_quote_amount, 4),
                            quote_symbol,
                            fills.items.len()
                        )
                    },
                    if fills.items.is_empty() {
                        "No fills".to_owned()
                    } else {
                        format!("{} fills", fills.items.len())
                    },
                    [
                        (
                            "Avg Entry",
                            analytics
                                .avg_entry
                                .map(|value| format!("{} {}", compact_number(value, 4), base_symbol))
                                .unwrap_or_else(|| "-".to_owned()),
                        ),
                        (
                            "Realized",
                            format_signed_asset_amount(analytics.realized_pnl_base, &base_symbol),
                        ),
                        (
                            "Open Quote",
                            format!("{} {}", compact_number(analytics.open_quote_amount, 4), quote_symbol),
                        ),
                    ],
                );
            }

            match (contract_address, latest) {
                (None, _) => module_card_json(
                    module,
                    None,
                    "missing",
                    "Not deployed",
                    "Not available here".to_owned(),
                    format!(
                        "{} is not deployed in this environment yet.",
                        trader_module_contract_key(module)
                    ),
                    "Missing".to_owned(),
                    [
                        ("Contract", "Unavailable".to_owned()),
                        ("Last Action", "-".to_owned()),
                        ("Last Seen", "-".to_owned()),
                    ],
                ),
                (Some(contract_address), None) => module_card_json(
                    module,
                    Some(contract_address),
                    "watch",
                    "Watching",
                    "No recent wallet activity".to_owned(),
                    "This product is deployed, but no recent canonical trader events were found for the selected authority."
                        .to_owned(),
                    "Watching".to_owned(),
                    [
                        ("Contract", trader_module_contract_key(module).to_owned()),
                        ("Last Action", "None yet".to_owned()),
                        ("Last Seen", "-".to_owned()),
                    ],
                ),
                (Some(contract_address), Some(latest)) => module_card_json(
                    module,
                    Some(contract_address),
                    "live",
                    "Live",
                    latest.exposure.clone(),
                    format!("{} · {}", latest.action, latest.context),
                    latest.action.clone(),
                    [
                        ("Latest", latest.action.clone()),
                        ("Context", latest.context.clone()),
                        ("Last Seen", format_timestamp_label(latest.timestamp_ms)),
                    ],
                ),
            }
        })
        .collect()
}

#[cfg(feature = "app_api")]
pub async fn handle_v1_contracts_rollups_swaps_fills_get(
    state: Arc<CoreState>,
    crate::NoritoQuery(params): crate::NoritoQuery<ContractRollupSwapsFillsParams>,
    _telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    let rollup = load_swap_fill_rollup(state, &params)?;
    let body = norito::json::to_json_pretty(&swap_fill_rollup_to_json_value(
        &rollup,
        params.limit,
        params.offset,
    ))
    .unwrap_or_else(|_| "{}".into());
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

#[cfg(feature = "app_api")]
pub async fn handle_v1_contracts_rollups_swaps_candles_get(
    state: Arc<CoreState>,
    crate::NoritoQuery(params): crate::NoritoQuery<ContractRollupSwapsCandlesParams>,
    _telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    let fills = load_swap_fill_rollup(
        state,
        &ContractRollupSwapsFillsParams {
            limit: None,
            offset: 0,
            authority: params.authority.clone(),
            contract_address: params.contract_address.clone(),
            contract_alias: params.contract_alias.clone(),
            scan_limit: params.scan_limit,
            count_mode: None,
        },
    )?;
    let bucket_ms = params
        .bucket_ms
        .unwrap_or(DEFAULT_TRADER_CANDLE_BUCKET_MS)
        .max(60_000);
    let mut buckets: BTreeMap<u64, Map> = BTreeMap::new();
    for fill in fills
        .items
        .iter()
        .filter(|item| item.timestamp_ms.is_some())
    {
        let timestamp_ms = fill.timestamp_ms.unwrap_or_default();
        let bucket_start_ms = timestamp_ms - (timestamp_ms % bucket_ms);
        let entry = buckets.entry(bucket_start_ms).or_insert_with(|| {
            let mut object = Map::new();
            object.insert("bucketStartMs".into(), Value::from(bucket_start_ms));
            object.insert("open".into(), Value::from(fill.price));
            object.insert("high".into(), Value::from(fill.price));
            object.insert("low".into(), Value::from(fill.price));
            object.insert("close".into(), Value::from(fill.price));
            object.insert("buyCount".into(), Value::from(0_u64));
            object.insert("sellCount".into(), Value::from(0_u64));
            object.insert("baseVolume".into(), Value::from(0_f64));
            object.insert("quoteVolume".into(), Value::from(0_f64));
            object
        });
        let high = entry
            .get("high")
            .and_then(Value::as_f64)
            .unwrap_or(fill.price);
        let low = entry
            .get("low")
            .and_then(Value::as_f64)
            .unwrap_or(fill.price);
        entry.insert("high".into(), Value::from(high.max(fill.price)));
        entry.insert("low".into(), Value::from(low.min(fill.price)));
        entry.insert("close".into(), Value::from(fill.price));
        let buy_count = entry.get("buyCount").and_then(Value::as_u64).unwrap_or(0);
        let sell_count = entry.get("sellCount").and_then(Value::as_u64).unwrap_or(0);
        if fill.side == "buy" {
            entry.insert("buyCount".into(), Value::from(buy_count + 1));
        } else {
            entry.insert("sellCount".into(), Value::from(sell_count + 1));
        }
        let base_volume = entry
            .get("baseVolume")
            .and_then(Value::as_f64)
            .unwrap_or(0.0);
        let quote_volume = entry
            .get("quoteVolume")
            .and_then(Value::as_f64)
            .unwrap_or(0.0);
        let fill_base = if fill.side == "buy" {
            fill.amount_in as f64
        } else {
            fill.amount_out as f64
        };
        let fill_quote = if fill.side == "buy" {
            fill.amount_out as f64
        } else {
            fill.amount_in as f64
        };
        entry.insert("baseVolume".into(), Value::from(base_volume + fill_base));
        entry.insert("quoteVolume".into(), Value::from(quote_volume + fill_quote));
    }
    let offset = usize::try_from(params.offset).unwrap_or(usize::MAX);
    let limit = params
        .limit
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(usize::MAX);
    let items = buckets
        .into_iter()
        .rev()
        .skip(offset)
        .take(limit)
        .map(|(_, value)| Value::Object(value))
        .collect::<Vec<_>>();
    let mut top = Map::new();
    top.insert("ok".into(), Value::Bool(true));
    top.insert("authority".into(), Value::from(fills.authority));
    top.insert("bucketMs".into(), Value::from(bucket_ms));
    top.insert("items".into(), Value::Array(items));
    let body = norito::json::to_json_pretty(&Value::Object(top)).unwrap_or_else(|_| "{}".into());
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

