// ---------------------- Accounts listing ----------------------

#[cfg(feature = "app_api")]
#[derive(Clone)]
struct AccountListItem {
    canonical_id: String,
    display_id: String,
    primary_alias: PrimaryAliasProjection,
}

#[cfg(feature = "app_api")]
#[derive(Clone)]
enum AccountSortField {
    Id,
    Metadata(Option<iroha_data_model::prelude::Name>),
    Unsupported,
}

#[cfg(feature = "app_api")]
#[derive(Clone)]
struct AccountSortSelector {
    ascending: bool,
    field: AccountSortField,
}

#[cfg(feature = "app_api")]
fn metadata_json_to_string(j: &iroha_primitives::json::Json) -> String {
    j.get().clone()
}

#[cfg(feature = "app_api")]
fn compile_account_sort_spec(spec: &[crate::filter::SortKey]) -> Vec<AccountSortSelector> {
    let mut selectors = Vec::new();
    for sk in spec {
        let ascending = matches!(sk.order, crate::filter::Order::Asc);
        let field = if sk.key.0.as_str() == "id" {
            AccountSortField::Id
        } else if let Some(rest) = sk.key.0.strip_prefix("metadata.") {
            AccountSortField::Metadata(rest.parse().ok())
        } else {
            AccountSortField::Unsupported
        };
        selectors.push(AccountSortSelector { ascending, field });
    }
    if selectors.is_empty() {
        selectors.push(AccountSortSelector {
            ascending: true,
            field: AccountSortField::Id,
        });
    }
    selectors
}

#[cfg(feature = "app_api")]
fn account_sort_key(
    account: &iroha_data_model::account::Account,
    selectors: &[AccountSortSelector],
) -> MultiSortKey {
    let mut components = Vec::with_capacity(selectors.len());
    for selector in selectors {
        let value: SortKeyValue = match selector.field {
            AccountSortField::Id => account.id().to_string().into(),
            AccountSortField::Metadata(Some(ref name)) => account
                .metadata()
                .get(name)
                .map(metadata_json_to_string)
                .unwrap_or_default()
                .into(),
            AccountSortField::Metadata(None) | AccountSortField::Unsupported => {
                String::new().into()
            }
        };
        if selector.ascending {
            components.push(SortKeyComponent::asc(value));
        } else {
            components.push(SortKeyComponent::desc(value));
        }
    }
    MultiSortKey::new(components)
}

#[cfg(feature = "app_api")]
fn account_filter_object(expr: &FilterExpr, acc: &iroha_data_model::account::Account) -> bool {
    use FilterExpr as F;
    match expr {
        F::And(list) => list.iter().all(|e| account_filter_object(e, acc)),
        F::Or(list) => list.iter().any(|e| account_filter_object(e, acc)),
        F::Not(inner) => !account_filter_object(inner, acc),
        F::Eq(f, v) => {
            if f.0 == "id" {
                v.as_str().is_some_and(|s| s == acc.id().to_string())
            } else if let Some(k) = f.0.strip_prefix("metadata.") {
                if let Ok(name) = k.parse::<iroha_data_model::prelude::Name>() {
                    acc.metadata().get(&name).is_some_and(|j| {
                        j.try_into_any_norito::<norito::json::Value>().ok().as_ref() == Some(v)
                    })
                } else {
                    false
                }
            } else {
                false
            }
        }
        F::Ne(f, v) => {
            if f.0 == "id" {
                v.as_str()
                    .map(|s| s != acc.id().to_string())
                    .unwrap_or(true)
            } else if let Some(k) = f.0.strip_prefix("metadata.") {
                if let Ok(name) = k.parse::<iroha_data_model::prelude::Name>() {
                    match acc.metadata().get(&name) {
                        Some(j) => j
                            .try_into_any_norito::<norito::json::Value>()
                            .ok()
                            .map(|nv| nv != *v)
                            .unwrap_or(true),
                        None => true,
                    }
                } else {
                    true
                }
            } else {
                false
            }
        }
        F::Lt(f, v) | F::Lte(f, v) | F::Gt(f, v) | F::Gte(f, v) => {
            if let Some(k) = f.0.strip_prefix("metadata.") {
                if let (Some(vn), Ok(name)) =
                    (v.as_u64(), k.parse::<iroha_data_model::prelude::Name>())
                {
                    if let Some(j) = acc.metadata().get(&name) {
                        if let Ok(nv) = j.try_into_any_norito::<norito::json::Value>() {
                            if let Some(mn) = nv.as_u64() {
                                return match expr {
                                    F::Lt(_, _) => mn < vn,
                                    F::Lte(_, _) => mn <= vn,
                                    F::Gt(_, _) => mn > vn,
                                    F::Gte(_, _) => mn >= vn,
                                    _ => false,
                                };
                            }
                        }
                    }
                }
            }
            false
        }
        F::In(f, list) => {
            if f.0 == "id" {
                let id = acc.id().to_string();
                list.iter().filter_map(|v| v.as_str()).any(|s| s == id)
            } else if let Some(k) = f.0.strip_prefix("metadata.") {
                if let Ok(name) = k.parse::<iroha_data_model::prelude::Name>() {
                    if let Some(j) = acc.metadata().get(&name) {
                        if let Ok(nv) = j.try_into_any_norito::<norito::json::Value>() {
                            return list.iter().any(|v| v == &nv);
                        }
                    }
                }
                false
            } else {
                false
            }
        }
        F::Nin(f, list) => {
            if f.0 == "id" {
                let id = acc.id().to_string();
                list.iter().filter_map(|v| v.as_str()).all(|s| s != id)
            } else if let Some(k) = f.0.strip_prefix("metadata.") {
                if let Ok(name) = k.parse::<iroha_data_model::prelude::Name>() {
                    if let Some(j) = acc.metadata().get(&name) {
                        if let Ok(nv) = j.try_into_any_norito::<norito::json::Value>() {
                            return list.iter().all(|v| v != &nv);
                        }
                    } else {
                        return true;
                    }
                }
                true
            } else {
                false
            }
        }
        F::Exists(f) => {
            if f.0 == "id" {
                true
            } else if let Some(k) = f.0.strip_prefix("metadata.") {
                if let Ok(name) = k.parse::<iroha_data_model::prelude::Name>() {
                    acc.metadata().get(&name).is_some()
                } else {
                    false
                }
            } else {
                false
            }
        }
        F::IsNull(f) => {
            if let Some(k) = f.0.strip_prefix("metadata.") {
                if let Ok(name) = k.parse::<iroha_data_model::prelude::Name>() {
                    acc.metadata().get(&name).is_some_and(|j| {
                        j.try_into_any_norito::<norito::json::Value>()
                            .ok()
                            .is_some_and(|v| v.is_null())
                    })
                } else {
                    false
                }
            } else {
                false
            }
        }
    }
}

#[cfg(feature = "app_api")]
fn account_filter_projection(expr: &FilterExpr, proj: &AccountListItem) -> bool {
    use FilterExpr as F;

    let field_str = |field: &str| -> Option<&str> {
        match field {
            "id" => Some(proj.canonical_id.as_str()),
            "primary_alias" => proj.primary_alias.literal.as_deref(),
            "primary_alias_name" => proj.primary_alias.name.as_deref(),
            "primary_alias_dataspace" => proj.primary_alias.dataspace.as_deref(),
            "primary_alias_domain" => proj.primary_alias.domain.as_deref(),
            _ => None,
        }
    };

    match expr {
        F::And(list) => list.iter().all(|e| account_filter_projection(e, proj)),
        F::Or(list) => list.iter().any(|e| account_filter_projection(e, proj)),
        F::Not(inner) => !account_filter_projection(inner, proj),
        F::Eq(f, v) => match f.0.as_str() {
            "has_primary_alias" => v
                .as_bool()
                .is_some_and(|flag| flag == proj.primary_alias.has_primary_alias),
            field => v
                .as_str()
                .zip(field_str(field))
                .is_some_and(|(expected, actual)| expected == actual),
        },
        F::Ne(f, v) => match f.0.as_str() {
            "has_primary_alias" => v
                .as_bool()
                .is_some_and(|flag| flag != proj.primary_alias.has_primary_alias),
            field => v
                .as_str()
                .map(|expected| field_str(field) != Some(expected))
                .unwrap_or(false),
        },
        F::In(f, list) => match f.0.as_str() {
            "has_primary_alias" => list
                .iter()
                .filter_map(norito::json::Value::as_bool)
                .any(|flag| flag == proj.primary_alias.has_primary_alias),
            field => field_str(field).is_some_and(|actual| {
                list.iter()
                    .filter_map(norito::json::Value::as_str)
                    .any(|expected| expected == actual)
            }),
        },
        F::Nin(f, list) => match f.0.as_str() {
            "has_primary_alias" => list
                .iter()
                .filter_map(norito::json::Value::as_bool)
                .all(|flag| flag != proj.primary_alias.has_primary_alias),
            field => field_str(field).is_none_or(|actual| {
                list.iter()
                    .filter_map(norito::json::Value::as_str)
                    .all(|expected| expected != actual)
            }),
        },
        F::Exists(f) => matches!(
            f.0.as_str(),
            "id" | "primary_alias"
                | "primary_alias_name"
                | "primary_alias_dataspace"
                | "primary_alias_domain"
                | "has_primary_alias"
        ),
        F::IsNull(f) => {
            matches!(
                f.0.as_str(),
                "primary_alias"
                    | "primary_alias_name"
                    | "primary_alias_dataspace"
                    | "primary_alias_domain"
            ) && field_str(f.0.as_str()).is_none()
        }
        F::Lt(_, _) | F::Lte(_, _) | F::Gt(_, _) | F::Gte(_, _) => false,
    }
}

#[cfg(feature = "app_api")]
fn account_from_world_entry(
    entry: iroha_data_model::account::AccountEntry<'_>,
) -> iroha_data_model::account::Account {
    account_from_key_value(entry.id(), entry.value())
}

#[cfg(feature = "app_api")]
fn account_from_key_value(
    id: &AccountId,
    value: &iroha_data_model::account::AccountValue,
) -> iroha_data_model::account::Account {
    let details = value.clone().into_inner();
    iroha_data_model::account::Account {
        id: id.clone(),
        metadata: details.metadata,
        label: None,
        uaid: details.uaid,
        opaque_ids: details.opaque_ids,
    }
}

#[cfg(feature = "app_api")]
fn account_read_response_from_world_entry(
    entry: iroha_data_model::account::AccountEntry<'_>,
) -> iroha_torii_shared::AccountReadResponse {
    let details = entry.value().clone().into_inner();
    iroha_torii_shared::AccountReadResponse {
        account_id: entry.id().clone(),
        label: None,
        uaid: details.uaid,
        opaque_ids: details.opaque_ids,
    }
}

#[cfg(feature = "app_api")]
pub(crate) fn collect_subject_accounts(
    world: &impl WorldReadOnly,
) -> Vec<iroha_data_model::account::Account> {
    collect_subject_accounts_from_iter(world.accounts_iter().map(account_from_world_entry))
}

#[cfg(feature = "app_api")]
fn collect_subject_accounts_from_iter(
    accounts: impl IntoIterator<Item = iroha_data_model::account::Account>,
) -> Vec<iroha_data_model::account::Account> {
    use std::collections::{BTreeMap, btree_map::Entry};

    let mut by_subject = BTreeMap::new();
    for account in accounts {
        let subject = account.id().subject_id();
        match by_subject.entry(subject) {
            Entry::Vacant(slot) => {
                slot.insert(account);
            }
            Entry::Occupied(_) => {}
        }
    }

    by_subject.into_values().collect()
}

#[cfg(feature = "app_api")]
fn account_filter_candidate_ids(
    expr: Option<&crate::filter::FilterExpr>,
) -> Option<BTreeSet<AccountId>> {
    use crate::filter::FilterExpr as F;

    match expr? {
        F::And(list) => {
            let mut selected = None;
            for nested in list {
                if let Some(candidates) = account_filter_candidate_ids(Some(nested)) {
                    intersect_account_candidates(&mut selected, candidates);
                }
            }
            selected
        }
        F::Or(list) => {
            let mut union = BTreeSet::new();
            for nested in list {
                let candidates = account_filter_candidate_ids(Some(nested))?;
                union.extend(candidates);
            }
            Some(union)
        }
        F::Eq(field, value) if field.0 == "id" => {
            Some(account_id_from_filter_value(value).into_iter().collect())
        }
        F::In(field, values) if field.0 == "id" => Some(
            values
                .iter()
                .filter_map(account_id_from_filter_value)
                .collect(),
        ),
        _ => None,
    }
}

#[cfg(feature = "app_api")]
fn collect_subject_accounts_for_filter(
    world: &impl WorldReadOnly,
    filter: Option<&crate::filter::FilterExpr>,
) -> Vec<iroha_data_model::account::Account> {
    if let Some(candidate_ids) = account_filter_candidate_ids(filter) {
        return collect_subject_accounts_from_iter(candidate_ids.into_iter().filter_map(
            |account_id| {
                world
                    .accounts()
                    .get_key_value(&account_id)
                    .map(|(id, value)| account_from_key_value(id, value))
            },
        ));
    }

    collect_subject_accounts(world)
}

#[cfg(all(test, feature = "app_api"))]
mod account_permissions_json_tests {
    use std::sync::Arc;

    use http_body_util::BodyExt as _;
    use iroha_core::{
        kura::Kura,
        query::store::LiveQueryStore,
        state::{State, World},
    };
    use iroha_data_model::{
        account::Account, nexus::DataSpaceId, permission::Permissions, prelude::AccountId,
    };
    use iroha_executor_data_model::permission::{
        account::CanModifyAccountMetadata, nexus::CanPublishSpaceDirectoryManifest,
        parameter::CanSetParameters,
    };

    use super::*;

    fn test_state_with_permissions(account_id: &AccountId) -> Arc<CoreState> {
        let account = Account::new(account_id.clone()).build(account_id);
        let role_id: RoleId = "effective-permission-test".parse().expect("role id");
        let role = Role::new(role_id.clone(), account_id.clone())
            .add_permission(CanSetParameters)
            .build(account_id);
        let mut world = World::with_assets_and_roles([], [account], [], [], [], [role]);
        world.grant_role_for_tests(account_id.clone(), role_id);
        let mut permissions = Permissions::new();
        permissions.insert(
            CanModifyAccountMetadata {
                account: account_id.clone(),
            }
            .into(),
        );
        permissions.insert(
            CanPublishSpaceDirectoryManifest {
                dataspace: DataSpaceId::new(7),
            }
            .into(),
        );
        world
            .account_permissions_mut_for_testing()
            .insert(account_id.clone(), permissions);
        Arc::new(State::new_for_testing(
            world,
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        ))
    }

    #[tokio::test]
    async fn account_permissions_handler_preserves_structured_payloads() {
        let authority = AccountId::new(
            checked_routing_fixture_keypair(
                0xA2,
                Algorithm::Ed25519,
                "derive account permissions fixture authority key",
            )
            .public_key()
            .clone(),
        );
        let state = test_state_with_permissions(&authority);
        let authority_literal = authority.to_string();

        let response = handle_v1_account_permissions_with_policy(
            state,
            axum::extract::Path(authority_literal.clone()),
            crate::NoritoQuery(PaginationParams {
                limit: Some(8),
                offset: 0,
                count_mode: None,
            }),
            MaybeTelemetry::disabled(),
        )
        .await
        .expect("permissions handler should succeed")
        .into_response();

        assert_eq!(response.status(), StatusCode::OK);
        let body = response
            .into_body()
            .collect()
            .await
            .expect("collect body")
            .to_bytes();
        let doc: norito::json::Value = norito::json::from_slice(&body).expect("valid JSON");
        let items = doc["items"].as_array().expect("items array");

        let metadata_permission = items
            .iter()
            .find(|item| item["name"].as_str() == Some("CanModifyAccountMetadata"))
            .expect("metadata permission item");
        assert_eq!(
            metadata_permission["payload"]["account"].as_str(),
            Some(authority_literal.as_str())
        );

        let manifest_permission = items
            .iter()
            .find(|item| item["name"].as_str() == Some("CanPublishSpaceDirectoryManifest"))
            .expect("manifest permission item");
        assert_eq!(
            manifest_permission["payload"]["dataspace"].as_u64(),
            Some(7)
        );

        items
            .iter()
            .find(|item| item["name"].as_str() == Some("CanSetParameters"))
            .expect("role-inherited permission item");
    }
}

#[cfg(feature = "app_api")]
fn uaid_parse_error(reason: &'static str) -> Error {
    iroha_logger::warn!(
        target: "torii.uaid.parse",
        reason,
        "invalid UAID literal rejected"
    );
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::InvalidSingularParameters,
    ))
}

#[cfg(feature = "app_api")]
fn canonicalize_uaid_literal(raw: &str) -> Result<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(uaid_parse_error("empty_literal"));
    }
    let hex_portion = match trimmed.get(..5) {
        Some(prefix) if prefix.eq_ignore_ascii_case("uaid:") => trimmed[5..].trim(),
        _ => trimmed,
    };
    if hex_portion.len() != 64 {
        return Err(uaid_parse_error("invalid_length"));
    }
    if !hex_portion.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err(uaid_parse_error("non_hex_character"));
    }
    Ok(hex_portion.to_ascii_lowercase())
}

#[cfg(feature = "app_api")]
fn parse_uaid_literal(raw: &str) -> Result<UniversalAccountId> {
    let canonical_hex = canonicalize_uaid_literal(raw)?;
    let hash = Hash::from_str(&canonical_hex).map_err(|_| uaid_parse_error("hash_decode"))?;
    Ok(UniversalAccountId::from_hash(hash))
}

#[cfg(all(test, feature = "app_api"))]
mod uaid_parsing_tests {
    use core::str::FromStr;

    use iroha_crypto::Hash;

    use super::*;

    const SAMPLE_UAID_HEX: &str =
        "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff";

    #[test]
    fn parses_trimmed_prefixed_literal() {
        let literal = format!("  UAID:{}  ", SAMPLE_UAID_HEX.to_uppercase());
        let parsed = parse_uaid_literal(&literal).expect("parse UAID literal");
        let expected_hash = Hash::from_str(SAMPLE_UAID_HEX).expect("decode UAID hash");
        let expected = UniversalAccountId::from_hash(expected_hash);
        assert_eq!(parsed, expected);
    }

    #[test]
    fn parses_mixed_case_prefix() {
        let literal = format!("  UaId:  {}  ", SAMPLE_UAID_HEX.to_uppercase());
        let parsed = parse_uaid_literal(&literal).expect("parse UAID literal");
        let expected_hash = Hash::from_str(SAMPLE_UAID_HEX).expect("decode UAID hash");
        let expected = UniversalAccountId::from_hash(expected_hash);
        assert_eq!(parsed, expected);
    }

    #[test]
    fn parses_raw_hex_literal_without_prefix() {
        let parsed = parse_uaid_literal(SAMPLE_UAID_HEX).expect("parse UAID literal");
        let expected_hash = Hash::from_str(SAMPLE_UAID_HEX).expect("decode UAID hash");
        let expected = UniversalAccountId::from_hash(expected_hash);
        assert_eq!(parsed, expected);
    }

    #[test]
    fn rejects_invalid_inputs() {
        assert!(parse_uaid_literal("").is_err());
        assert!(parse_uaid_literal("uaid:1234").is_err());
        let invalid_hex = format!("{}g", "0".repeat(63));
        assert!(parse_uaid_literal(&invalid_hex).is_err());
        assert!(parse_uaid_literal(&"0".repeat(64)).is_err());
    }
}

#[cfg(feature = "app_api")]
const ACCOUNT_ONBOARDING_RECEIPT_HASH_DOMAIN_V1: &[u8] =
    b"iroha:account-onboarding-plan-receipt:v1\0";

/// Secret-free intent accepted by the sponsored onboarding planner.
#[cfg(feature = "app_api")]
#[derive(
    Clone,
    Debug,
    PartialEq,
    Eq,
    Encode,
    Decode,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
)]
#[norito(deny_unknown_fields)]
pub struct AccountOnboardingPlanRequestDto {
    /// Request layout version. The only accepted value is `1`.
    pub version: u8,
    /// Catalog-free textual account alias.
    pub alias: String,
    /// Canonical domainless account identifier to create or repair.
    pub account_id: String,
    /// Optional permission names selected from the configured allowlist.
    #[norito(default)]
    pub permissions: Vec<String>,
}

#[cfg(feature = "app_api")]
impl AccountOnboardingPlanRequestDto {
    /// Current request layout version.
    pub const VERSION: u8 = 1;
}

/// Canonical body committed and signed by a stateless onboarding receipt.
#[cfg(feature = "app_api")]
#[derive(
    Clone,
    Debug,
    PartialEq,
    Eq,
    Encode,
    Decode,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
)]
#[norito(deny_unknown_fields)]
pub struct AccountOnboardingPlanBodyDto {
    /// Receipt layout version. The only accepted value is `1`.
    pub version: u8,
    /// Canonical normalized request embedded for stateless revalidation.
    pub request: AccountOnboardingPlanRequestDto,
    /// Configured Torii authority and transaction payer.
    pub authority: AccountId,
    /// Chain to which the receipt is bound.
    pub chain_id: ChainId,
    /// Committed state anchor used by planning.
    pub anchor: iroha_data_model::alias_setup::AliasPlanAnchorV1,
    /// Canonical account-alias resource and its live-state disposition.
    pub resource: iroha_data_model::alias_setup::AliasPlanResourceV1,
    /// Lease terms used only if the resource remains absent at apply time.
    pub acquisition: iroha_data_model::alias_setup::AliasLeaseAcquisitionV1,
    /// Policy, asset, cap, and deadline bounds revalidated before submission.
    pub quote_guard: iroha_data_model::alias_setup::AliasQuoteGuardV1,
    /// Exact framed instructions planned for the server-signed transaction.
    pub instructions: Vec<iroha_data_model::alias_setup::AliasFramedInstructionV1>,
    /// Optional native auto-renew follow-up that the resource owner must sign.
    #[norito(default)]
    pub owner_auto_renew_instruction:
        Option<iroha_data_model::alias_setup::AliasFramedInstructionV1>,
    /// Last block timestamp at which this receipt may be applied.
    pub valid_until_ms: u64,
}

#[cfg(feature = "app_api")]
impl AccountOnboardingPlanBodyDto {
    /// Current canonical receipt body layout version.
    pub const VERSION: u8 = 1;

    /// Compute the domain-separated canonical receipt hash.
    #[must_use]
    pub fn canonical_hash(&self) -> Hash {
        let encoded = self.encode();
        Hash::new_from_chunks(&[
            ACCOUNT_ONBOARDING_RECEIPT_HASH_DOMAIN_V1,
            encoded.as_slice(),
        ])
    }
}

/// Stateless, signer-authenticated onboarding plan receipt.
#[cfg(feature = "app_api")]
#[derive(
    Clone,
    Debug,
    PartialEq,
    Eq,
    Encode,
    Decode,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
)]
#[norito(deny_unknown_fields)]
pub struct AccountOnboardingPlanReceiptDto {
    /// Canonical plan body.
    pub body: AccountOnboardingPlanBodyDto,
    /// Domain-separated hash of `body`.
    pub plan_hash: Hash,
    /// Onboarding-authority signature over `plan_hash`.
    pub signature: Signature,
}

#[cfg(feature = "app_api")]
impl AccountOnboardingPlanReceiptDto {
    /// Create and sign a receipt without retaining any server-side plan state.
    fn try_new(
        body: AccountOnboardingPlanBodyDto,
        private_key: &iroha_crypto::PrivateKey,
    ) -> Result<Self> {
        let plan_hash = body.canonical_hash();
        let signature = Signature::try_new(private_key, plan_hash.as_ref()).map_err(|error| {
            Error::SerializationFailure {
                context: "account onboarding plan receipt signature",
                source: Box::new(error),
            }
        })?;
        Ok(Self {
            body,
            plan_hash,
            signature,
        })
    }

    /// Verify the canonical body hash and onboarding-authority signature.
    #[must_use]
    pub fn verify(&self) -> bool {
        self.plan_hash == self.body.canonical_hash()
            && self
                .signature
                .verify(self.body.authority.signatory(), self.plan_hash.as_ref())
                .is_ok()
    }
}

