#[cfg(feature = "app_api")]
fn faucet_pow_recent_claims(
    app: &crate::SharedAppState,
    faucet: &iroha_config::parameters::actual::ToriiFaucet,
    anchor_height: u64,
) -> Result<u64> {
    if faucet.pow_adaptive_lookback_blocks == 0
        || faucet.pow_adaptive_claims_per_extra_bit == 0
        || faucet.pow_adaptive_max_extra_bits == 0
    {
        return Ok(0);
    }

    let source_asset_id = AssetId::new(
        resolve_faucet_asset_definition_id(app, faucet)?,
        faucet.authority.clone(),
    );
    let faucet_amount = configured_faucet_quantity(faucet)?;
    let start_height = anchor_height
        .saturating_sub(faucet.pow_adaptive_lookback_blocks.saturating_sub(1))
        .max(1);
    let mut total = 0u64;
    for height in start_height..=anchor_height {
        let Some(nonzero_height) = usize::try_from(height).ok().and_then(NonZeroUsize::new) else {
            continue;
        };
        let Some(block) = app.state.block_by_height(nonzero_height) else {
            continue;
        };
        let claims_in_block = block
            .external_transactions()
            .filter(|tx| {
                tx.authority() == &faucet.authority
                    && faucet_executable_is_claim(
                        tx.instructions(),
                        &source_asset_id,
                        &faucet_amount,
                    )
            })
            .count();
        total = total.saturating_add(u64::try_from(claims_in_block).unwrap_or(u64::MAX));
    }

    let queued_claims = {
        let state_view = app.state.view();
        app.queue
            .all_transactions(&state_view)
            .filter(|tx| {
                tx.authority() == &faucet.authority
                    && faucet_executable_is_claim(
                        tx.as_ref().instructions(),
                        &source_asset_id,
                        &faucet_amount,
                    )
            })
            .count()
    };

    Ok(total.saturating_add(u64::try_from(queued_claims).unwrap_or(u64::MAX)))
}

#[cfg(feature = "app_api")]
fn faucet_pow_scrypt_params(
    faucet: &iroha_config::parameters::actual::ToriiFaucet,
) -> Result<ScryptParams> {
    ScryptParams::new(
        faucet.pow_scrypt_log_n,
        faucet.pow_scrypt_r,
        faucet.pow_scrypt_p,
        32,
    )
    .map_err(|_| faucet_invalid_request("invalid faucet pow scrypt configuration"))
}

#[cfg(feature = "app_api")]
fn faucet_pow_effective_difficulty_bits(
    app: &crate::SharedAppState,
    faucet: &iroha_config::parameters::actual::ToriiFaucet,
    anchor_height: u64,
) -> Result<u8> {
    let recent_claims = faucet_pow_recent_claims(app, faucet, anchor_height)?;
    let adaptive_bits = adaptive_faucet_pow_extra_bits(
        recent_claims,
        faucet.pow_adaptive_claims_per_extra_bit,
        faucet.pow_adaptive_max_extra_bits,
    );
    Ok(faucet.pow_difficulty_bits.saturating_add(adaptive_bits))
}

#[cfg(feature = "app_api")]
fn faucet_pow_challenge_salt(
    app: &crate::SharedAppState,
    faucet: &iroha_config::parameters::actual::ToriiFaucet,
    anchor_height: u64,
) -> Result<Option<[u8; 32]>> {
    if !faucet.pow_vrf_seed_enabled {
        return Ok(None);
    }

    let world = app.state.world_view();
    world
        .vrf_epochs()
        .iter()
        .filter_map(|(_, record)| {
            (record.finalized && record.updated_at_height <= anchor_height).then_some(record.seed)
        })
        .last()
        .map(Some)
        .ok_or_else(|| faucet_invalid_request("faucet pow vrf seed unavailable"))
}

#[cfg(feature = "app_api")]
fn faucet_pow_challenge(
    account_id: &AccountId,
    anchor_height: u64,
    anchor_hash: &HashOf<BlockHeader>,
    challenge_salt: Option<&[u8; 32]>,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(FAUCET_POW_DOMAIN_SEPARATOR);
    hasher.update(account_id.to_string().as_bytes());
    hasher.update(anchor_height.to_be_bytes());
    hasher.update(anchor_hash.as_ref());
    if let Some(challenge_salt) = challenge_salt {
        hasher.update(challenge_salt);
    }
    hasher.finalize().into()
}

#[cfg(feature = "app_api")]
fn faucet_pow_anchor_hash(
    app: &crate::SharedAppState,
    anchor_height: u64,
) -> Result<HashOf<BlockHeader>> {
    let height = usize::try_from(anchor_height)
        .ok()
        .and_then(NonZeroUsize::new)
        .ok_or_else(|| faucet_invalid_request("invalid faucet pow anchor height"))?;
    let block = app
        .state
        .block_by_height(height)
        .ok_or_else(|| faucet_invalid_request("unknown faucet pow anchor height"))?;
    Ok(block.hash())
}

#[cfg(feature = "app_api")]
fn faucet_pow_digest(
    challenge: &[u8; 32],
    scrypt_params: &ScryptParams,
    nonce_bytes: &[u8],
) -> Result<[u8; 32]> {
    let mut output = [0u8; 32];
    derive_scrypt(nonce_bytes, challenge, scrypt_params, &mut output)
        .map_err(|_| faucet_invalid_request("failed to derive faucet pow digest"))?;
    Ok(output)
}

#[cfg(feature = "app_api")]
fn verify_faucet_pow(
    app: &crate::SharedAppState,
    faucet: &iroha_config::parameters::actual::ToriiFaucet,
    account_id: &AccountId,
    anchor_height: Option<u64>,
    nonce_hex: Option<&str>,
) -> Result<()> {
    if faucet.pow_difficulty_bits == 0 && faucet.pow_adaptive_max_extra_bits == 0 {
        return Ok(());
    }

    let anchor_height =
        anchor_height.ok_or_else(|| faucet_invalid_request("faucet pow anchor height required"))?;
    let current_height = u64::try_from(app.state.committed_height()).unwrap_or(u64::MAX);
    if anchor_height == 0 || anchor_height > current_height {
        return Err(faucet_invalid_request(
            "faucet pow anchor height out of range",
        ));
    }
    if current_height.saturating_sub(anchor_height) > faucet.pow_max_anchor_age_blocks.get() {
        return Err(faucet_invalid_request("faucet pow anchor is stale"));
    }

    let effective_difficulty_bits =
        faucet_pow_effective_difficulty_bits(app, faucet, anchor_height)?;
    if effective_difficulty_bits == 0 {
        return Ok(());
    }

    let nonce_hex = nonce_hex
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| faucet_invalid_request("faucet pow nonce required"))?;
    let nonce_bytes =
        hex::decode(nonce_hex).map_err(|_| faucet_invalid_request("invalid faucet pow nonce"))?;
    if nonce_bytes.is_empty() || nonce_bytes.len() > 32 {
        return Err(faucet_invalid_request("invalid faucet pow nonce"));
    }

    let anchor_hash = faucet_pow_anchor_hash(app, anchor_height)?;
    let challenge_salt = faucet_pow_challenge_salt(app, faucet, anchor_height)?;
    let challenge = faucet_pow_challenge(
        account_id,
        anchor_height,
        &anchor_hash,
        challenge_salt.as_ref(),
    );
    let scrypt_params = faucet_pow_scrypt_params(faucet)?;
    let digest = faucet_pow_digest(&challenge, &scrypt_params, &nonce_bytes)?;
    if leading_zero_bits(&digest) < u32::from(effective_difficulty_bits) {
        return Err(faucet_invalid_request("invalid faucet pow solution"));
    }

    Ok(())
}

#[cfg(all(feature = "app_api", test))]
mod faucet_pow_tests {
    use super::adaptive_faucet_pow_extra_bits;

    #[test]
    fn adaptive_faucet_pow_extra_bits_scales_and_caps() {
        assert_eq!(adaptive_faucet_pow_extra_bits(0, 4, 6), 0);
        assert_eq!(adaptive_faucet_pow_extra_bits(3, 4, 6), 0);
        assert_eq!(adaptive_faucet_pow_extra_bits(4, 4, 6), 1);
        assert_eq!(adaptive_faucet_pow_extra_bits(12, 4, 6), 3);
        assert_eq!(adaptive_faucet_pow_extra_bits(999, 4, 6), 6);
        assert_eq!(adaptive_faucet_pow_extra_bits(10, 0, 6), 0);
        assert_eq!(adaptive_faucet_pow_extra_bits(10, 4, 0), 0);
    }

    #[test]
    fn faucet_invalid_request_returns_specific_app_error() {
        let err = super::faucet_invalid_request("invalid account id literal");
        match err {
            crate::Error::AppQueryValidation { code, message } => {
                assert_eq!(code, "invalid_account_id");
                assert_eq!(message, "invalid account id literal");
            }
            other => panic!("unexpected error variant: {other:?}"),
        }
    }

    #[test]
    fn onboarding_error_metadata_classifies_noncanonical_account_id() {
        let (code, hint) = super::onboarding_error_metadata(
            "account_id must use the canonical domainless representation",
        );
        assert_eq!(code, "noncanonical_account_id");
        assert!(hint.is_some());
    }

    #[test]
    fn onboarding_error_metadata_classifies_disallowed_permission() {
        let (code, hint) = super::onboarding_error_metadata(
            "requested permission is not in account_onboarding.additional_permissions",
        );
        assert_eq!(code, "requested_permission_not_allowed");
        assert!(hint.is_some());
    }

    #[test]
    fn onboarding_invalid_request_preserves_structured_code() {
        let err = super::onboarding_invalid_request("invalid canonical account_id");
        match err {
            crate::Error::AccountOnboardingValidation { code, hint, .. } => {
                assert_eq!(code, "invalid_account_id");
                assert!(hint.is_some());
            }
            other => panic!("unexpected error variant: {other:?}"),
        }
    }
}

#[cfg(feature = "app_api")]
const CONFIDENTIAL_NOTES_DEFAULT_LIMIT: u64 = 200;
#[cfg(feature = "app_api")]
const CONFIDENTIAL_NOTES_MAX_LIMIT: u64 = 1_000;

#[cfg(feature = "app_api")]
fn hex32(bytes: &[u8; 32]) -> String {
    hex::encode(bytes)
}

#[cfg(feature = "app_api")]
fn string_array(values: impl IntoIterator<Item = String>) -> Value {
    Value::Array(values.into_iter().map(Value::String).collect())
}

#[cfg(feature = "app_api")]
fn zk_instruction_record(kind: &'static str, payload: Map) -> Value {
    let mut by_kind = Map::new();
    by_kind.insert(kind.to_string(), Value::Object(payload));
    let mut root = Map::new();
    root.insert("zk".to_string(), Value::Object(by_kind));
    Value::Object(root)
}

#[cfg(feature = "app_api")]
fn confidential_note_instruction_payload(
    instruction: &InstructionBox,
    asset: &AssetDefinitionId,
) -> Option<Value> {
    if let Some(shield) = instruction.as_any().downcast_ref::<dm::isi::zk::Shield>() {
        if shield.asset != *asset {
            return None;
        }
        let mut payload = Map::new();
        payload.insert("asset".into(), Value::String(shield.asset.to_string()));
        payload.insert("from".into(), Value::String(shield.from.to_string()));
        payload.insert("amount".into(), Value::String(shield.amount.to_string()));
        payload.insert(
            "note_commitment".into(),
            Value::String(hex32(&shield.note_commitment)),
        );
        return Some(zk_instruction_record("Shield", payload));
    }

    if let Some(transfer) = instruction
        .as_any()
        .downcast_ref::<dm::isi::zk::ZkTransfer>()
    {
        if transfer.asset != *asset {
            return None;
        }
        let mut payload = Map::new();
        payload.insert("asset".into(), Value::String(transfer.asset.to_string()));
        payload.insert(
            "inputs".into(),
            string_array(transfer.inputs.iter().map(hex32)),
        );
        payload.insert(
            "outputs".into(),
            string_array(transfer.outputs.iter().map(hex32)),
        );
        if let Some(root_hint) = transfer.root_hint.as_ref() {
            payload.insert("root_hint".into(), Value::String(hex32(root_hint)));
        }
        return Some(zk_instruction_record("ZkTransfer", payload));
    }

    if let Some(unshield) = instruction.as_any().downcast_ref::<dm::isi::zk::Unshield>() {
        if unshield.asset != *asset {
            return None;
        }
        let mut payload = Map::new();
        payload.insert("asset".into(), Value::String(unshield.asset.to_string()));
        payload.insert("to".into(), Value::String(unshield.to.to_string()));
        payload.insert(
            "public_amount".into(),
            Value::String(unshield.public_amount.to_string()),
        );
        payload.insert(
            "inputs".into(),
            string_array(unshield.inputs.iter().map(hex32)),
        );
        if let Some(root_hint) = unshield.root_hint.as_ref() {
            payload.insert("root_hint".into(), Value::String(hex32(root_hint)));
        }
        return Some(zk_instruction_record("Unshield", payload));
    }

    None
}

#[cfg(feature = "app_api")]
fn confidential_notes_cursor(cursor: Option<&str>) -> Result<Option<u64>> {
    let Some(raw) = cursor.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    raw.parse::<u64>()
        .map(Some)
        .map_err(|_| confidential_invalid_request("invalid confidential notes cursor"))
}

#[cfg(feature = "app_api")]
fn decode_relay_signed_transaction(raw: &str) -> Result<SignedTransaction> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(confidential_invalid_request(
            "signed_tx_hex must not be empty",
        ));
    }
    if trimmed.starts_with("0x") || trimmed.starts_with("0X") {
        return Err(confidential_invalid_request(
            "signed_tx_hex must be plain hex without 0x prefix",
        ));
    }
    let bytes =
        hex::decode(trimmed).map_err(|_| confidential_invalid_request("invalid signed_tx_hex"))?;
    <SignedTransaction as iroha_version::codec::DecodeVersioned>::decode_all_versioned(&bytes)
        .map_err(|_| confidential_invalid_request("invalid versioned signed transaction bytes"))
}

#[cfg(feature = "app_api")]
fn relayable_zk_transfer_instruction(tx: &SignedTransaction) -> Result<InstructionBox> {
    let Executable::Instructions(instructions) = tx.instructions() else {
        return Err(confidential_invalid_request(
            "confidential relay accepts exactly one ZkTransfer instruction",
        ));
    };
    if instructions.len() != 1 {
        return Err(confidential_invalid_request(
            "confidential relay accepts exactly one ZkTransfer instruction",
        ));
    }
    let instruction = instructions
        .first()
        .cloned()
        .ok_or_else(|| confidential_invalid_request("missing relay instruction"))?;
    if instruction
        .as_any()
        .downcast_ref::<dm::isi::zk::ZkTransfer>()
        .is_none()
    {
        return Err(confidential_invalid_request(
            "confidential relay only accepts ZkTransfer",
        ));
    }
    Ok(instruction)
}

#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_confidential_notes(
    state: Arc<CoreState>,
    crate::NoritoQuery(query): crate::NoritoQuery<ConfidentialNotesQuery>,
) -> Result<impl IntoResponse> {
    let asset_literal = query
        .asset_definition_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| confidential_invalid_request("asset_definition_id is required"))?;
    let asset = asset_literal
        .parse::<AssetDefinitionId>()
        .map_err(|_| confidential_invalid_request("invalid asset_definition_id"))?;
    let max_height = state.committed_height() as u64;
    let requested_start = confidential_notes_cursor(query.cursor.as_deref())?
        .or(query.from_block)
        .unwrap_or(max_height);
    let start_height = requested_start.min(max_height);
    let limit = query
        .limit
        .unwrap_or(CONFIDENTIAL_NOTES_DEFAULT_LIMIT)
        .min(CONFIDENTIAL_NOTES_MAX_LIMIT);
    let mut items = Vec::new();
    let mut scanned_to_block = start_height;
    let mut next_cursor = None;

    if start_height > 0 && limit > 0 {
        let mut height = start_height;
        loop {
            scanned_to_block = height;
            let Some(nonzero_height) = nonzero_height(height) else {
                break;
            };
            if let Some(block) = state.block_by_height(nonzero_height) {
                let block_ref = block.as_ref();
                for (entrypoint_hash, tx, result) in external_signed_transaction_results(block_ref)
                {
                    if result.as_ref().is_err() {
                        continue;
                    }
                    let confidential_instructions: Vec<Value> = tx
                        .instructions()
                        .explicit_instructions()
                        .filter_map(|instruction| {
                            confidential_note_instruction_payload(instruction, &asset)
                        })
                        .collect();
                    if confidential_instructions.is_empty() {
                        continue;
                    }
                    let tx_hash = entrypoint_hash.to_string();
                    items.push(ConfidentialNoteRecordDto {
                        entrypoint_hash: tx_hash.clone(),
                        transaction_hash: tx_hash,
                        block: height,
                        result_ok: true,
                        authority: crate::account_literal::display_literal(tx.authority()),
                        metadata: metadata_to_json(tx.metadata()),
                        instructions: confidential_instructions,
                    });
                }
            }
            if items.len() as u64 >= limit {
                next_cursor = height
                    .checked_sub(1)
                    .filter(|next| *next > 0)
                    .map(|next| next.to_string());
                break;
            }
            if height == 1 {
                break;
            }
            height -= 1;
        }
    }

    Ok(JsonBody(ConfidentialNotesPageDto {
        items,
        next_cursor,
        scanned_to_block,
    })
    .into_response())
}

#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_confidential_relay_submit(
    app: crate::SharedAppState,
    crate::NoritoJson(req): crate::NoritoJson<ConfidentialRelaySubmitRequestDto>,
    telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    let Some(signer) = app.account_faucet.as_ref() else {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted("Confidential relay disabled".into()),
        ));
    };
    let source_tx = decode_relay_signed_transaction(&req.signed_tx_hex)?;
    if source_tx.chain() != app.chain_id.as_ref() {
        return Err(confidential_invalid_request(
            "signed transaction chain does not match this Torii",
        ));
    }
    source_tx.verify_signature().map_err(|err| {
        let reason = format!("signed transaction signature verification failed: {err}");
        confidential_invalid_request(&reason)
    })?;
    let source_tx_hash_hex = hex::encode(source_tx.hash().as_ref());
    let instruction = relayable_zk_transfer_instruction(&source_tx)?;

    let attachments = source_tx.attachments().cloned();
    let mut builder = TransactionBuilder::new(
        (*app.chain_id).clone(),
        signer.authority.clone(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    )
    .with_instructions([instruction])
    .with_metadata(source_tx.metadata().clone());
    builder.set_ttl(Duration::from_secs(APP_API_TRANSACTION_TTL_SECS));
    let mut builder = quote_app_api_transaction_builder(
        builder,
        app.queue.as_ref(),
        app.state.as_ref(),
        ENDPOINT_CONFIDENTIAL_RELAY_SUBMIT,
    )?;
    if let Some(attachments) = attachments {
        builder = builder.with_attachments(attachments);
    }
    let tx = sign_app_api_transaction(
        builder,
        signer.signer.private_key(),
        ENDPOINT_CONFIDENTIAL_RELAY_SUBMIT,
    )?;
    let tx_hash_hex = hex::encode(tx.hash().as_ref());

    handle_transaction_with_metrics(
        app.chain_id.clone(),
        app.queue.clone(),
        app.state.clone(),
        tx,
        telemetry,
        ENDPOINT_CONFIDENTIAL_RELAY_SUBMIT,
    )
    .await?;

    let response = ConfidentialRelaySubmitResponseDto {
        tx_hash_hex,
        source_tx_hash_hex,
        status: "QUEUED",
        relay_authority: signer.authority.to_string(),
    };
    let mut resp = Response::new(Body::from(
        norito::json::to_json_pretty(&response).unwrap_or_else(|_| "{}".into()),
    ));
    resp.headers_mut().insert(
        header::CONTENT_TYPE,
        header::HeaderValue::from_static("application/json"),
    );
    Ok((StatusCode::ACCEPTED, resp))
}

