#[cfg(all(test, feature = "app_api"))]
mod adapter_filter_tests {
    use super::*;
    #[cfg(feature = "app_api")]
    use crate::filter::FieldPath;
    use crate::{json_array, json_object, json_value};
    #[cfg(feature = "app_api")]
    use iroha_core::{kura::Kura, query::store::LiveQueryStore, state::World};

    fn obj(pairs: Vec<(&'static str, Value)>) -> Value {
        json_object(pairs)
    }

    fn arr(values: Vec<Value>) -> Value {
        json_array(values)
    }

    fn val<T: json::JsonSerialize + ?Sized>(value: &T) -> Value {
        json_value(value)
    }

    #[test]
    fn accounts_filter_adapter_accepts_id_eq_and_rejects_lt() {
        let ok = obj(vec![
            ("op", val("eq")),
            (
                "args",
                arr(vec![
                    val("id"),
                    val("sorauﾛ1NﾗhBUd2BﾂｦﾄiﾔﾆﾂﾇKSﾃaﾘﾒﾓQﾗrﾒoﾘﾅnｳﾘbQｳQJﾆLJ5HSE"),
                ]),
            ),
        ]);
        let expr: FilterExpr = norito::json::value::from_value(ok).unwrap();
        crate::filter::validate_filter(&expr).unwrap();
        #[cfg(feature = "app_api")]
        validate_accounts_filter_adapter(&expr).unwrap();

        let bad = obj(vec![
            ("op", val("lt")),
            ("args", arr(vec![val("id"), val(&5u64)])),
        ]);
        let expr2: FilterExpr = norito::json::value::from_value(bad).unwrap();
        crate::filter::validate_filter(&expr2).unwrap();
        #[cfg(feature = "app_api")]
        assert!(validate_accounts_filter_adapter(&expr2).is_err());
    }

    #[test]
    fn defs_filter_adapter_accepts_in_and_rejects_numeric() {
        let ok = obj(vec![
            ("op", val("in")),
            (
                "args",
                arr(vec![
                    val("id"),
                    arr(vec![
                        val(&test_asset_definition_literal_from_hex(
                            "550e8400e29b41d4a7164466554400dd",
                        )),
                        val(&test_asset_definition_literal_from_hex(
                            "550e8400e29b41d4a7164466554400ee",
                        )),
                    ]),
                ]),
            ),
        ]);
        let expr: FilterExpr = norito::json::value::from_value(ok).unwrap();
        crate::filter::validate_filter(&expr).unwrap();
        #[cfg(feature = "app_api")]
        validate_defs_filter_adapter(&expr).unwrap();

        let bad = obj(vec![
            ("op", val("gte")),
            ("args", arr(vec![val("id"), val(&1u64)])),
        ]);
        let expr2: FilterExpr = norito::json::value::from_value(bad).unwrap();
        crate::filter::validate_filter(&expr2).unwrap();
        #[cfg(feature = "app_api")]
        assert!(validate_defs_filter_adapter(&expr2).is_err());
    }

    #[cfg(feature = "app_api")]
    #[test]
    fn defs_filter_adapter_accepts_name_alias_and_metadata_nullability() {
        let name_eq = FilterExpr::Eq(FieldPath("name".into()), Value::from("CBDC"));
        validate_defs_filter_adapter(&name_eq).unwrap();

        let alias_null = FilterExpr::IsNull(FieldPath("alias".into()));
        validate_defs_filter_adapter(&alias_null).unwrap();

        let alias_binding_status = FilterExpr::Eq(
            FieldPath("alias_binding.status".into()),
            Value::from("leased_grace"),
        );
        validate_defs_filter_adapter(&alias_binding_status).unwrap();

        let alias_binding_bound_at = FilterExpr::Gt(
            FieldPath("alias_binding.bound_at_ms".into()),
            Value::from(10_u64),
        );
        validate_defs_filter_adapter(&alias_binding_bound_at).unwrap();

        let metadata_lt = FilterExpr::Lt(FieldPath("metadata.rank".into()), Value::from(2_u64));
        validate_defs_filter_adapter(&metadata_lt).unwrap();

        let bad = FilterExpr::IsNull(FieldPath("name".into()));
        assert!(validate_defs_filter_adapter(&bad).is_err());

        let bad_alias_binding = FilterExpr::Eq(
            FieldPath("alias_binding.bound_at_ms".into()),
            Value::from("10"),
        );
        assert!(validate_defs_filter_adapter(&bad_alias_binding).is_err());
    }

    #[cfg(feature = "app_api")]
    #[test]
    fn defs_filter_projection_matches_name_alias_and_metadata_passthrough() {
        let authority = AccountId::new(
            checked_routing_fixture_keypair(
                0xF2,
                Algorithm::Ed25519,
                "derive asset-definition projection authority fixture key",
            )
            .public_key()
            .clone(),
        );
        let definition = AssetDefinition::numeric(AssetDefinitionId::new(
            DomainId::try_new("issuer", "universal").expect("domain"),
            "cbdc".parse().expect("name"),
        ))
        .with_name("CBDC".to_owned())
        .build(&authority);
        let item = AssetDefinitionListItem {
            definition,
            id: "66owaQmAQMuHxPzxUN3bqZ6FJfDa".to_owned(),
            name: "CBDC".to_owned(),
            alias: Some("CBDC#centralbank".to_owned()),
            alias_binding: Some(AssetAliasBindingDto {
                alias: "CBDC#centralbank".to_owned(),
                status: "leased_grace".to_owned(),
                lease_expiry_ms: Some(100),
                grace_until_ms: Some(200),
                bound_at_ms: 50,
            }),
        };

        assert!(asset_definition_filter_projection(
            &FilterExpr::Eq(FieldPath("name".into()), Value::from("CBDC")),
            &item,
        ));
        assert!(asset_definition_filter_projection(
            &FilterExpr::Eq(FieldPath("alias".into()), Value::from("CBDC#centralbank"),),
            &item,
        ));
        assert!(asset_definition_filter_projection(
            &FilterExpr::Eq(
                FieldPath("alias_binding.status".into()),
                Value::from("leased_grace"),
            ),
            &item,
        ));
        assert!(asset_definition_filter_projection(
            &FilterExpr::Gt(
                FieldPath("alias_binding.bound_at_ms".into()),
                Value::from(10_u64)
            ),
            &item,
        ));
        assert!(asset_definition_filter_projection(
            &FilterExpr::Exists(FieldPath("metadata.rank".into())),
            &item,
        ));
        assert!(asset_definition_filter_projection(
            &FilterExpr::Lt(FieldPath("metadata.rank".into()), Value::from(2_u64)),
            &item,
        ));
        assert!(!asset_definition_filter_projection(
            &FilterExpr::IsNull(FieldPath("alias".into())),
            &item,
        ));
        assert!(!asset_definition_filter_projection(
            &FilterExpr::IsNull(FieldPath("alias_binding.status".into())),
            &item,
        ));
    }

    #[test]
    fn nfts_filter_adapter_accepts_exists_and_rejects_is_null() {
        let ok = obj(vec![("op", val("exists")), ("args", val("id"))]);
        let expr: FilterExpr = norito::json::value::from_value(ok).unwrap();
        crate::filter::validate_filter(&expr).unwrap();
        #[cfg(feature = "app_api")]
        validate_nfts_filter_adapter(&expr).unwrap();

        let bad = obj(vec![("op", val("is_null")), ("args", val("id"))]);
        let expr2: FilterExpr = norito::json::value::from_value(bad).unwrap();
        crate::filter::validate_filter(&expr2).unwrap();
        #[cfg(feature = "app_api")]
        assert!(validate_nfts_filter_adapter(&expr2).is_err());
    }

    #[test]
    fn rwas_filter_adapter_accepts_exists_and_rejects_is_null() {
        let ok = obj(vec![("op", val("exists")), ("args", val("id"))]);
        let expr: FilterExpr = norito::json::value::from_value(ok).unwrap();
        crate::filter::validate_filter(&expr).unwrap();
        #[cfg(feature = "app_api")]
        validate_rwas_filter_adapter(&expr).unwrap();

        let bad = obj(vec![("op", val("is_null")), ("args", val("id"))]);
        let expr2: FilterExpr = norito::json::value::from_value(bad).unwrap();
        crate::filter::validate_filter(&expr2).unwrap();
        #[cfg(feature = "app_api")]
        assert!(validate_rwas_filter_adapter(&expr2).is_err());
    }

    #[cfg(feature = "app_api")]
    #[test]
    fn asset_holder_filter_adapter_accepts_asset_and_scope_eq() {
        use iroha_test_samples::ALICE_ID;

        let asset_def = AssetDefinitionId::new(
            DomainId::try_new("issuer", "universal").expect("domain"),
            "cbdc".parse().expect("name"),
        );
        let expr = FilterExpr::Eq(
            FieldPath("asset".into()),
            Value::from(asset_def.to_string()),
        );
        validate_holders_filter_adapter(&expr).unwrap();
        let scope_expr = FilterExpr::Eq(FieldPath("scope".into()), Value::from("global"));
        validate_holders_filter_adapter(&scope_expr).unwrap();

        let bad = FilterExpr::Eq(FieldPath("asset".into()), Value::from("not-an-asset"));
        assert!(validate_holders_filter_adapter(&bad).is_err());
    }

    #[cfg(feature = "app_api")]
    #[test]
    fn asset_holder_filter_matches_asset_and_scope() {
        use iroha_test_samples::ALICE_ID;

        let asset_def = AssetDefinitionId::new(
            DomainId::try_new("issuer", "universal").expect("domain"),
            "cbdc".parse().expect("name"),
        );
        let item = AssetHolderListItem {
            account_id: ALICE_ID.clone(),
            canonical_id: ALICE_ID.to_string(),
            asset: asset_def.to_string(),
            asset_alias: Some("cbdc#issuer.main".to_owned()),
            scope: "global".to_owned(),
            quantity: iroha_primitives::numeric::Quantity::from(10_u32),
            primary_alias: PrimaryAliasProjection::default(),
        };
        let expr = FilterExpr::Eq(
            FieldPath("asset".into()),
            Value::from(asset_def.to_string()),
        );
        assert!(filter_asset_holder_item(&expr, &item));
        let scope_expr = FilterExpr::Eq(FieldPath("scope".into()), Value::from("global"));
        assert!(filter_asset_holder_item(&scope_expr, &item));

        let other_def = AssetDefinitionId::new(
            DomainId::try_new("issuer", "universal").expect("domain"),
            "usd".parse().expect("name"),
        );
        let expr2 = FilterExpr::Eq(
            FieldPath("asset".into()),
            Value::from(other_def.to_string()),
        );
        assert!(!filter_asset_holder_item(&expr2, &item));
    }

    #[test]
    fn sort_spec_parser_parses_keys_and_orders() {
        let spec = "metadata.display_name:desc,id:asc,unknown";
        #[cfg(feature = "app_api")]
        let parsed = parse_sort_spec(spec);
        #[cfg(feature = "app_api")]
        {
            assert_eq!(parsed.len(), 3);
            assert_eq!(parsed[0].key.0, "metadata.display_name");
            assert!(matches!(parsed[0].order, crate::filter::Order::Desc));
            assert_eq!(parsed[1].key.0, "id");
            assert!(matches!(parsed[1].order, crate::filter::Order::Asc));
            assert_eq!(parsed[2].key.0, "unknown");
        }
    }
}

/// POST /v1/accounts/{account_id}/assets/query — JSON envelope with pagination/sort
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_account_assets_query(
    state: Arc<CoreState>,
    axum::extract::Path(account_id): axum::extract::Path<String>,
    NoritoJson(envelope): NoritoJson<crate::filter::QueryEnvelope>,
    telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    handle_v1_account_assets_query_with_policy(
        state,
        axum::extract::Path(account_id),
        NoritoJson(envelope),
        telemetry,
    )
    .await
}

/// POST assets query with configurable address enforcement.
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_account_assets_query_with_policy(
    state: Arc<CoreState>,
    axum::extract::Path(account_id): axum::extract::Path<String>,
    NoritoJson(envelope): NoritoJson<crate::filter::QueryEnvelope>,
    telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    let generic_mode = envelope.select.is_some() || envelope.aggregate.is_some();
    let generic_envelope = envelope.clone();
    let (acct, _) = parse_account_path_segment_with_state(
        state.as_ref(),
        &account_id,
        &telemetry,
        ENDPOINT_ACCOUNTS_ASSETS_QUERY,
    )?;
    let world = state.world_view();
    let scoped_accounts = scoped_accounts_for_subject_sorted(&world, &acct);
    let projected_assets = collect_projected_account_assets(
        state.as_ref(),
        &world,
        &acct,
        &scoped_accounts,
        None,
        None,
    );
    drop(world);
    let crate::filter::QueryEnvelope {
        filter,
        sort,
        pagination,
        fetch_size,
        count_mode,
        ..
    } = envelope;
    let cap = app_query_page_cap(&state);
    let pagination = enforce_app_pagination(
        pagination.limit,
        pagination.offset,
        cap,
        ENDPOINT_ACCOUNTS_ASSETS_QUERY,
    )?;
    let limits = app_query_limits();
    let fetch_size = limits
        .clamp_fetch_size(fetch_size)
        .map(|opt| opt.map(|val| val.min(pagination.cap)))?;
    let count_mode = app_count_mode(count_mode.as_deref(), ENDPOINT_ACCOUNTS_ASSETS_QUERY);

    if let Some(ref expr) = filter {
        // Extra guard: reject overly deep filters early with 422
        {
            fn depth(e: &crate::filter::FilterExpr) -> usize {
                use crate::filter::FilterExpr as F;
                match e {
                    F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                    F::Not(inner) => 1 + depth(inner),
                    _ => 1,
                }
            }
            if depth(expr) > 10 {
                return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
            }
        }
        // Structural validation
        crate::filter::validate_filter(expr)
            .map_err(|e| map_filter_error(e, ENDPOINT_ACCOUNTS_ASSETS_QUERY))?;
        // Adapter-level validation (supported fields & types)
        if !generic_mode {
            validate_asset_filter_adapter(expr)?;
        }
    }

    if generic_mode {
        let rows = projected_assets
            .into_iter()
            .map(|item| account_asset_item_to_query_row(&item));
        return execute_generic_resource_query(
            state.as_ref(),
            crate::generic_query::RESOURCE_ACCOUNT_ASSETS,
            generic_envelope,
            rows,
            "live",
        );
    }

    let filter_ref = filter.as_ref();
    let selectors = compile_account_asset_sort_spec(&sort);
    let mapped_iter = projected_assets.into_iter().filter_map({
        let filter_ref = filter_ref;
        let selectors = selectors;
        move |projected| {
            if let Some(expr) = filter_ref
                && !filter_account_asset_item(expr, &projected)
            {
                return None;
            }
            let key = account_asset_sort_key(&projected, &selectors);
            Some((key, projected))
        }
    });
    let page = collect_page_streaming_for_mode(
        mapped_iter,
        pagination.offset,
        pagination.limit,
        fetch_size,
        count_mode,
    );
    // Norito JSON response
    let mut arr = Vec::with_capacity(page.items.len());
    for it in &page.items {
        let mut m = norito::json::Map::new();
        m.insert("asset".into(), norito::json::Value::from(it.asset.clone()));
        m.insert(
            "account_id".into(),
            norito::json::Value::from(it.account_id.clone()),
        );
        m.insert("scope".into(), norito::json::Value::from(it.scope.clone()));
        m.insert(
            "asset_name".into(),
            norito::json::Value::from(it.asset_name.clone()),
        );
        m.insert(
            "asset_alias".into(),
            it.asset_alias
                .as_ref()
                .map_or(norito::json::Value::Null, |alias| {
                    norito::json::Value::from(alias.clone())
                }),
        );
        m.insert(
            "quantity".into(),
            norito::json::Value::from(format!("{}", it.quantity)),
        );
        insert_primary_alias_fields(&mut m, &it.primary_alias);
        arr.push(norito::json::Value::Object(m));
    }
    let mut top = norito::json::Map::new();
    top.insert("items".into(), norito::json::Value::Array(arr));
    insert_page_metadata(&mut top, &page, count_mode);
    let body = norito::json::to_json_pretty(&top).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            e.to_string(),
        ))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

#[cfg(feature = "app_api")]
fn validate_asset_filter_adapter(expr: &FilterExpr) -> Result<()> {
    use FilterExpr as F;
    match expr {
        F::And(list) | F::Or(list) => {
            for e in list {
                validate_asset_filter_adapter(e)?;
            }
            Ok(())
        }
        F::Not(inner) => validate_asset_filter_adapter(inner),
        F::Eq(f, v) | F::Ne(f, v) => match f.0.as_str() {
            "asset"
            | "scope"
            | "primary_alias"
            | "primary_alias_name"
            | "primary_alias_dataspace"
            | "primary_alias_domain" => v
                .is_string()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "has_primary_alias" => v
                .is_bool()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "quantity" => v
                .is_number()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
        F::Lt(f, v) | F::Lte(f, v) | F::Gt(f, v) | F::Gte(f, v) => match f.0.as_str() {
            "quantity" => v
                .is_number()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
        F::In(f, list) | F::Nin(f, list) => match f.0.as_str() {
            "asset"
            | "scope"
            | "primary_alias"
            | "primary_alias_name"
            | "primary_alias_dataspace"
            | "primary_alias_domain" => list
                .iter()
                .all(norito::json::Value::is_string)
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "has_primary_alias" => list
                .iter()
                .all(norito::json::Value::is_bool)
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "quantity" => list
                .iter()
                .all(norito::json::Value::is_number)
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
        F::Exists(f) | F::IsNull(f) => match f.0.as_str() {
            "asset"
            | "scope"
            | "quantity"
            | "primary_alias"
            | "primary_alias_name"
            | "primary_alias_dataspace"
            | "primary_alias_domain"
            | "has_primary_alias" => Ok(()),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
    }
}

#[cfg(feature = "app_api")]
#[derive(Clone)]
struct AssetHolderListItem {
    account_id: iroha_data_model::account::AccountId,
    canonical_id: String,
    asset: String,
    asset_alias: Option<String>,
    scope: String,
    quantity: iroha_primitives::numeric::Quantity,
    primary_alias: PrimaryAliasProjection,
}

#[cfg(feature = "app_api")]
fn accumulate_asset_holder_quantity(
    map: &mut BTreeMap<
        (AccountId, iroha_data_model::asset::AssetBalanceScope),
        iroha_primitives::numeric::Quantity,
    >,
    asset_id: &AssetId,
    quantity: &iroha_primitives::numeric::Quantity,
    scope_filter: Option<&iroha_data_model::asset::AssetBalanceScope>,
) -> Result<()> {
    if let Some(expected_scope) = scope_filter
        && asset_id.scope() != expected_scope
    {
        return Ok(());
    }
    let entry = map
        .entry((asset_id.account().clone(), asset_id.scope().clone()))
        .or_insert_with(iroha_primitives::numeric::Quantity::zero);
    *entry = entry.checked_add(quantity).map_err(|error| {
        conversion_error(format!(
            "asset holder quantity overflow for `{asset_id}`: {error}"
        ))
    })?;
    Ok(())
}

#[cfg(feature = "app_api")]
#[derive(Clone, Copy)]
enum AssetHolderSortField {
    AccountId,
    Quantity,
}

#[cfg(feature = "app_api")]
struct AssetHolderSortSelector {
    ascending: bool,
    field: AssetHolderSortField,
}

#[cfg(feature = "app_api")]
fn compile_asset_holder_sort_spec(spec: &[crate::filter::SortKey]) -> Vec<AssetHolderSortSelector> {
    let mut selectors = Vec::new();
    for sk in spec {
        let field = match sk.key.0.as_str() {
            "account_id" => AssetHolderSortField::AccountId,
            "quantity" => AssetHolderSortField::Quantity,
            _ => continue,
        };
        selectors.push(AssetHolderSortSelector {
            ascending: matches!(sk.order, crate::filter::Order::Asc),
            field,
        });
    }
    if selectors.is_empty() {
        selectors.push(AssetHolderSortSelector {
            ascending: true,
            field: AssetHolderSortField::AccountId,
        });
    }
    selectors
}

#[cfg(feature = "app_api")]
fn asset_holder_sort_key(
    item: &AssetHolderListItem,
    selectors: &[AssetHolderSortSelector],
) -> MultiSortKey {
    let mut components = Vec::with_capacity(selectors.len());
    for selector in selectors {
        match selector.field {
            AssetHolderSortField::AccountId => {
                if selector.ascending {
                    components.push(SortKeyComponent::asc(&item.canonical_id));
                } else {
                    components.push(SortKeyComponent::desc(&item.canonical_id));
                }
            }
            AssetHolderSortField::Quantity => {
                if selector.ascending {
                    components.push(SortKeyComponent::asc(item.quantity.as_numeric()));
                } else {
                    components.push(SortKeyComponent::desc(item.quantity.as_numeric()));
                }
            }
        }
    }
    MultiSortKey::new(components)
}

#[cfg(feature = "app_api")]
fn filter_asset_holder_item(expr: &crate::filter::FilterExpr, item: &AssetHolderListItem) -> bool {
    use crate::filter::FilterExpr as F;

    let field_str = |field: &str| -> Option<&str> {
        match field {
            "account_id" => Some(item.canonical_id.as_str()),
            "asset" => Some(item.asset.as_str()),
            "asset_alias" => item.asset_alias.as_deref(),
            "scope" => Some(item.scope.as_str()),
            "primary_alias" => item.primary_alias.literal.as_deref(),
            "primary_alias_name" => item.primary_alias.name.as_deref(),
            "primary_alias_dataspace" => item.primary_alias.dataspace.as_deref(),
            "primary_alias_domain" => item.primary_alias.domain.as_deref(),
            _ => None,
        }
    };

    match expr {
        F::And(list) => list.iter().all(|e| filter_asset_holder_item(e, item)),
        F::Or(list) => list.iter().any(|e| filter_asset_holder_item(e, item)),
        F::Not(inner) => !filter_asset_holder_item(inner, item),
        F::Eq(f, v) => match f.0.as_str() {
            "has_primary_alias" => v
                .as_bool()
                .is_some_and(|flag| flag == item.primary_alias.has_primary_alias),
            "quantity" => v
                .as_u64()
                .map(|n| item.quantity == n.into())
                .unwrap_or(false),
            field => v
                .as_str()
                .zip(field_str(field))
                .is_some_and(|(expected, actual)| expected == actual),
        },
        F::Ne(f, v) => match f.0.as_str() {
            "has_primary_alias" => v
                .as_bool()
                .is_some_and(|flag| flag != item.primary_alias.has_primary_alias),
            "quantity" => v
                .as_u64()
                .map(|n| item.quantity != n.into())
                .unwrap_or(false),
            field => v
                .as_str()
                .map(|expected| field_str(field) != Some(expected))
                .unwrap_or(false),
        },
        F::Lt(f, v) => match (f.0.as_str(), v.as_u64()) {
            ("quantity", Some(n)) => item.quantity < n.into(),
            _ => false,
        },
        F::Lte(f, v) => match (f.0.as_str(), v.as_u64()) {
            ("quantity", Some(n)) => item.quantity <= n.into(),
            _ => false,
        },
        F::Gt(f, v) => match (f.0.as_str(), v.as_u64()) {
            ("quantity", Some(n)) => item.quantity > n.into(),
            _ => false,
        },
        F::Gte(f, v) => match (f.0.as_str(), v.as_u64()) {
            ("quantity", Some(n)) => item.quantity >= n.into(),
            _ => false,
        },
        F::In(f, list) => match f.0.as_str() {
            "has_primary_alias" => list
                .iter()
                .filter_map(norito::json::Value::as_bool)
                .any(|flag| flag == item.primary_alias.has_primary_alias),
            "quantity" => list
                .iter()
                .filter_map(norito::json::Value::as_u64)
                .any(|n| item.quantity == n.into()),
            field => field_str(field).is_some_and(|actual| {
                list.iter()
                    .filter_map(norito::json::Value::as_str)
                    .any(|expected| expected == actual)
            }),
        },
        F::Nin(f, list) => match f.0.as_str() {
            "has_primary_alias" => list
                .iter()
                .filter_map(norito::json::Value::as_bool)
                .all(|flag| flag != item.primary_alias.has_primary_alias),
            "quantity" => list
                .iter()
                .filter_map(norito::json::Value::as_u64)
                .all(|n| item.quantity != n.into()),
            field => field_str(field).is_none_or(|actual| {
                list.iter()
                    .filter_map(norito::json::Value::as_str)
                    .all(|expected| expected != actual)
            }),
        },
        F::Exists(f) => matches!(
            f.0.as_str(),
            "account_id"
                | "asset"
                | "asset_alias"
                | "scope"
                | "quantity"
                | "primary_alias"
                | "primary_alias_name"
                | "primary_alias_dataspace"
                | "primary_alias_domain"
                | "has_primary_alias"
        ),
        F::IsNull(f) => {
            matches!(
                f.0.as_str(),
                "primary_alias"
                    | "primary_alias_name"
                    | "primary_alias_dataspace"
                    | "primary_alias_domain"
            ) && field_str(f.0.as_str()).is_none()
        }
    }
}

#[cfg(feature = "app_api")]
fn account_id_from_filter_value(value: &Value) -> Option<AccountId> {
    AccountId::parse_encoded(value.as_str()?)
        .ok()
        .map(iroha_data_model::account::ParsedAccountId::into_account_id)
}

#[cfg(feature = "app_api")]
fn intersect_account_candidates(
    selected: &mut Option<BTreeSet<AccountId>>,
    candidates: BTreeSet<AccountId>,
) {
    if let Some(selected) = selected {
        selected.retain(|account_id| candidates.contains(account_id));
    } else {
        *selected = Some(candidates);
    }
}

#[cfg(feature = "app_api")]
fn asset_holder_filter_account_candidates(
    expr: Option<&crate::filter::FilterExpr>,
) -> Option<BTreeSet<AccountId>> {
    use crate::filter::FilterExpr as F;

    match expr? {
        F::And(list) => {
            let mut selected = None;
            for nested in list {
                if let Some(candidates) = asset_holder_filter_account_candidates(Some(nested)) {
                    intersect_account_candidates(&mut selected, candidates);
                }
            }
            selected
        }
        F::Or(list) => {
            let mut union = BTreeSet::new();
            for nested in list {
                let candidates = asset_holder_filter_account_candidates(Some(nested))?;
                union.extend(candidates);
            }
            Some(union)
        }
        F::Eq(field, value) if field.0 == "account_id" => {
            Some(account_id_from_filter_value(value).into_iter().collect())
        }
        F::In(field, values) if field.0 == "account_id" => Some(
            values
                .iter()
                .filter_map(account_id_from_filter_value)
                .collect(),
        ),
        _ => None,
    }
}

#[cfg(feature = "app_api")]
pub(crate) fn asset_balance_scope_literal(
    scope: &iroha_data_model::asset::AssetBalanceScope,
) -> String {
    match scope {
        iroha_data_model::asset::AssetBalanceScope::Global => "global".to_owned(),
        iroha_data_model::asset::AssetBalanceScope::Dataspace(dataspace) => {
            format!("dataspace:{}", dataspace.as_u64())
        }
    }
}

#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_asset_holders(
    state: Arc<CoreState>,
    axum::extract::Path(definition_id): axum::extract::Path<String>,
    crate::NoritoQuery(p): crate::NoritoQuery<AssetHolderGetParams>,
    telemetry: MaybeTelemetry,
) -> Result<impl IntoResponse> {
    use std::collections::BTreeMap;

    let account_filter = canonicalize_query_account_literal(
        "account_id",
        p.account_id.as_deref(),
        Some(state.as_ref()),
        &telemetry,
        ENDPOINT_ASSET_HOLDERS,
    )?
    .map(|canonical| {
        AccountId::parse_encoded(&canonical)
            .map(iroha_data_model::account::ParsedAccountId::into_account_id)
            .map_err(|err| conversion_error(format!("invalid account_id `{canonical}`: {err}")))
    })
    .transpose()?;
    let scope_filter = p
        .scope
        .as_deref()
        .map(str::trim)
        .filter(|raw| !raw.is_empty())
        .map(parse_asset_balance_scope_literal)
        .transpose()?;

    let now_ms = asset_alias_observation_time_ms(&state);
    let world = state.world_view();
    let def_id = resolve_asset_definition_selector(&world, &definition_id, now_ms)?;
    let asset_alias = world
        .asset_definition(&def_id)
        .ok()
        .and_then(|definition| definition.alias().as_ref().map(ToString::to_string));
    // Aggregate balances per account and scope.
    let mut map: BTreeMap<
        (AccountId, iroha_data_model::asset::AssetBalanceScope),
        iroha_primitives::numeric::Quantity,
    > = BTreeMap::new();
    if let Some(account_id) = account_filter.as_ref() {
        for asset in world.assets_in_account_by_definition_iter(account_id, &def_id) {
            accumulate_asset_holder_quantity(
                &mut map,
                asset.id(),
                asset.value().as_ref(),
                scope_filter.as_ref(),
            )?;
        }
    } else {
        for asset in world.asset_entries_by_definition_iter(&def_id) {
            accumulate_asset_holder_quantity(
                &mut map,
                asset.id(),
                asset.value().as_ref(),
                scope_filter.as_ref(),
            )?;
        }
    }
    let catalog = state.nexus_snapshot().dataspace_catalog;
    let alias_cache = primary_alias_projection_batch_for_account_ids(
        &world,
        &catalog,
        asset_alias_observation_time_ms(&state),
        map.keys().map(|(account_id, _)| account_id.clone()),
    );
    drop(world);
    record_account_literal_selection(&telemetry, ENDPOINT_ASSET_HOLDERS);
    let cap = app_query_page_cap(&state);
    let pagination = enforce_app_pagination(p.limit, p.offset, cap, ENDPOINT_ASSET_HOLDERS)?;
    let count_mode = app_count_mode(p.count_mode.as_deref(), ENDPOINT_ASSET_HOLDERS);
    let limits = app_query_limits();
    let fetch_cap = limits
        .clamp_fetch_size(None)?
        .map(|cap| cap.min(pagination.cap));

    let page = collect_page_streaming_for_mode(
        map.into_iter().map(|((account_id, scope), quantity)| {
            let canonical_id = account_id.to_string();
            let asset = def_id.to_string();
            let scope = asset_balance_scope_literal(&scope);
            let primary_alias = alias_cache.get(&account_id).cloned().unwrap_or_default();
            (
                format!("{canonical_id}:{scope}"),
                AssetHolderListItem {
                    account_id,
                    canonical_id,
                    asset,
                    asset_alias: asset_alias.clone(),
                    scope,
                    quantity,
                    primary_alias,
                },
            )
        }),
        pagination.offset,
        pagination.limit,
        fetch_cap,
        count_mode,
    );
    // Norito JSON response
    let mut arr = Vec::with_capacity(page.items.len());
    for it in &page.items {
        let mut m = norito::json::Map::new();
        let display = crate::account_literal::display_literal(&it.account_id);
        m.insert("asset".into(), norito::json::Value::from(it.asset.clone()));
        m.insert(
            "asset_alias".into(),
            it.asset_alias
                .as_ref()
                .map_or(norito::json::Value::Null, |alias| {
                    norito::json::Value::from(alias.clone())
                }),
        );
        m.insert("account_id".into(), norito::json::Value::from(display));
        m.insert("scope".into(), norito::json::Value::from(it.scope.clone()));
        m.insert(
            "quantity".into(),
            norito::json::Value::from(format!("{}", it.quantity)),
        );
        insert_primary_alias_fields(&mut m, &it.primary_alias);
        arr.push(norito::json::Value::Object(m));
    }
    let mut top = norito::json::Map::new();
    top.insert("items".into(), norito::json::Value::Array(arr));
    insert_page_metadata(&mut top, &page, count_mode);
    let body = norito::json::to_json_pretty(&top).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            e.to_string(),
        ))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

/// POST /v1/assets/{definition_id}/holders/query — JSON envelope with pagination/sort.
/// Supports filter fields: `account_id`, `asset`, `asset_alias`, `scope`, and `quantity`.
#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub async fn handle_v1_asset_holders_query(
    state: Arc<CoreState>,
    axum::extract::Path(definition_id): axum::extract::Path<String>,
    NoritoJson(envelope): NoritoJson<crate::filter::QueryEnvelope>,
    telemetry: MaybeTelemetry,
) -> Result<Response> {
    handle_v1_asset_holders_query_with_app(
        None,
        state,
        axum::extract::Path(definition_id),
        NoritoJson(envelope),
        telemetry,
    )
    .await
}

#[iroha_futures::telemetry_future]
#[cfg(feature = "app_api")]
pub(crate) async fn handle_v1_asset_holders_query_with_app(
    app: Option<crate::SharedAppState>,
    state: Arc<CoreState>,
    axum::extract::Path(definition_id): axum::extract::Path<String>,
    NoritoJson(envelope): NoritoJson<crate::filter::QueryEnvelope>,
    telemetry: MaybeTelemetry,
) -> Result<Response> {
    use std::collections::BTreeMap;

    let generic_mode = envelope.select.is_some() || envelope.aggregate.is_some();
    let mut generic_envelope = envelope.clone();
    let now_ms = asset_alias_observation_time_ms(&state);
    let (def_id, asset_alias) = {
        let world = state.world_view();
        let def_id = resolve_asset_definition_selector(&world, &definition_id, now_ms)?;
        let asset_alias = world
            .asset_definition(&def_id)
            .ok()
            .and_then(|definition| definition.alias().as_ref().map(ToString::to_string));
        (def_id, asset_alias)
    };
    record_account_literal_selection(&telemetry, ENDPOINT_ASSET_HOLDERS_QUERY);
    let crate::filter::QueryEnvelope {
        filter,
        sort,
        pagination,
        fetch_size,
        count_mode,
        ..
    } = envelope;
    let cap = app_query_page_cap(&state);
    let pagination = enforce_app_pagination(
        pagination.limit,
        pagination.offset,
        cap,
        ENDPOINT_ASSET_HOLDERS_QUERY,
    )?;
    let limits = app_query_limits();
    let fetch_size = limits
        .clamp_fetch_size(fetch_size)
        .map(|opt| opt.map(|val| val.min(pagination.cap)))?;
    let count_mode = app_count_mode(count_mode.as_deref(), ENDPOINT_ASSET_HOLDERS_QUERY);
    normalize_app_generic_count_mode(&mut generic_envelope, ENDPOINT_ASSET_HOLDERS_QUERY);
    let mut filter = filter;
    // Optional filtering via JSON DSL over projected fields
    if let Some(ref mut expr) = filter {
        // Extra guard: reject overly deep filters early with 422
        {
            fn depth(e: &crate::filter::FilterExpr) -> usize {
                use crate::filter::FilterExpr as F;
                match e {
                    F::And(list) | F::Or(list) => 1 + list.iter().map(depth).max().unwrap_or(0),
                    F::Not(inner) => 1 + depth(inner),
                    _ => 1,
                }
            }
            if depth(expr) > 10 {
                return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
            }
        }
        crate::filter::validate_filter(expr)
            .map_err(|e| map_filter_error(e, ENDPOINT_ASSET_HOLDERS_QUERY))?;
        validate_holders_filter_adapter(expr)?;
        canonicalize_filter_account_literals(
            expr,
            "account_id",
            Some(state.as_ref()),
            &telemetry,
            ENDPOINT_ASSET_HOLDERS_QUERY,
        )?;
    }
    generic_envelope.filter = filter.clone();
    let account_candidates = asset_holder_filter_account_candidates(filter.as_ref());
    if generic_mode {
        if let Some((rows, indexed_snapshot, query_source)) = asset_holder_projection_query_rows(
            app.as_ref(),
            state.as_ref(),
            &def_id,
            asset_alias.as_ref(),
            None,
        )
        .await?
        {
            let resource = crate::generic_query::registered_resource(
                crate::generic_query::RESOURCE_ASSET_HOLDERS,
            )
            .ok_or_else(|| Error::AppQueryValidation {
                code: "unsupported_query_resource",
                message: "resource `asset_holders` is not registered".to_owned(),
            })?;
            return crate::generic_query::execute_query_envelope(
                resource,
                generic_envelope,
                rows,
                app_query_page_cap(state.as_ref()),
                crate::generic_query::QuerySnapshot::new(
                    indexed_snapshot.0,
                    indexed_snapshot.1,
                    query_source,
                ),
            );
        }

        if !asset_holder_live_aggregate_enabled() {
            return Err(projection_archive_unavailable_error(
                "asset holder generic queries require a complete published query projection archive; live holder scans are disabled",
            ));
        }
        iroha_logger::warn!(
            asset_definition_id = %def_id,
            "serving asset holder generic query from live state because projection archive cache is incomplete"
        );
    }
    let world = state.world_view();
    let mut map: BTreeMap<
        (AccountId, iroha_data_model::asset::AssetBalanceScope),
        iroha_primitives::numeric::Quantity,
    > = BTreeMap::new();
    if let Some(account_candidates) = account_candidates.as_ref() {
        for account_id in account_candidates {
            for asset in world.assets_in_account_by_definition_iter(account_id, &def_id) {
                accumulate_asset_holder_quantity(
                    &mut map,
                    asset.id(),
                    asset.value().as_ref(),
                    None,
                )?;
            }
        }
    } else {
        for asset in world.asset_entries_by_definition_iter(&def_id) {
            accumulate_asset_holder_quantity(&mut map, asset.id(), asset.value().as_ref(), None)?;
        }
    }
    let catalog = state.nexus_snapshot().dataspace_catalog;
    let alias_cache = primary_alias_projection_batch_for_account_ids(
        &world,
        &catalog,
        asset_alias_observation_time_ms(&state),
        map.keys().map(|(account_id, _)| account_id.clone()),
    );
    drop(world);

    if generic_mode {
        let rows = map.into_iter().map(|((account_id, scope), quantity)| {
            let canonical_id = account_id.to_string();
            let primary_alias = alias_cache.get(&account_id).cloned().unwrap_or_default();
            let projected = AssetHolderListItem {
                account_id,
                canonical_id,
                asset: def_id.to_string(),
                asset_alias: asset_alias.clone(),
                scope: asset_balance_scope_literal(&scope),
                quantity,
                primary_alias,
            };
            asset_holder_item_to_query_row(&projected)
        });
        return execute_generic_resource_query(
            state.as_ref(),
            crate::generic_query::RESOURCE_ASSET_HOLDERS,
            generic_envelope,
            rows,
            "live_debug",
        );
    }

    let filter_ref = filter.as_ref();
    let selectors = compile_asset_holder_sort_spec(&sort);
    let mapped_iter = map.into_iter().filter_map({
        let filter_ref = filter_ref;
        let selectors = selectors;
        let asset = def_id.to_string();
        let asset_alias = asset_alias.clone();
        move |((account_id, scope), quantity)| {
            let canonical_id = account_id.to_string();
            let scope = asset_balance_scope_literal(&scope);
            let primary_alias = alias_cache.get(&account_id).cloned().unwrap_or_default();
            let projected = AssetHolderListItem {
                account_id,
                canonical_id,
                asset: asset.clone(),
                asset_alias: asset_alias.clone(),
                scope,
                quantity,
                primary_alias,
            };
            if let Some(expr) = filter_ref {
                if !filter_asset_holder_item(expr, &projected) {
                    return None;
                }
            }
            let key = asset_holder_sort_key(&projected, &selectors);
            Some((key, projected))
        }
    });
    let page = collect_page_streaming_for_mode(
        mapped_iter,
        pagination.offset,
        pagination.limit,
        fetch_size,
        count_mode,
    );
    // Norito JSON response
    let mut arr = Vec::with_capacity(page.items.len());
    for it in &page.items {
        let display = crate::account_literal::display_literal(&it.account_id);
        let mut m = norito::json::Map::new();
        m.insert("asset".into(), norito::json::Value::from(it.asset.clone()));
        m.insert(
            "asset_alias".into(),
            it.asset_alias
                .as_ref()
                .map_or(norito::json::Value::Null, |alias| {
                    norito::json::Value::from(alias.clone())
                }),
        );
        m.insert("account_id".into(), norito::json::Value::from(display));
        m.insert("scope".into(), norito::json::Value::from(it.scope.clone()));
        m.insert(
            "quantity".into(),
            norito::json::Value::from(format!("{}", it.quantity)),
        );
        insert_primary_alias_fields(&mut m, &it.primary_alias);
        arr.push(norito::json::Value::Object(m));
    }
    let mut top = norito::json::Map::new();
    top.insert("items".into(), norito::json::Value::Array(arr));
    insert_page_metadata(&mut top, &page, count_mode);
    let body = norito::json::to_json_pretty(&top).map_err(|e| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            e.to_string(),
        ))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

#[cfg(feature = "app_api")]
fn validate_holders_filter_adapter(expr: &FilterExpr) -> Result<()> {
    use FilterExpr as F;
    let validate_asset = |value: &norito::json::Value| -> Result<()> {
        let Some(raw) = value.as_str() else {
            return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
        };
        raw.parse::<iroha_data_model::asset::AssetDefinitionId>()
            .map(|_| ())
            .map_err(|_| Error::Query(iroha_data_model::ValidationFail::TooComplex))
    };
    let validate_scope = |value: &norito::json::Value| -> Result<()> {
        let Some(raw) = value.as_str() else {
            return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
        };
        parse_asset_balance_scope_literal(raw).map(|_| ())
    };

    match expr {
        F::And(list) | F::Or(list) => {
            for e in list {
                validate_holders_filter_adapter(e)?;
            }
            Ok(())
        }
        F::Not(inner) => validate_holders_filter_adapter(inner),
        F::Eq(f, v) | F::Ne(f, v) => match f.0.as_str() {
            "account_id"
            | "asset_alias"
            | "primary_alias"
            | "primary_alias_name"
            | "primary_alias_dataspace"
            | "primary_alias_domain" => v
                .is_string()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "has_primary_alias" => v
                .is_bool()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "asset" => validate_asset(v),
            "scope" => validate_scope(v),
            "quantity" => v
                .is_number()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
        F::Lt(f, v) | F::Lte(f, v) | F::Gt(f, v) | F::Gte(f, v) => match f.0.as_str() {
            "quantity" => v
                .is_number()
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
        F::In(f, list) | F::Nin(f, list) => match f.0.as_str() {
            "account_id"
            | "asset_alias"
            | "primary_alias"
            | "primary_alias_name"
            | "primary_alias_dataspace"
            | "primary_alias_domain" => list
                .iter()
                .all(norito::json::Value::is_string)
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "has_primary_alias" => list
                .iter()
                .all(norito::json::Value::is_bool)
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            "asset" => list.iter().try_for_each(validate_asset),
            "scope" => list.iter().try_for_each(validate_scope),
            "quantity" => list
                .iter()
                .all(norito::json::Value::is_number)
                .then_some(())
                .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex)),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
        F::Exists(f) | F::IsNull(f) => match f.0.as_str() {
            "account_id"
            | "asset"
            | "asset_alias"
            | "scope"
            | "quantity"
            | "primary_alias"
            | "primary_alias_name"
            | "primary_alias_dataspace"
            | "primary_alias_domain"
            | "has_primary_alias" => Ok(()),
            _ => Err(Error::Query(iroha_data_model::ValidationFail::TooComplex)),
        },
    }
}

#[cfg(feature = "app_api")]
fn aggregate_validation_error(message: impl Into<String>) -> Error {
    Error::AppQueryValidation {
        code: "unsupported_aggregate_shape",
        message: message.into(),
    }
}

#[cfg(feature = "app_api")]
fn projection_archive_unavailable_error(message: impl Into<String>) -> Error {
    Error::AppServiceUnavailable {
        code: "projection_archive_unavailable",
        message: message.into(),
    }
}

#[cfg(feature = "app_api")]
fn asset_holder_live_aggregate_enabled() -> bool {
    cfg!(test)
        || std::env::var("IROHA_TORII_ALLOW_LIVE_ASSET_HOLDER_AGGREGATE")
            .map(|value| value == "1" || value.eq_ignore_ascii_case("true"))
            .unwrap_or(false)
}

#[cfg(feature = "app_api")]
fn is_valid_aggregate_alias(alias: &str) -> bool {
    let mut chars = alias.chars();
    match chars.next() {
        Some(ch) if ch.is_ascii_alphabetic() || ch == '_' => {
            chars.all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
        }
        _ => false,
    }
}

#[cfg(feature = "app_api")]
fn json_value_to_numeric(value: &Value) -> Option<iroha_primitives::numeric::Numeric> {
    value
        .as_u64()
        .map(Into::into)
        .or_else(|| value.as_str()?.parse().ok())
}

#[cfg(feature = "app_api")]
fn compare_json_values(left: &Value, right: &Value) -> Option<Ordering> {
    if let (Some(lhs), Some(rhs)) = (json_value_to_numeric(left), json_value_to_numeric(right)) {
        return Some(lhs.cmp(&rhs));
    }
    if let (Some(lhs), Some(rhs)) = (left.as_bool(), right.as_bool()) {
        return Some(lhs.cmp(&rhs));
    }
    if let (Some(lhs), Some(rhs)) = (left.as_str(), right.as_str()) {
        return Some(lhs.cmp(rhs));
    }
    None
}

#[cfg(feature = "app_api")]
fn aggregate_field_value<'a>(row: &'a norito::json::Map, field: &str) -> Option<&'a Value> {
    row.get(field)
}

#[cfg(feature = "app_api")]
fn evaluate_filter_on_aggregate_row(
    expr: &crate::filter::FilterExpr,
    row: &norito::json::Map,
) -> bool {
    use crate::filter::FilterExpr as F;

    match expr {
        F::And(list) => list
            .iter()
            .all(|entry| evaluate_filter_on_aggregate_row(entry, row)),
        F::Or(list) => list
            .iter()
            .any(|entry| evaluate_filter_on_aggregate_row(entry, row)),
        F::Not(inner) => !evaluate_filter_on_aggregate_row(inner, row),
        F::Eq(field, value) => aggregate_field_value(row, &field.0)
            .is_some_and(|actual| compare_json_values(actual, value) == Some(Ordering::Equal)),
        F::Ne(field, value) => aggregate_field_value(row, &field.0)
            .is_some_and(|actual| compare_json_values(actual, value) != Some(Ordering::Equal)),
        F::Lt(field, value) => aggregate_field_value(row, &field.0)
            .is_some_and(|actual| compare_json_values(actual, value) == Some(Ordering::Less)),
        F::Lte(field, value) => aggregate_field_value(row, &field.0).is_some_and(|actual| {
            matches!(
                compare_json_values(actual, value),
                Some(Ordering::Less | Ordering::Equal)
            )
        }),
        F::Gt(field, value) => aggregate_field_value(row, &field.0)
            .is_some_and(|actual| compare_json_values(actual, value) == Some(Ordering::Greater)),
        F::Gte(field, value) => aggregate_field_value(row, &field.0).is_some_and(|actual| {
            matches!(
                compare_json_values(actual, value),
                Some(Ordering::Greater | Ordering::Equal)
            )
        }),
        F::In(field, values) => aggregate_field_value(row, &field.0).is_some_and(|actual| {
            values
                .iter()
                .any(|expected| compare_json_values(actual, expected) == Some(Ordering::Equal))
        }),
        F::Nin(field, values) => aggregate_field_value(row, &field.0).is_none_or(|actual| {
            values
                .iter()
                .all(|expected| compare_json_values(actual, expected) != Some(Ordering::Equal))
        }),
        F::Exists(field) => aggregate_field_value(row, &field.0).is_some(),
        F::IsNull(field) => aggregate_field_value(row, &field.0).is_none_or(Value::is_null),
    }
}

#[cfg(feature = "app_api")]
fn validate_aggregate_filter_fields(
    expr: &crate::filter::FilterExpr,
    allowed_fields: &BTreeSet<String>,
) -> Result<()> {
    use crate::filter::FilterExpr as F;

    let validate_field = |field: &crate::filter::FieldPath| -> Result<()> {
        if allowed_fields.contains(&field.0) {
            Ok(())
        } else {
            Err(aggregate_validation_error(format!(
                "aggregate field `{}` is not allowed",
                field.0
            )))
        }
    };

    match expr {
        F::And(list) | F::Or(list) => {
            for nested in list {
                validate_aggregate_filter_fields(nested, allowed_fields)?;
            }
            Ok(())
        }
        F::Not(inner) => validate_aggregate_filter_fields(inner, allowed_fields),
        F::Eq(field, _)
        | F::Ne(field, _)
        | F::Lt(field, _)
        | F::Lte(field, _)
        | F::Gt(field, _)
        | F::Gte(field, _)
        | F::In(field, _)
        | F::Nin(field, _)
        | F::Exists(field)
        | F::IsNull(field) => validate_field(field),
    }
}

#[cfg(feature = "app_api")]
fn validate_aggregate_sort_fields(
    sort: &[crate::filter::SortKey],
    allowed_fields: &BTreeSet<String>,
) -> Result<()> {
    for key in sort {
        if !allowed_fields.contains(&key.key.0) {
            return Err(aggregate_validation_error(format!(
                "aggregate sort key `{}` is not allowed",
                key.key.0
            )));
        }
    }
    Ok(())
}

#[cfg(feature = "app_api")]
enum AggregateMetricState {
    Count(u64),
    // Exact for the currently allowed distinct fields: accounts emit unique `id`
    // rows, and asset-holder rows are reduced in `account_id` order.
    DistinctCount {
        last_value: Option<String>,
        count: u64,
    },
    Sum(Option<iroha_primitives::numeric::Numeric>),
    Min(Option<iroha_primitives::numeric::Numeric>),
    Max(Option<iroha_primitives::numeric::Numeric>),
    Avg {
        sum: Option<iroha_primitives::numeric::Numeric>,
        count: u64,
    },
}

#[cfg(feature = "app_api")]
impl AggregateMetricState {
    fn new(metric: &crate::filter::AggregateMetric) -> Result<Self> {
        use crate::filter::AggregateFn as FnKind;

        match metric.r#fn {
            FnKind::Count => Ok(Self::Count(0)),
            FnKind::DistinctCount => Ok(Self::DistinctCount {
                last_value: None,
                count: 0,
            }),
            FnKind::Sum => Ok(Self::Sum(None)),
            FnKind::Min => Ok(Self::Min(None)),
            FnKind::Max => Ok(Self::Max(None)),
            FnKind::Avg => Ok(Self::Avg {
                sum: None,
                count: 0,
            }),
        }
    }

    fn update(
        &mut self,
        metric: &crate::filter::AggregateMetric,
        row: &norito::json::Map,
    ) -> Result<()> {
        use crate::filter::AggregateFn as FnKind;

        match (self, metric.r#fn) {
            (Self::Count(total), FnKind::Count) => {
                *total = total.saturating_add(1);
                Ok(())
            }
            (Self::DistinctCount { last_value, count }, FnKind::DistinctCount) => {
                let field = metric
                    .field
                    .as_ref()
                    .ok_or_else(|| aggregate_validation_error("distinct_count requires a field"))?;
                if let Some(value) = aggregate_field_value(row, &field.0) {
                    let encoded = norito::json::to_json(value).map_err(|err| {
                        Error::Query(iroha_data_model::ValidationFail::InternalError(
                            err.to_string(),
                        ))
                    })?;
                    if last_value.as_ref() != Some(&encoded) {
                        *count = count.saturating_add(1);
                        *last_value = Some(encoded);
                    }
                }
                Ok(())
            }
            (Self::Sum(total), FnKind::Sum) => {
                let field = metric
                    .field
                    .as_ref()
                    .ok_or_else(|| aggregate_validation_error("sum requires a field"))?;
                if let Some(value) =
                    aggregate_field_value(row, &field.0).and_then(json_value_to_numeric)
                {
                    *total = Some(match total.take() {
                        Some(existing) => existing.checked_add(value).ok_or_else(|| {
                            aggregate_validation_error("aggregate sum overflowed")
                        })?,
                        None => value,
                    });
                }
                Ok(())
            }
            (Self::Min(current), FnKind::Min) => {
                let field = metric
                    .field
                    .as_ref()
                    .ok_or_else(|| aggregate_validation_error("min requires a field"))?;
                if let Some(value) =
                    aggregate_field_value(row, &field.0).and_then(json_value_to_numeric)
                {
                    if current.as_ref().is_none_or(|existing| value < *existing) {
                        *current = Some(value);
                    }
                }
                Ok(())
            }
            (Self::Max(current), FnKind::Max) => {
                let field = metric
                    .field
                    .as_ref()
                    .ok_or_else(|| aggregate_validation_error("max requires a field"))?;
                if let Some(value) =
                    aggregate_field_value(row, &field.0).and_then(json_value_to_numeric)
                {
                    if current.as_ref().is_none_or(|existing| value > *existing) {
                        *current = Some(value);
                    }
                }
                Ok(())
            }
            (Self::Avg { sum, count }, FnKind::Avg) => {
                let field = metric
                    .field
                    .as_ref()
                    .ok_or_else(|| aggregate_validation_error("avg requires a field"))?;
                if let Some(value) =
                    aggregate_field_value(row, &field.0).and_then(json_value_to_numeric)
                {
                    *sum = Some(match sum.take() {
                        Some(existing) => existing.checked_add(value).ok_or_else(|| {
                            aggregate_validation_error("aggregate avg overflowed")
                        })?,
                        None => value,
                    });
                    *count = count.saturating_add(1);
                }
                Ok(())
            }
            _ => Err(aggregate_validation_error(
                "aggregate metric state mismatch",
            )),
        }
    }

    fn finalize(self) -> Result<Value> {
        match self {
            Self::Count(total) => Ok(Value::from(total)),
            Self::DistinctCount { count, .. } => Ok(Value::from(count)),
            Self::Sum(total) | Self::Min(total) | Self::Max(total) => Ok(total
                .map(|value| Value::from(value.to_string()))
                .unwrap_or(Value::Null)),
            Self::Avg { sum, count } => {
                let Some(sum) = sum else {
                    return Ok(Value::Null);
                };
                let divisor = iroha_primitives::numeric::Numeric::new(count, 0);
                let scale = sum.scale().max(6);
                let avg = sum
                    .try_decimal_div_round(
                        &divisor,
                        scale,
                        iroha_primitives::numeric::RoundingMode::TowardZero,
                    )
                    .map_err(|_| aggregate_validation_error("aggregate avg overflowed"))?;
                Ok(Value::from(avg.to_string()))
            }
        }
    }
}

#[cfg(feature = "app_api")]
struct AggregateGroupState {
    group_values: Vec<(String, Value)>,
    metrics: Vec<AggregateMetricState>,
}

#[cfg(feature = "app_api")]
fn aggregate_rows(
    rows: impl IntoIterator<Item = norito::json::Map>,
    aggregate: &crate::filter::AggregateSpec,
) -> Result<Vec<norito::json::Map>> {
    let mut grouped: BTreeMap<Vec<String>, AggregateGroupState> = BTreeMap::new();

    for row in rows {
        let group_values: Vec<(String, Value)> = aggregate
            .group_by
            .iter()
            .map(|field| {
                (
                    field.0.clone(),
                    row.get(&field.0).cloned().unwrap_or(Value::Null),
                )
            })
            .collect();
        let group_key: Vec<String> = group_values
            .iter()
            .map(|(_, value)| norito::json::to_json(value).unwrap_or_else(|_| "null".to_owned()))
            .collect();

        let entry = grouped
            .entry(group_key)
            .or_insert_with(|| AggregateGroupState {
                group_values: group_values.clone(),
                metrics: aggregate
                    .metrics
                    .iter()
                    .map(AggregateMetricState::new)
                    .collect::<Result<Vec<_>>>()
                    .expect("metric validation should happen before execution"),
            });

        for (state, metric) in entry.metrics.iter_mut().zip(&aggregate.metrics) {
            state.update(metric, &row)?;
        }
    }

    grouped
        .into_values()
        .map(|state| {
            let mut row = norito::json::Map::new();
            for (field, value) in state.group_values {
                row.insert(field, value);
            }
            for (metric, value) in aggregate.metrics.iter().zip(state.metrics) {
                row.insert(metric.alias.clone(), value.finalize()?);
            }
            Ok(row)
        })
        .collect()
}

#[cfg(feature = "app_api")]
fn sort_aggregate_rows_in_place(rows: &mut [norito::json::Map], sort: &[crate::filter::SortKey]) {
    rows.sort_by(|left, right| {
        for key in sort {
            let left_value = left.get(&key.key.0).unwrap_or(&Value::Null);
            let right_value = right.get(&key.key.0).unwrap_or(&Value::Null);
            let ordering = compare_json_values(left_value, right_value).unwrap_or_else(|| {
                let left_json =
                    norito::json::to_json(left_value).unwrap_or_else(|_| "null".to_owned());
                let right_json =
                    norito::json::to_json(right_value).unwrap_or_else(|_| "null".to_owned());
                left_json.cmp(&right_json)
            });
            if ordering != Ordering::Equal {
                return if matches!(key.order, crate::filter::Order::Asc) {
                    ordering
                } else {
                    ordering.reverse()
                };
            }
        }
        Ordering::Equal
    });
}

#[cfg(feature = "app_api")]
fn query_index_snapshot(state: &CoreState) -> (u64, Option<String>) {
    let snapshot = state.query_index_status_snapshot();
    let block_hash = snapshot
        .indexed_block_hash
        .map(|hash| hex::encode(hash.as_ref().as_ref()));
    (snapshot.indexed_height, block_hash)
}

#[cfg(feature = "app_api")]
fn generic_query_snapshot(
    state: &CoreState,
    query_source: &'static str,
) -> crate::generic_query::QuerySnapshot {
    let (indexed_height, indexed_block_hash) = query_index_snapshot(state);
    crate::generic_query::QuerySnapshot::new(indexed_height, indexed_block_hash, query_source)
}

#[cfg(feature = "app_api")]
fn execute_generic_resource_query<I>(
    state: &CoreState,
    resource_id: &str,
    mut envelope: crate::filter::QueryEnvelope,
    rows: I,
    query_source: &'static str,
) -> Result<Response, Error>
where
    I: IntoIterator<Item = norito::json::Map>,
{
    normalize_app_generic_count_mode(&mut envelope, "generic_resource_query");
    let resource = crate::generic_query::registered_resource(resource_id).ok_or_else(|| {
        Error::AppQueryValidation {
            code: "unsupported_query_resource",
            message: format!("resource `{resource_id}` is not registered"),
        }
    })?;
    crate::generic_query::execute_query_envelope(
        resource,
        envelope,
        rows,
        app_query_page_cap(state),
        generic_query_snapshot(state, query_source),
    )
}

#[cfg(feature = "app_api")]
fn object_row_from_value(value: Value) -> Result<norito::json::Map, Error> {
    match value {
        Value::Object(map) => Ok(map),
        _ => Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(
                "query row projection did not produce a JSON object".to_owned(),
            ),
        )),
    }
}

#[cfg(feature = "app_api")]
fn account_list_item_to_query_row(item: &AccountListItem) -> norito::json::Map {
    let mut row = norito::json::Map::new();
    row.insert("id".into(), Value::from(item.canonical_id.clone()));
    insert_primary_alias_fields(&mut row, &item.primary_alias);
    row
}

#[cfg(feature = "app_api")]
fn account_asset_item_to_query_row(item: &AccountAssetListItem) -> norito::json::Map {
    let mut row = norito::json::Map::new();
    row.insert("account_id".into(), Value::from(item.account_id.clone()));
    row.insert("asset".into(), Value::from(item.asset.clone()));
    row.insert("asset_name".into(), Value::from(item.asset_name.clone()));
    row.insert(
        "asset_alias".into(),
        item.asset_alias
            .as_ref()
            .map_or(Value::Null, |value| Value::from(value.clone())),
    );
    row.insert("scope".into(), Value::from(item.scope.clone()));
    row.insert("quantity".into(), Value::from(item.quantity.to_string()));
    insert_primary_alias_fields(&mut row, &item.primary_alias);
    row
}

#[cfg(feature = "app_api")]
fn asset_holder_item_to_query_row(item: &AssetHolderListItem) -> norito::json::Map {
    let mut row = norito::json::Map::new();
    row.insert("account_id".into(), Value::from(item.canonical_id.clone()));
    row.insert("asset".into(), Value::from(item.asset.clone()));
    row.insert(
        "asset_alias".into(),
        item.asset_alias
            .as_ref()
            .map_or(Value::Null, |value| Value::from(value.clone())),
    );
    row.insert("scope".into(), Value::from(item.scope.clone()));
    row.insert("quantity".into(), Value::from(item.quantity.to_string()));
    insert_primary_alias_fields(&mut row, &item.primary_alias);
    row
}

#[cfg(feature = "app_api")]
fn build_aggregate_response(
    state: &CoreState,
    mut rows: Vec<norito::json::Map>,
    sort: &[crate::filter::SortKey],
    pagination: EffectivePagination,
    having: Option<&crate::filter::FilterExpr>,
    indexed_snapshot: Option<(u64, Option<String>)>,
    query_source: &'static str,
) -> Result<Response, Error> {
    if let Some(expr) = having {
        rows.retain(|row| evaluate_filter_on_aggregate_row(expr, row));
    }
    if !sort.is_empty() {
        sort_aggregate_rows_in_place(&mut rows, sort);
    }
    let total = rows.len();
    let offset = usize::try_from(pagination.offset).unwrap_or(usize::MAX);
    let limit = usize::try_from(pagination.limit.unwrap_or(pagination.cap)).unwrap_or(usize::MAX);
    let items = rows
        .into_iter()
        .skip(offset)
        .take(limit)
        .collect::<Vec<_>>();
    let (indexed_height, indexed_block_hash) =
        indexed_snapshot.unwrap_or_else(|| query_index_snapshot(state));

    let mut top = norito::json::Map::new();
    top.insert(
        "items".into(),
        Value::Array(items.into_iter().map(Value::Object).collect()),
    );
    top.insert("total".into(), Value::from(total as u64));
    top.insert("indexed_height".into(), Value::from(indexed_height));
    top.insert(
        "indexed_block_hash".into(),
        indexed_block_hash.map_or(Value::Null, Value::from),
    );
    top.insert("query_source".into(), Value::from(query_source));
    let body = norito::json::to_json_pretty(&top).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            err.to_string(),
        ))
    })?;
    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(response)
}

#[cfg(feature = "app_api")]
fn validate_accounts_aggregate_request(
    aggregate: &crate::filter::AggregateSpec,
    sort: &[crate::filter::SortKey],
) -> Result<BTreeSet<String>> {
    use crate::filter::AggregateFn as FnKind;

    if aggregate.group_by.len() > 4 {
        return Err(aggregate_validation_error(
            "aggregate group_by supports at most four fields",
        ));
    }
    if aggregate.metrics.is_empty() || aggregate.metrics.len() > 8 {
        return Err(aggregate_validation_error(
            "aggregate metrics requires between one and eight metrics",
        ));
    }

    let allowed_group_fields = BTreeSet::from([
        "primary_alias_domain".to_owned(),
        "primary_alias_dataspace".to_owned(),
        "has_primary_alias".to_owned(),
    ]);
    let mut allowed_result_fields = BTreeSet::new();
    for field in &aggregate.group_by {
        if !allowed_group_fields.contains(&field.0) {
            return Err(aggregate_validation_error(format!(
                "accounts aggregate group_by field `{}` is not supported",
                field.0
            )));
        }
        allowed_result_fields.insert(field.0.clone());
    }

    for metric in &aggregate.metrics {
        if !is_valid_aggregate_alias(&metric.alias) {
            return Err(aggregate_validation_error(format!(
                "aggregate metric alias `{}` is invalid",
                metric.alias
            )));
        }
        if !allowed_result_fields.insert(metric.alias.clone()) {
            return Err(aggregate_validation_error(format!(
                "aggregate metric alias `{}` is duplicated",
                metric.alias
            )));
        }
        match metric.r#fn {
            FnKind::Count => {
                if metric.field.is_some() {
                    return Err(aggregate_validation_error("count must not declare a field"));
                }
            }
            FnKind::DistinctCount => match metric.field.as_ref().map(|field| field.0.as_str()) {
                Some("id") => {}
                _ => {
                    return Err(aggregate_validation_error(
                        "accounts aggregate distinct_count only supports field `id`",
                    ));
                }
            },
            _ => {
                return Err(aggregate_validation_error(
                    "accounts aggregate only supports `count` and `distinct_count(id)` metrics",
                ));
            }
        }
    }

    validate_aggregate_sort_fields(sort, &allowed_result_fields)?;
    if let Some(having) = aggregate.having.as_ref() {
        validate_aggregate_filter_fields(having, &allowed_result_fields)?;
    }
    Ok(allowed_result_fields)
}

#[cfg(feature = "app_api")]
fn validate_asset_holders_aggregate_request(
    aggregate: &crate::filter::AggregateSpec,
    sort: &[crate::filter::SortKey],
) -> Result<BTreeSet<String>> {
    use crate::filter::AggregateFn as FnKind;

    if aggregate.group_by.len() > 4 {
        return Err(aggregate_validation_error(
            "aggregate group_by supports at most four fields",
        ));
    }
    if aggregate.metrics.is_empty() || aggregate.metrics.len() > 8 {
        return Err(aggregate_validation_error(
            "aggregate metrics requires between one and eight metrics",
        ));
    }

    let allowed_group_fields = BTreeSet::from([
        "scope".to_owned(),
        "primary_alias_domain".to_owned(),
        "primary_alias_dataspace".to_owned(),
        "has_primary_alias".to_owned(),
    ]);
    let mut allowed_result_fields = BTreeSet::new();
    for field in &aggregate.group_by {
        if !allowed_group_fields.contains(&field.0) {
            return Err(aggregate_validation_error(format!(
                "asset holders aggregate group_by field `{}` is not supported",
                field.0
            )));
        }
        allowed_result_fields.insert(field.0.clone());
    }

    for metric in &aggregate.metrics {
        if !is_valid_aggregate_alias(&metric.alias) {
            return Err(aggregate_validation_error(format!(
                "aggregate metric alias `{}` is invalid",
                metric.alias
            )));
        }
        if !allowed_result_fields.insert(metric.alias.clone()) {
            return Err(aggregate_validation_error(format!(
                "aggregate metric alias `{}` is duplicated",
                metric.alias
            )));
        }
        match metric.r#fn {
            FnKind::Count => {
                if metric.field.is_some() {
                    return Err(aggregate_validation_error("count must not declare a field"));
                }
            }
            FnKind::DistinctCount => match metric.field.as_ref().map(|field| field.0.as_str()) {
                Some("account_id") => {}
                _ => {
                    return Err(aggregate_validation_error(
                        "asset holders distinct_count only supports field `account_id`",
                    ));
                }
            },
            FnKind::Sum | FnKind::Min | FnKind::Max | FnKind::Avg => {
                match metric.field.as_ref().map(|field| field.0.as_str()) {
                    Some("quantity") => {}
                    _ => {
                        return Err(aggregate_validation_error(
                            "numeric aggregate metrics only support field `quantity`",
                        ));
                    }
                }
            }
        }
    }

    validate_aggregate_sort_fields(sort, &allowed_result_fields)?;
    if let Some(having) = aggregate.having.as_ref() {
        validate_aggregate_filter_fields(having, &allowed_result_fields)?;
    }
    Ok(allowed_result_fields)
}

#[cfg(feature = "app_api")]
fn handle_v1_accounts_query_aggregate(
    state: Arc<CoreState>,
    accounts: Vec<iroha_data_model::account::Account>,
    envelope: crate::filter::QueryEnvelope,
) -> Result<Response, Error> {
    let crate::filter::QueryEnvelope {
        filter,
        select,
        aggregate,
        sort,
        pagination,
        ..
    } = envelope;
    if select.is_some() {
        return Err(aggregate_validation_error(
            "select is not supported when aggregate is present",
        ));
    }
    let aggregate = aggregate.ok_or_else(|| aggregate_validation_error("aggregate is required"))?;
    validate_accounts_aggregate_request(&aggregate, &sort)?;

    let rows = accounts.into_iter().filter_map(|account| {
        let projected = AccountListItem {
            canonical_id: account.id().to_string(),
            display_id: crate::account_literal::display_literal(account.id()),
            primary_alias: primary_alias_projection_for_account_id(state.as_ref(), account.id()),
        };
        if let Some(expr) = filter.as_ref()
            && !account_filter_projection(expr, &projected)
        {
            return None;
        }
        Some(account_list_item_to_query_row(&projected))
    });

    let aggregated = aggregate_rows(rows, &aggregate)?;
    let cap = app_query_page_cap(&state);
    let pagination = enforce_app_pagination(
        pagination.limit,
        pagination.offset,
        cap,
        ENDPOINT_ACCOUNTS_QUERY,
    )?;
    build_aggregate_response(
        state.as_ref(),
        aggregated,
        &sort,
        pagination,
        aggregate.having.as_ref(),
        None,
        "live",
    )
}

#[cfg(feature = "app_api")]
async fn handle_v1_asset_holders_query_aggregate(
    app: Option<&crate::SharedAppState>,
    state: Arc<CoreState>,
    def_id: AssetDefinitionId,
    asset_alias: Option<String>,
    filter: Option<crate::filter::FilterExpr>,
    aggregate: Option<crate::filter::AggregateSpec>,
    sort: Vec<crate::filter::SortKey>,
    pagination: EffectivePagination,
) -> Result<Response, Error> {
    let aggregate = aggregate.ok_or_else(|| aggregate_validation_error("aggregate is required"))?;
    validate_asset_holders_aggregate_request(&aggregate, &sort)?;

    if let Some((rows, indexed_snapshot, query_source)) = asset_holder_projection_query_rows(
        app,
        state.as_ref(),
        &def_id,
        asset_alias.as_ref(),
        filter.as_ref(),
    )
    .await?
    {
        let aggregated = aggregate_rows(rows, &aggregate)?;
        return build_aggregate_response(
            state.as_ref(),
            aggregated,
            &sort,
            pagination,
            aggregate.having.as_ref(),
            Some(indexed_snapshot),
            query_source,
        );
    }

    if !asset_holder_live_aggregate_enabled() {
        return Err(projection_archive_unavailable_error(
            "asset holder aggregate requires a complete published query projection archive; live holder scans are disabled",
        ));
    }
    iroha_logger::warn!(
        asset_definition_id = %def_id,
        "serving asset holder aggregate from live state because projection archive cache is incomplete"
    );

    let world = state.world_view();
    let mut map: BTreeMap<
        (AccountId, iroha_data_model::asset::AssetBalanceScope),
        iroha_primitives::numeric::Quantity,
    > = BTreeMap::new();
    for asset in world.asset_entries_by_definition_iter(&def_id) {
        accumulate_asset_holder_quantity(&mut map, asset.id(), asset.value().as_ref(), None)?;
    }
    let alias_cache: BTreeMap<_, _> = map
        .keys()
        .map(|(account_id, _)| {
            (
                account_id.clone(),
                primary_alias_projection_for_account_id(state.as_ref(), account_id),
            )
        })
        .collect();
    drop(world);

    let asset = def_id.to_string();
    let rows = map
        .into_iter()
        .filter_map(|((account_id, scope), quantity)| {
            let canonical_id = account_id.to_string();
            let primary_alias = alias_cache.get(&account_id).cloned().unwrap_or_default();
            let projected = AssetHolderListItem {
                account_id: account_id.clone(),
                canonical_id,
                asset: asset.clone(),
                asset_alias: asset_alias.clone(),
                scope: asset_balance_scope_literal(&scope),
                quantity,
                primary_alias,
            };
            if let Some(expr) = filter.as_ref()
                && !filter_asset_holder_item(expr, &projected)
            {
                return None;
            }
            Some(asset_holder_item_to_query_row(&projected))
        });

    let aggregated = aggregate_rows(rows, &aggregate)?;
    build_aggregate_response(
        state.as_ref(),
        aggregated,
        &sort,
        pagination,
        aggregate.having.as_ref(),
        None,
        "live_debug",
    )
}

#[cfg(feature = "app_api")]
fn asset_holder_projection_row_to_query_row(
    asset: &str,
    asset_alias: Option<&str>,
    row: QueryProjectionAssetHolderRow,
) -> norito::json::Map {
    let mut map = norito::json::Map::new();
    map.insert("account_id".into(), Value::from(row.account_id));
    map.insert("asset".into(), Value::from(asset.to_owned()));
    map.insert(
        "asset_alias".into(),
        asset_alias.map_or(Value::Null, |value| Value::from(value.to_owned())),
    );
    map.insert("scope".into(), Value::from(row.scope));
    map.insert("quantity".into(), Value::from(row.quantity.to_string()));
    insert_primary_alias_fields(
        &mut map,
        &PrimaryAliasProjection {
            literal: row.primary_alias,
            name: row.primary_alias_name,
            dataspace: row.primary_alias_dataspace,
            domain: row.primary_alias_domain,
            has_primary_alias: row.has_primary_alias,
        },
    );
    map
}

#[cfg(feature = "app_api")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum QueryProjectionArchiveResolutionSource {
    HotCache,
    LocalDurableStore,
    RemoteHydrated,
}

#[cfg(feature = "app_api")]
#[derive(Debug, Clone)]
struct RemoteProjectionArchiveSource {
    manifest_digest_hex: String,
    provider_id_hex: String,
    torii_base_url: reqwest::Url,
}

#[cfg(feature = "app_api")]
fn query_projection_archive_validation_error(message: impl Into<String>) -> Error {
    projection_archive_unavailable_error(message.into())
}

#[cfg(feature = "app_api")]
async fn asset_holder_projection_query_rows(
    app: Option<&crate::SharedAppState>,
    state: &CoreState,
    def_id: &AssetDefinitionId,
    endpoint_asset_alias: Option<&String>,
    filter: Option<&crate::filter::FilterExpr>,
) -> Result<Option<(Vec<norito::json::Map>, (u64, Option<String>), &'static str)>, Error> {
    let Some(checkpoint) = state.query_projection_checkpoint_snapshot() else {
        return Ok(None);
    };
    let asset_definition_id = def_id.to_string();
    let shards = checkpoint
        .shards
        .iter()
        .filter(|shard| {
            shard.resource == QueryProjectionResourceKind::AssetHolders
                && shard.asset_definition_id.as_deref() == Some(asset_definition_id.as_str())
        })
        .collect::<Vec<_>>();
    if shards.is_empty() {
        return Ok(None);
    }

    let mut query_source = "projection_da_cache";
    let mut rows = Vec::new();
    for shard in shards {
        let Some((archive, source)) =
            resolve_query_projection_archive_for_shard(app, state, &checkpoint, shard).await?
        else {
            return Ok(None);
        };
        if source == QueryProjectionArchiveResolutionSource::RemoteHydrated {
            query_source = "projection_da_hydrated";
        }
        let rowset = validate_query_projection_asset_holder_archive(
            &archive,
            &checkpoint,
            shard,
            &asset_definition_id,
        )?;
        let row_asset_alias = rowset
            .asset_alias
            .as_deref()
            .or(endpoint_asset_alias.map(String::as_str));
        for row in rowset.rows {
            let projected = asset_holder_projection_row_to_query_row(
                &asset_definition_id,
                row_asset_alias,
                row,
            );
            if filter.is_some_and(|expr| !evaluate_filter_on_aggregate_row(expr, &projected)) {
                continue;
            }
            rows.push(projected);
        }
    }

    Ok(Some((
        rows,
        (
            checkpoint.indexed_height,
            query_projection_block_hash_hex(checkpoint.indexed_block_hash),
        ),
        query_source,
    )))
}

#[cfg(feature = "app_api")]
pub(crate) fn query_projection_archive_storage_artifacts(
    archive: &QueryProjectionShardArchive,
) -> Result<
    (
        Vec<u8>,
        sorafs_car::CarBuildPlan,
        sorafs_manifest::ManifestV1,
    ),
    Error,
> {
    let archive_payload = archive.build_da_payload().map_err(|err| {
        query_projection_archive_validation_error(format!(
            "failed to encode query projection archive payload: {err}"
        ))
    })?;
    let plan = sorafs_car::CarBuildPlan::single_file_with_profile(
        archive_payload.payload.as_slice(),
        sorafs_chunker::ChunkProfile::DEFAULT,
    )
    .map_err(|err| {
        query_projection_archive_validation_error(format!(
            "failed to derive SoraFS chunk plan for query projection archive: {err}"
        ))
    })?;
    let stats = sorafs_car::CarWriter::new(&plan, archive_payload.payload.as_slice())
        .and_then(|writer| writer.write_to(std::io::sink()))
        .map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to derive SoraFS CAR metadata for query projection archive: {err}"
            ))
        })?;
    let root_cid = stats.root_cids.first().cloned().ok_or_else(|| {
        query_projection_archive_validation_error(
            "failed to derive SoraFS root CID for query projection archive",
        )
    })?;
    let mut car_digest = [0u8; 32];
    car_digest.copy_from_slice(stats.car_archive_digest.as_bytes());
    let manifest = sorafs_manifest::ManifestBuilder::new()
        .root_cid(root_cid)
        .dag_codec(sorafs_manifest::DagCodecId(stats.dag_codec))
        .chunking_from_profile(
            plan.chunk_profile,
            sorafs_manifest::BLAKE3_256_MULTIHASH_CODE,
        )
        .chunk_digest_sha3_256(sorafs_car::compute_chunk_plan_digest_sha3(&plan.chunks))
        .por_root(
            sorafs_car::compute_por_root(archive_payload.payload.as_slice(), &plan).map_err(
                |err| {
                    query_projection_archive_validation_error(format!(
                        "failed to derive SoraFS PoR root for query projection archive: {err}"
                    ))
                },
            )?,
        )
        .content_length(plan.content_length)
        .car_digest(car_digest)
        .car_size(stats.car_size)
        .pin_policy(sorafs_manifest::PinPolicy::default())
        .build()
        .map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to build SoraFS manifest for query projection archive: {err}"
            ))
        })?;
    Ok((archive_payload.payload, plan, manifest))
}

#[cfg(feature = "app_api")]
fn validate_query_projection_asset_holder_archive(
    archive: &QueryProjectionShardArchive,
    checkpoint: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpoint,
    shard: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpointShard,
    asset_definition_id: &str,
) -> Result<iroha_core::query::projection_rowset::QueryProjectionAssetHoldersShardRowSet, Error> {
    use iroha_core::query::{
        projection_checkpoint::QUERY_PROJECTION_SCHEMA_VERSION,
        projection_rowset::QUERY_PROJECTION_ROWSET_VERSION,
        projection_shard::{
            QUERY_PROJECTION_SHARD_ARCHIVE_VERSION, QUERY_PROJECTION_SHARD_ROWSET_CODEC,
        },
    };

    let archive_payload = archive.build_da_payload().map_err(|err| {
        query_projection_archive_validation_error(format!(
            "failed to verify query projection archive payload: {err}"
        ))
    })?;
    if archive.version != QUERY_PROJECTION_SHARD_ARCHIVE_VERSION {
        return Err(query_projection_archive_validation_error(format!(
            "query projection archive version mismatch: expected {QUERY_PROJECTION_SHARD_ARCHIVE_VERSION}, found {}",
            archive.version
        )));
    }
    if archive.schema_version != QUERY_PROJECTION_SCHEMA_VERSION {
        return Err(query_projection_archive_validation_error(format!(
            "query projection archive schema version mismatch: expected {QUERY_PROJECTION_SCHEMA_VERSION}, found {}",
            archive.schema_version
        )));
    }
    if archive.payload_codec.0 != QUERY_PROJECTION_SHARD_ROWSET_CODEC {
        return Err(query_projection_archive_validation_error(format!(
            "query projection archive rowset codec mismatch: expected {QUERY_PROJECTION_SHARD_ROWSET_CODEC}, found {}",
            archive.payload_codec.0
        )));
    }
    if archive.resource != shard.resource
        || archive.partition_id != shard.partition_id
        || archive.asset_definition_id != shard.asset_definition_id
        || archive.indexed_height != checkpoint.indexed_height
        || archive.indexed_block_hash != checkpoint.indexed_block_hash
        || archive_payload.payload_hash != shard.blob_hash
    {
        return Err(query_projection_archive_validation_error(
            "query projection archive does not match checkpoint reference",
        ));
    }

    let rowset: QueryProjectionShardRowSet =
        norito::decode_from_bytes(&archive.payload).map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to decode query projection rowset: {err}"
            ))
        })?;
    let QueryProjectionShardRowSet::AssetHolders(rowset) = rowset else {
        return Err(query_projection_archive_validation_error(
            "query projection archive has non-holder rowset",
        ));
    };
    if rowset.version != QUERY_PROJECTION_ROWSET_VERSION {
        return Err(query_projection_archive_validation_error(format!(
            "query projection rowset version mismatch: expected {QUERY_PROJECTION_ROWSET_VERSION}, found {}",
            rowset.version
        )));
    }
    if rowset.partition_id != shard.partition_id
        || rowset.asset_definition_id != asset_definition_id
    {
        return Err(query_projection_archive_validation_error(
            "query projection archive does not match checkpoint shard",
        ));
    }

    Ok(rowset)
}

#[cfg(feature = "app_api")]
async fn resolve_query_projection_archive_for_shard(
    app: Option<&crate::SharedAppState>,
    state: &CoreState,
    checkpoint: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpoint,
    shard: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpointShard,
) -> Result<
    Option<(
        QueryProjectionShardArchive,
        QueryProjectionArchiveResolutionSource,
    )>,
    Error,
> {
    let key = query_projection_checkpoint_cache_key(shard, checkpoint);
    if let Some(archive) = query_projection_archive_from_hot_cache(&key) {
        return Ok(Some((
            archive,
            QueryProjectionArchiveResolutionSource::HotCache,
        )));
    }

    let Some(app) = app else {
        return Ok(None);
    };

    if let Some(archive) = load_query_projection_archive_from_local_store(app, shard)? {
        cache_query_projection_archive_for_query(archive.clone());
        return Ok(Some((
            archive,
            QueryProjectionArchiveResolutionSource::LocalDurableStore,
        )));
    }

    let hydration_lock = {
        let mut locks = QUERY_PROJECTION_ARCHIVE_HYDRATION_LOCKS.lock().await;
        locks
            .entry(key.clone())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone()
    };
    let _guard = hydration_lock.lock().await;

    if let Some(archive) = query_projection_archive_from_hot_cache(&key) {
        return Ok(Some((
            archive,
            QueryProjectionArchiveResolutionSource::HotCache,
        )));
    }
    if let Some(archive) = load_query_projection_archive_from_local_store(app, shard)? {
        cache_query_projection_archive_for_query(archive.clone());
        return Ok(Some((
            archive,
            QueryProjectionArchiveResolutionSource::LocalDurableStore,
        )));
    }

    let hydrated = hydrate_query_projection_archive_from_remote(app, state, shard).await?;
    {
        let mut locks = QUERY_PROJECTION_ARCHIVE_HYDRATION_LOCKS.lock().await;
        if Arc::strong_count(&hydration_lock) <= 2 {
            locks.remove(&key);
        }
    }

    if let Some(archive) = hydrated {
        cache_query_projection_archive_for_query(archive.clone());
        return Ok(Some((
            archive,
            QueryProjectionArchiveResolutionSource::RemoteHydrated,
        )));
    }

    Ok(None)
}

#[cfg(feature = "app_api")]
fn load_query_projection_archive_from_local_store(
    app: &crate::SharedAppState,
    shard: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpointShard,
) -> Result<Option<QueryProjectionShardArchive>, Error> {
    use sorafs_node::{NodeStorageError, store::StorageError};

    let manifest_digest = *shard.manifest_digest.as_bytes();
    let stored = match app
        .sorafs_node()
        .manifest_metadata_by_digest(&manifest_digest)
    {
        Ok(stored) => stored,
        Err(NodeStorageError::Storage(StorageError::ManifestNotFound { .. })) => return Ok(None),
        Err(err) => {
            return Err(query_projection_archive_validation_error(format!(
                "failed to read locally stored query projection archive metadata: {err}"
            )));
        }
    };

    if stored.payload_digest() != shard.blob_hash.as_bytes() {
        return Err(query_projection_archive_validation_error(
            "locally stored query projection archive payload digest does not match checkpoint shard",
        ));
    }
    let content_length = usize::try_from(stored.content_length()).map_err(|_| {
        query_projection_archive_validation_error(
            "stored query projection archive exceeds host payload limits",
        )
    })?;
    let payload = app
        .sorafs_node()
        .read_payload_range(stored.manifest_id(), 0, content_length)
        .map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to read locally stored query projection archive payload: {err}"
            ))
        })?;
    decode_query_projection_archive_payload(&payload)
}

#[cfg(feature = "app_api")]
fn decode_query_projection_archive_payload(
    payload: &[u8],
) -> Result<Option<QueryProjectionShardArchive>, Error> {
    let decompressed = zstd::stream::decode_all(std::io::Cursor::new(payload)).map_err(|err| {
        query_projection_archive_validation_error(format!(
            "failed to decompress query projection archive payload: {err}"
        ))
    })?;
    let archive =
        norito::decode_from_bytes::<QueryProjectionShardArchive>(&decompressed).map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to decode query projection archive payload: {err}"
            ))
        })?;
    Ok(Some(archive))
}

#[cfg(feature = "app_api")]
async fn hydrate_query_projection_archive_from_remote(
    app: &crate::SharedAppState,
    state: &CoreState,
    shard: &iroha_core::query::projection_checkpoint::QueryProjectionCheckpointShard,
) -> Result<Option<QueryProjectionShardArchive>, Error> {
    let manifest_digest_hex = hex::encode(shard.manifest_digest.as_bytes());
    let Some(sources) =
        resolve_remote_projection_archive_sources(app, state, manifest_digest_hex.as_str()).await?
    else {
        return Ok(None);
    };

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .build()
        .map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to build query projection hydrate client: {err}"
            ))
        })?;

    let mut last_error = None;
    for source in &sources {
        match fetch_remote_query_projection_archive_from_source(&client, source).await {
            Ok((_manifest, payload)) => return decode_query_projection_archive_payload(&payload),
            Err(err) => {
                iroha_logger::warn!(
                    provider_id_hex = %source.provider_id_hex,
                    manifest_digest_hex = %source.manifest_digest_hex,
                    %err,
                    "failed to hydrate query projection archive from remote provider"
                );
                last_error = Some(err);
            }
        }
    }

    Err(query_projection_archive_validation_error(format!(
        "failed to hydrate query projection archive from remote providers{}",
        last_error
            .as_deref()
            .map(|err| format!(": {err}"))
            .unwrap_or_default()
    )))
}

#[cfg(feature = "app_api")]
async fn resolve_remote_projection_archive_sources(
    app: &crate::SharedAppState,
    state: &CoreState,
    manifest_digest_hex: &str,
) -> Result<Option<Vec<RemoteProjectionArchiveSource>>, Error> {
    use crate::sorafs::{EndpointKind, registry::collect_pin_registry};

    let snapshot = {
        let world = state.world_view();
        collect_pin_registry(&world).map_err(|err| {
            query_projection_archive_validation_error(format!(
                "failed to collect pin registry for query projection hydration: {err}"
            ))
        })?
    };

    let mut provider_specs = Vec::<String>::new();
    for prefer_completed in [true, false] {
        for order in &snapshot.replication_orders {
            if order.manifest_digest_hex() != manifest_digest_hex {
                continue;
            }
            if order.is_expired() {
                continue;
            }
            if prefer_completed != order.completion_epoch().is_some() {
                continue;
            }
            let Some(manifest) = snapshot.manifest_by_digest(order.manifest_digest_hex()) else {
                continue;
            };
            if manifest.status_label() != "approved" {
                continue;
            }
            for provider_id_hex in order.providers() {
                if !provider_specs
                    .iter()
                    .any(|existing| existing == provider_id_hex)
                {
                    provider_specs.push(provider_id_hex.clone());
                }
            }
        }
    }

    if provider_specs.is_empty() {
        return Ok(None);
    }

    let Some(cache) = app.sorafs_cache() else {
        return Err(query_projection_archive_validation_error(
            "SoraFS discovery cache is not available for query projection hydration",
        ));
    };

    let cache = cache.read().await;
    let mut sources = Vec::new();
    for provider_id_hex in provider_specs {
        let Ok(provider_bytes) = hex::decode(provider_id_hex.as_str()) else {
            continue;
        };
        let Ok(provider_id) = <[u8; 32]>::try_from(provider_bytes.as_slice()) else {
            continue;
        };
        let Some(record) = cache.record_by_provider(&provider_id) else {
            continue;
        };
        let Some(endpoint) = record
            .advert()
            .body
            .endpoints
            .iter()
            .find(|endpoint| endpoint.kind == EndpointKind::Torii)
        else {
            continue;
        };
        let torii_base_url =
            normalize_query_projection_provider_torii_base_url(&endpoint.host_pattern)
                .map_err(query_projection_archive_validation_error)?;
        sources.push(RemoteProjectionArchiveSource {
            manifest_digest_hex: manifest_digest_hex.to_owned(),
            provider_id_hex,
            torii_base_url,
        });
    }

    if sources.is_empty() {
        return Err(query_projection_archive_validation_error(
            "no SoraFS Torii provider routes are available for the requested projection shard",
        ));
    }

    Ok(Some(sources))
}

#[cfg(feature = "app_api")]
fn normalize_query_projection_provider_torii_base_url(
    host_pattern: &str,
) -> Result<reqwest::Url, String> {
    let trimmed = host_pattern.trim();
    if trimmed.is_empty() {
        return Err("provider advert endpoint host pattern must not be empty".to_string());
    }

    let with_scheme = if trimmed.contains("://") {
        trimmed.to_owned()
    } else {
        let lower = trimmed.to_ascii_lowercase();
        let scheme = if lower.starts_with("localhost")
            || lower.starts_with("127.")
            || lower.starts_with("[::1]")
            || lower.starts_with("::1")
        {
            "http"
        } else {
            "https"
        };
        format!("{scheme}://{trimmed}")
    };

    let mut url = reqwest::Url::parse(&with_scheme)
        .map_err(|err| format!("invalid provider advert endpoint `{trimmed}`: {err}"))?;
    if !url.path().ends_with('/') {
        let normalized = format!("{}/", url.path());
        url.set_path(&normalized);
    }
    Ok(url)
}

#[cfg(feature = "app_api")]
async fn fetch_remote_query_projection_archive_from_source(
    client: &reqwest::Client,
    source: &RemoteProjectionArchiveSource,
) -> Result<(sorafs_manifest::ManifestV1, Vec<u8>), String> {
    let manifest_url = source
        .torii_base_url
        .join(&format!(
            "v1/sorafs/storage/manifest/{}",
            source.manifest_digest_hex
        ))
        .map_err(|err| format!("failed to build remote manifest URL: {err}"))?;
    let manifest_response = client
        .get(manifest_url)
        .send()
        .await
        .map_err(|err| format!("failed to fetch remote manifest metadata: {err}"))?;
    let manifest_status = manifest_response.status();
    let manifest_body = manifest_response
        .bytes()
        .await
        .map_err(|err| format!("failed to read remote manifest metadata: {err}"))?;
    if !manifest_status.is_success() {
        let details = String::from_utf8_lossy(&manifest_body);
        return Err(format!(
            "remote manifest endpoint returned {manifest_status}: {}",
            details.trim()
        ));
    }

    let manifest_response =
        norito::json::from_slice::<crate::sorafs::api::StorageManifestResponseDto>(&manifest_body)
            .map_err(|err| format!("failed to decode remote manifest metadata response: {err}"))?;
    if manifest_response.manifest_digest_hex != source.manifest_digest_hex {
        return Err(format!(
            "remote manifest digest mismatch: expected {}, found {}",
            source.manifest_digest_hex, manifest_response.manifest_digest_hex
        ));
    }

    let manifest_bytes = base64::engine::general_purpose::STANDARD
        .decode(manifest_response.manifest_b64.as_bytes())
        .map_err(|err| format!("failed to decode remote manifest payload: {err}"))?;
    let manifest: sorafs_manifest::ManifestV1 = norito::decode_from_bytes(&manifest_bytes)
        .map_err(|err| format!("failed to decode remote manifest bytes: {err}"))?;
    let manifest_digest_hex = hex::encode(
        manifest
            .digest()
            .map_err(|err| format!("failed to digest remote manifest: {err}"))?
            .as_bytes(),
    );
    if manifest_digest_hex != source.manifest_digest_hex {
        return Err(format!(
            "decoded remote manifest digest mismatch: expected {}, found {manifest_digest_hex}",
            source.manifest_digest_hex
        ));
    }
    if manifest_response.content_length > usize::MAX as u64 {
        return Err("remote payload exceeds host limits".to_string());
    }

    let fetch_body = norito::json::to_vec(&crate::sorafs::api::StorageFetchRequestDto {
        manifest_id_hex: manifest_response.manifest_id_hex.clone(),
        offset: 0,
        length: manifest_response.content_length,
    })
    .map_err(|err| format!("failed to encode remote fetch request: {err}"))?;
    let fetch_url = source
        .torii_base_url
        .join("v1/sorafs/storage/fetch")
        .map_err(|err| format!("failed to build remote payload URL: {err}"))?;
    let fetch_response = client
        .post(fetch_url)
        .header(reqwest::header::CONTENT_TYPE, "application/json")
        .body(fetch_body)
        .send()
        .await
        .map_err(|err| format!("failed to fetch remote projection archive payload: {err}"))?;
    let fetch_status = fetch_response.status();
    let fetch_body = fetch_response.bytes().await.map_err(|err| {
        format!("failed to read remote projection archive payload response: {err}")
    })?;
    if !fetch_status.is_success() {
        let details = String::from_utf8_lossy(&fetch_body);
        return Err(format!(
            "remote payload endpoint returned {fetch_status}: {}",
            details.trim()
        ));
    }

    let fetch_response =
        norito::json::from_slice::<crate::sorafs::api::StorageFetchResponseDto>(&fetch_body)
            .map_err(|err| {
                format!("failed to decode remote projection archive payload response: {err}")
            })?;
    let payload = base64::engine::general_purpose::STANDARD
        .decode(fetch_response.data_b64.as_bytes())
        .map_err(|err| {
            format!("failed to decode remote projection archive payload bytes: {err}")
        })?;
    if payload.len() as u64 != manifest_response.content_length {
        return Err(format!(
            "remote payload length mismatch: expected {}, found {}",
            manifest_response.content_length,
            payload.len()
        ));
    }
    let payload_digest_hex = hex::encode(blake3::hash(&payload).as_bytes());
    if payload_digest_hex != manifest_response.payload_digest_hex {
        return Err(format!(
            "remote payload digest mismatch: expected {}, found {payload_digest_hex}",
            manifest_response.payload_digest_hex
        ));
    }

    Ok((manifest, payload))
}

// No route-level tests here to avoid heavy state setup; see filter unit tests for parser coverage.

#[iroha_futures::telemetry_future]
#[cfg(feature = "schema")]
pub async fn handle_schema() -> impl IntoResponse {
    let mm = iroha_schema_gen::build_schemas();
    use iroha_schema::Metadata;
    let mut total = 0u64;
    let mut structs = 0u64;
    let mut tuples = 0u64;
    let mut enums = 0u64;
    let mut ints = 0u64;
    let mut floats = 0u64;
    let mut strings = 0u64;
    let mut bools = 0u64;
    let mut fixed_points = 0u64;
    let mut arrays = 0u64;
    let mut vecs = 0u64;
    let mut maps = 0u64;
    let mut options = 0u64;
    let mut results = 0u64;
    let mut bitmaps = 0u64;
    let mut type_names: Vec<String> = Vec::new();
    for (_tid, entry) in mm.into_iter() {
        total += 1;
        type_names.push(entry.type_name.clone());
        match entry.metadata {
            Metadata::Struct(_) => structs += 1,
            Metadata::Tuple(_) => tuples += 1,
            Metadata::Enum(_) => enums += 1,
            Metadata::Int(_) => ints += 1,
            Metadata::Float(_) => floats += 1,
            Metadata::String => strings += 1,
            Metadata::Bool => bools += 1,
            Metadata::FixedPoint(_) => fixed_points += 1,
            Metadata::Array(_) => arrays += 1,
            Metadata::Vec(_) => vecs += 1,
            Metadata::Map(_) => maps += 1,
            Metadata::Option(_) => options += 1,
            Metadata::Result(_) => results += 1,
            Metadata::Bitmap(_) => bitmaps += 1,
        }
    }
    type_names.sort();
    if type_names.len() > 64 {
        type_names.truncate(64);
    }

    let mut m = norito::json::Map::new();
    m.insert("types_total".into(), norito::json::Value::from(total));
    m.insert("structs".into(), norito::json::Value::from(structs));
    m.insert("tuples".into(), norito::json::Value::from(tuples));
    m.insert("enums".into(), norito::json::Value::from(enums));
    m.insert("ints".into(), norito::json::Value::from(ints));
    m.insert("floats".into(), norito::json::Value::from(floats));
    m.insert("strings".into(), norito::json::Value::from(strings));
    m.insert("bools".into(), norito::json::Value::from(bools));
    m.insert(
        "fixed_points".into(),
        norito::json::Value::from(fixed_points),
    );
    m.insert("arrays".into(), norito::json::Value::from(arrays));
    m.insert("vecs".into(), norito::json::Value::from(vecs));
    m.insert("maps".into(), norito::json::Value::from(maps));
    m.insert("options".into(), norito::json::Value::from(options));
    m.insert("results".into(), norito::json::Value::from(results));
    m.insert("bitmaps".into(), norito::json::Value::from(bitmaps));
    let tn = type_names
        .into_iter()
        .map(norito::json::Value::from)
        .collect::<Vec<_>>();
    m.insert("type_names_sample".into(), norito::json::Value::Array(tn));
    let body = norito::json::to_json_pretty(&m).unwrap_or_else(|_| "{}".into());
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    resp
}

#[iroha_futures::telemetry_future]
pub async fn handle_get_configuration(kiso: KisoHandle) -> Result<impl IntoResponse> {
    let dto = kiso.get_dto().await?;
    // Serialize the DTO directly so new fields (e.g., SoraNet handshake/Puzzle config)
    // are exposed without hand-maintaining this JSON shape.
    let body = norito::json::to_json_pretty(&dto).unwrap_or_else(|_| "{}".into());
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}

#[iroha_futures::telemetry_future]
pub async fn handle_post_configuration(
    kiso: KisoHandle,
    value: ConfigUpdateDTO,
) -> Result<impl IntoResponse> {
    kiso.update_with_dto(value).await?;
    Ok((StatusCode::ACCEPTED, ()))
}

/// Return the exact current lane catalog and optimistic concurrency commitment.
pub fn handle_get_nexus_lane_lifecycle(state: &CoreState) -> Result<LaneLifecycleStatusV1> {
    // `State::view` retries across the state generation barrier, so catalog and
    // active incarnations cannot be mixed across a concurrent lifecycle commit.
    let view = state.view();
    LaneLifecycleStatusV1::new(
        view.nexus.enabled,
        &view.nexus.lane_catalog,
        &view.lane_incarnations,
    )
    .map_err(|err| conversion_error(format!("invalid committed lane lifecycle status: {err}")))
}

#[cfg(test)]
mod nexus_lane_lifecycle_tests {
    use super::*;

    fn enabled_state_for_lifecycle_test() -> Arc<CoreState> {
        let mut state = CoreState::new_for_testing(
            iroha_core::state::World::default(),
            Kura::blank_kura_for_testing(),
            iroha_core::query::store::LiveQueryStore::start_test(),
        );
        let configured_catalog = state.nexus_snapshot().lane_catalog;
        state
            .prepare_configured_primary_geometry_anchor(&configured_catalog)
            .expect("prepare the authenticated primary lane anchor");
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                ..Default::default()
            })
            .expect("enable Nexus for lifecycle test");
        Arc::new(state)
    }

    #[test]
    fn lane_lifecycle_status_binds_exact_current_catalog() {
        let state = enabled_state_for_lifecycle_test();
        let status = handle_get_nexus_lane_lifecycle(&state).expect("lifecycle status");
        assert!(status.nexus_enabled);
        let view = state.view();
        assert_eq!(
            status.validate().expect("validate lifecycle status"),
            view.nexus.lane_catalog
        );
        let expected_incarnations =
            iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations(
                &view.nexus.lane_catalog,
                &view.lane_incarnations,
            )
            .expect("canonical committed incarnations");
        assert_eq!(status.incarnations, expected_incarnations);
    }
}

pub mod block {
    //! Blocks stream handler

    use super::*;
    use crate::{block, stream::WebSocketNorito};

    /// Type for any error during blocks streaming
    #[derive(Debug, displaydoc::Display, thiserror::Error)]
    enum Error {
        /// Block consumption resulted in an error: {_0}
        Consumer(#[source] block::Error),
        /// Connection is closed
        Close,
    }

    impl From<block::Error> for Error {
        fn from(error: block::Error) -> Self {
            match error {
                block::Error::Stream(crate::stream::Error::Closed) => Self::Close,
                other => Self::Consumer(other),
            }
        }
    }

    type Result<T> = core::result::Result<T, Error>;

    #[cfg(not(test))]
    const HEARTBEAT_INTERVAL: std::time::Duration = std::time::Duration::from_secs(15);
    #[cfg(test)]
    const HEARTBEAT_INTERVAL: std::time::Duration = std::time::Duration::from_millis(25);

    fn close_frame_for_error(error: &Error) -> (u16, String) {
        use crate::stream::{
            CLOSE_INTERNAL_ERROR, CLOSE_INVALID_PAYLOAD, CLOSE_POLICY_VIOLATION,
            CLOSE_TRY_AGAIN_LATER, Error as StreamError,
        };

        match error {
            Error::Consumer(block::Error::Stream(StreamError::Decode(_)))
            | Error::Consumer(block::Error::Stream(StreamError::UnexpectedFrame { .. })) => (
                CLOSE_INVALID_PAYLOAD,
                "invalid_subscription_payload".to_owned(),
            ),
            Error::Consumer(block::Error::Stream(StreamError::ReadTimeout)) => {
                (CLOSE_POLICY_VIOLATION, "subscription_timeout".to_owned())
            }
            Error::Consumer(block::Error::InvalidHeight(_)) => (
                CLOSE_POLICY_VIOLATION,
                "invalid_block_subscription".to_owned(),
            ),
            Error::Consumer(block::Error::Stream(StreamError::SendTimeout)) => {
                (CLOSE_TRY_AGAIN_LATER, "stream_backpressure".to_owned())
            }
            Error::Consumer(block::Error::Stream(
                StreamError::Encode(_) | StreamError::WebSocket(_),
            )) => (CLOSE_INTERNAL_ERROR, "stream_internal_error".to_owned()),
            Error::Consumer(block::Error::Stream(StreamError::Closed)) | Error::Close => {
                (1000, "stream_closed".to_owned())
            }
        }
    }

    #[iroha_futures::telemetry_future]
    pub async fn handle_blocks_stream(
        kura: Arc<Kura>,
        stream: WebSocket,
        ws_message_timeout: std::time::Duration,
    ) -> eyre::Result<()> {
        let mut stream = WebSocketNorito::new(stream, ws_message_timeout);
        let init_and_subscribe = async {
            let mut consumer = block::Consumer::new(&mut stream, kura).await?;
            subscribe_forever(&mut consumer).await
        };

        match init_and_subscribe.await {
            Ok(()) => stream.close().await.map_err(Into::into),
            Err(Error::Close) => Ok(()),
            Err(err) => {
                let (code, reason) = close_frame_for_error(&err);
                if let Err(close_error) = stream.close_with(code, reason).await {
                    iroha_logger::debug!(%close_error, "failed to send block stream close frame");
                }
                Err(err.into())
            }
        }
    }

    /// Make endless `consumer` subscription for `blocks`
    ///
    /// Ideally should return `Result<!>` cause it either runs forever or returns error
    async fn subscribe_forever(consumer: &mut block::Consumer<'_>) -> Result<()> {
        let mut interval = tokio::time::interval(std::time::Duration::from_millis(10));
        let mut heartbeat = tokio::time::interval(HEARTBEAT_INTERVAL);
        heartbeat.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        heartbeat.tick().await;
        loop {
            tokio::select! {
                // Wait for stream to be closed by client
                closed = consumer.stream.closed() => {
                    match closed {
                        Ok(()) => return Err(Error::Close),
                        Err(err) => return Err(block::Error::from(err).into())
                    }
                }
                // This branch sends blocks
                _ = interval.tick() => consumer.consume().await?,
                _ = heartbeat.tick() => {
                    consumer.stream.ping().await.map_err(block::Error::from)?;
                }
            }
        }
    }
}

pub mod event {
    //! Events stream handler

    use super::*;
    use crate::{event, stream::WebSocketNorito};

    /// Type for any error during events streaming
    #[derive(Debug, displaydoc::Display, thiserror::Error)]
    enum Error {
        /// Event consumption resulted in an error: {_0}
        Consumer(#[source] event::Error),
        /// Event reception error
        Event(#[from] tokio::sync::broadcast::error::RecvError),
        /// Connection is closed
        Close,
    }

    impl From<event::Error> for Error {
        fn from(error: event::Error) -> Self {
            match error {
                event::Error::Stream(crate::stream::Error::Closed) => Self::Close,
                other => Self::Consumer(other),
            }
        }
    }

    type Result<T> = core::result::Result<T, Error>;

    #[cfg(not(test))]
    const HEARTBEAT_INTERVAL: std::time::Duration = std::time::Duration::from_secs(15);
    #[cfg(test)]
    const HEARTBEAT_INTERVAL: std::time::Duration = std::time::Duration::from_millis(25);

    fn close_frame_for_error(error: &Error) -> (u16, String) {
        use crate::stream::{
            CLOSE_INTERNAL_ERROR, CLOSE_INVALID_PAYLOAD, CLOSE_POLICY_VIOLATION,
            CLOSE_TRY_AGAIN_LATER, Error as StreamError,
        };

        match error {
            Error::Event(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => (
                CLOSE_TRY_AGAIN_LATER,
                format!("event_stream_lagged:{skipped}"),
            ),
            Error::Event(tokio::sync::broadcast::error::RecvError::Closed) => {
                (CLOSE_INTERNAL_ERROR, "event_source_closed".to_owned())
            }
            Error::Consumer(event::Error::Stream(StreamError::Decode(_)))
            | Error::Consumer(event::Error::Stream(StreamError::UnexpectedFrame { .. })) => (
                CLOSE_INVALID_PAYLOAD,
                "invalid_subscription_payload".to_owned(),
            ),
            Error::Consumer(event::Error::Stream(StreamError::ReadTimeout)) => {
                (CLOSE_POLICY_VIOLATION, "subscription_timeout".to_owned())
            }
            Error::Consumer(event::Error::InvalidSubscription(_)) => (
                CLOSE_POLICY_VIOLATION,
                "invalid_event_subscription".to_owned(),
            ),
            Error::Consumer(event::Error::Stream(StreamError::SendTimeout)) => {
                (CLOSE_TRY_AGAIN_LATER, "stream_backpressure".to_owned())
            }
            Error::Consumer(event::Error::Stream(
                StreamError::Encode(_) | StreamError::WebSocket(_),
            )) => (CLOSE_INTERNAL_ERROR, "stream_internal_error".to_owned()),
            Error::Consumer(event::Error::Stream(StreamError::Closed)) | Error::Close => {
                (1000, "stream_closed".to_owned())
            }
        }
    }

    /// Subscribes `stream` for `events` filtered by filter that is
    /// received through the `stream`
    #[iroha_futures::telemetry_future]
    pub async fn handle_events_stream(events: EventsSender, stream: WebSocket) -> eyre::Result<()> {
        handle_events_stream_with_receiver(
            events.subscribe(),
            stream,
            std::time::Duration::from_millis(defaults::torii::WS_MESSAGE_TIMEOUT_MS),
        )
        .await
    }

    /// Subscribe a pre-registered receiver to the event stream, ensuring buffered events
    /// emitted during the WebSocket upgrade are not dropped.
    #[iroha_futures::telemetry_future]
    pub async fn handle_events_stream_with_receiver(
        mut events_rx: tokio::sync::broadcast::Receiver<iroha_data_model::events::EventBox>,
        stream: WebSocket,
        ws_message_timeout: std::time::Duration,
    ) -> eyre::Result<()> {
        let mut stream = WebSocketNorito::new(stream, ws_message_timeout);
        let init_and_subscribe = async {
            let mut consumer = event::Consumer::new(&mut stream).await?;
            subscribe_forever(&mut events_rx, &mut consumer).await
        };

        match init_and_subscribe.await {
            Ok(()) => stream.close().await.map_err(Into::into),
            Err(Error::Close) => Ok(()),
            Err(err) => {
                let (code, reason) = close_frame_for_error(&err);
                if let Err(close_error) = stream.close_with(code, reason).await {
                    iroha_logger::debug!(%close_error, "failed to send event stream close frame");
                }
                Err(err.into())
            }
        }
    }

    /// Make endless `consumer` subscription for `events`
    ///
    /// Ideally should return `Result<!>` cause it either runs forever or returns error
    async fn subscribe_forever(
        events: &mut tokio::sync::broadcast::Receiver<iroha_data_model::events::EventBox>,
        consumer: &mut event::Consumer<'_>,
    ) -> Result<()> {
        let mut heartbeat = tokio::time::interval(HEARTBEAT_INTERVAL);
        heartbeat.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        heartbeat.tick().await;
        loop {
            tokio::select! {
                // Wait for stream to be closed by client
                closed = consumer.stream.closed() => {
                    match closed {
                        Ok(()) => return Err(Error::Close),
                        Err(err) => return Err(event::Error::from(err).into())
                    }
                }
                // This branch catches and sends events
                event = events.recv() => {
                    match event {
                        Ok(event) => {
                            iroha_logger::trace!(?event);
                            consumer.consume(event).await?;
                        }
                        Err(err) => return Err(Error::Event(err)),
                    }
                }
                _ = heartbeat.tick() => {
                    consumer.stream.ping().await.map_err(event::Error::from)?;
                }
            }
        }
    }
}

/// Get running Iroha version (block header version).
#[iroha_futures::telemetry_future]
pub async fn handle_version(state: Arc<CoreState>) -> Response {
    use iroha_version::Version;

    let latest_block = std::num::NonZeroUsize::new(state.committed_height())
        .and_then(|height| state.block_by_height(height));
    let mut resp = match latest_block {
        Some(block) => Response::new(Body::from(block.version().to_string())),
        None => {
            let mut resp = Response::new(Body::from("genesis not applied"));
            *resp.status_mut() = StatusCode::SERVICE_UNAVAILABLE;
            resp
        }
    };
    resp.headers_mut().insert(
        header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    resp
}

#[cfg(test)]
mod version_tests {
    use http_body_util::BodyExt as _;
    use iroha_core::{kura::Kura, query::store::LiveQueryStore, state::World};

    use super::*;

    #[tokio::test]
    async fn handle_version_reports_unavailable_without_genesis() {
        let state = Arc::new(CoreState::new_for_testing(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        ));
        let response = handle_version(state).await;
        let (parts, body) = response.into_parts();
        assert_eq!(parts.status, StatusCode::SERVICE_UNAVAILABLE);
        assert_eq!(
            parts
                .headers
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("text/plain; charset=utf-8"),
        );
        let body_bytes = body.collect().await.expect("collect body").to_bytes();
        assert_eq!(
            std::str::from_utf8(&body_bytes).expect("utf8"),
            "genesis not applied"
        );
    }
}

#[cfg(feature = "telemetry")]
#[iroha_futures::telemetry_future]
/// Handle POST `/v1/soranet/privacy/event`, forwarding relay observations into the secure aggregator.
pub async fn handle_post_soranet_privacy_event(
    telemetry: MaybeTelemetry,
    crate::NoritoJson(req): crate::NoritoJson<RecordSoranetPrivacyEventDto>,
) -> Result<impl IntoResponse> {
    if !telemetry.is_enabled() {
        return Err(Error::telemetry_profile_forbidden(
            SORANET_PRIVACY_EVENT_ENDPOINT,
            telemetry.profile(),
        ));
    }

    let RecordSoranetPrivacyEventDto { event, source } = req;
    let bucket_secs = telemetry
        .telemetry()
        .map(|handle| handle.soranet_privacy().config().bucket_secs)
        .unwrap_or_else(|| PrivacyBucketConfig::default().bucket_secs);
    let bucket_start = if bucket_secs > 0 {
        Some((event.timestamp_unix / bucket_secs) * bucket_secs)
    } else {
        None
    };

    telemetry.record_soranet_privacy_event(&event);

    iroha_logger::trace!(
        mode = %event.mode,
        timestamp = event.timestamp_unix,
        bucket_start,
        bucket_secs,
        source = source.as_deref().unwrap_or(""),
        "accepted SoraNet privacy event"
    );

    let mut entries = vec![
        json_entry("status", "accepted"),
        json_entry("mode", event.mode),
        json_entry("timestamp_unix", event.timestamp_unix),
    ];
    if let Some(bucket_start_unix) = bucket_start {
        entries.push(json_entry("bucket_start_unix", bucket_start_unix));
        entries.push(json_entry("bucket_duration_secs", bucket_secs));
    }
    if let Some(source_label) = source {
        entries.push(json_entry("source", source_label));
    }

    let payload = json_object(entries);
    Ok((StatusCode::ACCEPTED, JsonValueBody(payload)))
}

#[cfg(feature = "telemetry")]
#[iroha_futures::telemetry_future]
/// Handle POST `/v1/soranet/privacy/share`, ingesting Prio collector contributions.
pub async fn handle_post_soranet_privacy_share(
    telemetry: MaybeTelemetry,
    crate::NoritoJson(req): crate::NoritoJson<RecordSoranetPrivacyShareDto>,
) -> Result<impl IntoResponse> {
    if !telemetry.is_enabled() {
        return Err(Error::telemetry_profile_forbidden(
            SORANET_PRIVACY_SHARE_ENDPOINT,
            telemetry.profile(),
        ));
    }

    let RecordSoranetPrivacyShareDto {
        share,
        forwarded_by,
    } = req;
    let collector_id = share.collector_id;
    let bucket_start_unix = share.bucket_start_unix;
    let bucket_duration_secs = share.bucket_duration_secs;
    let mode = share.mode;
    let suppressed_hint = share.suppressed;

    if let Err(err) = telemetry.ingest_soranet_privacy_share(share) {
        iroha_logger::warn!(
            ?err,
            collector_id,
            bucket_start_unix,
            bucket_duration_secs,
            mode = %mode,
            "failed to ingest SoraNet privacy share"
        );
        return Err(conversion_error(format!(
            "invalid SoraNet privacy share: {err}"
        )));
    }

    iroha_logger::trace!(
        collector_id,
        bucket_start_unix,
        bucket_duration_secs,
        mode = %mode,
        suppressed_hint,
        forwarded_by = forwarded_by.as_deref().unwrap_or(""),
        "accepted SoraNet privacy share"
    );

    let mut entries = vec![
        json_entry("status", "accepted"),
        json_entry("collector_id", collector_id),
        json_entry("bucket_start_unix", bucket_start_unix),
        json_entry("bucket_duration_secs", bucket_duration_secs),
        json_entry("mode", mode),
        json_entry("suppressed_hint", suppressed_hint),
    ];
    if let Some(label) = forwarded_by {
        entries.push(json_entry("forwarded_by", label));
    }

    let payload = json_object(entries);
    Ok((StatusCode::ACCEPTED, JsonValueBody(payload)))
}

#[cfg(feature = "telemetry")]
/// Render the Prometheus metrics exposition when enabled by the active telemetry profile.
pub async fn handle_metrics(telemetry: &MaybeTelemetry, nexus_enabled: bool) -> Result<String> {
    if !telemetry.allows_expensive_metrics() {
        return Err(Error::telemetry_profile_forbidden(
            "metrics",
            telemetry.profile(),
        ));
    }

    telemetry
        .metrics()
        .await
        .try_to_string_with_nexus_gate(nexus_enabled)
        .map_err(Error::Prometheus)
}

/// Build a compact response with online peers.
pub fn handle_peers(
    online_peers: &OnlinePeersProvider,
    format: crate::utils::ResponseFormat,
) -> Response {
    // Caution: this short `.get` done frequently might cause the writer part to block, thus
    // blocking the P2P module
    let data = online_peers.get();
    match format {
        crate::utils::ResponseFormat::Norito => crate::NoritoBody(data).into_response(),
        crate::utils::ResponseFormat::Json => JsonBody(data).into_response(),
    }
}

#[cfg(feature = "telemetry")]
#[allow(clippy::unnecessary_wraps)]
/// Render the `/status` JSON payload or a specific nested field when requested.
pub async fn handle_status(
    telemetry: &MaybeTelemetry,
    accept: Option<axum::http::HeaderValue>,
    tail: Option<&str>,
    nexus_enabled: bool,
    nexus_routing_policy: Option<&ActualLaneRoutingPolicy>,
    offline: Option<iroha_torii_shared::offline_api::OfflineStatus>,
) -> Result<Response> {
    iroha_logger::debug!(
        tail = tail.unwrap_or(""),
        accept = ?accept,
        "serving /status"
    );
    if !telemetry.allows_metrics() {
        return Err(Error::telemetry_profile_forbidden(
            "status",
            telemetry.profile(),
        ));
    }

    let mut status = Status::from(telemetry.metrics().await);
    normalize_status_block_visibility(&mut status);
    if !nexus_enabled {
        status.strip_nexus();
    } else if let Some(policy) = nexus_routing_policy {
        status.nexus = Some(NexusStatus::from_routing_policy(policy));
    }
    status.offline = offline;
    if let Some(handle) = telemetry.telemetry() {
        status.sorafs_micropayments = handle.sorafs_micropayment_samples();
    }
    iroha_logger::debug!(
        blocks = status.blocks,
        blocks_non_empty = status.blocks_non_empty,
        txs_approved = status.txs_approved,
        txs_rejected = status.txs_rejected,
        "status snapshot built"
    );

    if let Some(tail) = tail {
        if !nexus_enabled && is_nexus_status_segment(tail) {
            return Err(Error::StatusSegmentNotFound(eyre!(
                "Nexus lanes are disabled; field \"{}\" is unavailable",
                tail
            )));
        }
        let segment = status_value_by_path(&status, tail)
            .ok_or_else(|| Error::StatusSegmentNotFound(eyre!("Path not found: \"{}\"", tail)))?;
        let s = norito::json::to_json(&segment).map_err(|e| Error::StatusFailure(eyre!(e)))?;
        let mut resp = axum::response::Response::new(axum::body::Body::from(s));
        resp.headers_mut().insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/json"),
        );
        Ok(resp)
    } else {
        let format = match crate::utils::negotiate_response_format(accept.as_ref()) {
            Ok(fmt) => fmt,
            Err(resp) => return Ok(resp),
        };
        match format {
            crate::utils::ResponseFormat::Norito => {
                let bytes =
                    norito::to_bytes(&status).map_err(|err| Error::StatusFailure(eyre!(err)))?;
                let mut resp = axum::response::Response::new(axum::body::Body::from(bytes));
                resp.headers_mut().insert(
                    axum::http::header::CONTENT_TYPE,
                    axum::http::HeaderValue::from_static(crate::utils::NORITO_MIME_TYPE),
                );
                Ok(resp)
            }
            crate::utils::ResponseFormat::Json => {
                let s = norito::json::to_json_pretty(&status)
                    .map_err(|e| Error::StatusFailure(eyre!(e)))?;
                let mut resp = axum::response::Response::new(axum::body::Body::from(s));
                resp.headers_mut().insert(
                    axum::http::header::CONTENT_TYPE,
                    axum::http::HeaderValue::from_static("application/json"),
                );
                Ok(resp)
            }
        }
    }
}

#[cfg(feature = "telemetry")]
fn normalize_status_block_visibility(status: &mut Status) {
    let Some(sumeragi) = status.sumeragi.as_ref() else {
        return;
    };
    let finality_height = sumeragi.commit_qc_height;
    if finality_height <= status.blocks {
        return;
    }
    status.blocks = finality_height;
}

#[cfg(feature = "telemetry")]
fn status_value_by_path(status: &Status, tail: &str) -> Option<norito::json::Value> {
    let mut segments = tail.split('/').filter(|s| !s.is_empty());
    let field = segments.next()?;
    match field {
        "observed_at_ms" if segments.next().is_none() => Some(status.observed_at_ms.into()),
        "peers" if segments.next().is_none() => Some(status.peers.into()),
        "blocks" if segments.next().is_none() => Some(status.blocks.into()),
        "blocks_non_empty" if segments.next().is_none() => Some(status.blocks_non_empty.into()),
        "commit_time_ms" if segments.next().is_none() => Some(status.commit_time_ms.into()),
        "txs_approved" if segments.next().is_none() => Some(status.txs_approved.into()),
        "txs_rejected" if segments.next().is_none() => Some(status.txs_rejected.into()),
        "last_rejection_at_ms" if segments.next().is_none() => {
            Some(json_value(&status.last_rejection_at_ms))
        }
        "txs_rejected_recent_5m" if segments.next().is_none() => {
            Some(status.txs_rejected_recent_5m.into())
        }
        "uptime" => {
            let duration = status.uptime.0;
            match segments.next() {
                None => Some(crate::json_object(vec![
                    ("secs", duration.as_secs()),
                    ("nanos", u64::from(duration.subsec_nanos())),
                ])),
                Some("secs") if segments.next().is_none() => Some(duration.as_secs().into()),
                Some("nanos") if segments.next().is_none() => {
                    Some(u64::from(duration.subsec_nanos()).into())
                }
                _ => None,
            }
        }
        "da_receipt_cursors" if segments.next().is_none() => Some(
            status
                .da_receipt_cursors
                .iter()
                .map(|cursor| {
                    crate::json_object(vec![
                        ("lane_id", json_value(&cursor.lane_id)),
                        ("epoch", json_value(&cursor.epoch)),
                        ("highest_sequence", json_value(&cursor.highest_sequence)),
                    ])
                })
                .collect::<Vec<_>>()
                .into(),
        ),
        "view_changes" if segments.next().is_none() => Some(status.view_changes.into()),
        "queue_size" if segments.next().is_none() => Some(status.queue_size.into()),
        "queue_queued" if segments.next().is_none() => Some(status.queue_queued.into()),
        "queue_inflight" if segments.next().is_none() => Some(status.queue_inflight.into()),
        "last_block_committed_at_ms" if segments.next().is_none() => {
            Some(status.last_block_committed_at_ms.into())
        }
        "last_non_empty_block_committed_at_ms" if segments.next().is_none() => {
            Some(status.last_non_empty_block_committed_at_ms.into())
        }
        "time_since_last_block_ms" if segments.next().is_none() => {
            Some(status.time_since_last_block_ms.into())
        }
        "time_since_last_non_empty_block_ms" if segments.next().is_none() => {
            Some(status.time_since_last_non_empty_block_ms.into())
        }
        "crypto" => match segments.next() {
            None => norito::json::to_value(&status.crypto).ok(),
            Some("sm_helpers_available") if segments.next().is_none() => {
                Some(status.crypto.sm_helpers_available.into())
            }
            Some("sm_openssl_preview_enabled") if segments.next().is_none() => {
                Some(status.crypto.sm_openssl_preview_enabled.into())
            }
            _ => None,
        },
        "offline" => {
            let offline = status.offline.as_ref()?;
            let value = norito::json::to_value(offline).ok()?;
            json_value_by_segments(value, segments)
        }
        "governance" if segments.next().is_none() => {
            norito::json::to_value(&status.governance).ok()
        }
        "dataspace_catalog" if segments.next().is_none() => {
            norito::json::to_value(&status.dataspace_catalog).ok()
        }
        "nexus" => {
            let nexus = status.nexus.as_ref()?;
            match segments.next() {
                None => norito::json::to_value(nexus).ok(),
                Some("routing_policy") => {
                    let routing = &nexus.routing_policy;
                    match segments.next() {
                        None => norito::json::to_value(routing).ok(),
                        Some("default_lane") if segments.next().is_none() => {
                            Some(routing.default_lane.into())
                        }
                        Some("default_dataspace") if segments.next().is_none() => {
                            Some(routing.default_dataspace.into())
                        }
                        Some("rules") if segments.next().is_none() => {
                            norito::json::to_value(&routing.rules).ok()
                        }
                        _ => None,
                    }
                }
                _ => None,
            }
        }
        "sorafs_micropayments" => match segments.next() {
            None => norito::json::to_value(&status.sorafs_micropayments).ok(),
            Some(provider_hex) => {
                let sample = status
                    .sorafs_micropayments
                    .iter()
                    .find(|entry| entry.provider_id_hex == provider_hex)?;
                match segments.next() {
                    None => norito::json::to_value(sample).ok(),
                    Some("credits") => match segments.next() {
                        None => norito::json::to_value(&sample.credits).ok(),
                        Some("deterministic_charge") if segments.next().is_none() => {
                            Some(json_value(&sample.credits.deterministic_charge))
                        }
                        Some("credit_generated") if segments.next().is_none() => {
                            Some(json_value(&sample.credits.credit_generated))
                        }
                        Some("credit_applied") if segments.next().is_none() => {
                            Some(json_value(&sample.credits.credit_applied))
                        }
                        Some("credit_carry") if segments.next().is_none() => {
                            Some(json_value(&sample.credits.credit_carry))
                        }
                        Some("outstanding") if segments.next().is_none() => {
                            Some(json_value(&sample.credits.outstanding))
                        }
                        _ => None,
                    },
                    Some("tickets") => match segments.next() {
                        None => norito::json::to_value(&sample.tickets).ok(),
                        Some("processed") if segments.next().is_none() => {
                            Some(sample.tickets.processed.into())
                        }
                        Some("won") if segments.next().is_none() => Some(sample.tickets.won.into()),
                        Some("duplicate") if segments.next().is_none() => {
                            Some(sample.tickets.duplicate.into())
                        }
                        _ => None,
                    },
                    _ => None,
                }
            }
        },
        _ => None,
    }
}

#[cfg(feature = "telemetry")]
#[allow(single_use_lifetimes)]
fn json_value_by_segments<'a>(
    mut value: norito::json::Value,
    segments: impl Iterator<Item = &'a str>,
) -> Option<norito::json::Value> {
    for segment in segments {
        value = match value {
            norito::json::Value::Object(map) => map.get(segment)?.clone(),
            norito::json::Value::Array(values) => {
                let index = segment.parse::<usize>().ok()?;
                values.get(index)?.clone()
            }
            _ => return None,
        };
    }
    Some(value)
}

#[cfg(feature = "telemetry")]
fn is_nexus_status_segment(tail: &str) -> bool {
    let mut segments = tail.split('/').filter(|s| !s.is_empty());
    matches!(
        segments.next(),
        Some(
            "teu_lane_commit"
                | "teu_dataspace_backlog"
                | "dataspace_catalog"
                | "nexus"
                | "tx_gossip"
                | "da_receipt_cursors"
        )
    )
}

